window.GNN_LESSONS=window.GNN_LESSONS||{};window.GNN_LESSONS["L5"]={"deck":"L5","slides":[{"p":1,"title":"5주차: 더 깊은 GNN 학습하기","terms":["Over-smoothing","Over-squashing","Under-reaching","Depth","GCN"],"pass1":[{"kind":"say","lines":["5주차 주제는 'GNN을 깊게 쌓기'예요.","층을 2개, 3개가 아니라 10개, 50개 쌓으면 무슨 일이 생길까요?","놀랍게도 성능이 **떨어져요**. 왜 그런지가 오늘의 이야기예요."]},{"kind":"analogy","head":"소문이 퍼지는 교실","scene":"민수네 반 서른 명이 저마다 다른 이야기를 들고 있어요. 쉬는 시간마다 옆자리 친구와 이야기를 나누죠. 한두 번은 좋아요. 그런데 스무 번 반복하면 반 전체가 똑같은 이야기만 해요.","map":[["쉬는 시간마다 이야기 나누기","**메시지 패싱(Message Passing)** 한 층"],["열 번, 스무 번 반복","층을 깊게 쌓기, 즉 **깊이(Depth)** 늘리기"],["반 전체가 같은 이야기","**과도한 평활화(Over-smoothing)**"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"4주차와 무엇이 다른가요","items":["4주차는 '옆으로 넓은 문제'였어요. 이웃이 너무 많아서 메모리가 터지는 문제요.","5주차는 '위로 높은 문제'예요. 층을 많이 쌓으면 망가지는 문제요.","망가지는 방식이 네 가지예요. 하나씩 이름을 붙여 가며 배워요.","**과도한 평활화(Over-smoothing)**, **과도한 압착(Over-squashing)**, **도달 실패(Under-reaching)**, 최적화예요."]},{"kind":"compare","head":"네 가지 고장을 한 줄로","cols":["이름","무슨 일이 생기나"],"rows":[["**과도한 평활화(Over-smoothing)**","다 섞여서 노드를 구별할 수 없게 돼요"],["**과도한 압착(Over-squashing)**","먼 노드 정보가 눌려서 사라져요"],["**도달 실패(Under-reaching)**","필요한 노드가 아예 보이지 않아요"],["최적화","기울기가 사라져서 학습 자체가 안 돼요"]]}],"pass3":[],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.055,0.185,0.55,0.115],"c":[0.0275,0.169,0.605,0.147],"r":7.3167,"img":"img/L5/walk/p001_20_01.jpg","say":"제목이 'Training Deeper GNNs', 즉 '더 깊은 GNN 학습하기'예요."},{"b":[0.235,0.49,0.145,0.045],"c":[0.2075,0.4575,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p001_20_02.jpg","say":"이오준 교수님 이름이에요."},{"b":[0.155,0.58,0.26,0.045],"c":[0.142,0.5475,0.286,0.11],"r":4.6222,"img":"img/L5/walk/p001_20_03.jpg","say":"가톨릭대학교 인공지능학과, 아래에 이메일 주소가 있어요."},{"b":[0.66,0.02,0.335,0.955],"c":[0.5915,0,0.4085,1],"r":0.7262,"img":"img/L5/walk/p001_20_04.jpg","say":"점과 선으로 그린 그래프 무늬예요. 점이 노드, 선이 엣지예요."}]}},{"p":2,"title":"목차: 오늘 배울 네 덩어리","terms":["Over-smoothing","Over-squashing","Under-reaching","DeepGCNs"],"pass1":[{"kind":"say","lines":["오늘은 네 덩어리로 가요.","먼저 '무엇이 깊은 GNN을 막는가'를 진단해요.","그다음 평활화와 압착, 도달 실패를 차례로 보고, 마지막에 해법을 배워요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"points","head":"이번 레슨이 다루는 범위","items":["p.1 부터 p.20 까지예요.","01 덩어리 전체(복습 포함)와, 02 덩어리 중 **과도한 평활화(Over-smoothing)** 부분이에요.","**과도한 압착(Over-squashing)**과 **도달 실패(Under-reaching)**는 p.21 부터 자세히 봐요.","**DeepGCNs** 같은 해법은 p.36 부터 나와요."]},{"kind":"compare","head":"네 덩어리와 다루는 쪽","cols":["덩어리","무엇을 하나","쪽"],"rows":[["01 진단","무엇이 깊이를 막는지 알아내기","p.3 ~ p.14"],["02 평활화와 압착","정반대 두 고장을 파고들기","p.15 ~ p.27"],["03 **도달 실패(Under-reaching)**","아예 못 보는 경우 다루기","p.28 ~ p.31"],["04 해법","**DeepGCNs** 등 처방 배우기","p.35 이후"]]}],"pass3":[],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.278,0.143,0.653,0.148],"c":[0.2454,0.127,0.7183,0.18],"r":7.0943,"img":"img/L5/walk/p002_11_01.jpg","say":"01 무엇이 깊은 GNN을 막는가? 네 가지 장애물을 표로 정리해요."},{"b":[0.278,0.331,0.653,0.148],"c":[0.2454,0.315,0.7183,0.18],"r":7.0943,"img":"img/L5/walk/p002_11_02.jpg","say":"02 **과도한 평활화(Over-smoothing)**와 **과도한 압착(Over-squashing)**. 정반대의 고장이에요."},{"b":[0.278,0.52,0.653,0.148],"c":[0.2454,0.504,0.7183,0.18],"r":7.0943,"img":"img/L5/walk/p002_11_03.jpg","say":"03 **도달 실패(Under-reaching)**. 층이 적어서 아예 못 보는 경우예요."},{"b":[0.278,0.709,0.653,0.148],"c":[0.2454,0.693,0.7183,0.18],"r":7.0943,"img":"img/L5/walk/p002_11_04.jpg","say":"04 더 깊은 GNN을 학습시키는 해법. **DeepGCNs** 같은 처방이 나와요."}]}},{"p":3,"title":"구분: 무엇이 깊은 GNN을 막는가","terms":["Message Passing","Depth","Receptive Field"],"pass1":[{"kind":"say","lines":["**메시지 패싱(Message Passing)**에서 **깊이(Depth)**는 곧 '내가 볼 수 있는 거리'예요.","층 하나면 한 걸음, 층 셋이면 세 걸음 떨어진 곳까지 봐요.","그러면 깊을수록 좋아야 하는데, 왜 대부분의 GNN은 두세 층에서 멈출까요?"]},{"kind":"look","walked":1}],"pass2":[{"kind":"points","head":"이 한 문장을 뜯어 보면","items":["층 하나를 지나면 내 이웃(1홉)의 정보가 들어와요.","층 둘이면 이웃의 이웃(2홉)까지 들어와요.","그러니 층의 개수가 곧 **수용 영역(Receptive Field)**, 즉 내가 보는 범위예요.","그런데 실제 GNN은 거의 다 층이 두세 개예요. 이 모순이 오늘의 질문이에요."]}],"pass3":[],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.048,0.346,0.48,0.07],"c":[0.024,0.326,0.528,0.11],"r":8.5333,"img":"img/L5/walk/p003_11_01.jpg","say":"큰 제목: '무엇이 깊은 GNN을 막는가?'"},{"b":[0.045,0.45,0.52,0.08],"c":[0.019,0.4322,0.572,0.1156],"r":8.7966,"img":"img/L5/walk/p003_11_02.jpg","say":"한 문장: '메시지 패싱에서 깊이는 곧 도달 범위예요. 그런데 왜 두세 층에서 멈출까요?'"}]}},{"p":4,"title":"복습: GCN 한 층은 메시지 더하기 집계","terms":["GCN","Message Passing","Aggregation","Embedding","Degree","ReLU","Adjacency Matrix","Self-loop"],"pass1":[{"kind":"say","lines":["**GCN** 한 층은 두 단계로 되어 있어요.","먼저 이웃마다 보낼 쪽지를 만들고(메시지), 그 쪽지들을 하나로 합쳐요(**집계(Aggregation)**).","이 한 층을 여러 번 반복하는 데서 오늘의 모든 고장이 나와요."]},{"kind":"analogy","head":"쪽지를 걷어 요약하는 반장","scene":"반장이 짝꿍 세 명에게 쪽지를 받아요. 먼저 세 명이 각자 쪽지를 씁니다. 그다음 반장이 그 쪽지 세 장을 걷어서 한 장으로 요약해요. 쪽지를 쓰는 일과 걷어서 요약하는 일, 이 두 가지가 GNN 한 층이 하는 전부예요.","map":[["쪽지를 쓰는 일","메시지 계산"],["걷어서 한 장으로 요약","**집계(Aggregation)**"],["요약된 한 장","새 **임베딩(Embedding)**"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.055,"y":0.15,"w":0.22,"h":0.04,"say":"'GNN 층 = 메시지 + 집계'. 한 층이 두 단계로 쪼개져요.","c":[0.043,0.115,0.244,0.11],"r":3.9434,"img":"img/L5/walk/p004_20_01.jpg"},{"x":0.09,"y":0.214,"w":0.18,"h":0.038,"say":"'메시지 계산'. 이웃마다 보낼 쪽지를 만드는 단계예요.","c":[0.078,0.178,0.204,0.11],"r":3.297,"img":"img/L5/walk/p004_20_02.jpg"},{"x":0.13,"y":0.283,"w":0.37,"h":0.038,"say":"'이웃 노드마다 임베딩을 어떻게 만들까?'가 이 단계의 질문이에요.","c":[0.1115,0.247,0.407,0.11],"r":6.5778,"img":"img/L5/walk/p004_20_03.jpg"},{"x":0.09,"y":0.351,"w":0.18,"h":0.038,"say":"'메시지 집계'. 걷은 쪽지를 하나로 합치는 단계예요.","c":[0.078,0.315,0.204,0.11],"r":3.297,"img":"img/L5/walk/p004_20_04.jpg"},{"x":0.13,"y":0.417,"w":0.32,"h":0.038,"say":"'그 임베딩들을 어떻게 합칠까?'가 이 단계의 질문이에요.","c":[0.114,0.381,0.352,0.11],"r":5.6889,"img":"img/L5/walk/p004_20_05.jpg"},{"x":0.458,"y":0.812,"w":0.46,"h":0.075,"say":"오른쪽 아래가 갱신 규칙이에요. 괄호 안 앞쪽이 나, 뒤쪽이 이웃이에요.","c":[0.435,0.7945,0.506,0.11],"r":8.1778,"img":"img/L5/walk/p004_20_06.jpg"}]},{"kind":"formula","head":"갱신 규칙을 기호 하나씩","tex":"h_i^{(l+1)} = \\sigma \\left( h_i^{(l)} W_0^{(l)} + \\sum_{j \\in \\mathcal{N}_i} \\frac{1}{c_{ij}} h_j^{(l)} W_1^{(l)} \\right)","parts":[{"sym":"h_i^{(l)}","say":"노드 $i$ 가 층 $l$ 에서 들고 있는 **임베딩(Embedding)**이에요."},{"sym":"\\mathcal{N}_i","say":"노드 $i$ 의 이웃 목록이에요. 짝꿍 명단이라고 보면 돼요."},{"sym":"\\sum_{j \\in \\mathcal{N}_i}","say":"이웃들 것을 전부 더하라는 뜻이에요. 쪽지를 다 걷는 일이에요."},{"sym":"c_{ij}","say":"나누는 상수예요. 이웃이 많은 노드가 너무 큰 값을 받지 않게 해요."},{"sym":"W_0^{(l)}","say":"**내 정보**를 다루는 학습 가중치예요."},{"sym":"W_1^{(l)}","say":"**이웃 정보**를 다루는 학습 가중치예요."},{"sym":"\\sigma","say":"비선형 함수, 보통 **렐루(ReLU)**예요. 음수를 0으로 깎아요."}],"whole":"우리말로 하면 '내 것을 규칙 $W_0$ 로 바꾸고, 이웃 것을 규칙 $W_1$ 로 바꿔 모두 더한 뒤, 마지막에 **렐루(ReLU)**를 통과시킨다'예요."},{"kind":"steps","head":"노드 셋으로 한 층 돌려 보기","steps":["이웃 목록부터 적어요. 1의 이웃은 2, 2의 이웃은 1과 3, 3의 이웃은 2예요.","**차수(Degree)**는 각각 1, 2, 1 이에요.","노드 1: 내 값 4, 이웃 값 0. 이웃 평균은 $0 \\div 1 = 0$. 합은 $4 + 0 = 4$ 예요.","노드 2: 내 값 0, 이웃 값 4와 -2. 이웃 평균은 $(4 - 2) \\div 2 = 1$. 합은 $0 + 1 = 1$ 이에요.","노드 3: 내 값 -2, 이웃 값 0. 합은 $-2 + 0 = -2$ 예요.","마지막에 **렐루(ReLU)**를 씌워요. 음수인 -2 만 0 이 돼요."],"answer":"층 1 의 값은 4, 1, 0 이에요. 값의 폭이 6 에서 4 로 좁아졌어요. 이것이 평활화의 첫걸음이에요.","given":"노드 세 개를 한 줄로 이었어요. 시작 값은 4, 0, -2 이고 $W_0 = W_1 = 1$, $c_{ij}$ 는 내 **차수(Degree)** 예요."},{"kind":"mining","src":"마이닝 2강 Representation of Graphs and Storage","lines":["누가 누구의 이웃인지 적는 방법이 **인접행렬(Adjacency Matrix)**이에요.","노드가 $n$ 개면 $n \\times n$ 표를 만들고 이어져 있으면 1, 아니면 0 을 적어요.","이게 편한 이유가 있어요. 이웃을 전부 더하는 일이 곱셈 한 번 $A H$ 로 끝나거든요.","시험 계산 문제가 거의 다 이 모양인 이유예요."]},{"kind":"warn","head":"여기서 헷갈리기 쉬워요","items":["슬라이드에는 $c_{ij}$ 가 무엇인지 적혀 있지 않아요.","원래 **GCN** 논문에서는 두 노드 **차수(Degree)**를 곱해 제곱근을 씌운 값을 써요.","시험 문제는 보통 $\\tilde{A} = D^{-1} A$ 처럼 직접 알려 주니, 문제에 적힌 정의를 그대로 쓰세요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 9번 (DeepGCN, 10점) (b) 의 계산 틀","q":"Calculate the output at layer k=2, where H(k) = sigma(A H(k-1)) + H(k-1) and sigma is ReLU.","qko":"$H^{(k)} = \\sigma(A H^{(k-1)}) + H^{(k-1)}$ 이고 $\\sigma$ 가 **렐루(ReLU)** 일 때 층 $k=2$ 의 출력을 구하세요.","solve":["노드 세 개를 한 줄로 잇고 시작 값을 4, 0, -2 라고 해요.","$A H^{(0)}$ 는 이웃 값의 합이에요. 차례로 0, $4 + (-2) = 2$, 0 이에요.","**렐루(ReLU)**를 씌우면 0, 2, 0 이에요. 여기에 시작 값을 더해요.","$H^{(1)}$ 은 $0 + 4 = 4$, $2 + 0 = 2$, $0 + (-2) = -2$ 예요.","다시 $A H^{(1)}$ 을 구하면 2, $4 + (-2) = 2$, 2 예요. **렐루(ReLU)** 후에도 그대로예요.","$H^{(1)}$ 을 더하면 $2 + 4 = 6$, $2 + 2 = 4$, $2 + (-2) = 0$ 이에요."],"answer":"$H^{(2)}$ 는 6, 4, 0 이에요. 검산은 $\\sigma(AH^{(1)}) + \\sigma(AH^{(0)}) + H^{(0)}$ 로 하면 $2+0+4$, $2+2+0$, $2+0-2$ 로 같아요."},{"kind":"points","head":"계산 문제 다섯 단계","items":["1단계. 그림에서 **인접행렬(Adjacency Matrix)**을 적어요. 이웃 목록부터 쓰면 실수가 줄어요.","2단계. 문제가 정규화하라고 하면 각 행을 그 행의 합으로 나눠요.","3단계. $A H$ 를 계산해요. 성분이 0 아니면 1 이라 사실 덧셈만 하면 돼요.","4단계. **렐루(ReLU)**를 **성분마다** 씌워요. 행 전체를 보고 판단하는 게 아니에요.","5단계. 모델 고유의 항을 더해요. 잔차면 이전 층을, GCNII 면 맨 처음 입력을 더해요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"A GNN layer consists of message computation followed by aggregation over the neighborhood.","ko":"GNN 한 층은 메시지 계산과 이웃에 대한 집계로 이루어진다.","tip":"message computation 과 aggregation 두 단어를 그대로 외워 두세요."},{"kind":"check","q":"**차수(Degree)**가 뜻하는 것은 무엇인가요?","choices":["노드에 붙은 선의 개수","GNN의 층 수","임베딩 벡터의 길이","그래프의 노드 수"],"a":0,"why":"**차수(Degree)**는 이웃 수예요. 이 값이 $c_{ij}$ 를 정하고, 나중에는 **정상 분포(Stationary Distribution)**도 정해요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4082,0.0757],"c":[0,0.0019,0.4491,0.1077],"r":7.4132,"img":"img/L5/walk/p004_h.jpg"},"parts":[{"b":[0.055,0.15,0.22,0.04],"c":[0.043,0.115,0.244,0.11],"r":3.9434,"img":"img/L5/walk/p004_12_01.jpg","say":"맨 위 굵은 줄: 'GNN 층 = 메시지 + 집계'예요."},{"b":[0.012,0.525,0.43,0.18],"c":[0,0.509,0.473,0.212],"r":3.9665,"img":"img/L5/walk/p004_12_02.jpg","say":"왼쪽 빨간 점선 상자가 'GNN Layer 1', 즉 한 층이에요."}]}},{"p":5,"title":"복습: 메시지 계산은 보낼 쪽지 만들기","terms":["Message Passing","Embedding","Aggregation","GCN"],"pass1":[{"kind":"say","lines":["메시지 계산은 '보낼 쪽지를 만드는 단계'예요.","가장 단순한 방법은 내 **임베딩(Embedding)**에 가중치 행렬을 곱하는 것이에요.","아직 보내지도 않았고 섞이지도 않았어요. 만들기만 한 상태예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.05,"y":0.14,"w":0.66,"h":0.04,"say":"'직관: 각 노드는 메시지를 하나 만들고, 그 메시지를 나중에 다른 노드에 보내요.'","c":[0.017,0.0867,0.726,0.1467],"r":8.798,"img":"img/L5/walk/p005_20_01.jpg"},{"x":0.065,"y":0.278,"w":0.4,"h":0.045,"say":"'예: 선형 층'. 가장 단순한 메시지 함수예요.","c":[0.045,0.2455,0.44,0.11],"r":7.1111,"img":"img/L5/walk/p005_20_02.jpg"},{"x":0.105,"y":0.356,"w":0.33,"h":0.038,"say":"'노드 특징에 가중치 행렬을 곱한다'. 이 한 줄이 선형 층의 전부예요.","c":[0.0885,0.32,0.363,0.11],"r":5.8667,"img":"img/L5/walk/p005_20_03.jpg"},{"x":0.29,"y":0.519,"w":0.37,"h":0.06,"say":"'메시지 함수'의 일반형이에요. 위 식은 이것의 가장 쉬운 경우예요.","c":[0.2715,0.494,0.407,0.11],"r":6.5778,"img":"img/L5/walk/p005_20_04.jpg"},{"x":0.229,"y":0.642,"w":0.17,"h":0.3,"say":"왼쪽 아래가 입력 그래프예요. A가 대상 노드예요.","c":[0.214,0.626,0.2,0.332],"r":1.071,"img":"img/L5/walk/p005_20_05.jpg"},{"x":0.472,"y":0.642,"w":0.27,"h":0.3,"say":"오른쪽에서 빨간 점선이 메시지 부분을 감싸고 있어요.","c":[0.4585,0.626,0.297,0.332],"r":1.5904,"img":"img/L5/walk/p005_20_06.jpg"}]},{"kind":"formula","head":"메시지 함수를 기호 하나씩","tex":"\\mathbf{m}_u^{(l)} = \\mathbf{W}^{(l)} \\mathbf{h}_u^{(l-1)}","parts":[{"sym":"\\mathbf{m}_u^{(l)}","say":"노드 $u$ 가 층 $l$ 에서 만든 메시지예요. $u$ 가 쓴 쪽지죠."},{"sym":"\\mathbf{h}_u^{(l-1)}","say":"$u$ 의 **바로 앞 층** **임베딩(Embedding)**이에요."},{"sym":"\\mathbf{W}^{(l)}","say":"층 $l$ 의 학습 가중치 행렬이에요. 생각을 쪽지로 옮기는 번역기예요."},{"sym":"(l)","say":"위첨자는 층 번호예요. 메시지는 층 $l$ 에서 만들되 재료는 층 $l-1$ 것이에요."}],"whole":"우리말로 하면 '지난 층의 내 값에 가중치를 곱해서 이번 층에 보낼 쪽지를 만든다'예요."},{"kind":"steps","head":"메시지 하나를 손으로 만들어 보기","steps":["내 값이 두 칸짜리로 3 과 -1 이라고 해요.","가중치 행렬은 첫 줄이 2 와 0, 둘째 줄이 1 과 1 이에요.","결과의 첫 칸은 $2 \\times 3 + 0 \\times (-1) = 6 + 0 = 6$ 이에요.","결과의 둘째 칸은 $1 \\times 3 + 1 \\times (-1) = 3 - 1 = 2$ 예요."],"answer":"메시지는 6 과 2 예요. 아직 이웃과 섞이지 않았어요. 섞는 것은 다음 슬라이드 일이에요.","given":"노드 $u$ 의 이전 값이 3, -1 이고 가중치가 2x2 행렬이에요."},{"kind":"warn","head":"메시지와 임베딩을 구별하세요","items":["**임베딩(Embedding)**은 노드가 지금 들고 있는 값이에요.","메시지는 그 값을 남에게 보내려고 가공한 것이에요.","그리고 이 단계에는 이웃이 전혀 등장하지 않아요. 섞이는 것은 **집계(Aggregation)**에서예요."]}],"pass3":[{"kind":"check","q":"메시지를 만들 때 쓰는 재료는 무엇인가요?","choices":["같은 층의 이웃 임베딩","바로 앞 층의 내 임베딩","맨 처음 입력 특징","인접행렬"],"a":1,"why":"위첨자가 $(l-1)$ 이에요. 지난 층의 내 값으로 이번 층 쪽지를 써요."},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Each node first computes a message from its own previous-layer embedding.","ko":"각 노드는 먼저 자기 이전 층 임베딩으로부터 메시지를 계산한다.","tip":"previous-layer 라는 표현이 순서를 정확히 말해 줘요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2185,0.0757],"c":[0.0011,0.0019,0.2425,0.1077],"r":4.0029,"img":"img/L5/walk/p005_h.jpg"},"parts":[{"b":[0.05,0.14,0.66,0.04],"c":[0.017,0.0867,0.726,0.1467],"r":8.798,"img":"img/L5/walk/p005_11_01.jpg","say":"맨 위: '각 노드는 메시지를 하나 만들고, 나중에 다른 노드에 보내요.'"},{"b":[0.29,0.519,0.37,0.06],"c":[0.2715,0.494,0.407,0.11],"r":6.5778,"img":"img/L5/walk/p005_11_02.jpg","say":"가운데 굵은 글씨가 '메시지 함수'예요. 쪽지 쓰는 방법 자체를 가리켜요."}]}},{"p":6,"title":"복습: 집계는 걷은 쪽지 합치기","terms":["Aggregation","Over-smoothing","Embedding","Adjacency Matrix","GCN"],"pass1":[{"kind":"say","lines":["**집계(Aggregation)**는 '걷은 쪽지를 하나로 합치는 단계'예요.","합, 평균, 최댓값이 대표적인 합치는 방법이에요.","여기서 미리 알아 둘 것이 있어요. 평균을 반복하면 값들이 가운데로 모여요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.05,"y":0.14,"w":0.5,"h":0.04,"say":"'직관: 각 노드는 노드 v의 이웃들이 보낸 메시지를 모아요.'","c":[0.025,0.1044,0.55,0.1111],"r":8.8009,"img":"img/L5/walk/p006_20_01.jpg"},{"x":0.34,"y":0.259,"w":0.3,"h":0.062,"say":"일반형 식이에요. AGG 라는 빈칸에 합, 평균, 최댓값이 들어가요.","c":[0.325,0.235,0.33,0.11],"r":5.3333,"img":"img/L5/walk/p006_20_02.jpg"},{"x":0.075,"y":0.358,"w":0.38,"h":0.045,"say":"'예: 합, 평균, 최대 집계'. 3주차 표현력 수업에서 본 그 순서예요.","c":[0.056,0.3255,0.418,0.11],"r":6.7556,"img":"img/L5/walk/p006_20_03.jpg"},{"x":0.34,"y":0.475,"w":0.3,"h":0.062,"say":"AGG 자리에 '합'을 넣은 경우예요.","c":[0.325,0.451,0.33,0.11],"r":5.3333,"img":"img/L5/walk/p006_20_04.jpg"},{"x":0.505,"y":0.68,"w":0.16,"h":0.11,"say":"오른쪽에서 빨간 점선이 이번에는 위쪽 집계 상자를 감싸요.","c":[0.485,0.664,0.2,0.142],"r":2.5039,"img":"img/L5/walk/p006_20_05.jpg"}]},{"kind":"formula","head":"집계 식을 기호 하나씩","tex":"\\mathbf{h}_v^{(l)} = \\text{AGG}^{(l)}\\left(\\left\\{ \\mathbf{m}_u^{(l)}, \\; u \\in N(v) \\right\\}\\right)","parts":[{"sym":"\\mathbf{h}_v^{(l)}","say":"노드 $v$ 의 층 $l$ 결과 **임베딩(Embedding)**이에요."},{"sym":"\\text{AGG}^{(l)}","say":"**집계(Aggregation)** 함수의 일반 이름이에요."},{"sym":"\\{ \\cdots \\}","say":"중괄호는 순서 없는 모음이에요. 걷은 쪽지 더미죠."},{"sym":"u \\in N(v)","say":"쪽지를 보낸 사람은 $v$ 의 이웃들이라는 뜻이에요."}],"whole":"들어갈 때는 메시지 $\\mathbf{m}$ 인데 나올 때는 **임베딩(Embedding)** $\\mathbf{h}$ 예요. 이 한 번의 변신이 GNN 한 층의 전부예요."},{"kind":"figure","head":"같은 쪽지 더미, 세 가지 요약 방법","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<circle class=\"n\" cx=\"50\" cy=\"60\" r=\"18\"/>\n<circle class=\"n\" cx=\"50\" cy=\"130\" r=\"18\"/>\n<circle class=\"n\" cx=\"50\" cy=\"200\" r=\"18\"/>\n<text class=\"tl\" x=\"50\" y=\"66\" font-size=\"14\" text-anchor=\"middle\">u<\/text>\n<text class=\"tl\" x=\"50\" y=\"136\" font-size=\"14\" text-anchor=\"middle\">w<\/text>\n<text class=\"tl\" x=\"50\" y=\"206\" font-size=\"14\" text-anchor=\"middle\">x<\/text>\n<text class=\"t\" x=\"110\" y=\"66\" font-size=\"14\" text-anchor=\"middle\">6, 2<\/text>\n<text class=\"t\" x=\"110\" y=\"136\" font-size=\"14\" text-anchor=\"middle\">2, 3<\/text>\n<text class=\"t\" x=\"110\" y=\"206\" font-size=\"14\" text-anchor=\"middle\">0, 4<\/text>\n<line class=\"e2 b1\" x1=\"140\" y1=\"62\" x2=\"186\" y2=\"110\"/>\n<line class=\"e2 b1\" x1=\"140\" y1=\"132\" x2=\"186\" y2=\"130\"/>\n<line class=\"e2 b1\" x1=\"140\" y1=\"202\" x2=\"186\" y2=\"150\"/>\n<rect class=\"box2 b1\" x=\"188\" y=\"102\" width=\"62\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b1\" x=\"219\" y=\"136\" font-size=\"15\" text-anchor=\"middle\">집계<\/text>\n<rect class=\"box b2\" x=\"286\" y=\"44\" width=\"176\" height=\"36\" rx=\"7\"/>\n<text class=\"t b2\" x=\"374\" y=\"67\" font-size=\"14\" text-anchor=\"middle\">합: 8, 9  개수까지 기억<\/text>\n<rect class=\"box b3\" x=\"286\" y=\"112\" width=\"176\" height=\"36\" rx=\"7\"/>\n<text class=\"t b3\" x=\"374\" y=\"135\" font-size=\"14\" text-anchor=\"middle\">평균: 2.67, 3  비율만<\/text>\n<rect class=\"box b4\" x=\"286\" y=\"180\" width=\"176\" height=\"36\" rx=\"7\"/>\n<text class=\"t b4\" x=\"374\" y=\"203\" font-size=\"14\" text-anchor=\"middle\">최댓값: 6, 4  큰 값만<\/text>\n<text class=\"tm b4\" x=\"240\" y=\"248\" font-size=\"14\" text-anchor=\"middle\">평균을 반복하는 것이 과도한 평활화의 씨앗이에요<\/text>\n<\/svg>","caption":"합은 몇 명이 보냈는지까지 남아요. 평균과 최댓값은 개수를 잊어버려요. 평균을 반복하는 것이 **과도한 평활화(Over-smoothing)**의 씨앗이에요.","builds":4},{"kind":"steps","head":"세 가지 집계를 나란히 계산","steps":["이웃 셋의 메시지가 6과 2, 2와 3, 0과 4 예요.","합은 첫 칸 $6 + 2 + 0 = 8$, 둘째 칸 $2 + 3 + 4 = 9$ 예요.","평균은 그 합을 3 으로 나눠요. $8 \\div 3 \\approx 2.667$, $9 \\div 3 = 3$ 이에요.","최댓값은 각 칸에서 가장 큰 값 하나를 골라요. 6 과 4 예요."],"answer":"합은 8과 9, 평균은 약 2.667과 3, 최댓값은 6과 4 예요. 셋이 서로 다른 답을 내요.","given":"노드 $v$ 의 이웃이 셋이고 각자 두 칸짜리 메시지를 보냈어요."},{"kind":"mining","src":"마이닝 2강 Representation of Graphs and Storage","lines":["합 집계는 **인접행렬(Adjacency Matrix)** 곱 $A H$ 한 줄로 쓸 수 있어요.","$A$ 의 $i$ 번째 행과 $H$ 를 곱하면 그게 곧 노드 $i$ 이웃들의 특징 합이거든요.","그래서 시험 계산 문제가 거의 전부 $\\sigma(A H)$ 모양이에요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"Sum aggregation keeps the size of the neighborhood, while mean and max discard it.","ko":"합 집계는 이웃의 개수 정보를 남기지만 평균과 최댓값은 그것을 버린다.","tip":"keeps 와 discard 를 대비시키면 문장이 깔끔해져요."},{"kind":"check","q":"평균 **집계(Aggregation)**를 계속 반복하면 어떻게 되나요?","choices":["값들이 점점 커져요","값들이 서로 비슷해져요","값들이 서로 멀어져요","아무 변화가 없어요"],"a":1,"why":"평균은 가운데로 모으는 연산이에요. 반복하면 **과도한 평활화(Over-smoothing)**가 돼요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2185,0.0757],"c":[0.0011,0.0019,0.2425,0.1077],"r":4.0029,"img":"img/L5/walk/p006_h.jpg"},"parts":[{"b":[0.05,0.14,0.5,0.04],"c":[0.025,0.1044,0.55,0.1111],"r":8.8009,"img":"img/L5/walk/p006_11_01.jpg","say":"맨 위: '각 노드는 노드 v의 이웃들이 보낸 메시지를 모아요.'"},{"b":[0.075,0.358,0.38,0.045],"c":[0.056,0.3255,0.418,0.11],"r":6.7556,"img":"img/L5/walk/p006_11_02.jpg","say":"'예: 합, 평균, 최대 집계'. 합치는 방법이 여러 가지예요."}]}},{"p":7,"title":"복습: 이웃만 모으면 내가 사라진다","terms":["Aggregation","Concatenation","Residual Connection","Self-loop","Embedding"],"pass1":[{"kind":"say","lines":["이웃 것만 모으면 **내 정보가 사라져요**.","그래서 내 메시지도 따로 만들어서 마지막에 합쳐 줘요.","합치는 방법이 두 가지예요. **이어 붙이기(Concatenation)** 아니면 더하기예요."]},{"kind":"analogy","head":"내 의견을 빠뜨린 회의록","scene":"반장이 친구 세 명의 의견을 걷어 회의록을 썼어요. 그런데 다 쓰고 보니 정작 반장 자기 의견이 한 줄도 없어요. 다음 회의 때는 '내 의견'이라는 칸을 따로 만들어 두기로 했죠. 칸을 따로 두면 섞이지 않고 남아요.","map":[["친구 세 명의 의견","이웃 메시지"],["빠진 내 의견","$v$ 자신의 이전 **임베딩(Embedding)**"],["칸을 따로 만들기","**이어 붙이기(Concatenation)**"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"formula","head":"합치는 식을 기호 하나씩","tex":"\\mathbf{h}_v^{(l)} = \\text{CONCAT}\\left( \\text{AGG}\\left(\\left\\{ \\mathbf{m}_u^{(l)} \\right\\}\\right), \\; \\mathbf{m}_v^{(l)} \\right)","parts":[{"sym":"\\text{CONCAT}","say":"**이어 붙이기(Concatenation)**예요. 종이 두 장을 나란히 붙이는 일이에요."},{"sym":"\\text{AGG}(\\{\\mathbf{m}_u\\})","say":"첫째 칸이에요. 이웃들 쪽지를 합친 결과죠."},{"sym":"\\mathbf{m}_v^{(l)}","say":"둘째 칸이에요. 내가 나에게 쓴 메시지예요."},{"sym":"\\mathbf{B}^{(l)}","say":"내 정보 전용 가중치예요. 이웃용 $\\mathbf{W}$ 와 따로 배워요."}],"whole":"이웃 먼저 모으고, 그다음 나를 붙여요. 순서가 정해져 있어요."},{"kind":"figure","head":"내 정보를 넣을 때와 넣지 않을 때","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"112\" y=\"30\" font-size=\"15\" text-anchor=\"middle\">이웃만 모을 때<\/text>\n<text class=\"tb\" x=\"352\" y=\"30\" font-size=\"15\" text-anchor=\"middle\">나까지 넣을 때<\/text>\n<circle class=\"n\" cx=\"34\" cy=\"70\" r=\"15\"/>\n<circle class=\"n\" cx=\"34\" cy=\"116\" r=\"15\"/>\n<circle class=\"n\" cx=\"34\" cy=\"162\" r=\"15\"/>\n<circle class=\"n2\" cx=\"34\" cy=\"212\" r=\"15\"/>\n<text class=\"tl\" x=\"34\" y=\"217\" font-size=\"13\" text-anchor=\"middle\">v<\/text>\n<line class=\"e2\" x1=\"50\" y1=\"74\" x2=\"86\" y2=\"106\"/>\n<line class=\"e2\" x1=\"50\" y1=\"116\" x2=\"86\" y2=\"120\"/>\n<line class=\"e2\" x1=\"50\" y1=\"158\" x2=\"86\" y2=\"134\"/>\n<rect class=\"box\" x=\"88\" y=\"94\" width=\"52\" height=\"52\" rx=\"7\"/>\n<text class=\"t\" x=\"114\" y=\"126\" font-size=\"14\" text-anchor=\"middle\">집계<\/text>\n<text class=\"t b1\" x=\"112\" y=\"176\" font-size=\"14\" text-anchor=\"middle\">결과 8, 9<\/text>\n<text class=\"tm b1\" x=\"112\" y=\"248\" font-size=\"13\" text-anchor=\"middle\">v 의 원래 값이 없어요<\/text>\n<circle class=\"n\" cx=\"274\" cy=\"70\" r=\"15\"/>\n<circle class=\"n\" cx=\"274\" cy=\"116\" r=\"15\"/>\n<circle class=\"n\" cx=\"274\" cy=\"162\" r=\"15\"/>\n<circle class=\"n2\" cx=\"274\" cy=\"212\" r=\"15\"/>\n<text class=\"tl\" x=\"274\" y=\"217\" font-size=\"13\" text-anchor=\"middle\">v<\/text>\n<line class=\"e2\" x1=\"290\" y1=\"74\" x2=\"326\" y2=\"106\"/>\n<line class=\"e2\" x1=\"290\" y1=\"116\" x2=\"326\" y2=\"120\"/>\n<line class=\"e2\" x1=\"290\" y1=\"158\" x2=\"326\" y2=\"134\"/>\n<rect class=\"box\" x=\"328\" y=\"94\" width=\"52\" height=\"52\" rx=\"7\"/>\n<text class=\"t\" x=\"354\" y=\"126\" font-size=\"14\" text-anchor=\"middle\">집계<\/text>\n<line class=\"e2 b2\" x1=\"290\" y1=\"206\" x2=\"406\" y2=\"152\"/>\n<text class=\"t b2\" x=\"360\" y=\"186\" font-size=\"14\" text-anchor=\"middle\">결과 9, 11<\/text>\n<text class=\"tm b2\" x=\"360\" y=\"248\" font-size=\"13\" text-anchor=\"middle\">v 의 1, 2 가 더해졌어요<\/text>\n<\/svg>","caption":"이웃만 모으면 $v$ 의 원래 값이 어디에도 없어요. 나를 넣으면 남아요. 이 생각이 나중에 **잔차 연결(Residual Connection)**로 다시 나와요.","builds":2},{"kind":"steps","head":"이어 붙이기와 더하기를 비교","steps":["이웃 집계 결과가 8 과 9 라고 해요.","내 이전 값이 1 과 1 이고 내 전용 가중치를 곱하면 1 과 2 가 나와요.","**이어 붙이기(Concatenation)**를 하면 8, 9, 1, 2 로 네 칸이 돼요.","더하기를 하면 $8 + 1 = 9$, $9 + 2 = 11$ 로 두 칸 그대로예요."],"answer":"이어 붙이기는 길지만 내 것과 이웃 것을 구별할 수 있어요. 더하기는 짧지만 섞여요.","given":"이웃 집계 결과 8, 9 와 내 메시지 1, 2 를 합쳐요."},{"kind":"warn","head":"자기 고리와 헷갈리지 마세요","items":["내 정보를 넣는 방법이 두 가지예요.","하나는 이 슬라이드처럼 전용 가중치 $\\mathbf{B}$ 를 두고 따로 합치는 방법이에요.","다른 하나는 **자기 고리(Self-loop)**를 넣어 $\\tilde{A} = A + I$ 로 만드는 방법이에요.","**자기 고리(Self-loop)**를 쓰면 나와 이웃에 같은 가중치가 걸려서 구별하는 힘이 약해져요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"The self representation is concatenated with the aggregated neighbor representation.","ko":"자기 표현은 집계된 이웃 표현과 이어 붙여진다.","tip":"concatenated with 라는 짝을 통째로 외워 두세요."},{"kind":"check","q":"**이어 붙이기(Concatenation)**를 하면 벡터 길이가 어떻게 되나요?","choices":["그대로예요","길어져요","짧아져요","1이 돼요"],"a":1,"why":"8, 9 와 1, 2 를 붙이면 네 칸이 돼요. 대신 내 것과 이웃 것이 섞이지 않아요."},{"kind":"points","head":"이 슬라이드가 5주차에서 중요한 이유","items":["**잔차 연결(Residual Connection)**은 여기서 배운 '더하기' 방식의 확장이에요.","다만 차이가 하나 있어요. 잔차는 가중치 없이 **그대로** 더해요.","가중치가 없으니 원래 값이 손상 없이 다음 층까지 전달돼요.","그래서 기울기도 살아남고 원래 특징도 살아남아요. p.41 에서 다시 만나요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.3266,0.0757],"c":[0,0.0019,0.3593,0.1077],"r":5.9309,"img":"img/L5/walk/p007_h.jpg"},"parts":[{"b":[0.05,0.136,0.45,0.042],"c":[0.0275,0.102,0.495,0.11],"r":8.0,"img":"img/L5/walk/p007_20_01.jpg","say":"'문제: 노드 v 자신의 정보가 사라질 수 있다.'"},{"b":[0.07,0.204,0.48,0.045],"c":[0.046,0.1715,0.528,0.11],"r":8.5333,"img":"img/L5/walk/p007_20_02.jpg","say":"'다음 값의 계산은 이전 값에 직접 의존하지 않는다.'"},{"b":[0.05,0.333,0.47,0.052],"c":[0.0265,0.304,0.517,0.11],"r":8.3556,"img":"img/L5/walk/p007_20_03.jpg","say":"'해법: 다음을 포함. 이전 내 값을 계산에 넣는다.'"},{"b":[0.075,0.414,0.48,0.04],"c":[0.051,0.379,0.528,0.11],"r":8.5333,"img":"img/L5/walk/p007_20_04.jpg","say":"'(1) 메시지: 노드 v 자신에게서도 메시지를 만든다.'"},{"b":[0.27,0.475,0.44,0.048],"c":[0.248,0.444,0.484,0.11],"r":7.8222,"img":"img/L5/walk/p007_20_05.jpg","say":"왼쪽은 이웃용 가중치 W, 오른쪽은 내 전용 가중치 B 예요. 기호가 달라요."},{"b":[0.28,0.722,0.42,0.11],"c":[0.259,0.706,0.462,0.142],"r":5.784,"img":"img/L5/walk/p007_20_06.jpg","say":"맨 아래 식이 CONCAT 이에요. 이웃 먼저 모으고 나를 나중에 붙여요."}]}},{"p":8,"title":"영상에서는 깊을수록 좋았다","terms":["CNN","Receptive Field","Depth","Residual Connection"],"pass1":[{"kind":"say","lines":["먼저 그래프가 아니라 영상 이야기부터 봐요.","영상 인식에서는 층을 깊게 쌓을수록 **수용 영역(Receptive Field)**이 넓어지고 성능이 좋아졌어요.","**수용 영역(Receptive Field)**은 '출력 한 칸을 만드는 데 영향을 준 입력의 범위'예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.055,"y":0.14,"w":0.42,"h":0.04,"say":"'컴퓨터 비전에서 깊은 DNN이 거둔 전례 없는 성공.'","c":[0.034,0.105,0.462,0.11],"r":7.4667,"img":"img/L5/walk/p008_20_01.jpg"},{"x":0.055,"y":0.206,"w":0.42,"h":0.04,"say":"'더 깊은 DNN은 더 넓은 수용 영역을 만든다.' 이 줄이 핵심이에요.","c":[0.034,0.171,0.462,0.11],"r":7.4667,"img":"img/L5/walk/p008_20_02.jpg"},{"x":0.069,"y":0.321,"w":0.48,"h":0.494,"say":"왼쪽 막대그래프. 연도별 오류율이에요. 주황 점선은 층 수예요.","c":[0.045,0.2963,0.528,0.5434],"r":1.7274,"img":"img/L5/walk/p008_20_03.jpg"},{"x":0.7,"y":0.2,"w":0.15,"h":0.65,"say":"오른쪽 세 장. 아래는 단순한 줄무늬, 위로 갈수록 알아볼 수 있는 모양이에요.","c":[0.636,0.1675,0.2781,0.715],"r":0.6915,"img":"img/L5/walk/p008_20_04.jpg"},{"x":0.865,"y":0.29,"w":0.055,"h":0.045,"say":"맨 위가 '층 3'. 깊을수록 더 크고 의미 있는 것을 봐요.","c":[0.7925,0.2575,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p008_20_05.jpg"}]},{"kind":"compare","head":"연도별 오류율과 층 수","cols":["연도와 모델","오류율","층 수"],"rows":[["2010 얕은 모델","28.2","얕음"],["2012 AlexNet","16.4","8"],["2014 VGG","7.3","19"],["2015 ResNet","3.57","152"]]},{"kind":"figure","head":"격자에서 수용 영역이 커지는 속도","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<rect class=\"box\" x=\"20\" y=\"50\" width=\"120\" height=\"120\" rx=\"4\"/>\n<rect class=\"box2 b1\" x=\"56\" y=\"86\" width=\"48\" height=\"48\" rx=\"3\"/>\n<rect class=\"n2 b1\" x=\"72\" y=\"102\" width=\"16\" height=\"16\"/>\n<text class=\"tb\" x=\"80\" y=\"36\" font-size=\"14\" text-anchor=\"middle\">1층: 9칸<\/text>\n<rect class=\"box\" x=\"180\" y=\"50\" width=\"120\" height=\"120\" rx=\"4\"/>\n<rect class=\"box2 b2\" x=\"204\" y=\"74\" width=\"72\" height=\"72\" rx=\"3\"/>\n<rect class=\"n2 b2\" x=\"232\" y=\"102\" width=\"16\" height=\"16\"/>\n<text class=\"tb\" x=\"240\" y=\"36\" font-size=\"14\" text-anchor=\"middle\">2층: 25칸<\/text>\n<rect class=\"box\" x=\"340\" y=\"50\" width=\"120\" height=\"120\" rx=\"4\"/>\n<rect class=\"box2 b3\" x=\"352\" y=\"62\" width=\"96\" height=\"96\" rx=\"3\"/>\n<rect class=\"n2 b3\" x=\"392\" y=\"102\" width=\"16\" height=\"16\"/>\n<text class=\"tb\" x=\"400\" y=\"36\" font-size=\"14\" text-anchor=\"middle\">3층: 49칸<\/text>\n<text class=\"tb b4\" x=\"240\" y=\"212\" font-size=\"15\" text-anchor=\"middle\">격자에서는 층 수의 제곱으로만 커져요<\/text>\n<text class=\"tm b4\" x=\"240\" y=\"238\" font-size=\"14\" text-anchor=\"middle\">그래프에서는 지수로 커져요. 이 차이가 전부예요<\/text>\n<\/svg>","caption":"**CNN**에서는 층 하나에 반경이 1 씩 커져요. 칸 수는 그 제곱이에요. 천천히 커지죠.","builds":4},{"kind":"steps","head":"층 수에 따른 수용 영역 크기","steps":["3x3 필터를 쓰면 한 층에 각 방향으로 1 칸씩 더 멀리 봐요.","1층은 반경 1, 즉 3x3 = 9 칸이에요.","2층은 반경 2, 즉 5x5 = 25 칸이에요.","3층은 반경 3, 즉 7x7 = 49 칸이에요.","10층은 반경 10, 즉 21x21 = 441 칸이에요."],"answer":"층 10 개로도 224x224 그림의 약 1퍼센트예요. 그래서 **CNN**은 깊게 쌓아도 남는 게 있어요.","given":"3x3 필터를 쓰는 **CNN** 층을 쌓아요."},{"kind":"warn","head":"깊게 쌓기가 저절로 된 것은 아니에요","items":["2014년까지는 20층이 넘으면 오히려 성능이 떨어졌어요.","그걸 뚫은 것이 2015년 ResNet 의 **잔차 연결(Residual Connection)**이에요.","$y = F(x) + x$ 로 원래 입력을 그대로 더해 주면 정보가 끊기지 않아요.","이 아이디어를 그래프로 옮긴 것이 p.41 의 처방이에요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"In vision the receptive field of a CNN grows only quadratically with the number of layers.","ko":"비전에서는 CNN의 수용 영역이 층 수의 제곱으로만 커진다.","tip":"quadratically 가 뒤에 나올 exponentially 와 대비되는 단어예요."},{"kind":"check","q":"**수용 영역(Receptive Field)**이 뜻하는 것은 무엇인가요?","choices":["신경망의 층 수","출력 한 칸에 영향을 준 입력의 범위","임베딩 벡터의 길이","학습률"],"a":1,"why":"출력 한 칸을 만드는 데 관여한 입력의 범위예요. 오늘 하루 종일 쓰는 단어예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.9047,0.3011],"c":[0,0.0019,0.9951,0.3331],"r":5.3109,"img":"img/L5/walk/p008_h.jpg"},"parts":[{"b":[0.069,0.321,0.48,0.494],"c":[0.045,0.2963,0.528,0.5434],"r":1.7274,"img":"img/L5/walk/p008_11_01.jpg","say":"막대가 오류율이에요. 낮을수록 좋아요. 왼쪽 28.2 에서 오른쪽 3.57 로 떨어져요."},{"b":[0.455,0.37,0.115,0.045],"c":[0.4125,0.3375,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p008_11_02.jpg","say":"주황 네모 안에 '152 layers'. 2015년 ResNet 이 152층이에요."}]}},{"p":9,"title":"GNN의 힘은 깊이 곱하기 너비","terms":["Expressive Power","Depth","Width","Over-smoothing","Under-reaching"],"pass1":[{"kind":"say","lines":["GNN의 **표현력(Expressive Power)**을 정하는 것은 두 가지예요.","**깊이(Depth)**, 즉 층 수와 **너비(Width)**, 즉 벡터 길이예요.","중요한 건 각각이 아니라 **둘의 곱**이에요. 이걸 용량이라고 불러요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.055,"y":0.132,"w":0.54,"h":0.04,"say":"'GNN도 더 넓은 수용 영역을 얻으려면 더 깊은 구조가 필요할까요?'","c":[0.028,0.092,0.594,0.12],"r":8.8,"img":"img/L5/walk/p009_20_01.jpg"},{"x":0.055,"y":0.183,"w":0.37,"h":0.04,"say":"'GNN의 표현력을 제한하는 것은 무엇일까요?'","c":[0.0365,0.148,0.407,0.11],"r":6.5778,"img":"img/L5/walk/p009_20_02.jpg"},{"x":0.09,"y":0.238,"w":0.1,"h":0.038,"say":"답 하나: '깊이 d'. 층이 몇 개인가예요.","c":[0.04,0.202,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p009_20_03.jpg"},{"x":0.09,"y":0.293,"w":0.1,"h":0.038,"say":"답 둘: '너비 w'. 임베딩 벡터가 몇 칸인가예요.","c":[0.04,0.257,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p009_20_04.jpg"},{"x":0.055,"y":0.343,"w":0.43,"h":0.042,"say":"'용량 dw 가 제한되면 GNN은 힘을 크게 잃는다.' 곱이라는 점이 핵심이에요.","c":[0.0335,0.309,0.473,0.11],"r":7.6444,"img":"img/L5/walk/p009_20_05.jpg"}]},{"kind":"points","head":"세 문제의 공통점을 찾아보세요","items":["최단 경로는 두 노드 사이 모든 길을 따져야 해요.","사이클 탐지는 멀리 돌아오는 고리까지 봐야 해요.","부분그래프 찾기는 흩어진 노드들이 어떤 모양을 이루는지 봐야 해요.","셋 다 **그래프 전체**를 봐야 풀리는 문제예요. 그래서 큰 용량이 필요해요."]},{"kind":"compare","head":"용량을 채우는 두 가지 방법","cols":["무엇을 늘리나","용량 $dw$","파라미터 수","생기는 부작용"],"rows":[["**깊이(Depth)**를 2배","2배","2배","평활화와 **기울기 소실(Vanishing Gradient)**"],["**너비(Width)**를 2배","2배","4배","**과적합(Overfitting)**과 메모리 폭발"]]},{"kind":"steps","head":"전역 문제를 풀려면 얼마나 필요할까","steps":["용량 $dw$ 가 노드 수 $N$ 정도는 되어야 한다고 해요.","**과도한 평활화(Over-smoothing)**를 피하려고 **깊이(Depth)**를 3 으로 묶어요.","노드가 1,000 개면 **너비(Width)**가 약 $1000 \\div 3 \\approx 333$ 이어야 해요.","노드가 10,000 개면 약 3,333 이어야 해요.","노드가 100,000 개면 약 33,333 이어야 해요."],"answer":"가중치 행렬이 너비의 제곱이라, 노드 10만 개면 층 하나에 파라미터가 11억 개예요. 현실적이지 않아요.","given":"깊이를 작게 고정하고 너비만 키워 보는 계산이에요."},{"kind":"warn","head":"이 표는 크기 감각을 잡기 위한 예시예요","items":["Loukas 의 정리에 나오는 정확한 상수와 로그 항까지 옮긴 것은 아니에요.","시험에서는 '**깊이(Depth)**와 **너비(Width)**의 **곱**이 그래프 크기에 따라 커져야 한다'만 정확히 쓰면 돼요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"The expressive power of a message-passing GNN is governed by the product of its depth and width.","ko":"메시지 패싱 GNN의 표현력은 깊이와 너비의 곱으로 결정된다.","tip":"the product of its depth and width 가 채점 포인트예요."},{"kind":"check","q":"GNN의 **표현력(Expressive Power)**을 정하는 것은 무엇인가요?","choices":["깊이만","너비만","깊이와 너비의 곱","학습률과 배치 크기"],"a":2,"why":"각각이 아니라 곱이에요. 그래서 한쪽만 키워서는 해결되지 않아요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5762,0.3742],"c":[0,0,0.6338,0.4117],"r":2.7368,"img":"img/L5/walk/p009_h.jpg"},"parts":[{"b":[0.142,0.448,0.188,0.4],"c":[0.13,0.428,0.212,0.44],"r":0.8566,"img":"img/L5/walk/p009_11_01.jpg","say":"'Shortest Path'. 두 노드 사이 가장 짧은 길 찾기예요."},{"b":[0.335,0.448,0.274,0.4],"c":[0.3213,0.428,0.3014,0.44],"r":1.2178,"img":"img/L5/walk/p009_11_02.jpg","say":"'Cycle Detection'. 그래프 안에 고리가 있는지 찾기예요."},{"b":[0.615,0.448,0.241,0.4],"c":[0.603,0.428,0.2651,0.44],"r":1.0711,"img":"img/L5/walk/p009_11_03.jpg","say":"'Subgraph'. 특정 모양이 들어 있는지 찾기예요."}]}},{"p":10,"title":"복습: CNN은 자리마다 가중치가 다르다","terms":["CNN","GCN","Aggregation","ReLU"],"pass1":[{"kind":"say","lines":["**CNN** 한 층은 3x3 안의 아홉 칸에 **각각 다른 가중치**를 곱해서 더해요.","'각각 다른'이 중요해요. 왼쪽에서 온 정보와 오른쪽에서 온 정보를 구별할 수 있거든요.","그래프에는 왼쪽 오른쪽이 없어서 이렇게 할 수가 없어요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.055,"y":0.146,"w":0.27,"h":0.042,"say":"'3x3 필터를 쓴 CNN 한 층'이 이 슬라이드의 주제예요.","c":[0.0415,0.112,0.297,0.11],"r":4.8,"img":"img/L5/walk/p010_20_01.jpg"},{"x":0.069,"y":0.315,"w":0.223,"h":0.352,"say":"왼쪽 애니메이션. 파란 격자 9칸이 초록 격자 1칸을 만들어요.","c":[0.057,0.2974,0.247,0.3872],"r":1.1341,"img":"img/L5/walk/p010_20_02.jpg"},{"x":0.306,"y":0.321,"w":0.194,"h":0.296,"say":"가운데 원 아홉 개. 들어오는 화살표 색이 전부 달라요.","c":[0.294,0.305,0.218,0.328],"r":1.1816,"img":"img/L5/walk/p010_20_03.jpg"},{"x":0.531,"y":0.4,"w":0.33,"h":0.06,"say":"'메시지를 각각 변환'. 아래첨자가 W 에도 붙어 있어요.","c":[0.5145,0.375,0.363,0.11],"r":5.8667,"img":"img/L5/walk/p010_20_04.jpg"},{"x":0.531,"y":0.47,"w":0.29,"h":0.055,"say":"'전부 더하기'. 변환한 다음 모두 합쳐요.","c":[0.5165,0.4425,0.319,0.11],"r":5.1556,"img":"img/L5/walk/p010_20_05.jpg"},{"x":0.17,"y":0.8,"w":0.51,"h":0.07,"say":"맨 아래 전체 갱신 식이에요. 가운데 픽셀이 4번이에요.","c":[0.1445,0.7783,0.561,0.1133],"r":8.8026,"img":"img/L5/walk/p010_20_06.jpg"}]},{"kind":"formula","head":"전체 갱신 식을 기호 하나씩","tex":"\\mathbf{h}_4^{(l+1)} = \\sigma\\left( \\mathbf{W}_0^{(l)}\\mathbf{h}_0^{(l)} + \\mathbf{W}_1^{(l)}\\mathbf{h}_1^{(l)} + \\cdots + \\mathbf{W}_8^{(l)}\\mathbf{h}_8^{(l)} \\right)","parts":[{"sym":"\\mathbf{h}_4","say":"가운데 픽셀이에요. 3x3 을 0부터 8까지 세면 가운데가 4번이에요."},{"sym":"\\mathbf{h}_0 \\cdots \\mathbf{h}_8","say":"나와 여덟 이웃, 모두 아홉 칸이에요."},{"sym":"\\mathbf{W}_0 \\cdots \\mathbf{W}_8","say":"**자리마다 다른** 가중치 아홉 개예요. 이 점이 핵심이에요."},{"sym":"\\sigma","say":"비선형 함수, 보통 **렐루(ReLU)**예요."}],"whole":"우리말로 하면 '나와 여덟 이웃 각각에 그 자리 전용 가중치를 곱해 전부 더한 뒤 **렐루(ReLU)**를 통과시킨다'예요."},{"kind":"steps","head":"한 줄짜리 필터로 손계산","steps":["세 칸짜리 값이 2, 5, 1 이고 가중치가 1, -2, 3 이라고 해요.","첫째 항은 $1 \\times 2 = 2$ 예요.","둘째 항은 $-2 \\times 5 = -10$ 이에요.","셋째 항은 $3 \\times 1 = 3$ 이에요.","합은 $2 - 10 + 3 = -5$ 예요.","**렐루(ReLU)**를 씌우면 음수라서 0 이 돼요."],"answer":"가운데 칸의 다음 값은 0 이에요. 가중치가 자리마다 달라서 왼쪽 이웃과 오른쪽 이웃이 다르게 기여했어요.","given":"1차원으로 줄인 세 칸짜리 필터예요."},{"kind":"warn","head":"아래첨자 i 를 오해하지 마세요","items":["$\\mathbf{W}_i$ 의 $i$ 는 노드 번호가 아니라 **필터 안의 자리 번호**예요.","이미지의 모든 위치에서 같은 아홉 개 가중치를 돌려 써요. 이것을 가중치 공유라고 불러요.","**CNN**은 위치 사이에서는 공유하고 자리 사이에서는 공유하지 않아요. **GCN**은 둘 다 공유해요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"A CNN assigns a distinct weight matrix to each of the nine fixed positions in its kernel.","ko":"CNN은 커널의 고정된 아홉 자리마다 서로 다른 가중치 행렬을 배정한다.","tip":"distinct 와 fixed positions 가 GCN 과의 대비를 만들어 줘요."},{"kind":"check","q":"**CNN**에서 가중치가 자리마다 다른 덕분에 얻는 것은 무엇인가요?","choices":["계산이 빨라져요","왼쪽 이웃과 오른쪽 이웃을 구별할 수 있어요","메모리를 아껴요","층을 더 쌓을 수 있어요"],"a":1,"why":"자리가 정해져 있으니 방향을 구별해요. 그래프에는 자리가 없어서 이게 안 돼요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2993,0.1748],"c":[0,0.0019,0.3293,0.2068],"r":2.8309,"img":"img/L5/walk/p010_h.jpg"},"parts":[{"b":[0.306,0.321,0.194,0.296],"c":[0.294,0.305,0.218,0.328],"r":1.1816,"img":"img/L5/walk/p010_11_01.jpg","say":"원 아홉 개로 들어오는 화살표 색이 전부 달라요."},{"b":[0.531,0.4,0.33,0.06],"c":[0.5145,0.375,0.363,0.11],"r":5.8667,"img":"img/L5/walk/p010_11_02.jpg","say":"'메시지를 각각 변환'. 이웃마다 전용 가중치가 있다는 뜻이에요."}]}},{"p":11,"title":"복습: 그래프는 이웃을 먼저 정해야 한다","terms":["CNN","GCN","Aggregation","Over-smoothing"],"pass1":[{"kind":"say","lines":["**CNN**과 **GCN**의 결정적 차이는 '이웃을 어떻게 정하느냐'예요.","격자는 이웃이 저절로 아홉 칸으로 정해져요.","그래프는 노드마다 이웃 수가 달라서 먼저 이웃을 정의해야 해요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.055,"y":0.144,"w":0.52,"h":0.04,"say":"'CNN과 GCN의 핵심 차이는 합성곱을 어떻게 계산하느냐예요.'","c":[0.029,0.1062,0.572,0.1156],"r":8.7966,"img":"img/L5/walk/p011_20_01.jpg"},{"x":0.055,"y":0.211,"w":0.6,"h":0.04,"say":"'CNN에서는 정해진 커널 크기로 격자 위 이웃과 그냥 합성곱을 해요.'","c":[0.025,0.1643,0.66,0.1333],"r":8.8022,"img":"img/L5/walk/p011_20_02.jpg"},{"x":0.055,"y":0.278,"w":0.89,"h":0.068,"say":"'그래프에서는 먼저 이웃을 정의한 다음 그 이웃 안에서 합성곱을 해요.'","c":[0.0105,0.2131,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p011_20_03.jpg"},{"x":0.06,"y":0.386,"w":0.32,"h":0.042,"say":"'그러면 깊은 GCN은 어디에 있을까요?' 이것이 오늘의 질문이에요.","c":[0.044,0.352,0.352,0.11],"r":5.6889,"img":"img/L5/walk/p011_20_04.jpg"},{"x":0.222,"y":0.469,"w":0.18,"h":0.3,"say":"왼쪽 격자. 가운데 빨간 점 주위 여덟 칸이 노란색이에요. 늘 아홉 칸이에요.","c":[0.21,0.453,0.204,0.332],"r":1.0924,"img":"img/L5/walk/p011_20_05.jpg"},{"x":0.597,"y":0.469,"w":0.14,"h":0.3,"say":"오른쪽 그래프. 점선 동심원이 홉 거리예요. 이웃 수가 노드마다 달라요.","c":[0.567,0.453,0.2,0.332],"r":1.071,"img":"img/L5/walk/p011_20_06.jpg"}]},{"kind":"compare","head":"두 식을 나란히 놓고 비교","cols":["항목","**CNN**","**GCN**"],"rows":[["더하는 범위","격자의 고정된 아홉 자리","$v$ 의 이웃들, 개수가 제각각"],["가중치","자리마다 다름","하나를 모두가 공유"],["내 항","가운데 자리에 이미 포함","따로 떼어 더함"]]},{"kind":"steps","head":"가중치를 공유하면 무슨 일이 생기나","steps":["이웃 셋의 값이 6, 2, 1 이고 내 값이 3 이라고 해요.","**CNN**처럼 자리마다 다른 가중치 2, -1, 3 과 내 가중치 1 을 쓰면 결과는 다음과 같아요.","$2 \\times 6 + (-1) \\times 2 + 3 \\times 1 + 1 \\times 3 = 12 - 2 + 3 + 3 = 16$ 이에요.","**GCN**처럼 전부 1 을 공유하면 $6 + 2 + 1 + 3 = 12$ 예요.","12 는 네 값의 단순 합이에요. 평균으로 보면 $12 \\div 4 = 3$ 이고요."],"answer":"**GCN**은 이웃 값이 6, 2, 1 이든 1, 2, 6 이든 똑같이 12 로 봐요. 순서를 구별하지 않아요.","given":"노드 $v$ 의 이웃이 셋이고 값이 6, 2, 1 이에요. 내 값은 3 이에요."},{"kind":"warn","head":"슬라이드의 이 한 줄은 일반 그래프에는 맞지 않아요","items":["'가장 가까운 k개 이웃을 찾아서 한다'고 적혀 있는데, 보통 그래프는 이웃이 엣지로 이미 주어져 있어요.","k개 최근접 이웃으로 이웃을 만들어 내는 것은 점구름처럼 엣지가 원래 없는 데이터일 때예요.","p.41 의 **DeepGCNs**가 바로 그런 점구름 문제에서 나온 모델이라 설명이 섞여 들어온 것으로 보여요.","답안에는 '그래프에서는 이웃 집합을 먼저 정해야 한다'까지만 쓰면 안전해요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"A GCN shares one weight matrix across all neighbors, which makes a layer behave like a weighted average.","ko":"GCN은 모든 이웃에 가중치 행렬 하나를 공유하므로 한 층이 가중평균처럼 동작한다.","tip":"behave like a weighted average 가 평활화로 이어지는 연결고리예요."},{"kind":"check","q":"**GCN**이 모든 이웃에 같은 가중치를 쓰는 이유는 무엇인가요?","choices":["계산을 빠르게 하려고","그래프의 이웃에는 표준 순서가 없어서","메모리를 아끼려고","층을 깊게 쌓으려고"],"a":1,"why":"순서가 없으니 순서에 의존하지 않는 것이 옳은 설계예요. 대신 잘 섞이는 대가를 치러요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.9378,0.3503],"c":[0,0.0004,1,0.3853],"r":4.614,"img":"img/L5/walk/p011_h.jpg"},"parts":[{"b":[0.06,0.386,0.32,0.042],"c":[0.044,0.352,0.352,0.11],"r":5.6889,"img":"img/L5/walk/p011_11_01.jpg","say":"굵은 글씨: '그러면 깊은 GCN은 어디에 있을까요?' 오늘 덱의 출발 질문이에요."}]}},{"p":12,"title":"깊이의 역설","terms":["Depth","Residual Connection","Over-smoothing","DeepGCNs","CNN","GCN"],"pass1":[{"kind":"say","lines":["영상에서는 깊을수록 좋고, 그래프에서는 깊을수록 나빠요.","이 모순에 '**깊이(Depth)**의 역설'이라는 이름이 붙었어요.","그리고 **잔차 연결(Residual Connection)**만으로는 이 문제가 풀리지 않아요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.067,"y":0.231,"w":0.425,"h":0.226,"say":"'잔차 CNN은 100층이 넘어도 안정적으로 학습되고 정확도도 좋아져요.'","c":[0.0457,0.215,0.4675,0.258],"r":3.2214,"img":"img/L5/walk/p012_20_01.jpg"},{"x":0.507,"y":0.231,"w":0.426,"h":0.226,"say":"'고전 GCN은 2~3층에서 가장 좋고, 무작정 쌓으면 정확도가 떨어져요.'","c":[0.4857,0.215,0.4686,0.258],"r":3.2289,"img":"img/L5/walk/p012_20_02.jpg"},{"x":0.067,"y":0.484,"w":0.866,"h":0.185,"say":"'최적화는 쉬워지지만, 반복된 전파가 노드 특징에 하는 일은 바꾸지 못해요.'","c":[0.0237,0.468,0.9526,0.217],"r":7.8042,"img":"img/L5/walk/p012_20_03.jpg"},{"x":0.062,"y":0.704,"w":0.81,"h":0.048,"say":"'핵심 질문: 층을 쌓으면 무엇이 망가지고, 깊지 않고도 멀리 보려면?'","c":[0.0215,0.638,0.891,0.18],"r":8.8,"img":"img/L5/walk/p012_20_04.jpg"}]},{"kind":"figure","head":"같은 깊이인데 결과가 정반대","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<line class=\"e\" x1=\"40\" y1=\"180\" x2=\"220\" y2=\"180\"/>\n<line class=\"e\" x1=\"40\" y1=\"40\" x2=\"40\" y2=\"180\"/>\n<polyline class=\"e2 b1\" points=\"50,170 90,124 130,90 170,66 210,54\" fill=\"none\"/>\n<text class=\"tb b1\" x=\"130\" y=\"34\" font-size=\"14\" text-anchor=\"middle\">비전: 계속 좋아짐<\/text>\n<text class=\"tm b1\" x=\"130\" y=\"202\" font-size=\"13\" text-anchor=\"middle\">2층에서 152층까지<\/text>\n<line class=\"e\" x1=\"270\" y1=\"180\" x2=\"450\" y2=\"180\"/>\n<line class=\"e\" x1=\"270\" y1=\"40\" x2=\"270\" y2=\"180\"/>\n<polyline class=\"e2 b2\" points=\"278,92 300,54 330,60 370,100 410,140 444,164\" fill=\"none\"/>\n<circle class=\"n2 b2\" cx=\"300\" cy=\"54\" r=\"8\"/>\n<text class=\"tb b2\" x=\"362\" y=\"34\" font-size=\"14\" text-anchor=\"middle\">그래프: 2~3층이 정점<\/text>\n<text class=\"tm b2\" x=\"362\" y=\"202\" font-size=\"13\" text-anchor=\"middle\">그 뒤로는 떨어져요<\/text>\n<rect class=\"box2 b3\" x=\"66\" y=\"222\" width=\"350\" height=\"34\" rx=\"7\"/>\n<text class=\"tb b3\" x=\"240\" y=\"244\" font-size=\"15\" text-anchor=\"middle\">같은 깊이인데 결과가 정반대, 이것이 깊이의 역설<\/text>\n<\/svg>","caption":"왼쪽은 영상, 오른쪽은 그래프예요. 층을 늘릴 때 곡선 모양이 정반대예요.","builds":3},{"kind":"points","head":"'잔차만으로는 부족하다'가 무슨 뜻인가요","items":["**잔차 연결(Residual Connection)**은 학습이 **되게** 해 줘요. **기울기 소실(Vanishing Gradient)**을 막거든요.","실제로 **DeepGCNs**는 잔차와 확장 연결로 56층 GCN을 학습시켰어요.","그런데 '메시지를 반복하면 값이 비슷해진다'는 사실 자체는 바뀌지 않아요.","즉 최적화는 고치지만 **과도한 평활화(Over-smoothing)**는 고치지 못해요."]},{"kind":"compare","head":"층 수를 모아 보면","cols":["상황","잘 되는 층 수"],"rows":[["잔차 **CNN** (영상)","100층 이상"],["고전 **GCN**","2층에서 3층"],["최신 **GCN** 일반","3층에서 4층 이하"],["**DeepGCNs** (잔차와 확장)","56층"]]}],"pass3":[{"kind":"warn","head":"p.12 와 p.13 의 숫자가 어긋나요","items":["p.12 는 고전 GCN 이 '2~3층'에서 가장 좋다고 적었어요.","그런데 바로 다음 p.13 은 최신 모델이 '3~4층을 넘지 않는다'고 적었어요.","둘 다 틀린 말은 아니에요. 하나는 '가장 좋은 깊이', 다른 하나는 '실제 쓰이는 최대 깊이'거든요.","답안에는 '보통 2층에서 4층 사이'처럼 범위로 쓰면 어느 쪽으로도 틀리지 않아요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Residual connections ease optimization but do not change what repeated propagation does to node features.","ko":"잔차 연결은 최적화를 쉽게 하지만, 반복된 전파가 노드 특징에 하는 일을 바꾸지는 못한다.","tip":"ease optimization 과 do not change 의 대비가 채점 포인트예요."},{"kind":"check","q":"**잔차 연결(Residual Connection)**이 고치는 것과 못 고치는 것은 무엇인가요?","choices":["둘 다 고쳐요","최적화는 고치고 과도한 평활화는 못 고쳐요","과도한 평활화는 고치고 최적화는 못 고쳐요","둘 다 못 고쳐요"],"a":1,"why":"기울기는 살려 주지만 반복 전파가 특징을 섞는 일 자체는 그대로예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.1533,0.0757],"c":[0,0.0019,0.2,0.1077],"r":3.3014,"img":"img/L5/walk/p012_h.jpg"},"parts":[{"b":[0.067,0.231,0.425,0.226],"c":[0.0457,0.215,0.4675,0.258],"r":3.2214,"img":"img/L5/walk/p012_11_01.jpg","say":"왼쪽 상자: '비전, 보통 깊을수록 좋다'. 100층이 넘어도 안정적이에요."},{"b":[0.507,0.231,0.426,0.226],"c":[0.4857,0.215,0.4686,0.258],"r":3.2289,"img":"img/L5/walk/p012_11_02.jpg","say":"오른쪽 상자: '그래프, 깊을수록 나빠질 때가 많다'. 2~3층이 정점이에요."},{"b":[0.067,0.484,0.866,0.185],"c":[0.0237,0.468,0.9526,0.217],"r":7.8042,"img":"img/L5/walk/p012_11_03.jpg","say":"아래 상자: '잔차 연결만으로는 부족하다'. 이 문장이 오늘 제일 중요해요."}]}},{"p":13,"title":"유명한 모델도 전부 서너 층","terms":["GCN","Depth","Width","Receptive Field","Under-reaching","Over-smoothing"],"pass1":[{"kind":"say","lines":["실제로 유명한 모델들이 몇 층인지 눈으로 확인해요.","**GCN**도 GraphSage 도 숨은 층이 두 개예요.","즉 최신 모델도 서너 층을 넘지 않아요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.06,"y":0.154,"w":0.45,"h":0.044,"say":"'최신 GCN 모델은 대개 3~4층을 넘지 않아요.' 이 한 줄이 전부예요.","c":[0.0375,0.121,0.495,0.11],"r":8.0,"img":"img/L5/walk/p013_20_01.jpg"},{"x":0.184,"y":0.321,"w":0.066,"h":0.031,"say":"왼쪽 그림 제목 'GCN'이에요.","c":[0.117,0.2815,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p013_20_02.jpg"},{"x":0.063,"y":0.37,"w":0.347,"h":0.315,"say":"입력에서 숨은 층 둘을 지나 출력으로 가요. ReLU 가 사이에 있어요.","c":[0.0456,0.354,0.3817,0.347],"r":1.9556,"img":"img/L5/walk/p013_20_03.jpg"},{"x":0.688,"y":0.321,"w":0.118,"h":0.031,"say":"오른쪽 그림 제목 'GraphSage'예요.","c":[0.647,0.2815,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p013_20_04.jpg"},{"x":0.521,"y":0.37,"w":0.417,"h":0.285,"say":"1. 이웃 샘플링, 2. 이웃 정보 집계, 3. 예측 세 단계예요.","c":[0.5002,0.354,0.4587,0.317],"r":2.5725,"img":"img/L5/walk/p013_20_05.jpg"},{"x":0.035,"y":0.722,"w":0.2,"h":0.037,"say":"'더 읽을거리'에 원문 링크가 있어요.","c":[0.023,0.6855,0.224,0.11],"r":3.6202,"img":"img/L5/walk/p013_20_06.jpg"}]},{"kind":"points","head":"그림에서 깊이와 너비를 구별하세요","items":["숨은 층 네모 안에 같은 그래프가 여러 개 세로로 쌓여 있어요.","세로로 쌓인 것은 채널, 즉 **너비(Width)**예요.","가로로 늘어선 것이 층, 즉 **깊이(Depth)**예요.","p.9 에서 말한 두 축이 그림에서 이렇게 구별돼요."]},{"kind":"steps","head":"서너 층이면 얼마나 보이나","steps":["노드 100 개, 평균 **차수(Degree)** 4 인 그래프를 생각해요.","0홉은 나 자신 1 개예요.","1홉에 새로 4 개가 닿아요. 누적 5 개예요.","2홉부터는 왔던 길 하나를 빼고 3 갈래씩 퍼져요. $4 \\times 3 = 12$ 개, 누적 17 개예요.","3홉은 $12 \\times 3 = 36$ 개, 누적 53 개예요.","4홉은 $36 \\times 3 = 108$ 개인데 그래프에 100 개뿐이라 이미 전체를 덮어요."],"answer":"4층이면 그래프 전체가 내 **수용 영역(Receptive Field)**이에요. 얕으면 못 보고 깊으면 다 섞여요.","given":"노드 100 개, 평균 차수 4 인 그래프예요."},{"kind":"mining","src":"마이닝 10강 Random Walk-based GRL","lines":["오른쪽 GraphSage 의 1단계 '이웃 샘플링'은 마이닝의 DeepWalk 와 발상이 닮았어요.","DeepWalk 도 이웃을 전부 쓰지 않고 걸어 다니며 만난 노드만 썼거든요.","차이는 DeepWalk 가 노드마다 벡터를 표에 외워 두는 방식이라는 점이에요.","GraphSage 는 함수를 배우니 처음 보는 노드에도 그대로 쓸 수 있어요."]}],"pass3":[{"kind":"warn","head":"p.13 과 p.12 의 숫자가 어긋나요","items":["여기는 '3~4층을 넘지 않는다', 앞 p.12 는 '2~3층이 가장 좋다'예요.","답안에는 '보통 2층에서 4층'처럼 범위로 쓰세요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"State-of-the-art GCN models are normally no deeper than three or four layers.","ko":"최신 GCN 모델들은 보통 서너 층보다 깊지 않다.","tip":"no deeper than 이라는 표현을 통째로 외워 두세요."},{"kind":"check","q":"4층 GNN 이 '얕아서 문제'이면서 동시에 '깊어서 문제'인 이유는 무엇인가요?","choices":["계산이 느려서","4홉 밖은 못 보는데 4홉 안은 이미 전체라서","메모리가 부족해서","가중치가 많아서"],"a":1,"why":"4홉 밖은 **도달 실패(Under-reaching)**, 4홉 안은 **과도한 평활화(Over-smoothing)**예요. 양쪽 다 문제예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.8013,0.3454],"c":[0,0.0006,0.8814,0.3799],"r":4.1246,"img":"img/L5/walk/p013_h.jpg"},"parts":[{"b":[0.063,0.37,0.347,0.315],"c":[0.0456,0.354,0.3817,0.347],"r":1.9556,"img":"img/L5/walk/p013_11_01.jpg","say":"왼쪽 GCN. 'Hidden layer'라고 적힌 큰 네모가 **두 개**예요."},{"b":[0.521,0.37,0.417,0.285],"c":[0.5002,0.354,0.4587,0.317],"r":2.5725,"img":"img/L5/walk/p013_11_02.jpg","say":"오른쪽 GraphSage. 첫 그림에 k=1 과 k=2 만 있어요. 2층이에요."}]}},{"p":14,"title":"네 가지 장애물 표","terms":["Over-smoothing","Over-squashing","Under-reaching","Vanishing Gradient","Overfitting","Low-pass Filter","Bottleneck","Receptive Field"],"pass1":[{"kind":"say","lines":["깊은 GCN을 막는 장애물은 정확히 네 가지예요.","**과도한 평활화(Over-smoothing)**, **과도한 압착(Over-squashing)**, **도달 실패(Under-reaching)**, 최적화예요.","이 표 한 장이 오늘 덱 전체의 지도예요. 통째로 외워 두세요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"표를 열별로 읽어요","boxes":[{"x":0.052,"y":0.173,"w":0.896,"h":0.092,"say":"열 제목 네 개: 장애물, 무엇이 잘못되나, 근본 원인, 무엇에 따라 커지나.","c":[0.0072,0.1194,0.9856,0.1991],"r":8.8005,"img":"img/L5/walk/p014_20_01.jpg"},{"x":0.213,"y":0.265,"w":0.271,"h":0.102,"say":"평활화가 잘못되는 점: '노드 표현이 수렴하고 클래스를 구분할 수 없게 된다.'","c":[0.1995,0.249,0.2981,0.134],"r":3.9549,"img":"img/L5/walk/p014_20_02.jpg"},{"x":0.484,"y":0.265,"w":0.266,"h":0.102,"say":"평활화의 원인: '반복되는 저역 통과 필터링, 즉 라플라시안 평활화.'","c":[0.4707,0.249,0.2926,0.134],"r":3.8819,"img":"img/L5/walk/p014_20_03.jpg"},{"x":0.484,"y":0.367,"w":0.266,"h":0.133,"say":"압착의 원인: '지수로 커지는 수용 영역이 병목을 지나며 고정 길이 벡터로 눌린다.'","c":[0.4707,0.351,0.2926,0.165],"r":3.1526,"img":"img/L5/walk/p014_20_04.jpg"},{"x":0.484,"y":0.5,"w":0.266,"h":0.101,"say":"도달 실패의 원인: '문제 반경보다 층이 적다.'","c":[0.4707,0.484,0.2926,0.133],"r":3.9111,"img":"img/L5/walk/p014_20_05.jpg"},{"x":0.75,"y":0.601,"w":0.198,"h":0.14,"say":"최적화가 커지는 조건: '층 수, 적은 레이블 노드.'","c":[0.738,0.585,0.222,0.172],"r":2.2946,"img":"img/L5/walk/p014_20_06.jpg"}]},{"kind":"compare","head":"네 장애물을 한 줄씩","cols":["장애물","무엇이 잘못되나","무엇에 따라 커지나"],"rows":[["**과도한 평활화(Over-smoothing)**","노드 표현이 수렴해 구별 불가","층 수, 촘촘한 그래프"],["**과도한 압착(Over-squashing)**","먼 노드 정보가 압축되어 소실","먼 거리 의존, **병목(Bottleneck)** 구조"],["**도달 실패(Under-reaching)**","관련 노드를 아예 못 봄","층이 너무 적음"],["최적화","**기울기 소실(Vanishing Gradient)**, **과적합(Overfitting)**","층 수, 적은 레이블"]]},{"kind":"figure","head":"네 장애물과 그 조건","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<rect class=\"box2 b1\" x=\"10\" y=\"26\" width=\"108\" height=\"62\" rx=\"8\"/>\n<text class=\"tb b1\" x=\"64\" y=\"50\" font-size=\"14\" text-anchor=\"middle\">과도한 평활화<\/text>\n<text class=\"tm b1\" x=\"64\" y=\"72\" font-size=\"13\" text-anchor=\"middle\">다 섞여 같아짐<\/text>\n<rect class=\"box b2\" x=\"126\" y=\"26\" width=\"108\" height=\"62\" rx=\"8\"/>\n<text class=\"tb b2\" x=\"180\" y=\"50\" font-size=\"14\" text-anchor=\"middle\">과도한 압착<\/text>\n<text class=\"tm b2\" x=\"180\" y=\"72\" font-size=\"13\" text-anchor=\"middle\">병목에서 뭉개짐<\/text>\n<rect class=\"box b3\" x=\"242\" y=\"26\" width=\"108\" height=\"62\" rx=\"8\"/>\n<text class=\"tb b3\" x=\"296\" y=\"50\" font-size=\"14\" text-anchor=\"middle\">도달 실패<\/text>\n<text class=\"tm b3\" x=\"296\" y=\"72\" font-size=\"13\" text-anchor=\"middle\">아예 오지 않음<\/text>\n<rect class=\"box b4\" x=\"358\" y=\"26\" width=\"110\" height=\"62\" rx=\"8\"/>\n<text class=\"tb b4\" x=\"413\" y=\"50\" font-size=\"14\" text-anchor=\"middle\">최적화<\/text>\n<text class=\"tm b4\" x=\"413\" y=\"72\" font-size=\"13\" text-anchor=\"middle\">학습이 안 됨<\/text>\n<text class=\"t b1\" x=\"64\" y=\"112\" font-size=\"13\" text-anchor=\"middle\">층 수, 촘촘한 그래프<\/text>\n<text class=\"t b2\" x=\"180\" y=\"112\" font-size=\"13\" text-anchor=\"middle\">먼 거리, 병목 구조<\/text>\n<text class=\"t b3\" x=\"296\" y=\"112\" font-size=\"13\" text-anchor=\"middle\">층이 너무 적음<\/text>\n<text class=\"t b4\" x=\"413\" y=\"112\" font-size=\"13\" text-anchor=\"middle\">층 수, 적은 레이블<\/text>\n<rect class=\"box2 b5\" x=\"118\" y=\"146\" width=\"244\" height=\"40\" rx=\"8\"/>\n<text class=\"tb b5\" x=\"240\" y=\"172\" font-size=\"15\" text-anchor=\"middle\">전부 층을 쌓을 때 생기는 일<\/text>\n<text class=\"tb b5\" x=\"240\" y=\"216\" font-size=\"14\" text-anchor=\"middle\">평활화는 연결이 촘촘할 때 심해지고<\/text>\n<text class=\"tb b5\" x=\"240\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">압착은 연결이 성길 때 심해져요<\/text>\n<\/svg>","caption":"네 가지 모두 층을 쌓을 때 생겨요. 다만 평활화와 압착은 **정반대 조건**에서 심해져요.","builds":5},{"kind":"points","head":"네 가지를 일상어로 바꾸면","items":["**과도한 평활화(Over-smoothing)**는 '너무 많이 섞였다'예요. 반 전체가 같은 의견이 된 상태죠.","**과도한 압착(Over-squashing)**은 '좁은 관에 너무 많이 밀어 넣었다'예요.","**도달 실패(Under-reaching)**는 '아예 도착하지 않았다'예요. 압착과 달리 오지도 못한 거예요.","최적화는 **기울기 소실(Vanishing Gradient)**과 **과적합(Overfitting)**이에요. 그래프만의 문제가 아니에요."]},{"kind":"mining","src":"마이닝 1강 Introduction to Graph","lines":["**저역 통과 필터(Low-pass Filter)**는 음악의 이퀄라이저에서 고음만 죽이는 장치와 같아요.","여기서 '고음'은 '이웃끼리 값이 다른 부분'이에요.","그게 깎이면 이웃끼리 값이 같아져요. 그것이 평활화예요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"Stacking message-passing layers causes over-smoothing, over-squashing, under-reaching and optimization issues.","ko":"메시지 패싱 층을 쌓으면 과도한 평활화, 과도한 압착, 도달 실패, 그리고 최적화 문제가 생긴다.","tip":"네 단어를 이 순서로 외워 두면 서술형에서 빠뜨리지 않아요."},{"kind":"warn","head":"압착과 도달 실패를 구별하세요","items":["**도달 실패(Under-reaching)**는 경로가 아예 없어요. 민감도가 **정확히 0** 이에요.","**과도한 압착(Over-squashing)**은 경로는 있는데 너무 좁아요. 0 은 아니지만 아주 작아요.","이 '정확히 0'과 '작지만 0 은 아님'의 차이가 시험에 나오기 좋아요."]},{"kind":"check","q":"**과도한 평활화(Over-smoothing)**의 근본 원인은 무엇인가요?","choices":["반복되는 저역 통과 필터링","고정 길이 벡터와 병목","층 수가 문제 반경보다 적음","가중치 행렬이 너무 많음"],"a":0,"why":"**저역 통과 필터(Low-pass Filter)**가 반복되면서 이웃 간 차이가 깎여요."},{"kind":"check","q":"**과도한 압착(Over-squashing)**이 심해지는 조건은 무엇인가요?","choices":["촘촘하게 잘 연결된 그래프","**병목(Bottleneck)** 구조와 먼 거리 의존","레이블이 많을 때","너비가 클 때"],"a":1,"why":"평활화와 정반대예요. 평활화는 촘촘할 때, 압착은 병목이 있을 때 심해져요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5518,0.2121],"c":[0,0.0019,0.6069,0.2441],"r":4.42,"img":"img/L5/walk/p014_h.jpg"},"parts":[{"b":[0.052,0.265,0.161,0.102],"c":[0.0325,0.249,0.2,0.134],"r":2.6534,"img":"img/L5/walk/p014_11_01.jpg","say":"'과도한 평활화'. 노드 표현이 수렴해서 구별이 안 돼요."},{"b":[0.052,0.367,0.161,0.133],"c":[0.0325,0.351,0.2,0.165],"r":2.1549,"img":"img/L5/walk/p014_11_02.jpg","say":"'과도한 압착'. 먼 노드 정보가 압축되어 사라져요."},{"b":[0.052,0.5,0.161,0.101],"c":[0.0325,0.484,0.2,0.133],"r":2.6734,"img":"img/L5/walk/p014_11_03.jpg","say":"'도달 실패'. 관련 노드를 아예 보지 못해요."},{"b":[0.052,0.601,0.161,0.14],"c":[0.0325,0.585,0.2,0.172],"r":2.0672,"img":"img/L5/walk/p014_11_04.jpg","say":"'최적화'. 기울기 소실, 과적합, 불안정한 학습이에요."}]}},{"p":15,"title":"구분: 평활화 대 압착","terms":["Over-smoothing","Over-squashing","Bottleneck"],"pass1":[{"kind":"say","lines":["**과도한 평활화(Over-smoothing)**와 **과도한 압착(Over-squashing)**은 정반대 방향의 고장이에요.","하나는 '너무 많이 섞여서', 다른 하나는 '섞여야 할 것이 못 들어와서' 생겨요.","그래서 하나를 고치면 다른 하나가 나빠져요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"compare","head":"정반대라는 말의 뜻","cols":["항목","**과도한 평활화(Over-smoothing)**","**과도한 압착(Over-squashing)**"],"rows":[["한 줄 요약","너무 많이 섞였다","섞여야 할 것이 못 들어왔다"],["언제 심해지나","그래프가 촘촘할 때","**병목(Bottleneck)**이 있을 때"],["결과","노드들이 서로 같아짐","먼 노드 정보가 사라짐"],["고치는 방향","덜 섞이게 하기","더 잘 통하게 하기"]]},{"kind":"points","head":"마지막 줄이 고약해요","items":["덜 섞이게 하면 먼 신호도 덜 오게 돼요.","더 잘 통하게 하면 더 빨리 섞여 버려요.","즉 두 처방이 서로 반대 방향으로 밀어요.","이 갈등이 p.24 의 치거 부등식에서 수학으로 확인돼요."]}],"pass3":[],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.048,0.278,0.51,0.1],"c":[0.0225,0.262,0.561,0.132],"r":7.5556,"img":"img/L5/walk/p015_11_01.jpg","say":"큰 제목: '과도한 평활화와 과도한 압착'."},{"b":[0.045,0.462,0.48,0.09],"c":[0.021,0.446,0.528,0.122],"r":7.694,"img":"img/L5/walk/p015_11_02.jpg","say":"'둘 다 깊은 모델을 무너뜨리지만 방식은 정반대예요.'"}]}},{"p":16,"title":"수용 영역이 그래프 전체가 된다","terms":["Over-smoothing","Receptive Field","Degree","Small-world","Embedding"],"pass1":[{"kind":"say","lines":["**과도한 평활화(Over-smoothing)**는 모든 노드 **임베딩(Embedding)**이 같은 값으로 수렴하는 일이에요.","왜 생길까요? **수용 영역(Receptive Field)**이 그래프 전체로 부풀기 때문이에요.","$K$ 층 GNN에서 각 노드의 **수용 영역(Receptive Field)**은 정확히 $K$ 홉 이웃이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.055,"y":0.138,"w":0.52,"h":0.04,"say":"'과도한 평활화 문제: 모든 노드 임베딩이 같은 값으로 수렴한다.'","c":[0.029,0.1002,0.572,0.1156],"r":8.7966,"img":"img/L5/walk/p016_20_01.jpg"},{"x":0.09,"y":0.195,"w":0.52,"h":0.038,"say":"'노드 임베딩으로 노드를 구별하려는 것이니 이건 나쁜 일이에요.'","c":[0.064,0.1562,0.572,0.1156],"r":8.7966,"img":"img/L5/walk/p016_20_02.jpg"},{"x":0.055,"y":0.259,"w":0.3,"h":0.038,"say":"'과도한 평활화는 왜 일어날까요?'","c":[0.04,0.223,0.33,0.11],"r":5.3333,"img":"img/L5/walk/p016_20_03.jpg"},{"x":0.1,"y":0.315,"w":0.5,"h":0.038,"say":"'수용 영역: 관심 노드의 임베딩을 결정하는 노드들의 집합.'","c":[0.075,0.2784,0.55,0.1111],"r":8.8009,"img":"img/L5/walk/p016_20_04.jpg"},{"x":0.13,"y":0.38,"w":0.5,"h":0.038,"say":"'K층 GNN에서 각 노드의 수용 영역은 K홉 이웃이에요.'","c":[0.105,0.3434,0.55,0.1111],"r":8.8009,"img":"img/L5/walk/p016_20_05.jpg"},{"x":0.038,"y":0.457,"w":0.26,"h":0.031,"say":"세 그림의 제목이 각각 1층, 2층, 3층의 수용 영역이에요.","c":[0.025,0.4175,0.286,0.11],"r":4.6222,"img":"img/L5/walk/p016_20_06.jpg"}]},{"kind":"figure","head":"층이 하나 늘 때마다 한 홉씩 부푼다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<circle class=\"hl b1\" cx=\"80\" cy=\"120\" r=\"34\" fill=\"none\"/>\n<circle class=\"hl b2\" cx=\"240\" cy=\"120\" r=\"34\" fill=\"none\"/>\n<circle class=\"hl b2\" cx=\"240\" cy=\"120\" r=\"56\" fill=\"none\"/>\n<circle class=\"hl b3\" cx=\"400\" cy=\"120\" r=\"34\" fill=\"none\"/>\n<circle class=\"hl b3\" cx=\"400\" cy=\"120\" r=\"56\" fill=\"none\"/>\n<circle class=\"hl b3\" cx=\"400\" cy=\"120\" r=\"76\" fill=\"none\"/>\n<circle class=\"n2\" cx=\"80\" cy=\"120\" r=\"12\"/>\n<circle class=\"n2\" cx=\"240\" cy=\"120\" r=\"12\"/>\n<circle class=\"n2\" cx=\"400\" cy=\"120\" r=\"12\"/>\n<circle class=\"n3 b1\" cx=\"58\" cy=\"100\" r=\"7\"/>\n<circle class=\"n3 b1\" cx=\"104\" cy=\"102\" r=\"7\"/>\n<circle class=\"n3 b1\" cx=\"62\" cy=\"142\" r=\"7\"/>\n<circle class=\"n3 b1\" cx=\"100\" cy=\"144\" r=\"7\"/>\n<circle class=\"n3 b2\" cx=\"218\" cy=\"100\" r=\"7\"/>\n<circle class=\"n3 b2\" cx=\"264\" cy=\"102\" r=\"7\"/>\n<circle class=\"n3 b2\" cx=\"222\" cy=\"142\" r=\"7\"/>\n<circle class=\"n3 b2\" cx=\"260\" cy=\"144\" r=\"7\"/>\n<circle class=\"n3 b2\" cx=\"206\" cy=\"86\" r=\"7\"/>\n<circle class=\"n3 b2\" cx=\"276\" cy=\"86\" r=\"7\"/>\n<circle class=\"n3 b2\" cx=\"200\" cy=\"152\" r=\"7\"/>\n<circle class=\"n3 b2\" cx=\"282\" cy=\"154\" r=\"7\"/>\n<circle class=\"n3 b3\" cx=\"378\" cy=\"100\" r=\"7\"/>\n<circle class=\"n3 b3\" cx=\"424\" cy=\"102\" r=\"7\"/>\n<circle class=\"n3 b3\" cx=\"382\" cy=\"142\" r=\"7\"/>\n<circle class=\"n3 b3\" cx=\"420\" cy=\"144\" r=\"7\"/>\n<circle class=\"n3 b3\" cx=\"366\" cy=\"86\" r=\"7\"/>\n<circle class=\"n3 b3\" cx=\"436\" cy=\"86\" r=\"7\"/>\n<circle class=\"n3 b3\" cx=\"360\" cy=\"152\" r=\"7\"/>\n<circle class=\"n3 b3\" cx=\"442\" cy=\"154\" r=\"7\"/>\n<circle class=\"n3 b3\" cx=\"400\" cy=\"58\" r=\"7\"/>\n<circle class=\"n3 b3\" cx=\"400\" cy=\"182\" r=\"7\"/>\n<circle class=\"n3 b3\" cx=\"346\" cy=\"70\" r=\"7\"/>\n<circle class=\"n3 b3\" cx=\"456\" cy=\"70\" r=\"7\"/>\n<text class=\"tb b1\" x=\"80\" y=\"34\" font-size=\"15\" text-anchor=\"middle\">1층: 5개<\/text>\n<text class=\"tb b2\" x=\"240\" y=\"34\" font-size=\"15\" text-anchor=\"middle\">2층: 17개<\/text>\n<text class=\"tb b3\" x=\"400\" y=\"34\" font-size=\"15\" text-anchor=\"middle\">3층: 53개<\/text>\n<text class=\"tb b4\" x=\"240\" y=\"228\" font-size=\"16\" text-anchor=\"middle\">차수 4 인 그래프에서 5개, 17개, 53개<\/text>\n<text class=\"tm b4\" x=\"240\" y=\"252\" font-size=\"14\" text-anchor=\"middle\">두 배씩이 아니라 세 배씩 늘어요<\/text>\n<\/svg>","caption":"노란 점이 관심 노드, 빨간 점이 **수용 영역(Receptive Field)**이에요. 세 배씩 늘어나요.","builds":4},{"kind":"steps","head":"수용 영역이 커지는 속도를 세어 보기","steps":["평균 **차수(Degree)**가 4 인 그래프를 생각해요.","나 자신이 1 개예요.","1홉에 4 개가 닿아요. 누적 5 개예요.","2홉은 $4 \\times 3 = 12$ 개, 누적 17 개예요.","3홉은 $12 \\times 3 = 36$ 개, 누적 53 개예요.","6홉이면 누적 1,457 개까지 가요."],"answer":"격자는 층 수의 제곱으로 커지는데 그래프는 지수로 커져요. 10층이면 441 대 118,097 로 268배 차이예요.","given":"평균 차수 4 인 그래프에서 $K$ 홉 안의 노드 수를 세요."},{"kind":"mining","src":"마이닝 1강 Introduction to Graph","lines":["**좁은 세상(Small-world)** 성질은 아무 두 사람이나 여섯 다리면 이어진다는 그 이야기예요.","척도 없는 성질도 있어요. 이웃이 수천 명인 허브 노드가 존재한다는 뜻이에요.","마이닝에서는 좋은 소식이었어요. 정보가 빨리 퍼지니까요.","GNN에서는 나쁜 소식이에요. **좁은 세상(Small-world)**이라 몇 층만에 다 섞이거든요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"In a K-layer GNN the receptive field of every node is its K-hop neighbourhood, which grows exponentially with K.","ko":"K층 GNN에서 모든 노드의 수용 영역은 K홉 이웃이고, 그 크기는 K에 대해 지수적으로 커진다.","tip":"grows exponentially 가 CNN 의 quadratically 와 대비되는 표현이에요."},{"kind":"check","q":"3층 GNN 에서 한 노드의 **수용 영역(Receptive Field)**은 무엇인가요?","choices":["직접 이웃만","3홉 안의 모든 노드","그래프 전체","자기 자신만"],"a":1,"why":"$K$ 층이면 정확히 $K$ 홉이에요. 다만 실제 그래프에서는 3홉이 거의 전체이기도 해요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.8593,0.4741],"c":[0,0,0.9452,0.5215],"r":3.2222,"img":"img/L5/walk/p016_h.jpg"},"parts":[{"b":[0.038,0.494,0.261,0.444],"c":[0.0249,0.4718,0.2871,0.4884],"r":1.045,"img":"img/L5/walk/p016_11_01.jpg","say":"1층. 노란 노드 주위에 빨간 점이 몇 개뿐이에요."},{"b":[0.354,0.494,0.257,0.444],"c":[0.3411,0.4718,0.2827,0.4884],"r":1.029,"img":"img/L5/walk/p016_11_02.jpg","say":"2층. 빨간 점이 그래프 절반 가까이로 늘었어요."},{"b":[0.694,0.494,0.244,0.444],"c":[0.6818,0.4718,0.2684,0.4884],"r":0.977,"img":"img/L5/walk/p016_11_03.jpg","say":"3층. 거의 전부가 빨간색이에요. 세 그림 모두 같은 그래프예요."}]}},{"p":17,"title":"두 노드의 수용 영역이 겹쳐 간다","terms":["Over-smoothing","Receptive Field","Embedding"],"pass1":[{"kind":"say","lines":["**수용 영역(Receptive Field)**이 커지는 것만이 문제가 아니에요.","**두 노드의 수용 영역이 겹치는 정도**가 폭발적으로 커져요.","같은 재료로 만든 요리는 맛이 비슷하죠. **임베딩(Embedding)**도 마찬가지예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.055,"y":0.138,"w":0.14,"h":0.04,"say":"'과도한 평활화'가 이 슬라이드의 주제예요.","c":[0.025,0.103,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p017_20_01.jpg"},{"x":0.09,"y":0.195,"w":0.7,"h":0.045,"say":"'두 노드의 수용 영역 겹침: 홉 수를 늘리면 공유 이웃이 빠르게 늘어나요.'","c":[0.055,0.1397,0.77,0.1556],"r":8.7975,"img":"img/L5/walk/p017_20_02.jpg"},{"x":0.125,"y":0.302,"w":0.68,"h":0.04,"say":"'두 노드의 수용 영역이 많이 겹치면 두 임베딩은 매우 비슷해져요.'","c":[0.091,0.2464,0.748,0.1511],"r":8.8006,"img":"img/L5/walk/p017_20_03.jpg"},{"x":0.1,"y":0.545,"w":0.18,"h":0.05,"say":"범례가 p.16 과 달라요. 이번에는 관심 노드가 **둘**이에요.","c":[0.088,0.515,0.204,0.11],"r":3.297,"img":"img/L5/walk/p017_20_04.jpg"},{"x":0.14,"y":0.585,"w":0.18,"h":0.04,"say":"빨간색의 뜻도 '내 수용 영역'에서 '공유 이웃'으로 바뀌었어요.","c":[0.128,0.55,0.204,0.11],"r":3.297,"img":"img/L5/walk/p017_20_05.jpg"}]},{"kind":"figure","head":"겹치는 부분이 커지면 임베딩이 같아진다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<circle class=\"hl b1\" cx=\"58\" cy=\"110\" r=\"26\" fill=\"none\"/>\n<circle class=\"hl b1\" cx=\"102\" cy=\"110\" r=\"26\" fill=\"none\"/>\n<circle class=\"hl b2\" cx=\"204\" cy=\"110\" r=\"42\" fill=\"none\"/>\n<circle class=\"hl b2\" cx=\"266\" cy=\"110\" r=\"42\" fill=\"none\"/>\n<circle class=\"hl b3\" cx=\"368\" cy=\"110\" r=\"58\" fill=\"none\"/>\n<circle class=\"hl b3\" cx=\"416\" cy=\"110\" r=\"58\" fill=\"none\"/>\n<circle class=\"n2 b1\" cx=\"58\" cy=\"110\" r=\"9\"/>\n<circle class=\"n2 b1\" cx=\"102\" cy=\"110\" r=\"9\"/>\n<circle class=\"n2 b2\" cx=\"204\" cy=\"110\" r=\"9\"/>\n<circle class=\"n2 b2\" cx=\"266\" cy=\"110\" r=\"9\"/>\n<circle class=\"n2 b3\" cx=\"368\" cy=\"110\" r=\"9\"/>\n<circle class=\"n2 b3\" cx=\"416\" cy=\"110\" r=\"9\"/>\n<text class=\"tb b1\" x=\"80\" y=\"34\" font-size=\"14\" text-anchor=\"middle\">1홉<\/text>\n<text class=\"tb b2\" x=\"235\" y=\"34\" font-size=\"14\" text-anchor=\"middle\">2홉<\/text>\n<text class=\"tb b3\" x=\"392\" y=\"34\" font-size=\"14\" text-anchor=\"middle\">3홉<\/text>\n<text class=\"t b1\" x=\"80\" y=\"176\" font-size=\"14\" text-anchor=\"middle\">겹침 약 5퍼센트<\/text>\n<text class=\"t b2\" x=\"235\" y=\"176\" font-size=\"14\" text-anchor=\"middle\">겹침 약 17퍼센트<\/text>\n<text class=\"t b3\" x=\"392\" y=\"192\" font-size=\"14\" text-anchor=\"middle\">겹침 약 53퍼센트<\/text>\n<text class=\"tm b1\" x=\"80\" y=\"198\" font-size=\"13\" text-anchor=\"middle\">임베딩 다름<\/text>\n<text class=\"tm b2\" x=\"235\" y=\"198\" font-size=\"13\" text-anchor=\"middle\">조금 비슷<\/text>\n<text class=\"tb b4\" x=\"240\" y=\"238\" font-size=\"15\" text-anchor=\"middle\">재료가 같아지면 결과도 같아져요<\/text>\n<\/svg>","caption":"노란 점 둘이 관심 노드예요. 원이 각자의 **수용 영역(Receptive Field)**이고, 겹치는 부분이 공유 이웃이에요.","builds":4},{"kind":"steps","head":"겹침 비율을 손으로 계산","steps":["노드 100 개인 그래프에서 한 노드의 수용 영역 크기를 p.16 표에서 가져와요.","1홉이면 5 개이니 전체의 5퍼센트예요.","두 노드가 무관하게 퍼진다고 보면 겹칠 개수는 $100 \\times 0.05 \\times 0.05 = 0.25$ 개예요.","2홉이면 17퍼센트이니 $100 \\times 0.17 \\times 0.17 = 2.89$ 개예요.","3홉이면 53퍼센트이니 $100 \\times 0.53 \\times 0.53 = 28.1$ 개예요.","이걸 수용 영역 크기로 나누면 겹침 비율이 5, 17, 53퍼센트로 나와요."],"answer":"3층에서 이미 재료의 절반 이상이 공통이에요. 4층이면 사실상 전부 같아요.","given":"노드 100 개, 평균 차수 4 인 그래프에서 두 노드를 고른 경우예요."},{"kind":"mining","src":"마이닝 6강 Link Prediction","lines":["'두 노드의 이웃이 얼마나 겹치나'는 마이닝에서 아주 익숙한 양이에요.","공통 이웃 개수를 세서 '이 둘이 앞으로 친구가 될까'를 예측했죠.","재미있는 반전이 있어요. 마이닝에서는 겹침이 크면 **좋은 신호**였어요.","GNN에서는 겹침이 크면 **나쁜 신호**예요. 같은 양인데 해석이 반대예요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"If two nodes have highly overlapped receptive fields, their embeddings become highly similar.","ko":"두 노드의 수용 영역이 많이 겹치면 두 임베딩은 매우 비슷해진다.","tip":"highly overlapped 라는 슬라이드 표현을 그대로 쓰면 돼요."},{"kind":"warn","head":"계산의 근사에 주의하세요","items":["겹침 개수를 $100 p^2$ 로 잡은 것은 '두 수용 영역이 무관하게 퍼진다'는 가정이에요.","실제로 두 노드가 가까우면 훨씬 더 많이 겹쳐요.","답안에는 숫자보다 논리를 쓰세요. '수용 영역이 지수로 커진다, 그래서 겹친다, 그래서 같아진다'예요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.7717,0.3324],"c":[0,0.0012,0.8489,0.3657],"r":4.1268,"img":"img/L5/walk/p017_h.jpg"},"parts":[{"b":[0.055,0.463,0.26,0.05],"c":[0.042,0.433,0.286,0.11],"r":4.6222,"img":"img/L5/walk/p017_11_01.jpg","say":"'1홉 이웃 겹침 단 1개 노드'."},{"b":[0.365,0.463,0.23,0.09],"c":[0.353,0.447,0.254,0.122],"r":3.7013,"img":"img/L5/walk/p017_11_02.jpg","say":"'2홉 이웃 겹침 약 20개 노드'."},{"b":[0.72,0.463,0.23,0.09],"c":[0.708,0.447,0.254,0.122],"r":3.7013,"img":"img/L5/walk/p017_11_03.jpg","say":"'3홉 이웃 겹침 거의 모든 노드!' 스무 배씩 늘어나요."}]}},{"p":18,"title":"평활화의 공간 관점: 랜덤워크","terms":["Over-smoothing","Random Walk","Stationary Distribution","Self-loop","Degree","Small-world","Adjacency Matrix"],"pass1":[{"kind":"say","lines":["GNN의 메시지 패싱은 수학적으로 그래프 위 **랜덤워크(Random Walk)**와 같아요.","**랜덤워크(Random Walk)**는 '매 걸음 이웃 하나를 무작위로 골라 이동하는 것'이에요.","층을 무한히 쌓으면 그 워크가 섞여 버려서 노드의 개성이 사라져요."]},{"kind":"analogy","head":"욕조에 떨어뜨린 물감 한 방울","scene":"커다란 욕조에 파란 물감 한 방울을 떨어뜨려요. 처음에는 그 자리만 진한 파랑이에요. 시간이 지나면 조금씩 퍼져서 주변이 옅은 파랑이 되죠. 아주 오래 두면 욕조 전체가 균일한 아주 옅은 파랑이 돼요. 이제 어느 곳의 물을 떠도 색이 똑같아요.","map":[["물감 한 방울","한 노드의 특징"],["시간이 지나며 퍼지는 것","층을 쌓는 **메시지 패싱(Message Passing)**"],["전체가 균일해진 상태","**정상 분포(Stationary Distribution)**로의 수렴"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"formula","head":"랜덤워크 행렬을 기호 하나씩","tex":"\\tilde{A}_{rw} = \\tilde{D}^{-1} \\tilde{A}","parts":[{"sym":"\\tilde{A}","say":"**자기 고리(Self-loop)**를 더한 **인접행렬(Adjacency Matrix)**이에요."},{"sym":"\\tilde{D}","say":"각 노드의 **차수(Degree)**를 대각선에 놓은 행렬이에요."},{"sym":"\\tilde{D}^{-1}","say":"대각선 값을 각각 역수로 바꾼 것이에요."},{"sym":"\\tilde{A}_{rw}","say":"행 정규화된 인접행렬이에요. 각 행의 합이 1 이 돼요."}],"whole":"하는 일은 간단해요. '인접행렬의 각 행을 그 행의 합으로 나눈다'예요. 그러면 확률처럼 읽을 수 있어요."},{"kind":"figure","head":"신호가 층을 거치며 평평해진다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tm\" x=\"40\" y=\"28\" font-size=\"14\" text-anchor=\"middle\">층<\/text>\n<text class=\"tm\" x=\"120\" y=\"28\" font-size=\"14\" text-anchor=\"middle\">노드1<\/text>\n<text class=\"tm\" x=\"210\" y=\"28\" font-size=\"14\" text-anchor=\"middle\">노드2<\/text>\n<text class=\"tm\" x=\"300\" y=\"28\" font-size=\"14\" text-anchor=\"middle\">노드3<\/text>\n<text class=\"tm\" x=\"390\" y=\"28\" font-size=\"14\" text-anchor=\"middle\">노드4<\/text>\n<text class=\"t\" x=\"40\" y=\"62\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<rect class=\"box2\" x=\"78\" y=\"44\" width=\"84\" height=\"26\" rx=\"5\"/>\n<rect class=\"box\" x=\"168\" y=\"44\" width=\"84\" height=\"26\" rx=\"5\"/>\n<rect class=\"box\" x=\"258\" y=\"44\" width=\"84\" height=\"26\" rx=\"5\"/>\n<rect class=\"box\" x=\"348\" y=\"44\" width=\"84\" height=\"26\" rx=\"5\"/>\n<text class=\"tb\" x=\"120\" y=\"63\" font-size=\"14\" text-anchor=\"middle\">1.000<\/text>\n<text class=\"t\" x=\"210\" y=\"63\" font-size=\"14\" text-anchor=\"middle\">0.000<\/text>\n<text class=\"t\" x=\"300\" y=\"63\" font-size=\"14\" text-anchor=\"middle\">0.000<\/text>\n<text class=\"t\" x=\"390\" y=\"63\" font-size=\"14\" text-anchor=\"middle\">0.000<\/text>\n<text class=\"t b1\" x=\"40\" y=\"106\" font-size=\"15\" text-anchor=\"middle\">1<\/text>\n<rect class=\"box2 b1\" x=\"78\" y=\"88\" width=\"84\" height=\"26\" rx=\"5\"/>\n<rect class=\"box b1\" x=\"168\" y=\"88\" width=\"84\" height=\"26\" rx=\"5\"/>\n<rect class=\"box b1\" x=\"258\" y=\"88\" width=\"84\" height=\"26\" rx=\"5\"/>\n<rect class=\"box b1\" x=\"348\" y=\"88\" width=\"84\" height=\"26\" rx=\"5\"/>\n<text class=\"tb b1\" x=\"120\" y=\"107\" font-size=\"14\" text-anchor=\"middle\">0.500<\/text>\n<text class=\"t b1\" x=\"210\" y=\"107\" font-size=\"14\" text-anchor=\"middle\">0.333<\/text>\n<text class=\"t b1\" x=\"300\" y=\"107\" font-size=\"14\" text-anchor=\"middle\">0.000<\/text>\n<text class=\"t b1\" x=\"390\" y=\"107\" font-size=\"14\" text-anchor=\"middle\">0.000<\/text>\n<text class=\"t b2\" x=\"40\" y=\"150\" font-size=\"15\" text-anchor=\"middle\">2<\/text>\n<rect class=\"box2 b2\" x=\"78\" y=\"132\" width=\"84\" height=\"26\" rx=\"5\"/>\n<rect class=\"box b2\" x=\"168\" y=\"132\" width=\"84\" height=\"26\" rx=\"5\"/>\n<rect class=\"box b2\" x=\"258\" y=\"132\" width=\"84\" height=\"26\" rx=\"5\"/>\n<rect class=\"box b2\" x=\"348\" y=\"132\" width=\"84\" height=\"26\" rx=\"5\"/>\n<text class=\"tb b2\" x=\"120\" y=\"151\" font-size=\"14\" text-anchor=\"middle\">0.417<\/text>\n<text class=\"t b2\" x=\"210\" y=\"151\" font-size=\"14\" text-anchor=\"middle\">0.278<\/text>\n<text class=\"t b2\" x=\"300\" y=\"151\" font-size=\"14\" text-anchor=\"middle\">0.111<\/text>\n<text class=\"t b2\" x=\"390\" y=\"151\" font-size=\"14\" text-anchor=\"middle\">0.000<\/text>\n<text class=\"t b3\" x=\"40\" y=\"194\" font-size=\"15\" text-anchor=\"middle\">3<\/text>\n<rect class=\"box2 b3\" x=\"78\" y=\"176\" width=\"84\" height=\"26\" rx=\"5\"/>\n<rect class=\"box b3\" x=\"168\" y=\"176\" width=\"84\" height=\"26\" rx=\"5\"/>\n<rect class=\"box b3\" x=\"258\" y=\"176\" width=\"84\" height=\"26\" rx=\"5\"/>\n<rect class=\"box b3\" x=\"348\" y=\"176\" width=\"84\" height=\"26\" rx=\"5\"/>\n<text class=\"tb b3\" x=\"120\" y=\"195\" font-size=\"14\" text-anchor=\"middle\">0.347<\/text>\n<text class=\"t b3\" x=\"210\" y=\"195\" font-size=\"14\" text-anchor=\"middle\">0.269<\/text>\n<text class=\"t b3\" x=\"300\" y=\"195\" font-size=\"14\" text-anchor=\"middle\">0.130<\/text>\n<text class=\"t b3\" x=\"390\" y=\"195\" font-size=\"14\" text-anchor=\"middle\">0.056<\/text>\n<rect class=\"box2 b4\" x=\"78\" y=\"216\" width=\"354\" height=\"30\" rx=\"6\"/>\n<text class=\"tb b4\" x=\"255\" y=\"236\" font-size=\"15\" text-anchor=\"middle\">극한에서는 넷 다 0.200, 구별 불가<\/text>\n<\/svg>","caption":"노드 1 에만 1 을 주고 출발했어요. 층마다 이웃 평균을 내면 값들이 점점 가까워져요.","builds":4},{"kind":"steps","head":"노드 넷으로 랜덤워크를 돌려 보기","steps":["노드 넷을 한 줄로 이어요. **자기 고리(Self-loop)**를 더하면 **차수(Degree)**가 2, 3, 3, 2 예요.","행 1 은 나와 2 번에 각각 절반씩이에요. 행 2 는 1, 2, 3 에 각각 3분의 1 씩이에요.","출발은 노드 1 에만 1, 나머지 0 이에요.","층 1 의 노드 1 은 $(1 + 0) \\div 2 = 0.5$, 노드 2 는 $(1 + 0 + 0) \\div 3 \\approx 0.333$ 이에요.","층 2 의 노드 1 은 $(0.5 + 0.333) \\div 2 \\approx 0.417$, 노드 3 은 $0.333 \\div 3 \\approx 0.111$ 이에요.","층 3 은 0.347, 0.269, 0.130, 0.056 이에요. 최대와 최소 차이가 1.0 에서 0.29 로 줄었어요."],"answer":"극한에서는 넷 다 0.2 가 돼요. **차수(Degree)** 2, 3, 3, 2 를 합이 10 으로 나눈 것이 **정상 분포(Stationary Distribution)**거든요.","given":"노드 네 개를 한 줄로 이은 그래프예요."},{"kind":"mining","src":"마이닝 3강 Centrality, 마이닝 10강 Random Walk-based GRL","lines":["PageRank 가 바로 이 **랜덤워크(Random Walk)**의 **정상 분포(Stationary Distribution)**를 찾는 알고리즘이에요.","수렴할 때까지 반복해서 값을 갱신했던 그 계산이요.","차이는 목적이에요. PageRank 는 수렴한 값을 **중요도 점수로 쓰려고** 반복했어요.","GNN은 수렴하면 노드를 구별할 수 없어서 망해요. 같은 수학, 정반대 평가예요."]}],"pass3":[{"kind":"warn","head":"슬라이드의 마지막 줄은 조심해서 읽으세요","items":["'모든 노드의 특징 벡터가 차수에 정확히 비례한다'고 적혀 있어요.","차수에 비례하는 것은 **정상 분포(Stationary Distribution)**예요. 랜덤워크가 어디에 머무르는가의 이야기죠.","슬라이드가 쓴 행 정규화로 특징을 전파하면 특징은 네 노드 모두 **같은 상수**로 수렴해요. 위 예에서 전부 0.2 였죠.","차수의 제곱근에 비례하게 되는 것은 대칭 정규화를 쓸 때예요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Stacking l GCN layers is the same as taking l steps of a random walk on the graph.","ko":"GCN 층을 l개 쌓는 것은 그래프 위에서 랜덤워크를 l걸음 걷는 것과 같다.","tip":"is the same as taking l steps 라는 표현이 깔끔해요."},{"kind":"check","q":"**정상 분포(Stationary Distribution)**가 뜻하는 것은 무엇인가요?","choices":["랜덤워크를 아주 오래 돌렸을 때 각 노드에 머무를 확률","노드의 초기 특징","가중치 행렬의 고윳값","층의 개수"],"a":0,"why":"위 예에서 차수 2, 3, 3, 2 를 합 10 으로 나눈 0.2, 0.3, 0.3, 0.2 가 그것이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.3968,0.0757],"c":[0,0.0019,0.4365,0.1077],"r":7.2052,"img":"img/L5/walk/p018_h.jpg"},"parts":[{"b":[0.055,0.146,0.89,0.078],"c":[0.0105,0.0861,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p018_20_01.jpg","say":"'개념: 수용 영역이 그래프 전체를 덮을 만큼 커져서 국소 특징이 씻겨 나가요.'"},{"b":[0.055,0.278,0.89,0.078],"c":[0.0105,0.2181,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p018_20_02.jpg","say":"'메커니즘: GNN 메시지 패싱은 수학적으로 그래프 위 랜덤워크와 같아요.'"},{"b":[0.44,0.386,0.13,0.048],"c":[0.405,0.355,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p018_20_03.jpg","say":"가운데 식이 행 정규화된 인접행렬이에요. rw 는 random walk 예요."},{"b":[0.055,0.463,0.89,0.082],"c":[0.0105,0.4051,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p018_20_04.jpg","say":"'실제 데이터 대부분은 좁은 세상 성질이라 랜덤워크가 빠르게 섞여요.'"},{"b":[0.055,0.59,0.89,0.082],"c":[0.0105,0.5321,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p018_20_05.jpg","say":"'결과: 층이 무한히 깊어지면 노드 표현이 정상 분포로 수렴해요.'"}]}},{"p":19,"title":"평활화의 스펙트럼 관점: 저역 통과 필터","terms":["Over-smoothing","Low-pass Filter","Graph Laplacian","Eigenvalue","Self-loop","GCN"],"pass1":[{"kind":"say","lines":["같은 현상을 이번에는 '주파수'의 말로 봐요.","그래프 합성곱은 **저역 통과 필터(Low-pass Filter)**예요. 빠르게 변하는 성분을 깎아요.","음악에 비유하면 앞 슬라이드는 '소리가 퍼진다', 이번은 '고음이 깎인다'예요."]},{"kind":"analogy","head":"고음만 죽이는 이퀄라이저","scene":"스피커에 이퀄라이저가 달려 있어요. 여기서 고음 손잡이를 0 으로 내리면 치찰음이나 심벌즈 소리가 사라져요. 저음만 남으니 소리가 웅웅거리죠. 이 손잡이를 노래를 틀 때마다 매번 내리면, 여러 번 반복한 끝에는 거의 저음만 남아요.","map":[["고음","이웃끼리 값이 다른 성분"],["고음 손잡이를 내리기","**저역 통과 필터(Low-pass Filter)** 한 번 통과"],["매번 반복해서 내리기","층을 여러 개 쌓기"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"formula","head":"정규화 그래프 라플라시안","tex":"\\tilde{L} = I - \\tilde{D}^{-\\frac{1}{2}} \\tilde{A} \\tilde{D}^{-\\frac{1}{2}}","parts":[{"sym":"I","say":"단위행렬이에요. 대각선이 1, 나머지가 0 이에요."},{"sym":"\\tilde{D}^{-1/2}","say":"**차수(Degree)**의 제곱근의 역수를 대각선에 놓은 행렬이에요."},{"sym":"\\tilde{L}","say":"**그래프 라플라시안(Graph Laplacian)**이에요. **고윳값(Eigenvalue)**이 0 이상 2 이하예요."},{"sym":"\\lambda_i","say":"$i$ 번째 **고윳값(Eigenvalue)**이에요. 클수록 고주파예요."}],"whole":"집계 행렬은 $I - \\tilde{L}$ 이고 그 **고윳값(Eigenvalue)**은 $1 - \\lambda_i$ 예요. $l$ 층 지나면 $(1-\\lambda_i)^l$ 배가 돼요."},{"kind":"figure","head":"고윳값에 따른 필터 배율","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<line class=\"e\" x1=\"60\" y1=\"140\" x2=\"440\" y2=\"140\"/>\n<line class=\"e\" x1=\"60\" y1=\"40\" x2=\"60\" y2=\"240\"/>\n<text class=\"tm\" x=\"46\" y=\"46\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"tm\" x=\"46\" y=\"145\" font-size=\"14\" text-anchor=\"middle\">0<\/text>\n<text class=\"tm\" x=\"42\" y=\"244\" font-size=\"14\" text-anchor=\"middle\">-1<\/text>\n<text class=\"tm\" x=\"62\" y=\"160\" font-size=\"14\">0<\/text>\n<text class=\"tm\" x=\"240\" y=\"160\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"tm\" x=\"438\" y=\"160\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tm\" x=\"250\" y=\"182\" font-size=\"14\" text-anchor=\"middle\">고윳값<\/text>\n<line class=\"e2 b1\" x1=\"60\" y1=\"40\" x2=\"440\" y2=\"240\"/>\n<circle class=\"n2 b2\" cx=\"60\" cy=\"40\" r=\"8\"/>\n<text class=\"tb b2\" x=\"76\" y=\"36\" font-size=\"14\">0 이면 배율 1, 절대 안 죽음<\/text>\n<circle class=\"n2 b3\" cx=\"250\" cy=\"140\" r=\"8\"/>\n<text class=\"tb b3\" x=\"266\" y=\"132\" font-size=\"14\">1 이면 배율 0, 즉시 사라짐<\/text>\n<circle class=\"n4 b4\" cx=\"440\" cy=\"240\" r=\"8\"/>\n<text class=\"tb b4\" x=\"180\" y=\"262\" font-size=\"14\">2 이면 배율 -1, 크기가 그대로<\/text>\n<\/svg>","caption":"가로축이 **고윳값(Eigenvalue)**, 세로축이 한 층당 배율이에요. 0 이면 1 배, 1 이면 0 배, 2 이면 -1 배예요.","builds":4},{"kind":"steps","head":"노드 셋으로 고윳값을 직접 구하기","steps":["노드 세 개를 한 줄로 이어요. **차수(Degree)**가 1, 2, 1 이에요.","첫 번째 고유벡터를 1, 루트2, 1 로 잡으면 곱해도 그대로예요. 배율이 1 이니 고윳값은 $1 - 1 = 0$ 이에요.","두 번째를 1, 0, -1 로 잡으면 곱한 결과가 전부 0 이에요. 배율이 0 이니 고윳값은 $1 - 0 = 1$ 이에요.","세 번째를 1, 마이너스 루트2, 1 로 잡으면 부호가 뒤집혀요. 배율이 -1 이니 고윳값은 $1 - (-1) = 2$ 예요.","그러니 세 고윳값이 0, 1, 2 예요. 필터 배율은 차례로 1, 0, -1 이에요."],"answer":"고윳값 1 인 성분은 한 층에 사라지고, 고윳값 2 인 성분은 크기가 전혀 줄지 않고 부호만 뒤집혀요.","given":"노드 세 개를 한 줄로 이은 그래프예요. **자기 고리(Self-loop)**는 넣지 않았어요."},{"kind":"mining","src":"마이닝 5강 Community Detection","lines":["**그래프 라플라시안(Graph Laplacian)**의 고유벡터는 스펙트럴 클러스터링에서 이미 만났어요.","그래프를 두 덩어리로 자르는 문제를 풀면 답이 그 고유벡터로 나왔거든요.","위에서 구한 1, 0, -1 을 보세요. 양끝의 부호가 반대예요. '여기를 가르면 좋다'는 정보죠.","그런데 **GCN**은 이 성분을 한 층만에 0 으로 지워 버려요. 가르는 데 필요한 정보를 깎는 셈이에요."]}],"pass3":[{"kind":"warn","head":"이 슬라이드의 마지막 줄에는 수학적 오류가 있어요","items":["'모든 고윳값이 0보다 크면 배율의 크기가 1보다 작다'고 적혀 있어요.","그런데 **고윳값(Eigenvalue)**이 정확히 2 이면 배율이 -1 이라 크기가 1 이에요. 1 보다 작지 않아요.","그러면 층을 아무리 쌓아도 그 성분은 **크기가 줄지 않아요**. 부호만 번갈아 바뀔 뿐이에요.","고윳값이 정확히 2 가 되는 것은 그래프에 이분 성분이 있을 때예요. 위 예의 한 줄 그래프가 그런 경우예요."]},{"kind":"points","head":"바르게 고쳐 쓰면","items":["'고윳값이 0 보다 크고 2 보다 작은 성분은 지수적으로 감쇠한다'가 정확한 문장이에요.","그리고 실제로는 **자기 고리(Self-loop)**를 넣으니 최대 고윳값이 2 보다 엄격히 작아져요.","노드 둘짜리 그래프로 확인하면, 자기 고리가 없을 때 고윳값이 0 과 2 예요.","자기 고리를 넣으면 0 과 1 로 내려가요. 그래서 예외가 사라져요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Graph convolution acts as a low-pass filter, so high-frequency components decay exponentially with depth.","ko":"그래프 합성곱은 저역 통과 필터로 작동하므로 고주파 성분이 깊이에 따라 지수적으로 감쇠한다.","tip":"acts as a low-pass filter 를 통째로 외워 두세요."},{"kind":"check","q":"**고윳값(Eigenvalue)**이 클수록 그 성분은 어떤 신호인가요?","choices":["이웃끼리 값이 비슷한 매끄러운 신호","이웃끼리 값이 크게 다른 고주파 신호","항상 0 인 신호","노드 개수에 비례하는 신호"],"a":1,"why":"큰 고윳값에 딸린 고유벡터가 엣지를 건널 때 값이 빠르게 변하는 신호예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4472,0.0757],"c":[0,0.0019,0.492,0.1077],"r":8.1213,"img":"img/L5/walk/p019_h.jpg"},"parts":[{"b":[0.055,0.146,0.89,0.078],"c":[0.0105,0.0861,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p019_20_01.jpg","say":"'개념: 그래프 합성곱은 엄격한 저역 통과 필터로 작동해요.'"},{"b":[0.055,0.278,0.48,0.04],"c":[0.031,0.243,0.528,0.11],"r":8.5333,"img":"img/L5/walk/p019_20_02.jpg","say":"'그래프 라플라시안 스펙트럼: 정규화 그래프 라플라시안을 생각해요.'"},{"b":[0.4,0.34,0.19,0.05],"c":[0.388,0.31,0.214,0.11],"r":3.4586,"img":"img/L5/walk/p019_20_03.jpg","say":"가운데 식이 정규화 그래프 라플라시안이에요."},{"b":[0.07,0.432,0.88,0.075],"c":[0.026,0.3717,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p019_20_04.jpg","say":"'고윳값이 0 이상 2 이하예요. 큰 고윳값에 딸린 고유벡터가 고주파 신호예요.'"},{"b":[0.055,0.558,0.89,0.075],"c":[0.0105,0.4966,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p019_20_05.jpg","say":"'주파수 감쇠: 이 필터를 l 번 곱하면 i번째 성분이 그만큼 줄어요.'"},{"b":[0.055,0.691,0.89,0.075],"c":[0.0105,0.6296,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p019_20_06.jpg","say":"'결과: 고주파 성분이 지수적으로 사라지고 매끄러운 성분만 남아요.'"}]}},{"p":20,"title":"평활화를 재는 자 두 개","terms":["Over-smoothing","Dirichlet Energy","MAD","Graph Laplacian","Embedding"],"pass1":[{"kind":"say","lines":["평활화가 얼마나 진행됐는지 재는 자가 두 개예요.","**디리클레 에너지(Dirichlet Energy)**는 '이어진 노드끼리 얼마나 다른가'를 전부 더한 값이에요.","**MAD**는 노드 표현들 사이의 평균 코사인 거리, 즉 각도만 보는 자예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.055,"y":0.14,"w":0.76,"h":0.04,"say":"'완화 전략을 평가하려고 과도한 평활화를 수치화해요.'","c":[0.017,0.0756,0.836,0.1689],"r":8.7994,"img":"img/L5/walk/p020_20_01.jpg"},{"x":0.09,"y":0.278,"w":0.56,"h":0.038,"say":"'노드 임베딩이 엣지를 건너며 얼마나 변하는지 그 총량을 재요.'","c":[0.062,0.2348,0.616,0.1245],"r":8.7961,"img":"img/L5/walk/p020_20_02.jpg"},{"x":0.27,"y":0.323,"w":0.47,"h":0.08,"say":"디리클레 에너지 식이에요. 엣지마다 차이의 제곱을 더해요.","c":[0.2465,0.307,0.517,0.112],"r":8.2063,"img":"img/L5/walk/p020_20_03.jpg"},{"x":0.085,"y":0.43,"w":0.82,"h":0.04,"say":"'에너지 극한이 0 이면 공간이 완전히 무너진 것이고 평활화가 심각해요.'","c":[0.044,0.3589,0.902,0.1822],"r":8.8011,"img":"img/L5/walk/p020_20_04.jpg"},{"x":0.09,"y":0.543,"w":0.78,"h":0.038,"say":"'노드 표현 사이의 평균 코사인 거리를 재서 크기와 무관하게 수치화해요.'","c":[0.051,0.4753,0.858,0.1733],"r":8.8017,"img":"img/L5/walk/p020_20_05.jpg"},{"x":0.39,"y":0.617,"w":0.21,"h":0.075,"say":"MAD 식이에요. 1 에서 코사인 유사도를 뺀 값이에요.","c":[0.378,0.5995,0.234,0.11],"r":3.7818,"img":"img/L5/walk/p020_20_06.jpg"}]},{"kind":"formula","head":"디리클레 에너지를 기호 하나씩","tex":"E\\left(H^{(l)}\\right) = \\frac{1}{2} \\sum_{(u,v) \\in \\mathcal{E}} A_{uv} \\left\\| h_u^{(l)} - h_v^{(l)} \\right\\|^2","parts":[{"sym":"E(H^{(l)})","say":"층 $l$ 에서의 **디리클레 에너지(Dirichlet Energy)**, 숫자 하나예요."},{"sym":"\\frac{1}{2}","say":"엣지 하나를 양방향으로 두 번 세니까 반으로 나눠요."},{"sym":"A_{uv}","say":"엣지가 있으면 1, 없으면 0 이에요."},{"sym":"\\| h_u - h_v \\|^2","say":"두 벡터 차이의 각 칸을 제곱해서 더한 값이에요."}],"whole":"우리말로 하면 '이어져 있는 두 노드의 **임베딩(Embedding)**이 얼마나 다른지를 전부 더한 값'이에요. 0 이 되면 완전한 평활화예요."},{"kind":"formula","head":"MAD 를 기호 하나씩","tex":"D(h_i, h_j) = 1 - \\frac{h_i \\cdot h_j}{\\|h_i\\| \\|h_j\\|}","parts":[{"sym":"h_i \\cdot h_j","say":"두 벡터의 내적이에요. 칸끼리 곱해서 더해요."},{"sym":"\\|h_i\\|","say":"$h_i$ 의 길이예요. 각 칸을 제곱해 더한 뒤 제곱근을 씌워요."},{"sym":"\\frac{h_i \\cdot h_j}{\\|h_i\\|\\|h_j\\|}","say":"코사인 유사도예요. 두 벡터가 이루는 각도의 코사인이죠."},{"sym":"1 - (\\cdot)","say":"유사도를 거리로 뒤집어요. 같은 방향이면 0 이 돼요."}],"whole":"**MAD**는 방향만 봐요. 그래서 모든 값이 절반으로 줄어도 **MAD**는 변하지 않아요."},{"kind":"figure","head":"두 지표가 함께 0 을 향해 떨어진다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<line class=\"e\" x1=\"60\" y1=\"210\" x2=\"430\" y2=\"210\"/>\n<line class=\"e\" x1=\"60\" y1=\"40\" x2=\"60\" y2=\"210\"/>\n<text class=\"tm\" x=\"60\" y=\"232\" font-size=\"14\" text-anchor=\"middle\">층 0<\/text>\n<text class=\"tm\" x=\"240\" y=\"232\" font-size=\"14\" text-anchor=\"middle\">층 1<\/text>\n<text class=\"tm\" x=\"410\" y=\"232\" font-size=\"14\" text-anchor=\"middle\">층 2<\/text>\n<polyline class=\"e2 b1\" points=\"60,50 240,184 410,205\" fill=\"none\"/>\n<circle class=\"n2 b1\" cx=\"60\" cy=\"50\" r=\"8\"/>\n<circle class=\"n2 b1\" cx=\"240\" cy=\"184\" r=\"8\"/>\n<circle class=\"n2 b1\" cx=\"410\" cy=\"205\" r=\"8\"/>\n<text class=\"tb b1\" x=\"76\" y=\"46\" font-size=\"14\">디리클레 에너지 2.00, 0.32, 0.05<\/text>\n<polyline class=\"e2 b2\" points=\"60,50 240,166 410,202\" fill=\"none\"/>\n<circle class=\"n3 b2\" cx=\"240\" cy=\"166\" r=\"8\"/>\n<circle class=\"n3 b2\" cx=\"410\" cy=\"202\" r=\"8\"/>\n<text class=\"tb b2\" x=\"120\" y=\"112\" font-size=\"14\">MAD 1.00, 0.28, 0.05<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"258\" font-size=\"15\" text-anchor=\"middle\">둘 다 0 을 향해 떨어지면 한 점으로 붕괴<\/text>\n<\/svg>","caption":"노드 둘짜리 그래프로 계산한 값이에요. 층마다 두 지표가 나란히 줄어들어요.","builds":3},{"kind":"steps","head":"두 지표를 직접 계산","steps":["노드 둘의 시작 값이 각각 (1, 0) 과 (0, 1) 이에요. 층마다 내 것 70퍼센트에 상대 것 30퍼센트를 섞어요.","층 1 은 (0.7, 0.3) 과 (0.3, 0.7) 이에요.","층 2 는 $0.7 \\times 0.7 + 0.3 \\times 0.3 = 0.58$ 식으로 (0.58, 0.42) 와 (0.42, 0.58) 이에요.","에너지는 차이 제곱이에요. 층 0 은 $1 + 1 = 2$, 층 1 은 $0.16 + 0.16 = 0.32$ 예요.","층 2 는 $0.0256 + 0.0256 = 0.0512$ 예요. 층마다 0.16 배씩 줄어요.","MAD 는 층 0 이 1, 층 1 이 $1 - 0.42 \\div 0.58 \\approx 0.276$, 층 2 가 약 0.050 이에요."],"answer":"에너지는 2, 0.32, 0.0512. MAD 는 1.00, 0.276, 0.050. 두 지표가 나란히 0 을 향해요.","given":"노드 둘과 엣지 하나짜리 아주 작은 그래프예요."}],"pass3":[{"kind":"warn","head":"슬라이드의 에너지 식에는 기호가 어긋난 곳이 있어요","items":["왼쪽의 합 형태는 **정규화하지 않은** 라플라시안을 써야 오른쪽 트레이스 형태와 같아져요.","슬라이드는 오른쪽에 정규화된 **그래프 라플라시안(Graph Laplacian)**을 썼어요.","정규화 버전으로 맞추려면 차이를 각 노드 차수의 제곱근으로 나눠야 해요.","시험에서는 왼쪽 합 형태만 정확히 쓰면 충분해요."]},{"kind":"warn","head":"두 지표를 함께 봐야 하는 이유","items":["**디리클레 에너지(Dirichlet Energy)**는 임베딩을 전부 절반으로 줄이기만 해도 4분의 1 이 돼요.","구별은 유지되는데도 에너지만 작아지는 거죠.","**MAD**는 방향만 보니 이 함정이 없어요. 그래서 둘을 같이 봐요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Over-smoothing is measured by Dirichlet energy and by Mean Average Distance; both going to zero means the nodes have collapsed.","ko":"과도한 평활화는 디리클레 에너지와 평균 코사인 거리로 측정하며, 둘 다 0 으로 가면 노드들이 붕괴한 것이다.","tip":"Dirichlet energy 와 Mean Average Distance 두 이름을 정확히 쓰세요."},{"kind":"check","q":"**MAD**가 **디리클레 에너지(Dirichlet Energy)**보다 나은 점은 무엇인가요?","choices":["계산이 빠르다","벡터의 크기 변화에 속지 않는다","그래프 구조를 본다","층 수를 알려 준다"],"a":1,"why":"**MAD**는 각도만 재요. 전부 절반이 되어도 각도는 그대로라 값이 변하지 않아요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.953,0.2015],"c":[0,0.0019,1,0.2335],"r":7.6136,"img":"img/L5/walk/p020_h.jpg"},"parts":[{"b":[0.075,0.225,0.2,0.04],"c":[0.063,0.19,0.224,0.11],"r":3.6202,"img":"img/L5/walk/p020_11_01.jpg","say":"'지표 1: 디리클레 에너지'."},{"b":[0.075,0.491,0.29,0.042],"c":[0.0605,0.457,0.319,0.11],"r":5.1556,"img":"img/L5/walk/p020_11_02.jpg","say":"'지표 2: 평균 코사인 거리 (MAD)'."}]}},{"p":21,"title":"과도한 압착: 수용 영역의 폭발","terms":["Over-squashing","Receptive Field","Bottleneck","Over-smoothing"],"pass1":[{"kind":"say","lines":["이제 반대편 고장인 **과도한 압착(Over-squashing)**으로 넘어가요.","$k$ 홉 이웃의 크기는 지수로 커지는데, 그걸 담는 벡터 길이는 고정이에요.","그래서 먼 노드의 신호가 쥐어짜여서 사라져요."]},{"kind":"analogy","head":"수백 명의 이야기를 쪽지 한 장에","scene":"전교생 500명에게 소풍 장소 의견을 받아요. 그런데 교장 선생님께 드릴 종이는 딱 한 장뿐이에요. 열 명이면 한 줄씩 적지만, 500명이면 한 사람당 글자 몇 개도 못 적죠.","map":[["전교생 500명","지수로 커진 $k$ 홉 이웃"],["종이 한 장","고정 길이 노드 특징 벡터"],["사라진 개별 의견","**과도한 압착(Over-squashing)**"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.055,"y":0.14,"w":0.89,"h":0.07,"say":"'수용 영역 폭발 현상: 한 노드의 k홉 이웃 크기는 반지름에 따라 지수로 커져요.'","c":[0.0105,0.0761,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p021_20_01.jpg"},{"x":0.055,"y":0.225,"w":0.89,"h":0.071,"say":"'핵심 갈등 지점: 그 정보를 전부 고정 길이 벡터 하나에 압축해 넣어야 해요.'","c":[0.0105,0.1616,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p021_20_02.jpg"},{"x":0.055,"y":0.36,"w":0.89,"h":0.072,"say":"'결과 과도한 압착: 멀리 있는 노드의 중요한 신호가 눌려 사라져요.'","c":[0.0105,0.2971,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p021_20_03.jpg"},{"x":0.194,"y":0.506,"w":0.285,"h":0.334,"say":"(a) RNN seq2seq 모델의 병목이에요.","c":[0.1798,0.4893,0.3135,0.3674],"r":1.517,"img":"img/L5/walk/p021_20_04.jpg"},{"x":0.528,"y":0.506,"w":0.257,"h":0.334,"say":"(b) 그래프 신경망의 병목이에요. 여러 갈래가 한 지점을 통과해요.","c":[0.5152,0.4893,0.2827,0.3674],"r":1.3679,"img":"img/L5/walk/p021_20_05.jpg"}]},{"kind":"figure","head":"지수로 커지는데 담을 곳은 고정","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<circle class=\"n b1\" cx=\"30\" cy=\"34\" r=\"8\"/>\n<circle class=\"n b1\" cx=\"30\" cy=\"62\" r=\"8\"/>\n<circle class=\"n b1\" cx=\"30\" cy=\"90\" r=\"8\"/>\n<circle class=\"n b1\" cx=\"30\" cy=\"118\" r=\"8\"/>\n<circle class=\"n b1\" cx=\"30\" cy=\"146\" r=\"8\"/>\n<circle class=\"n b1\" cx=\"30\" cy=\"174\" r=\"8\"/>\n<circle class=\"n b1\" cx=\"30\" cy=\"202\" r=\"8\"/>\n<circle class=\"n b1\" cx=\"30\" cy=\"230\" r=\"8\"/>\n<circle class=\"n b2\" cx=\"130\" cy=\"48\" r=\"10\"/>\n<circle class=\"n b2\" cx=\"130\" cy=\"104\" r=\"10\"/>\n<circle class=\"n b2\" cx=\"130\" cy=\"160\" r=\"10\"/>\n<circle class=\"n b2\" cx=\"130\" cy=\"216\" r=\"10\"/>\n<circle class=\"n b3\" cx=\"224\" cy=\"76\" r=\"12\"/>\n<circle class=\"n b3\" cx=\"224\" cy=\"188\" r=\"12\"/>\n<circle class=\"n2 b4\" cx=\"310\" cy=\"132\" r=\"16\"/>\n<line class=\"e b2\" x1=\"38\" y1=\"34\" x2=\"122\" y2=\"44\"/>\n<line class=\"e b2\" x1=\"38\" y1=\"62\" x2=\"122\" y2=\"52\"/>\n<line class=\"e b2\" x1=\"38\" y1=\"90\" x2=\"122\" y2=\"100\"/>\n<line class=\"e b2\" x1=\"38\" y1=\"118\" x2=\"122\" y2=\"108\"/>\n<line class=\"e b2\" x1=\"38\" y1=\"146\" x2=\"122\" y2=\"156\"/>\n<line class=\"e b2\" x1=\"38\" y1=\"174\" x2=\"122\" y2=\"164\"/>\n<line class=\"e b2\" x1=\"38\" y1=\"202\" x2=\"122\" y2=\"212\"/>\n<line class=\"e b2\" x1=\"38\" y1=\"230\" x2=\"122\" y2=\"220\"/>\n<line class=\"e b3\" x1=\"140\" y1=\"48\" x2=\"214\" y2=\"72\"/>\n<line class=\"e b3\" x1=\"140\" y1=\"104\" x2=\"214\" y2=\"80\"/>\n<line class=\"e b3\" x1=\"140\" y1=\"160\" x2=\"214\" y2=\"184\"/>\n<line class=\"e b3\" x1=\"140\" y1=\"216\" x2=\"214\" y2=\"192\"/>\n<line class=\"e2 b4\" x1=\"236\" y1=\"76\" x2=\"296\" y2=\"126\"/>\n<line class=\"e2 b4\" x1=\"236\" y1=\"188\" x2=\"296\" y2=\"138\"/>\n<rect class=\"box2 b4\" x=\"352\" y=\"110\" width=\"118\" height=\"44\" rx=\"7\"/>\n<text class=\"tb b4\" x=\"411\" y=\"130\" font-size=\"14\" text-anchor=\"middle\">고정 길이 벡터<\/text>\n<text class=\"t b4\" x=\"411\" y=\"148\" font-size=\"13\" text-anchor=\"middle\">64칸<\/text>\n<line class=\"e2 b4\" x1=\"327\" y1=\"132\" x2=\"348\" y2=\"132\"/>\n<text class=\"tm b1\" x=\"30\" y=\"256\" font-size=\"13\" text-anchor=\"middle\">8개<\/text>\n<text class=\"tm b2\" x=\"130\" y=\"256\" font-size=\"13\" text-anchor=\"middle\">4개<\/text>\n<text class=\"tm b3\" x=\"224\" y=\"256\" font-size=\"13\" text-anchor=\"middle\">2개<\/text>\n<text class=\"tb b4\" x=\"400\" y=\"190\" font-size=\"14\" text-anchor=\"middle\">노드 수는 두 배씩<\/text>\n<text class=\"tb b4\" x=\"400\" y=\"212\" font-size=\"14\" text-anchor=\"middle\">담을 곳은 그대로<\/text>\n<\/svg>","caption":"왼쪽에서 오른쪽으로 갈수록 노드 수가 반씩 줄지만, 거꾸로 보면 멀어질수록 두 배씩 늘어요. 마지막 **병목(Bottleneck)**이 고정 길이 벡터예요.","builds":4},{"kind":"steps","head":"얼마나 담을 수 없는지 세어 보기","steps":["가지가 두 개씩 갈라지는 나무를 생각해요. 벡터 길이는 64 로 고정이에요.","거리 3 이면 그 거리에 있는 노드가 8 개예요. 벡터 한 칸당 $8 \\div 64 = 0.13$ 개예요.","거리 6 이면 64 개예요. 한 칸당 딱 1 개, 여기가 분기점이에요.","거리 10 이면 1,024 개예요. 한 칸에 16 개를 우겨넣어야 해요.","거리 12 면 4,096 개, 한 칸에 64 개예요."],"answer":"벡터 길이를 128 로 두 배 늘려도 거리 하나를 더 버틸 뿐이에요. 노드 수는 두 배씩 늘어나니까요.","given":"이진 나무에서 뿌리 노드가 $k$ 홉 아래 정보를 전부 모아야 해요."},{"kind":"compare","head":"평활화와 압착은 원인이 같아요","cols":["항목","**과도한 평활화(Over-smoothing)**","**과도한 압착(Over-squashing)**"],"rows":[["공통 원인","**수용 영역(Receptive Field)**의 지수적 폭발","**수용 영역(Receptive Field)**의 지수적 폭발"],["사고 나는 방식","너무 많이 섞여 구별이 사라짐","담을 공간이 없어 뭉개짐"],["언제 심한가","촘촘하게 잘 연결된 그래프","**병목(Bottleneck)**이 있는 그래프"]]}],"pass3":[{"kind":"warn","head":"4주차의 확장성 문제와 헷갈리지 마세요","items":["4주차는 '계산이 오래 걸리고 메모리가 터진다'는 공학적 문제였어요. 샘플링으로 풀었죠.","**과도한 압착(Over-squashing)**은 '다 계산해도 정보가 벡터에 안 담긴다'는 표현력의 문제예요.","무한한 GPU 가 있어도 안 풀려요.","또 압착은 **깊게 쌓아야만** 생겨요. 얕으면 멀리 안 보니 대신 도달 실패가 생겨요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"The k-hop neighbourhood grows exponentially while the node feature vector has a fixed dimension.","ko":"k홉 이웃은 지수적으로 커지는 반면 노드 특징 벡터의 차원은 고정되어 있다.","tip":"grows exponentially 와 fixed dimension 의 대비가 압착의 정의예요."},{"kind":"check","q":"**과도한 압착(Over-squashing)**이 생기는 근본 이유는 무엇인가요?","choices":["층이 너무 적어서","이웃은 지수로 늘어나는데 벡터 길이는 고정이라서","가중치를 공유해서","레이블이 적어서"],"a":1,"why":"왼쪽은 지수로 커지고 오른쪽은 그대로예요. 물리적으로 다 담을 수가 없어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.9453,0.4278],"c":[0,0,1,0.4706],"r":3.7777,"img":"img/L5/walk/p021_h.jpg"},"parts":[{"b":[0.194,0.506,0.285,0.334],"c":[0.1798,0.4893,0.3135,0.3674],"r":1.517,"img":"img/L5/walk/p021_12_01.jpg","say":"왼쪽은 RNN 의 병목이에요. 빨간 선이 전부 마지막 원으로 몰려요."},{"b":[0.528,0.506,0.257,0.334],"c":[0.5152,0.4893,0.2827,0.3674],"r":1.3679,"img":"img/L5/walk/p021_12_02.jpg","say":"오른쪽은 GNN 의 병목이에요. 구조는 달라도 문제는 똑같아요."}]}},{"p":22,"title":"압착을 재는 자: 야코비안","terms":["Over-squashing","Jacobian","Bottleneck","Graph Rewiring","Adjacency Matrix"],"pass1":[{"kind":"say","lines":["'정보가 안 온다'를 수학으로 재는 방법이 **야코비안(Jacobian)**이에요.","**야코비안(Jacobian)**은 '먼 노드의 입력을 조금 흔들면 내 출력이 얼마나 흔들리나'예요.","이 값이 0 에 가까우면 그 관계를 아예 배울 수가 없어요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.03,"y":0.138,"w":0.25,"h":0.038,"say":"제목 아래 '이론적 정의와 야코비안 행렬'이에요.","c":[0.0175,0.102,0.275,0.11],"r":4.4444,"img":"img/L5/walk/p022_20_01.jpg"},{"x":0.09,"y":0.185,"w":0.86,"h":0.07,"say":"'한 노드의 출력이 멀리 있는 노드의 입력에 얼마나 민감한지를 봅니다.'","c":[0.047,0.1244,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p022_20_02.jpg"},{"x":0.09,"y":0.274,"w":0.86,"h":0.07,"say":"'과도한 압착은 야코비안 행렬의 노름으로 재요.'","c":[0.047,0.2134,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p022_20_03.jpg"},{"x":0.028,"y":0.364,"w":0.312,"h":0.075,"say":"왼쪽 파란 상자: 갱신 함수와 메시지 함수의 기울기 상한이에요.","c":[0.0124,0.3465,0.3432,0.11],"r":5.5467,"img":"img/L5/walk/p022_20_04.jpg"},{"x":0.375,"y":0.352,"w":0.243,"h":0.093,"say":"가운데가 부등식이에요. 오른쪽에 두 항의 곱이 있어요.","c":[0.3629,0.336,0.2673,0.125],"r":3.8016,"img":"img/L5/walk/p022_20_05.jpg"},{"x":0.66,"y":0.364,"w":0.312,"h":0.075,"say":"오른쪽 주황 상자: 노드 사이의 위상적 영향만 떼어 내는 행렬 성분이에요.","c":[0.6444,0.3465,0.3432,0.11],"r":5.5467,"img":"img/L5/walk/p022_20_06.jpg"},{"x":0.09,"y":0.467,"w":0.86,"h":0.07,"say":"'지수 감쇠: 병목을 지나면 이 값이 거리에 따라 지수적으로 줄어요.'","c":[0.047,0.4064,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p022_20_07.jpg"}]},{"kind":"formula","head":"야코비안 상계를 기호 하나씩","tex":"\\left| \\frac{\\partial h_i^{(r+1)}}{\\partial x_s} \\right| \\le (\\alpha \\beta)^{r+1} \\left( \\hat{A}^{r+1} \\right)_{is}","parts":[{"sym":"\\partial","say":"편미분 기호예요. '조금 바꿨을 때 얼마나 바뀌나'를 뜻해요."},{"sym":"h_i^{(r+1)}","say":"층을 지난 뒤 노드 $i$ 의 표현이에요."},{"sym":"x_s","say":"노드 $s$ 의 **맨 처음** 입력 특징이에요."},{"sym":"(\\alpha\\beta)^{r+1}","say":"**신경망** 쪽 감쇠예요. 가중치 크기로 정해져요."},{"sym":"(\\hat{A}^{r+1})_{is}","say":"**그래프 구조** 쪽 통행량이에요. **인접행렬(Adjacency Matrix)** 거듭제곱의 한 칸이에요."}],"whole":"우리말로 하면 '$s$ 가 $i$ 에 주는 영향은, 신경망의 증폭 한계와 그래프가 허용하는 통행량의 곱보다 클 수 없다'예요."},{"kind":"figure","head":"거리에 따라 영향력이 급격히 0 으로","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<line class=\"e\" x1=\"56\" y1=\"200\" x2=\"450\" y2=\"200\"/>\n<line class=\"e\" x1=\"56\" y1=\"40\" x2=\"56\" y2=\"200\"/>\n<text class=\"tm\" x=\"56\" y=\"222\" font-size=\"13\" text-anchor=\"middle\">0<\/text>\n<text class=\"tm\" x=\"134\" y=\"222\" font-size=\"13\" text-anchor=\"middle\">1<\/text>\n<text class=\"tm\" x=\"212\" y=\"222\" font-size=\"13\" text-anchor=\"middle\">2<\/text>\n<text class=\"tm\" x=\"290\" y=\"222\" font-size=\"13\" text-anchor=\"middle\">3<\/text>\n<text class=\"tm\" x=\"368\" y=\"222\" font-size=\"13\" text-anchor=\"middle\">4<\/text>\n<text class=\"tm\" x=\"440\" y=\"222\" font-size=\"13\" text-anchor=\"middle\">5<\/text>\n<text class=\"tm\" x=\"250\" y=\"246\" font-size=\"14\" text-anchor=\"middle\">두 노드 사이 거리<\/text>\n<text class=\"tm\" x=\"26\" y=\"46\" font-size=\"13\" text-anchor=\"middle\">영향력<\/text>\n<polyline class=\"e2 b1\" points=\"56,50 134,118 212,160 290,182 368,193 440,198\" fill=\"none\"/>\n<circle class=\"n2 b1\" cx=\"56\" cy=\"50\" r=\"7\"/>\n<circle class=\"n2 b1\" cx=\"134\" cy=\"118\" r=\"7\"/>\n<circle class=\"n2 b1\" cx=\"212\" cy=\"160\" r=\"7\"/>\n<circle class=\"n2 b1\" cx=\"290\" cy=\"182\" r=\"7\"/>\n<circle class=\"n2 b1\" cx=\"368\" cy=\"193\" r=\"7\"/>\n<circle class=\"n2 b1\" cx=\"440\" cy=\"198\" r=\"7\"/>\n<text class=\"t b2\" x=\"72\" y=\"44\" font-size=\"13\">0.347<\/text>\n<text class=\"t b2\" x=\"112\" y=\"110\" font-size=\"13\">0.139<\/text>\n<text class=\"t b2\" x=\"190\" y=\"152\" font-size=\"13\">0.035<\/text>\n<text class=\"t b2\" x=\"268\" y=\"174\" font-size=\"13\">0.007<\/text>\n<text class=\"t b2\" x=\"346\" y=\"186\" font-size=\"13\">0.001<\/text>\n<text class=\"tb b3\" x=\"290\" y=\"76\" font-size=\"14\" text-anchor=\"middle\">한 걸음 멀어질 때마다<\/text>\n<text class=\"tb b3\" x=\"290\" y=\"98\" font-size=\"14\" text-anchor=\"middle\">대략 4분의 1 이하로<\/text>\n<\/svg>","caption":"노드 넷을 한 줄로 이은 그래프에서 계산한 값이에요. 한 걸음 멀어질 때마다 4분의 1 이하로 줄어요.","builds":3},{"kind":"steps","head":"길 그래프에서 영향력을 직접 계산","steps":["노드 넷을 한 줄로 잇고 자기 고리를 더해요. **차수(Degree)**가 2, 3, 3, 2 예요.","각 행을 그 **차수(Degree)**로 나눠요. 행 1 은 0.5, 0.5, 0, 0 이에요.","두 걸음 뒤 노드 1 의 분포는 0.417, 0.417, 0.167, 0 이에요. 합이 1 이니 검산 통과예요.","세 걸음 뒤 노드 1 에서 노드 4 로 가는 값은 $0.167 \\times \\frac{1}{3} \\approx 0.056$ 이에요.","같은 자리에 남을 값은 $0.417 \\times 0.5 + 0.417 \\times \\frac{1}{3} \\approx 0.347$ 이에요.","여기에 신경망 감쇠 0.5 를 세 번 곱하면 각각 0.043 과 0.007 이에요."],"answer":"내 영향이 3홉 떨어진 노드 영향의 6.25배예요. 거리가 6 이면 상계가 0.0001 아래로 떨어져요.","given":"노드 네 개를 한 줄로 이었고, 신경망 쪽 감쇠는 한 층당 0.5 라고 해요."},{"kind":"points","head":"두 항을 구별하는 것이 핵심이에요","items":["신경망 항은 가중치를 키우면 커져요. 대신 학습이 불안정해져요.","그래프 구조 항은 **학습으로 절대 못 고쳐요**. 그래프가 그렇게 생긴 거니까요.","그래서 구조를 직접 고치는 처방이 필요해요.","그것이 p.36 에 나올 **그래프 재배선(Graph Rewiring)**이에요."]}],"pass3":[{"kind":"warn","head":"이 슬라이드에는 표기가 어긋난 곳이 두 군데 있어요","items":["본문은 '노드 j 의 초기 특징'이라고 하는데 부등식의 아래첨자는 s 예요. 같은 노드를 두 이름으로 부르고 있어요.","그리고 마지막 불릿이 'f' 로 시작해요. 'If' 의 'I' 가 떨어져 나간 거예요.","원래 문장은 'If 이 값이 0 에 가까우면 신경망은 그 상호작용을 배울 수 없어요' 입니다.","또 이 식은 **상계**예요. 작으면 '확실히 작다'고 말할 수 있지만, 크다고 영향이 크다고 말할 수는 없어요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Over-squashing is quantified by the Jacobian, which decays exponentially with the distance between the two nodes.","ko":"과도한 압착은 야코비안으로 수치화되며, 그 값은 두 노드 사이 거리에 따라 지수적으로 감쇠한다.","tip":"is quantified by the Jacobian 이 채점 포인트예요."},{"kind":"check","q":"**야코비안(Jacobian)** 상계의 두 항 중 학습으로 고칠 수 없는 쪽은 어디인가요?","choices":["신경망 항","그래프 구조 항","둘 다 고칠 수 있어요","둘 다 못 고쳐요"],"a":1,"why":"구조 항은 그래프 모양이 정해요. 그래서 **그래프 재배선(Graph Rewiring)** 같은 처방이 나왔어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.9445,0.6497],"c":[0,0,1,0.7147],"r":2.4874,"img":"img/L5/walk/p022_h.jpg"},"parts":[{"b":[0.3,0.691,0.18,0.21],"c":[0.288,0.675,0.204,0.242],"r":1.4986,"img":"img/L5/walk/p022_11_01.jpg","say":"왼쪽 아령 모양. 덩어리 둘이 가는 목으로 이어져 있어요."},{"b":[0.52,0.691,0.22,0.21],"c":[0.508,0.675,0.244,0.242],"r":1.7925,"img":"img/L5/walk/p022_11_02.jpg","say":"오른쪽도 같아요. 빽빽한 덩어리 둘을 선 하나가 잇고 있어요."}]}},{"p":23,"title":"압착은 그래프 모양의 문제","terms":["Over-squashing","Ricci Curvature","Clique","Bottleneck","Over-smoothing"],"pass1":[{"kind":"say","lines":["압착은 결국 **그래프의 모양** 문제예요.","그 모양을 재는 자가 **리치 곡률(Ricci Curvature)**이에요.","곡률이 양수면 길이 여러 갈래라 잘 흐르고, 음수면 길이 하나뿐이라 막혀요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.03,"y":0.138,"w":0.2,"h":0.038,"say":"제목 아래 '위상 관점 (그래프 곡률)'이에요.","c":[0.018,0.102,0.224,0.11],"r":3.6202,"img":"img/L5/walk/p023_20_01.jpg"},{"x":0.09,"y":0.185,"w":0.4,"h":0.038,"say":"'과도한 압착은 근본적으로 그래프 기하의 문제예요.'","c":[0.07,0.149,0.44,0.11],"r":7.1111,"img":"img/L5/walk/p023_20_02.jpg"},{"x":0.09,"y":0.235,"w":0.86,"h":0.038,"say":"'이산 리치 곡률: 엣지 곡률은 이어진 두 노드의 이웃이 어떤 관계인지 재요.'","c":[0.047,0.1584,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p023_20_03.jpg"},{"x":0.11,"y":0.319,"w":0.72,"h":0.038,"say":"'양의 곡률: 이웃이 많이 겹쳐요. 여러 경로로 정보가 쉽게 흘러요.'","c":[0.074,0.258,0.792,0.16],"r":8.8,"img":"img/L5/walk/p023_20_04.jpg"},{"x":0.11,"y":0.407,"w":0.86,"h":0.072,"say":"'음의 곡률: 이웃이 겹침 없이 퍼져요. 구조적 병목이 되어 압착을 만들어요.'","c":[0.054,0.3474,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p023_20_05.jpg"}]},{"kind":"figure","head":"곡률 세 가지","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb b1\" x=\"76\" y=\"30\" font-size=\"14\" text-anchor=\"middle\">클리크: 곡률 양수<\/text>\n<text class=\"tb b2\" x=\"240\" y=\"30\" font-size=\"14\" text-anchor=\"middle\">격자: 곡률 0<\/text>\n<text class=\"tb b3\" x=\"404\" y=\"30\" font-size=\"14\" text-anchor=\"middle\">나무: 곡률 음수<\/text>\n<line class=\"e2 b1\" x1=\"42\" y1=\"60\" x2=\"110\" y2=\"60\"/>\n<line class=\"e2 b1\" x1=\"42\" y1=\"60\" x2=\"42\" y2=\"128\"/>\n<line class=\"e2 b1\" x1=\"42\" y1=\"60\" x2=\"110\" y2=\"128\"/>\n<line class=\"e2 b1\" x1=\"42\" y1=\"60\" x2=\"76\" y2=\"94\"/>\n<line class=\"e2 b1\" x1=\"110\" y1=\"60\" x2=\"42\" y2=\"128\"/>\n<line class=\"e2 b1\" x1=\"110\" y1=\"60\" x2=\"110\" y2=\"128\"/>\n<line class=\"e2 b1\" x1=\"110\" y1=\"60\" x2=\"76\" y2=\"94\"/>\n<line class=\"e2 b1\" x1=\"42\" y1=\"128\" x2=\"110\" y2=\"128\"/>\n<line class=\"e2 b1\" x1=\"42\" y1=\"128\" x2=\"76\" y2=\"94\"/>\n<line class=\"e2 b1\" x1=\"110\" y1=\"128\" x2=\"76\" y2=\"94\"/>\n<circle class=\"n2 b1\" cx=\"42\" cy=\"60\" r=\"9\"/>\n<circle class=\"n2 b1\" cx=\"110\" cy=\"60\" r=\"9\"/>\n<circle class=\"n2 b1\" cx=\"42\" cy=\"128\" r=\"9\"/>\n<circle class=\"n2 b1\" cx=\"110\" cy=\"128\" r=\"9\"/>\n<circle class=\"n2 b1\" cx=\"76\" cy=\"94\" r=\"9\"/>\n<line class=\"e b2\" x1=\"198\" y1=\"60\" x2=\"282\" y2=\"60\"/>\n<line class=\"e b2\" x1=\"198\" y1=\"94\" x2=\"282\" y2=\"94\"/>\n<line class=\"e b2\" x1=\"198\" y1=\"128\" x2=\"282\" y2=\"128\"/>\n<line class=\"e b2\" x1=\"198\" y1=\"60\" x2=\"198\" y2=\"128\"/>\n<line class=\"e b2\" x1=\"240\" y1=\"60\" x2=\"240\" y2=\"128\"/>\n<line class=\"e b2\" x1=\"282\" y1=\"60\" x2=\"282\" y2=\"128\"/>\n<circle class=\"n3 b2\" cx=\"198\" cy=\"60\" r=\"8\"/>\n<circle class=\"n3 b2\" cx=\"240\" cy=\"60\" r=\"8\"/>\n<circle class=\"n3 b2\" cx=\"282\" cy=\"60\" r=\"8\"/>\n<circle class=\"n3 b2\" cx=\"198\" cy=\"94\" r=\"8\"/>\n<circle class=\"n3 b2\" cx=\"240\" cy=\"94\" r=\"8\"/>\n<circle class=\"n3 b2\" cx=\"282\" cy=\"94\" r=\"8\"/>\n<circle class=\"n3 b2\" cx=\"198\" cy=\"128\" r=\"8\"/>\n<circle class=\"n3 b2\" cx=\"240\" cy=\"128\" r=\"8\"/>\n<circle class=\"n3 b2\" cx=\"282\" cy=\"128\" r=\"8\"/>\n<line class=\"e b3\" x1=\"404\" y1=\"52\" x2=\"368\" y2=\"88\"/>\n<line class=\"e b3\" x1=\"404\" y1=\"52\" x2=\"440\" y2=\"88\"/>\n<line class=\"e b3\" x1=\"368\" y1=\"88\" x2=\"348\" y2=\"130\"/>\n<line class=\"e b3\" x1=\"368\" y1=\"88\" x2=\"388\" y2=\"130\"/>\n<line class=\"e b3\" x1=\"440\" y1=\"88\" x2=\"420\" y2=\"130\"/>\n<line class=\"e b3\" x1=\"440\" y1=\"88\" x2=\"460\" y2=\"130\"/>\n<circle class=\"n4 b3\" cx=\"404\" cy=\"52\" r=\"8\"/>\n<circle class=\"n4 b3\" cx=\"368\" cy=\"88\" r=\"8\"/>\n<circle class=\"n4 b3\" cx=\"440\" cy=\"88\" r=\"8\"/>\n<circle class=\"n4 b3\" cx=\"348\" cy=\"130\" r=\"8\"/>\n<circle class=\"n4 b3\" cx=\"388\" cy=\"130\" r=\"8\"/>\n<circle class=\"n4 b3\" cx=\"420\" cy=\"130\" r=\"8\"/>\n<circle class=\"n4 b3\" cx=\"460\" cy=\"130\" r=\"8\"/>\n<text class=\"t b1\" x=\"76\" y=\"176\" font-size=\"13\" text-anchor=\"middle\">길이 여러 갈래<\/text>\n<text class=\"t b2\" x=\"240\" y=\"176\" font-size=\"13\" text-anchor=\"middle\">길이 몇 갈래<\/text>\n<text class=\"t b3\" x=\"404\" y=\"176\" font-size=\"13\" text-anchor=\"middle\">길이 딱 하나<\/text>\n<text class=\"tb b4\" x=\"76\" y=\"204\" font-size=\"13\" text-anchor=\"middle\">압착 약함<\/text>\n<text class=\"tb b4\" x=\"76\" y=\"224\" font-size=\"13\" text-anchor=\"middle\">평활화 심함<\/text>\n<text class=\"tb b4\" x=\"404\" y=\"204\" font-size=\"13\" text-anchor=\"middle\">압착 심함<\/text>\n<text class=\"tb b4\" x=\"404\" y=\"224\" font-size=\"13\" text-anchor=\"middle\">평활화 약함<\/text>\n<text class=\"tm b4\" x=\"240\" y=\"252\" font-size=\"14\" text-anchor=\"middle\">양쪽 다 좋은 구조가 없어요<\/text>\n<\/svg>","caption":"삼각형이 많을수록 곡률이 양수, 갈라지기만 할수록 음수예요. **리치 곡률(Ricci Curvature)**은 **엣지마다** 정해져요.","builds":4},{"kind":"steps","head":"길이 몇 갈래인지 세어 보기","steps":["노드 넷이 전부 이어진 **클리크(Clique)**에서 1 번에서 2 번으로 가는 두 걸음 길을 세어요.","3 번을 거치거나 4 번을 거칠 수 있어요. 두 갈래예요. 직접 가는 한 걸음 길도 있고요.","이번에는 나무를 봐요. 뿌리 1 아래 2 와 3, 2 아래 4 와 5 예요.","4 번에서 5 번으로 가는 길은 2 번을 거치는 하나뿐이에요.","4 번에서 3 번으로 가는 길도 2 번과 1 번을 거치는 하나뿐이에요."],"answer":"나무에서는 두 노드 사이 길이 **항상 정확히 하나**예요. 그 길을 끊으면 연결이 끊겨요. 그래서 압착이 심해요.","given":"**클리크(Clique)** 와 나무에서 두 노드 사이 경로 수를 세요."},{"kind":"compare","head":"곡률에 따른 두 고장","cols":["구조","**과도한 압착(Over-squashing)**","**과도한 평활화(Over-smoothing)**"],"rows":[["**클리크(Clique)**, 곡률 양수","거의 없음","심각"],["격자, 곡률 0","보통","보통"],["나무와 다리, 곡률 음수","심각","거의 없음"]]},{"kind":"mining","src":"마이닝 1강 Introduction to Graph, 마이닝 5강 Community Detection","lines":["'삼각형이 많은가'를 재는 양을 이미 배웠어요. 군집 계수예요.","내 친구들끼리도 서로 친구인 비율이죠. 군집 계수가 높으면 곡률도 양수예요.","커뮤니티 **안쪽** 엣지는 삼각형이 많아 곡률이 양수예요.","커뮤니티 **사이**를 잇는 다리는 곡률이 음수라 **병목(Bottleneck)**이 돼요."]}],"pass3":[{"kind":"warn","head":"곡률은 노드가 아니라 엣지마다 정해져요","items":["'이 그래프의 곡률'이 아니라 '이 **엣지**의 곡률'이에요.","같은 그래프 안에서도 커뮤니티 안쪽 엣지는 양수, 커뮤니티를 잇는 다리는 음수일 수 있어요.","그리고 **리치 곡률(Ricci Curvature)**에는 여러 버전이 있어요. 문제가 어느 정의를 주는지 보고 답하세요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Negative curvature edges act as structural bottlenecks and cause severe over-squashing.","ko":"음의 곡률 엣지는 구조적 병목 역할을 하며 심각한 과도한 압착을 일으킨다.","tip":"structural bottlenecks 라는 슬라이드 표현을 그대로 쓰세요."},{"kind":"check","q":"곡률이 **음수**인 엣지의 특징은 무엇인가요?","choices":["이웃이 많이 겹친다","이웃이 겹치지 않고 퍼진다","삼각형이 많다","노드 차수가 높다"],"a":1,"why":"겹치지 않고 퍼지면 우회로가 없어요. 그 엣지가 유일한 통로가 되니 **병목(Bottleneck)**이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.9355,0.4736],"c":[0,0,1,0.5209],"r":3.4129,"img":"img/L5/walk/p023_h.jpg"},"parts":[{"b":[0.257,0.519,0.146,0.32],"c":[0.23,0.503,0.2,0.352],"r":1.0101,"img":"img/L5/walk/p023_11_01.jpg","say":"(a) 클리크. 점들이 서로 전부 이어져 있어요. 곡률 양수예요."},{"b":[0.417,0.519,0.152,0.32],"c":[0.393,0.503,0.2,0.352],"r":1.0101,"img":"img/L5/walk/p023_11_02.jpg","say":"(b) 격자. 가로세로로만 이어져 있어요. 곡률 0 이에요."},{"b":[0.587,0.519,0.142,0.32],"c":[0.558,0.503,0.2,0.352],"r":1.0101,"img":"img/L5/walk/p023_11_03.jpg","say":"(c) 나무. 갈라지기만 하고 고리가 없어요. 곡률 음수예요."}]}},{"p":24,"title":"치거 부등식: 하나를 고치면 하나가 나빠진다","terms":["Cheeger Inequality","Spectral Gap","Expander Graph","Bottleneck","Over-smoothing","Over-squashing"],"pass1":[{"kind":"say","lines":["**치거 부등식(Cheeger Inequality)**은 '그래프에 병목이 있는가'를 숫자 하나로 재게 해 줘요.","그 숫자가 **스펙트럼 간격(Spectral Gap)**, 즉 라플라시안의 두 번째로 작은 고윳값이에요.","간격이 작으면 **병목(Bottleneck)**, 크면 잘 섞이는 그래프예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.03,"y":0.138,"w":0.23,"h":0.038,"say":"제목 아래 '치거 부등식 (CHUNG, 1997)'. **치거 부등식(Cheeger Inequality)**의 출처예요.","c":[0.018,0.102,0.254,0.11],"r":4.1051,"img":"img/L5/walk/p024_20_01.jpg"},{"x":0.39,"y":0.222,"w":0.19,"h":0.068,"say":"가운데가 부등식이에요. 가운데 항이 치거 상수예요.","c":[0.378,0.201,0.214,0.11],"r":3.4586,"img":"img/L5/walk/p024_20_02.jpg"},{"x":0.065,"y":0.315,"w":0.8,"h":0.075,"say":"'h(G)는 가장 좁은 절단이 얼마나 좁은지이고, 두 번째로 작은 고윳값이 스펙트럼 간격이에요.'","c":[0.025,0.2636,0.88,0.1778],"r":8.7989,"img":"img/L5/walk/p024_20_03.jpg"},{"x":0.4,"y":0.454,"w":0.17,"h":0.04,"say":"빨간 글씨: '작은 간격 곧 병목'. 이 한 줄이 핵심이에요.","c":[0.385,0.419,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p024_20_04.jpg"},{"x":0.067,"y":0.549,"w":0.425,"h":0.226,"say":"'느린 섞임: 특징이 여러 층 동안 구별되지만 먼 신호가 지나오지 못해요.'","c":[0.0457,0.533,0.4675,0.258],"r":3.2214,"img":"img/L5/walk/p024_20_05.jpg"},{"x":0.507,"y":0.549,"w":0.426,"h":0.226,"say":"'빠른 섞임: 먼 신호가 빨리 오지만 몇 층 만에 특징이 수렴해요.'","c":[0.4857,0.533,0.4686,0.258],"r":3.2289,"img":"img/L5/walk/p024_20_06.jpg"}]},{"kind":"formula","head":"치거 부등식을 기호 하나씩","tex":"\\frac{\\lambda_2}{2} \\le h(G) \\le \\sqrt{2 \\lambda_2}","parts":[{"sym":"h(G)","say":"치거 상수예요. 그래프를 둘로 자를 때 '자른 엣지 수 나누기 작은 쪽 부피'의 최솟값이에요."},{"sym":"\\lambda_2","say":"**스펙트럼 간격(Spectral Gap)**이에요. 두 번째로 작은 고윳값이죠."},{"sym":"\\le","say":"부등호예요. 왼쪽과 오른쪽이 가운데를 위아래로 가둬요."}],"whole":"이 부등식이 말하는 것은 '두 값이 같이 커지고 같이 작아진다'예요. 계산이 어려운 $h(G)$ 를 쉬운 $\\lambda_2$ 로 대신 잴 수 있어요."},{"kind":"figure","head":"두 그래프를 나란히 비교","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb b1\" x=\"116\" y=\"30\" font-size=\"15\" text-anchor=\"middle\">길 그래프: 간격 작음<\/text>\n<line class=\"e2 b1\" x1=\"42\" y1=\"86\" x2=\"92\" y2=\"86\"/>\n<line class=\"e2 b1\" x1=\"92\" y1=\"86\" x2=\"142\" y2=\"86\"/>\n<line class=\"e2 b1\" x1=\"142\" y1=\"86\" x2=\"192\" y2=\"86\"/>\n<circle class=\"n b1\" cx=\"42\" cy=\"86\" r=\"13\"/>\n<circle class=\"n b1\" cx=\"92\" cy=\"86\" r=\"13\"/>\n<circle class=\"n b1\" cx=\"142\" cy=\"86\" r=\"13\"/>\n<circle class=\"n b1\" cx=\"192\" cy=\"86\" r=\"13\"/>\n<line class=\"hl b2\" x1=\"117\" y1=\"56\" x2=\"117\" y2=\"116\"/>\n<text class=\"tb b2\" x=\"117\" y=\"140\" font-size=\"13\" text-anchor=\"middle\">여기 한 개만 끊으면 반으로<\/text>\n<text class=\"t b3\" x=\"116\" y=\"172\" font-size=\"14\" text-anchor=\"middle\">치거 상수 0.333<\/text>\n<text class=\"t b3\" x=\"116\" y=\"194\" font-size=\"14\" text-anchor=\"middle\">스펙트럼 간격 0.5<\/text>\n<text class=\"tb b4\" x=\"116\" y=\"224\" font-size=\"14\" text-anchor=\"middle\">압착 심함<\/text>\n<text class=\"tb b4\" x=\"116\" y=\"246\" font-size=\"14\" text-anchor=\"middle\">평활화 느림<\/text>\n<text class=\"tb b1\" x=\"356\" y=\"30\" font-size=\"15\" text-anchor=\"middle\">완전그래프: 간격 큼<\/text>\n<line class=\"e2 b1\" x1=\"306\" y1=\"60\" x2=\"406\" y2=\"60\"/>\n<line class=\"e2 b1\" x1=\"306\" y1=\"60\" x2=\"306\" y2=\"116\"/>\n<line class=\"e2 b1\" x1=\"306\" y1=\"60\" x2=\"406\" y2=\"116\"/>\n<line class=\"e2 b1\" x1=\"406\" y1=\"60\" x2=\"306\" y2=\"116\"/>\n<line class=\"e2 b1\" x1=\"406\" y1=\"60\" x2=\"406\" y2=\"116\"/>\n<line class=\"e2 b1\" x1=\"306\" y1=\"116\" x2=\"406\" y2=\"116\"/>\n<circle class=\"n2 b1\" cx=\"306\" cy=\"60\" r=\"13\"/>\n<circle class=\"n2 b1\" cx=\"406\" cy=\"60\" r=\"13\"/>\n<circle class=\"n2 b1\" cx=\"306\" cy=\"116\" r=\"13\"/>\n<circle class=\"n2 b1\" cx=\"406\" cy=\"116\" r=\"13\"/>\n<text class=\"tb b2\" x=\"356\" y=\"140\" font-size=\"13\" text-anchor=\"middle\">어디를 잘라도 네 개를 끊어야 해요<\/text>\n<text class=\"t b3\" x=\"356\" y=\"172\" font-size=\"14\" text-anchor=\"middle\">치거 상수 0.667<\/text>\n<text class=\"t b3\" x=\"356\" y=\"194\" font-size=\"14\" text-anchor=\"middle\">스펙트럼 간격 1.333<\/text>\n<text class=\"tb b4\" x=\"356\" y=\"224\" font-size=\"14\" text-anchor=\"middle\">압착 없음<\/text>\n<text class=\"tb b4\" x=\"356\" y=\"246\" font-size=\"14\" text-anchor=\"middle\">평활화 빠름<\/text>\n<\/svg>","caption":"길 그래프는 간격이 작아 **병목(Bottleneck)**이 있고, 완전그래프는 간격이 커서 **확장 그래프(Expander Graph)**에 가까워요.","builds":4},{"kind":"steps","head":"두 그래프로 부등식을 직접 확인","steps":["완전그래프 네 개부터 해요. **차수(Degree)**가 전부 3, 부피 합이 12 예요.","둘씩 자르면 끊는 엣지가 4 개, 작은 쪽 부피가 6 이니 $4 \\div 6 \\approx 0.667$ 이에요.","고윳값은 0 과 $\\frac{4}{3} \\approx 1.333$ 이에요. 부등식 왼쪽이 $1.333 \\div 2 = 0.667$ 로 딱 등호예요.","이번에는 노드 넷을 한 줄로 이은 길 그래프예요. **차수(Degree)**가 1, 2, 2, 1 이에요.","가운데를 자르면 엣지 1 개, 양쪽 부피가 3 씩이라 $1 \\div 3 \\approx 0.333$ 이에요.","고윳값은 0, 0.5, 1.5, 2 이니 두 번째로 작은 값이 0.5 예요. $0.5 \\div 2 = 0.25 \\le 0.333$ 이에요."],"answer":"완전그래프는 간격 1.333 에 치거 상수 0.667, 길 그래프는 0.5 에 0.333 이에요. 성격이 정확히 반대예요.","given":"노드 넷짜리 완전그래프와 노드 넷짜리 길 그래프를 비교해요."},{"kind":"mining","src":"마이닝 5강 Community Detection","lines":["치거 상수는 마이닝에서 배운 정규화 컷과 사실상 같은 양이에요.","최소 컷만 보면 노드 하나만 똑 떼어내는 답이 나와서, 분모에 덩어리 크기를 넣었죠.","치거 상수도 똑같아요. 분자는 끊은 엣지 수, 분모는 작은 쪽 부피예요.","그래서 위 계산에서 노드 하나만 떼는 답이 이기지 못했어요."]}],"pass3":[{"kind":"warn","head":"고윳값 번호 매기기가 p.19 와 어긋나요","items":["p.19 는 0 번부터 세어서 가장 작은 고윳값이 0 번이라고 했어요. 그러면 두 번째로 작은 것은 1 번이죠.","그런데 이 슬라이드는 두 번째로 작은 고윳값을 2 번이라고 불러요. 1 번부터 세는 방식이에요.","헷갈리지 않으려면 번호가 아니라 뜻으로 외우세요. '가장 작은 고윳값은 항상 0, 그다음이 **스펙트럼 간격(Spectral Gap)**'이에요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"A small spectral gap means a bottleneck, so features stay distinct but distant signals cannot pass.","ko":"스펙트럼 간격이 작으면 병목이 있다는 뜻이라, 특징은 구별되지만 먼 신호가 통과하지 못한다.","tip":"cannot pass 가 압착, stay distinct 가 평활화가 적다는 뜻이에요."},{"kind":"check","q":"**스펙트럼 간격(Spectral Gap)**이 **큰** 그래프에서 심해지는 고장은 무엇인가요?","choices":["**과도한 압착(Over-squashing)**","**과도한 평활화(Over-smoothing)**","둘 다","둘 다 아님"],"a":1,"why":"간격이 크면 **확장 그래프(Expander Graph)**에 가까워 빨리 섞여요. 압착은 없어지지만 평활화가 빨라져요."},{"kind":"points","head":"이 슬라이드를 한 줄로 요약하면","items":["**치거 부등식(Cheeger Inequality)**은 '병목이 있는가'를 고윳값 하나로 재게 해 줘요.","간격이 작으면 **병목(Bottleneck)**, 크면 **확장 그래프(Expander Graph)**에 가까워요.","그리고 두 고장이 이 값 하나를 두고 정반대로 움직여요.","그래서 연결성만 바꿔서는 둘을 동시에 줄일 수 없어요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.7826,0.4784],"c":[0,0,0.8608,0.5262],"r":2.9082,"img":"img/L5/walk/p024_h.jpg"},"parts":[{"b":[0.067,0.549,0.425,0.226],"c":[0.0457,0.533,0.4675,0.258],"r":3.2214,"img":"img/L5/walk/p024_11_01.jpg","say":"왼쪽: '병목이 있는 그래프, 작은 간격'. 평활화는 적지만 압착이 강해요."},{"b":[0.507,0.549,0.426,0.226],"c":[0.4857,0.533,0.4686,0.258],"r":3.2289,"img":"img/L5/walk/p024_11_02.jpg","say":"오른쪽: '확장 그래프에 가까움, 큰 간격'. 압착은 적지만 평활화가 빨라요."}]}},{"p":25,"title":"올리비에 리치 곡률: 옮기는 비용으로 재기","terms":["Ricci Curvature","Optimal Transport","Clique","Over-squashing"],"pass1":[{"kind":"say","lines":["곡률을 정확히 어떻게 재는지 배워요.","엣지 양끝 노드의 **이웃 분포를 옮기는 데 드는 비용**으로 재요. 이걸 **최적 수송(Optimal Transport)**이라고 해요.","비용이 싸면 곡률이 크고, 비싸면 음수예요."]},{"kind":"analogy","head":"책상 위 물건을 옮기는 비용","scene":"민수와 지연이가 각자 책상에 연필을 몇 자루씩 놓아 두었어요. 민수 책상 모양을 지연이 책상 모양으로 바꾸려면 연필을 옮겨야 하죠. 두 사람이 이미 같은 자리에 연필을 두었다면 그건 그냥 두면 돼요. 옮길 게 적으면 비용이 싸요.","map":[["이미 같은 자리에 있는 연필","두 노드의 공통 이웃"],["옮기는 데 드는 총 비용","**최적 수송(Optimal Transport)** 비용"],["비용이 싸다","곡률이 크다, 즉 잘 흐른다"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.03,"y":0.138,"w":0.27,"h":0.038,"say":"제목 아래 '올리비에 리치 곡률 (그래프에서)'이에요.","c":[0.0165,0.102,0.297,0.11],"r":4.8,"img":"img/L5/walk/p025_20_01.jpg"},{"x":0.09,"y":0.185,"w":0.66,"h":0.038,"say":"'개념: 최적 수송을 써서 리치 곡률 개념을 이산 공간에 맞춘 것이에요.'","c":[0.057,0.1307,0.726,0.1467],"r":8.798,"img":"img/L5/walk/p025_20_02.jpg"},{"x":0.09,"y":0.269,"w":0.86,"h":0.04,"say":"'메커니즘: 인접한 두 노드의 이웃 분포 사이에서 드는 최적 수송 비용을 계산해요.'","c":[0.047,0.1934,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p025_20_03.jpg"},{"x":0.09,"y":0.358,"w":0.18,"h":0.04,"say":"'곡률 엣지 지표'. 아래 네모 상자에 식이 있어요.","c":[0.078,0.323,0.204,0.11],"r":3.297,"img":"img/L5/walk/p025_20_04.jpg"},{"x":0.148,"y":0.568,"w":0.284,"h":0.11,"say":"네모 상자 안의 식이에요. 1 에서 비용을 거리로 나눈 값을 빼요.","c":[0.1338,0.552,0.3124,0.142],"r":3.9111,"img":"img/L5/walk/p025_20_05.jpg"}]},{"kind":"formula","head":"곡률 식을 기호 하나씩","tex":"\\kappa(u, v) = 1 - \\frac{W_1(\\mu_u, \\mu_v)}{d(u, v)}","parts":[{"sym":"\\kappa(u,v)","say":"엣지 $(u,v)$ 의 **리치 곡률(Ricci Curvature)**이에요."},{"sym":"\\mu_u","say":"노드 $u$ 에서 한 걸음 뒤 어디 있을지에 대한 확률 분포예요."},{"sym":"W_1(\\mu_u, \\mu_v)","say":"$\\mu_u$ 를 $\\mu_v$ 로 옮기는 **최적 수송(Optimal Transport)** 최소 비용이에요."},{"sym":"d(u,v)","say":"두 노드 사이 최단 거리예요. 엣지로 이어져 있으면 1 이에요."}],"whole":"엣지에 대해서는 $d(u,v) = 1$ 이라 식이 간단해져요. 곡률은 그냥 '1 빼기 옮기는 비용'이에요."},{"kind":"figure","head":"삼각형과 다리에서 비용 비교","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb b1\" x=\"112\" y=\"28\" font-size=\"14\" text-anchor=\"middle\">삼각형: 공통 이웃은 제자리<\/text>\n<line class=\"e2 b1\" x1=\"66\" y1=\"106\" x2=\"158\" y2=\"106\"/>\n<line class=\"e2 b1\" x1=\"66\" y1=\"106\" x2=\"112\" y2=\"56\"/>\n<line class=\"e2 b1\" x1=\"158\" y1=\"106\" x2=\"112\" y2=\"56\"/>\n<circle class=\"n2 b1\" cx=\"66\" cy=\"106\" r=\"15\"/>\n<circle class=\"n3 b1\" cx=\"158\" cy=\"106\" r=\"15\"/>\n<circle class=\"n b1\" cx=\"112\" cy=\"56\" r=\"15\"/>\n<text class=\"tl b1\" x=\"66\" y=\"111\" font-size=\"13\" text-anchor=\"middle\">u<\/text>\n<text class=\"tl b1\" x=\"158\" y=\"111\" font-size=\"13\" text-anchor=\"middle\">v<\/text>\n<text class=\"tl b1\" x=\"112\" y=\"61\" font-size=\"13\" text-anchor=\"middle\">c<\/text>\n<text class=\"t b2\" x=\"112\" y=\"152\" font-size=\"13\" text-anchor=\"middle\">절반만 거리 1 옮기면 끝<\/text>\n<text class=\"tb b2\" x=\"112\" y=\"178\" font-size=\"14\" text-anchor=\"middle\">수송 비용 0.5<\/text>\n<text class=\"tb b3\" x=\"112\" y=\"206\" font-size=\"15\" text-anchor=\"middle\">곡률 +0.5<\/text>\n<text class=\"tb b1\" x=\"352\" y=\"28\" font-size=\"14\" text-anchor=\"middle\">다리: 전부 멀리 옮겨야 함<\/text>\n<line class=\"e2 b1\" x1=\"312\" y1=\"96\" x2=\"392\" y2=\"96\"/>\n<line class=\"e2 b1\" x1=\"312\" y1=\"96\" x2=\"268\" y2=\"62\"/>\n<line class=\"e2 b1\" x1=\"312\" y1=\"96\" x2=\"268\" y2=\"130\"/>\n<line class=\"e2 b1\" x1=\"392\" y1=\"96\" x2=\"436\" y2=\"62\"/>\n<line class=\"e2 b1\" x1=\"392\" y1=\"96\" x2=\"436\" y2=\"130\"/>\n<circle class=\"n2 b1\" cx=\"312\" cy=\"96\" r=\"15\"/>\n<circle class=\"n3 b1\" cx=\"392\" cy=\"96\" r=\"15\"/>\n<circle class=\"n b1\" cx=\"268\" cy=\"62\" r=\"11\"/>\n<circle class=\"n b1\" cx=\"268\" cy=\"130\" r=\"11\"/>\n<circle class=\"n b1\" cx=\"436\" cy=\"62\" r=\"11\"/>\n<circle class=\"n b1\" cx=\"436\" cy=\"130\" r=\"11\"/>\n<text class=\"tl b1\" x=\"312\" y=\"101\" font-size=\"13\" text-anchor=\"middle\">u<\/text>\n<text class=\"tl b1\" x=\"392\" y=\"101\" font-size=\"13\" text-anchor=\"middle\">v<\/text>\n<text class=\"t b2\" x=\"352\" y=\"160\" font-size=\"13\" text-anchor=\"middle\">한 덩어리는 거리 3 을 옮겨야 해요<\/text>\n<text class=\"tb b2\" x=\"352\" y=\"184\" font-size=\"14\" text-anchor=\"middle\">수송 비용 약 1.667<\/text>\n<text class=\"tb b3\" x=\"352\" y=\"210\" font-size=\"15\" text-anchor=\"middle\">곡률 -0.667<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"248\" font-size=\"14\" text-anchor=\"middle\">이웃이 겹칠수록 옮길 것이 적고, 곡률이 커요<\/text>\n<\/svg>","caption":"겹치는 이웃은 옮길 필요가 없어서 공짜예요. 그래서 이웃이 겹칠수록 비용이 싸고 곡률이 커요.","builds":3},{"kind":"steps","head":"세 가지 경우를 직접 계산","steps":["삼각형부터요. $u$ 의 이웃은 $v$ 와 $c$, $v$ 의 이웃은 $u$ 와 $c$ 예요. 각각 절반씩이에요.","$c$ 에 있는 절반은 제자리에 두면 되니 공짜예요. $v$ 의 절반만 $u$ 로 거리 1 을 옮겨요.","비용이 $0.5$ 이니 곡률은 $1 - 0.5 = +0.5$ 예요.","이번에는 노드 넷짜리 **클리크(Clique)** 의 엣지예요. 공통 이웃이 둘이라 3분의 2 가 공짜예요.","비용이 약 $0.333$ 이니 곡률은 $1 - 0.333 \\approx +0.667$ 이에요.","마지막으로 다리예요. 공통 이웃이 없어 전부 옮겨야 해요. 한 덩어리는 거리 3 을 가야 하죠."],"answer":"다리의 비용은 약 1.667 이라 곡률이 $1 - 1.667 \\approx -0.667$ 이에요. 공통 이웃이 많을수록 곡률이 커져요.","given":"이웃 분포는 이웃들에게 똑같이 나눈 것으로 잡아요."}],"pass3":[{"kind":"warn","head":"이 슬라이드의 참고문헌이 잘못 붙어 있어요","items":["p.25, p.26, p.27 모두 참고문헌이 'Chung 1997, Spectral Graph Theory' 로 적혀 있어요.","그 책에는 올리비에 리치 곡률이 나오지 않아요. p.24 치거 부등식의 출처가 그대로 복사된 것으로 보여요.","곡률과 압착을 연결한 것은 p.22 와 p.23 에 적힌 Topping 외 (ICLR 2022) 예요.","그리고 이웃 분포를 정의하는 방법이 문헌마다 조금씩 달라요. 문제에 주어진 정의를 그대로 쓰세요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Ollivier-Ricci curvature is one minus the optimal transport cost between the two neighborhood distributions.","ko":"올리비에 리치 곡률은 1 에서 두 이웃 분포 사이의 최적 수송 비용을 뺀 값이다.","tip":"optimal transport cost 라는 표현이 정의의 핵심이에요."},{"kind":"check","q":"**최적 수송(Optimal Transport)** 비용이 **작을수록** 곡률은 어떻게 되나요?","choices":["작아져요","커져요","변하지 않아요","항상 0 이에요"],"a":1,"why":"식이 1 에서 비용을 빼는 형태라, 비용이 작으면 곡률이 커요. 겹치는 이웃이 많다는 뜻이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.7954,0.3381],"c":[0,0.001,0.875,0.3719],"r":4.1827,"img":"img/L5/walk/p025_h.jpg"},"parts":[{"b":[0.576,0.358,0.306,0.18],"c":[0.5607,0.342,0.3366,0.212],"r":2.8226,"img":"img/L5/walk/p025_12_01.jpg","say":"맨 위: 이웃이 보라색 선으로 많이 이어져 있어요. 곡률이 양수예요."},{"b":[0.576,0.54,0.306,0.18],"c":[0.5607,0.524,0.3366,0.212],"r":2.8226,"img":"img/L5/walk/p025_12_02.jpg","say":"가운데: 한 줄씩 짝지어 이어져 있어요. 곡률이 0 이에요."},{"b":[0.576,0.72,0.306,0.18],"c":[0.5607,0.704,0.3366,0.212],"r":2.8226,"img":"img/L5/walk/p025_12_03.jpg","say":"맨 아래: 전혀 안 이어지고 부채꼴로 퍼져요. 곡률이 음수예요."}]}},{"p":26,"title":"양의 곡률은 평활화를 가속한다","terms":["Ricci Curvature","Over-smoothing","Clique","Degree"],"pass1":[{"kind":"say","lines":["곡률이 1 에 가까우면 두 노드의 이웃이 거의 같아요.","그러면 둘의 특징 차이가 층마다 빠르게 줄어들어요.","즉 양의 곡률은 **과도한 평활화(Over-smoothing)**를 **가속**해요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.03,"y":0.138,"w":0.3,"h":0.038,"say":"제목 아래 '양의 곡률은 과도한 평활화를 일으킨다'예요.","c":[0.015,0.102,0.33,0.11],"r":5.3333,"img":"img/L5/walk/p026_20_01.jpg"},{"x":0.09,"y":0.195,"w":0.86,"h":0.075,"say":"'직관: 곡률이 크게 양수면 두 이웃 집합이 많이 겹친다는 뜻이에요.'","c":[0.047,0.1369,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p026_20_02.jpg"},{"x":0.09,"y":0.323,"w":0.52,"h":0.038,"say":"'구조적 한계: 곡률은 공유 이웃 수의 하한을 알려 줘요.'","c":[0.064,0.2842,0.572,0.1156],"r":8.7966,"img":"img/L5/walk/p026_20_03.jpg"},{"x":0.39,"y":0.401,"w":0.19,"h":0.08,"say":"공유 이웃 비율이 곡률보다 작을 수 없다는 부등식이에요.","c":[0.378,0.385,0.214,0.112],"r":3.3968,"img":"img/L5/walk/p026_20_04.jpg"},{"x":0.09,"y":0.516,"w":0.86,"h":0.04,"say":"'특징 수렴: 두 노드 사이 특징 거리가 다음과 같이 제한돼요.'","c":[0.047,0.4404,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p026_20_05.jpg"},{"x":0.31,"y":0.636,"w":0.34,"h":0.05,"say":"앞에 1 빼기 곡률이 곱해져 있어요. 곡률이 1 이면 이 인자가 0 이에요.","c":[0.293,0.606,0.374,0.11],"r":6.0444,"img":"img/L5/walk/p026_20_06.jpg"}]},{"kind":"formula","head":"구조적 한계를 기호 하나씩","tex":"\\frac{|N_u \\cap N_v|}{\\max(m, n)} \\ge \\kappa(u, v)","parts":[{"sym":"N_u \\cap N_v","say":"$u$ 와 $v$ 의 **공통 이웃** 집합이에요."},{"sym":"|\\cdot|","say":"집합의 원소 개수예요."},{"sym":"\\max(m, n)","say":"두 노드의 이웃 수 중 큰 쪽이에요."},{"sym":"\\ge","say":"'작을 수 없다'는 뜻이에요."}],"whole":"우리말로 하면 '공유 이웃의 비율은 곡률보다 작을 수 없다'예요. 곡률이 0.9 면 이웃의 90퍼센트 이상이 공통이에요."},{"kind":"steps","head":"p.25 의 세 경우로 부등식 검증","steps":["삼각형은 공통 이웃이 $c$ 하나, 두 노드 이웃 수가 각각 2 예요.","비율이 $1 \\div 2 = 0.5$ 이고 곡률도 0.5 이니 **딱 등호**로 맞아요.","**클리크(Clique)** 엣지는 공통 이웃이 둘, 이웃 수가 3 이에요.","비율이 $2 \\div 3 \\approx 0.667$ 이고 곡률도 0.667 이니 역시 등호예요.","다리는 공통 이웃이 없어 비율이 0 이고 곡률이 -0.667 이에요. $0 \\ge -0.667$ 로 성립해요."],"answer":"세 경우 모두 성립하고, 양의 곡률 두 경우에서는 정확히 등호가 나왔어요.","given":"p.25 에서 계산한 삼각형, 클리크 엣지, 다리를 그대로 씁니다."},{"kind":"compare","head":"곡률에 따라 거리가 줄어드는 속도","cols":["층","곡률 0.9","곡률 0.5","곡률 0"],"rows":[["0","1.000","1.000","1.000"],["1","0.100","0.500","1.000"],["2","0.010","0.250","1.000"],["3","0.001","0.125","1.000"]]},{"kind":"points","head":"표를 읽는 법","items":["특징 거리 상계에 1 빼기 곡률이 곱해져 있어요.","곡률 0.9 면 층마다 0.1 배가 돼요. 3층이면 1000분의 1 이에요.","사실상 같은 노드가 된 거예요.","그래서 **클리크(Clique)**처럼 빽빽한 부분이 평활화의 진원지예요."]}],"pass3":[{"kind":"warn","head":"슬라이드에 정의되지 않은 기호가 있어요","items":["분모의 $\\max(m, n)$ 에서 $m$ 과 $n$ 이 무엇인지 어디에도 적혀 있지 않아요.","문맥과 위 검증 계산으로 볼 때 두 노드의 이웃 수로 읽는 것이 맞아요.","실제로 그렇게 두면 삼각형과 **클리크(Clique)**에서 등호가 정확히 성립해요.","특징 거리 식의 $h$ 함수도 구체적인 모양이 적혀 있지 않아요. 결론만 외우면 충분해요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Edges with curvature close to one force the two representations to collapse and accelerate over-smoothing.","ko":"곡률이 1 에 가까운 엣지는 두 표현을 붕괴시켜 과도한 평활화를 가속한다.","tip":"accelerate over-smoothing 이 슬라이드의 결론 표현이에요."},{"kind":"check","q":"곡률이 0.9 인 엣지로 이어진 두 노드는 몇 층 만에 거의 같아지나요?","choices":["100층","10층","3층","전혀 같아지지 않아요"],"a":2,"why":"층마다 0.1 배씩이라 3층이면 1000분의 1 이에요. 사실상 같은 노드예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.8838,0.7517],"c":[0,0,0.9722,0.8269],"r":2.0902,"img":"img/L5/walk/p026_h.jpg"},"parts":[{"b":[0.09,0.796,0.8,0.048],"c":[0.05,0.7311,0.88,0.1778],"r":8.7989,"img":"img/L5/walk/p026_11_01.jpg","say":"맨 아래 결론: '곡률이 1 에 가까운 엣지는 국소 표현을 무너뜨려서 과도한 평활화를 가속해요.'"}]}},{"p":27,"title":"음의 곡률은 압착을 일으킨다","terms":["Ricci Curvature","Over-squashing","Jacobian","Graph Rewiring","Bottleneck","Degree"],"pass1":[{"kind":"say","lines":["곡률이 음수면 두 이웃 집합을 잇는 **통로 엣지가 거의 없어요**.","통로가 없으면 그 엣지 하나가 유일한 길이에요. 즉 **병목(Bottleneck)**이죠.","그러면 **야코비안(Jacobian)**이 0 으로 밀려서 먼 정보가 구조적으로 막혀요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.03,"y":0.138,"w":0.29,"h":0.038,"say":"제목 아래 '음의 곡률은 과도한 압착을 일으킨다'예요.","c":[0.0155,0.102,0.319,0.11],"r":5.1556,"img":"img/L5/walk/p027_20_01.jpg"},{"x":0.09,"y":0.188,"w":0.86,"h":0.04,"say":"'직관: 곡률이 크게 음수면 두 이웃 집합을 잇는 통로 엣지가 부족해요.'","c":[0.047,0.1124,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p027_20_02.jpg"},{"x":0.09,"y":0.272,"w":0.7,"h":0.038,"say":"'통로 한계: 통로 엣지의 개수는 음의 곡률에 의해 엄격하게 제한돼요.'","c":[0.055,0.2132,0.77,0.1556],"r":8.7975,"img":"img/L5/walk/p027_20_03.jpg"},{"x":0.4,"y":0.319,"w":0.19,"h":0.06,"say":"통로 엣지 개수의 상한 식이에요.","c":[0.388,0.294,0.214,0.11],"r":3.4586,"img":"img/L5/walk/p027_20_04.jpg"},{"x":0.09,"y":0.401,"w":0.86,"h":0.04,"say":"'사라지는 야코비안: 먼 노드에 대한 민감도가 크기 항으로 제한돼요.'","c":[0.047,0.3254,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p027_20_05.jpg"},{"x":0.39,"y":0.469,"w":0.22,"h":0.09,"say":"민감도 상한 식이에요. 분자가 통로 수, 분모가 주변 혼잡도예요.","c":[0.378,0.453,0.244,0.122],"r":3.5556,"img":"img/L5/walk/p027_20_06.jpg"},{"x":0.09,"y":0.578,"w":0.86,"h":0.04,"say":"'결론: 음의 곡률이 통로를 줄여서 민감도를 0 으로 몰아가요.'","c":[0.047,0.5024,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p027_20_07.jpg"}]},{"kind":"formula","head":"민감도 상한을 기호 하나씩","tex":"\\alpha \\le \\frac{|S| + 2}{\\sum_{w \\in \\tilde{N}_v} \\left( \\deg(w) + 1 \\right)}","parts":[{"sym":"\\alpha","say":"먼 노드가 나에게 미치는 영향의 크기예요."},{"sym":"|S|","say":"통로 엣지의 개수예요. 두 이웃 집합을 직접 잇는 엣지죠."},{"sym":"\\deg(w)","say":"노드 $w$ 의 **차수(Degree)**예요."},{"sym":"\\sum_{w} (\\deg(w)+1)","say":"분모예요. $v$ 주변 전체의 혼잡도라고 보면 돼요."}],"whole":"우리말로 하면 '영향력은 통로 수를 주변 혼잡도로 나눈 값보다 클 수 없다'예요. 도로의 차선 수 나누기 통행량이에요."},{"kind":"steps","head":"통로를 더하면 얼마나 좋아지나","steps":["다리 예를 써요. $u$ 쪽에 이웃 둘, $v$ 쪽에 이웃 둘이고 그 사이 엣지가 없어요.","통로 엣지 개수가 0 이에요. 분자는 $0 + 2 = 2$ 예요.","분모를 구해요. $v$ 자신과 이웃들의 **차수(Degree)**에 1 씩 더해 합하면 $4 + 2 + 2 + 4 = 12$ 예요.","그러니 영향력 상한이 $2 \\div 12 \\approx 0.167$ 이에요.","이번에는 통로 엣지를 두 개 더해 봐요. 분자가 $2 + 2 = 4$ 가 돼요.","차수도 바뀌어 분모가 $4 + 3 + 3 + 4 = 14$ 예요. 상한이 $4 \\div 14 \\approx 0.286$ 이에요."],"answer":"통로 둘을 더하니 상한이 0.167 에서 0.286 으로 약 1.7배 커졌어요. 이것이 **그래프 재배선(Graph Rewiring)**의 원리예요.","given":"p.25 의 다리 예를 그대로 씁니다. 곡률은 약 -0.667 이었어요."},{"kind":"warn","head":"통로를 아무 데나 더하면 안 돼요","items":["슬라이드 오른쪽 그림 (b) 가 그 경고예요.","통로를 한 노드에만 몰아서 만들면 그 노드가 새 **병목(Bottleneck)**이 돼요.","우회로를 만든 게 아니라 새 다리를 만든 셈이죠.","그래서 **그래프 재배선(Graph Rewiring)**은 '어디에 더하는가'가 중요해요."]}],"pass3":[{"kind":"warn","head":"p.26 과 p.27 이 모순처럼 보이지만 아니에요","items":["p.26 은 **양의** 곡률이 나쁘다고 하고, p.27 은 **음의** 곡률이 나쁘다고 해요.","나빠지는 것이 서로 다르기 때문이에요. 양수면 평활화가, 음수면 압착이 심해져요.","그러니 이상적인 처방은 '극단으로 치우친 엣지의 곡률을 가운데로 모으는 것'이에요.","그리고 이 슬라이드에도 정의되지 않은 기호가 있어요. 통로 한계 식의 $n$ 이 무엇인지 적혀 있지 않아요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Negative curvature restricts the number of pathway edges, driving the sensitivity to zero.","ko":"음의 곡률은 통로 엣지의 수를 제한하여 민감도를 0 으로 몰아간다.","tip":"driving the sensitivity to zero 가 압착의 수학적 진술이에요."},{"kind":"check","q":"**그래프 재배선(Graph Rewiring)**이 하는 일은 무엇인가요?","choices":["가중치를 다시 학습해요","엣지를 더하거나 빼서 그래프 모양을 고쳐요","층 수를 줄여요","임베딩 차원을 늘려요"],"a":1,"why":"**야코비안(Jacobian)**의 구조 항은 학습으로 못 고쳐요. 그래서 그래프 자체를 고치는 처방이 나왔어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.8957,0.6041],"c":[0,0,0.9853,0.6645],"r":2.636,"img":"img/L5/walk/p027_h.jpg"},"parts":[{"b":[0.069,0.654,0.195,0.24],"c":[0.057,0.638,0.219,0.272],"r":1.4314,"img":"img/L5/walk/p027_11_01.jpg","say":"(a) 보라색 엣지가 두 이웃 집합을 이어 정보 통로 역할을 해요."},{"b":[0.514,0.654,0.201,0.24],"c":[0.502,0.638,0.225,0.272],"r":1.4706,"img":"img/L5/walk/p027_11_02.jpg","say":"(b) 엣지가 새 병목을 만들어 상황을 더 나쁘게 할 수도 있어요."}]}},{"p":28,"title":"구분: 도달 실패","terms":["Under-reaching","Over-squashing","Depth","Jacobian"],"pass1":[{"kind":"say","lines":["**도달 실패(Under-reaching)**는 압착의 **반대편 실패**예요.","$K$ 층 GNN은 각 노드의 $K$ 홉 이웃만 봐요.","그보다 먼 노드의 정보는 **아예 오지 않아요**. 거의 안 오는 게 아니라 하나도 안 와요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"compare","head":"압착과 도달 실패의 차이","cols":["항목","**과도한 압착(Over-squashing)**","**도달 실패(Under-reaching)**"],"rows":[["정보가 오기는 하나","온다","안 온다"],["**야코비안(Jacobian)** 값","0 은 아니지만 아주 작음","정확히 0"],["언제 생기나","깊게 쌓아 멀리 볼 때","얕아서 멀리 못 볼 때"],["원인","**병목(Bottleneck)**과 고정 길이 벡터","층 수가 문제 반경보다 적음"]]},{"kind":"points","head":"어느 쪽으로도 도망갈 곳이 없어요","items":["**깊이(Depth)**를 늘리면 **도달 실패(Under-reaching)**는 풀려요.","그런데 평활화와 압착이 심해져요.","**깊이(Depth)**를 줄이면 그 반대예요.","이것이 오늘 덱이 '깊이의 역설'이라고 부른 것의 전모예요."]}],"pass3":[],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.048,0.395,0.26,0.07],"c":[0.035,0.375,0.286,0.11],"r":4.6222,"img":"img/L5/walk/p028_11_01.jpg","say":"큰 제목: '도달 실패'."},{"b":[0.045,0.505,0.59,0.08],"c":[0.0155,0.4794,0.649,0.1311],"r":8.8007,"img":"img/L5/walk/p028_11_02.jpg","say":"'정반대의 실패예요. K층 GNN은 K홉 이웃만 보기 때문에 그보다 먼 정보는 아예 오지 않아요.'"}]}},{"p":29,"title":"도달 실패의 정의: 정확히 0","terms":["Under-reaching","Over-squashing","Jacobian","Receptive Field","Virtual Node","Degree"],"pass1":[{"kind":"say","lines":["$K$ 층 표현은 오직 $K$ 홉 이웃이 만드는 부분그래프만의 함수예요.","그 밖의 노드에 대한 **야코비안(Jacobian)**은 **정확히 0** 이에요.","압착의 '작은 값'과 다른 점이에요. 0 에 무엇을 곱해도 0 이니 학습으로 못 고쳐요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.055,"y":0.138,"w":0.89,"h":0.04,"say":"'수용 영역의 한계: K층이면 노드 표현을 K홉 이웃에서 재귀적으로 모아 계산해요.'","c":[0.0105,0.0591,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p029_20_01.jpg"},{"x":0.055,"y":0.222,"w":0.89,"h":0.075,"say":"'엄밀한 경계: K층 표현은 오직 K홉 이웃이 유도하는 부분그래프의 함수예요.'","c":[0.0105,0.1606,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p029_20_02.jpg"},{"x":0.055,"y":0.321,"w":0.89,"h":0.072,"say":"'정의: 필요한 정보가 노드 u 에 있는데 최단 거리가 K 보다 클 때 일어나요.'","c":[0.0105,0.2581,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p029_20_03.jpg"},{"x":0.055,"y":0.432,"w":0.64,"h":0.085,"say":"'수학적 결과: 야코비안 민감도가 정확히 0 이에요.'","c":[0.023,0.4034,0.704,0.1422],"r":8.8014,"img":"img/L5/walk/p029_20_04.jpg"},{"x":0.715,"y":0.42,"w":0.21,"h":0.062,"say":"오른쪽 식이 그 결론이에요. 부등호가 아니라 **등호**로 0 이에요.","c":[0.703,0.396,0.234,0.11],"r":3.7818,"img":"img/L5/walk/p029_20_05.jpg"}]},{"kind":"formula","head":"도달 실패의 결론식","tex":"\\frac{\\partial h_v^{(K)}}{\\partial x_u} = 0 \\quad \\text{when} \\quad d(u,v) > K","parts":[{"sym":"h_v^{(K)}","say":"$K$ 층 뒤 노드 $v$ 의 표현이에요."},{"sym":"x_u","say":"노드 $u$ 의 맨 처음 입력 특징이에요."},{"sym":"d(u,v)","say":"최단 경로 거리예요. 엣지 몇 개를 지나야 하는지죠."},{"sym":"= 0","say":"등호예요. 근사가 아니라 **정확히** 0 이에요."}],"whole":"p.22 의 압착 식은 부등호였어요. 작지만 0 은 아닐 수 있다는 뜻이죠. 여기는 **등호로 0** 이에요. 이 차이가 두 고장을 가릅니다."},{"kind":"figure","head":"2층이면 4번부터는 정확히 0","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<line class=\"e2\" x1=\"52\" y1=\"80\" x2=\"120\" y2=\"80\"/>\n<line class=\"e2\" x1=\"120\" y1=\"80\" x2=\"188\" y2=\"80\"/>\n<line class=\"e\" x1=\"188\" y1=\"80\" x2=\"256\" y2=\"80\"/>\n<line class=\"e\" x1=\"256\" y1=\"80\" x2=\"324\" y2=\"80\"/>\n<line class=\"e\" x1=\"324\" y1=\"80\" x2=\"392\" y2=\"80\"/>\n<rect class=\"box2 b1\" x=\"26\" y=\"50\" width=\"188\" height=\"60\" rx=\"10\"/>\n<circle class=\"n2\" cx=\"52\" cy=\"80\" r=\"16\"/>\n<circle class=\"n2\" cx=\"120\" cy=\"80\" r=\"16\"/>\n<circle class=\"n2\" cx=\"188\" cy=\"80\" r=\"16\"/>\n<circle class=\"n\" cx=\"256\" cy=\"80\" r=\"16\"/>\n<circle class=\"n\" cx=\"324\" cy=\"80\" r=\"16\"/>\n<circle class=\"n\" cx=\"392\" cy=\"80\" r=\"16\"/>\n<text class=\"tl\" x=\"52\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"tl\" x=\"120\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"188\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">3<\/text>\n<text class=\"tl\" x=\"256\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">4<\/text>\n<text class=\"tl\" x=\"324\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">5<\/text>\n<text class=\"tl\" x=\"392\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">6<\/text>\n<text class=\"tb b1\" x=\"120\" y=\"36\" font-size=\"14\" text-anchor=\"middle\">2층의 수용 영역<\/text>\n<text class=\"t b2\" x=\"52\" y=\"132\" font-size=\"14\" text-anchor=\"middle\">0.417<\/text>\n<text class=\"t b2\" x=\"120\" y=\"132\" font-size=\"14\" text-anchor=\"middle\">0.417<\/text>\n<text class=\"t b2\" x=\"188\" y=\"132\" font-size=\"14\" text-anchor=\"middle\">0.167<\/text>\n<text class=\"tb b2\" x=\"256\" y=\"132\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<text class=\"tb b2\" x=\"324\" y=\"132\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<text class=\"tb b2\" x=\"392\" y=\"132\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"180\" font-size=\"15\" text-anchor=\"middle\">작은 값이 아니라 정확히 0 이에요<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"208\" font-size=\"15\" text-anchor=\"middle\">0 에 무엇을 곱해도 0 이니<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"236\" font-size=\"15\" text-anchor=\"middle\">학습으로는 절대 못 고쳐요<\/text>\n<\/svg>","caption":"노드 여섯 개를 한 줄로 이었어요. 2층 GNN에서 노드 1 이 보는 범위는 1, 2, 3 뿐이에요.","builds":3},{"kind":"steps","head":"길 그래프에서 0 을 직접 확인","steps":["노드 여섯 개를 한 줄로 잇고 자기 고리를 더해요. **차수(Degree)**가 2, 3, 3, 3, 3, 2 예요.","행 1 은 0.5, 0.5, 0, 0, 0, 0 이에요. 행 2 는 3분의 1 씩 세 칸이고요.","두 걸음 뒤 노드 1 의 분포는 0.417, 0.417, 0.167, 0, 0, 0 이에요. 합이 1 이니 검산 통과예요.","4, 5, 6 번 칸이 **정확히 0** 이에요. 반올림한 0 이 아니에요.","세 걸음으로 늘리면 0.347, 0.403, 0.194, 0.056, 0, 0 이에요.","노드 4 가 드디어 보여요. 그래도 5 와 6 은 여전히 정확히 0 이에요."],"answer":"노드 1 이 노드 6 을 보려면 정확히 5층이 필요해요. 4층까지는 아무리 학습해도 0 이에요.","given":"노드 여섯 개를 한 줄로 이은 그래프예요."},{"kind":"points","head":"그럼 어떻게 고치나요","items":["층을 늘리면 돼요. 다만 평활화와 압착이 따라와요.","그래프에 지름길을 놓을 수도 있어요. **가상 노드(Virtual Node)**를 하나 끼워 넣는 방법이에요.","**가상 노드(Virtual Node)**는 모든 노드와 이어진 가짜 노드예요. 그러면 어떤 두 노드도 2홉이면 통해요.","아니면 한 층에서 여러 홉을 동시에 보게 하면 돼요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"Under-reaching occurs when the required information sits at a node farther than K hops, so the Jacobian is identically zero.","ko":"도달 실패는 필요한 정보가 K홉보다 먼 노드에 있을 때 생기며, 그래서 야코비안이 항등적으로 0 이다.","tip":"identically zero 가 압착과 구별되는 결정적 표현이에요."},{"kind":"warn","head":"K홉 안이라고 다 잘 보이는 것은 아니에요","items":["$K$ 홉 **밖**은 **도달 실패(Under-reaching)**로 정확히 0 이에요.","$K$ 홉 **안**이라도 **병목(Bottleneck)**을 지나면 **과도한 압착(Over-squashing)**으로 거의 0 이에요.","즉 두 고장은 배타적이지 않고 같이 일어날 수 있어요. 슬라이드 그림에 둘이 함께 그려진 이유예요."]},{"kind":"check","q":"**도달 실패(Under-reaching)**일 때 **야코비안(Jacobian)** 값은 얼마인가요?","choices":["아주 작은 값","정확히 0","1 에 가까운 값","음수"],"a":1,"why":"정확히 0 이에요. 0 에 어떤 가중치를 곱해도 0 이라 학습으로 되살릴 수 없어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.937,0.5145],"c":[0,0,1,0.566],"r":3.141,"img":"img/L5/walk/p029_h.jpg"},"parts":[{"b":[0.34,0.543,0.34,0.358],"c":[0.323,0.5251,0.374,0.3938],"r":1.6884,"img":"img/L5/walk/p029_11_01.jpg","say":"그림 한 장에 오늘의 두 고장이 다 있어요."},{"b":[0.395,0.548,0.18,0.06],"c":[0.383,0.523,0.204,0.11],"r":3.297,"img":"img/L5/walk/p029_11_02.jpg","say":"빨간 X 표시가 있는 쪽이 '도달 실패'예요. 너무 멀어서 못 와요."},{"b":[0.405,0.76,0.18,0.05],"c":[0.393,0.73,0.204,0.11],"r":3.297,"img":"img/L5/walk/p029_11_03.jpg","say":"파란 점선이 몰려드는 쪽이 '과도한 압착'이에요. 오긴 오는데 뭉개져요."}]}},{"p":30,"title":"넓게 만들어도 안 된다","terms":["Under-reaching","Depth","Width","Over-smoothing","Graph Rewiring","Virtual Node"],"pass1":[{"kind":"say","lines":["'층을 못 늘리면 대신 벡터를 엄청 길게 하면 되지 않나요?'","답은 **안 된다**예요.","Loukas 는 **깊이(Depth)**와 **너비(Width)**의 **곱**이 그래프 크기에 따라 커져야 한다고 증명했어요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"compare","head":"두 방법의 비용 차이","cols":["무엇을 늘리나","용량","파라미터 수","부작용"],"rows":[["**깊이(Depth)**를 2배","2배","2배","**과도한 평활화(Over-smoothing)**와 압착"],["**너비(Width)**를 2배","2배","4배","과적합과 메모리 폭발"]]},{"kind":"steps","head":"너비로 채우면 얼마나 드나","steps":["용량이 노드 수 $N$ 정도는 되어야 한다고 하고, **깊이(Depth)**를 3 으로 고정해요.","노드 1,000 개면 **너비(Width)**가 약 333 이어야 해요. 가중치 행렬이 $333 \\times 333$ 이니 약 11만 개예요.","노드 10,000 개면 너비가 약 3,333, 파라미터가 약 1,111만 개예요.","노드 100,000 개면 너비가 약 33,333, 파라미터가 약 11억 개예요.","이게 층 **하나** 값이에요. 3층이면 세 배죠."],"answer":"가중치 행렬이 너비의 제곱이라 너비를 두 배로 하면 파라미터가 네 배예요. 깊이는 두 배면 두 배고요.","given":"용량이 노드 수만큼 필요하다고 두고, 깊이를 3 으로 고정해요."},{"kind":"points","head":"결론을 세 단계로 정리하면","items":["첫째, 전역 성질을 계산하려면 용량이 그래프 크기만큼 커야 해요.","둘째, 평활화 때문에 **깊이(Depth)**는 2에서 4 정도로 묶여 있어요.","셋째, 그러면 **너비(Width)**가 노드 수만큼 커져야 하는데 파라미터가 제곱으로 폭발해요.","그래서 깊이도 너비도 아닌 제 3 의 길이 필요해요."]},{"kind":"points","head":"제 3 의 길이 무엇인가요","items":["**그래프 재배선(Graph Rewiring)**으로 그래프 자체를 고치기예요.","**가상 노드(Virtual Node)**를 넣어 모든 노드를 2홉으로 잇기예요.","한 층에서 여러 홉을 동시에 보는 다중 홉 집계예요.","p.36 의 처방 표가 정확히 이 목록이에요."]}],"pass3":[{"kind":"warn","head":"슬라이드의 기호 표기가 부정확해요","items":["'깊이와 너비의 곱이 그래프 크기 O(N) 에 비례해야 한다'고 적혀 있어요.","그런데 O 표기는 '이보다 크지 않다'는 **상계** 기호예요.","여기서 말하려는 것은 '이 정도는 되어야 한다'는 **하계**이니 오메가 기호를 써야 맞아요.","답안에는 기호를 피하고 말로 쓰세요. '깊이와 너비의 곱이 그래프 크기에 따라 커져야 한다'예요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"No amount of width can overcome under-reaching if the depth is kept a small constant.","ko":"깊이를 작은 상수로 유지하면 너비를 아무리 늘려도 도달 실패를 극복할 수 없다.","tip":"No amount of width 라는 표현이 강한 부정을 잘 전달해요."},{"kind":"check","q":"**너비(Width)**를 두 배로 늘리면 파라미터 수는 어떻게 되나요?","choices":["그대로","두 배","네 배","절반"],"a":2,"why":"가중치 행렬이 너비 곱하기 너비라서 제곱으로 늘어요. 그래서 너비로 채우는 게 훨씬 비싸요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.3139,0.0757],"c":[0,0.0019,0.3453,0.1077],"r":5.6998,"img":"img/L5/walk/p030_h.jpg"},"parts":[{"b":[0.055,0.151,0.64,0.042],"c":[0.023,0.1009,0.704,0.1422],"r":8.8014,"img":"img/L5/walk/p030_11_01.jpg","say":"질문: '얕은 신경망의 너비를 무한히 키우면 도달 실패를 풀 수 있을까요?'"},{"b":[0.055,0.278,0.89,0.075],"c":[0.0105,0.2166,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p030_11_02.jpg","say":"'이론적 한계: 깊이와 너비의 곱이 그래프 크기에 비례하지 않으면 전역 성질을 계산할 수 없어요.'"},{"b":[0.055,0.463,0.89,0.075],"c":[0.0105,0.4016,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p030_11_03.jpg","say":"'결론: 깊이를 작은 상수로 두면 너비를 아무리 키워도 도달 실패를 넘을 수 없어요.'"}]}},{"p":31,"title":"과제에 따라 다르다","terms":["Under-reaching","Homophily","Heterophily","GCN","Depth"],"pass1":[{"kind":"say","lines":["**도달 실패(Under-reaching)**가 늘 나쁜 건 아니에요. 과제에 따라 달라요.","**동질성(Homophily)**이 강한 그래프에서는 2층이면 충분해요.","**동질성(Homophily)**은 '비슷한 것끼리 연결되는 경향'이에요."]},{"kind":"analogy","head":"반 친구만 봐도 아는 것과 모르는 것","scene":"전학생이 어느 동아리인지 맞히려면 옆자리 친구 셋만 봐도 거의 맞아요. 같은 동아리끼리 앉으니까요. 그런데 '이 학생이 3년 뒤 어느 대학에 갈까'를 맞히려면 옆자리만 봐서는 안 돼요. 먼 곳의 정보가 필요하죠.","map":[["옆자리만 봐도 되는 문제","**동질성(Homophily)**이 강한 인용망과 소셜망"],["먼 곳을 봐야 하는 문제","분자 화학과 알고리즘 과제"],["옆자리가 오히려 헷갈리는 경우","**이질성(Heterophily)** 그래프"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"steps","head":"동질성이 왜 도달 실패를 무력화하나","steps":["논문 인용망에서 '이 논문은 기계학습 분야인가'를 맞힌다고 해요.","**동질성(Homophily)**이 강하면 내 이웃의 80퍼센트가 나와 같은 분야예요.","2홉이면 $0.8 \\times 0.8 = 0.64$ 예요. 아직 쓸 만해요.","3홉이면 $0.8 \\times 0.8 \\times 0.8 \\approx 0.512$ 예요. 동전 던지기와 비슷해요.","4홉이면 약 0.410 이에요. 이제는 오히려 방해가 돼요."],"answer":"3홉만 가도 확률이 절반 근처예요. 즉 먼 노드는 정보가 아니라 잡음이에요. 2층에서 멈추는 게 정답이에요.","given":"이웃의 80퍼센트가 나와 같은 분야인 인용망을 생각해요."},{"kind":"compare","head":"이질성 그래프는 왜 어려운가","cols":["홉","이 거리에서 만나는 것","나와 같은 부류일 확률"],"rows":[["1","피해자 계정","낮음"],["2","다른 사기꾼","높음"],["3","또 다른 피해자","낮음"]]},{"kind":"points","head":"이질성 그래프에서 GCN 이 약한 이유","items":["**이질성(Heterophily)** 그래프에서는 **짝수 홉**이 중요해요.","그런데 **GCN**은 층마다 1홉씩 섞으면서 짝수 홉과 홀수 홉을 구별하지 않아요.","다 합쳐 버리니 중요한 신호가 지워져요.","그래서 **이질성(Heterophily)** 그래프에는 다른 처방이 필요해요."]},{"kind":"mining","src":"마이닝 10강 Random Walk-based GRL","lines":["**동질성(Homophily)**은 node2vec 을 배울 때 정면으로 다뤘어요.","같은 커뮤니티에 속하면 비슷하다는 것이 **동질성(Homophily)**, 역할이 같으면 비슷하다는 것이 구조적 동등성이었죠.","node2vec 은 걸음 전략을 바꿔서 둘 중 무엇을 잡을지 조절했어요.","GNN 쪽 대응이 오늘 배울 다중 홉 집계 같은 처방이에요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"Under-reaching is harmless on highly homophilous graphs but fatal on molecular and algorithmic tasks.","ko":"도달 실패는 동질성이 강한 그래프에서는 해가 없지만 분자와 알고리즘 과제에서는 치명적이다.","tip":"harmless 와 fatal 을 대비시키면 슬라이드 구조 그대로예요."},{"kind":"check","q":"**동질성(Homophily)**이 강한 그래프에서 2층 **GCN**이 잘 되는 이유는 무엇인가요?","choices":["계산이 빨라서","직접 이웃만으로도 클래스가 예측되어서","파라미터가 적어서","메모리를 아껴서"],"a":1,"why":"Cora 와 Citeseer 에서 2층 **GCN**이 잘 되는 이유가 이거예요. 먼 노드는 오히려 잡음이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4561,0.0757],"c":[0,0.0019,0.5017,0.1077],"r":8.2814,"img":"img/L5/walk/p031_h.jpg"},"parts":[{"b":[0.055,0.146,0.28,0.04],"c":[0.041,0.111,0.308,0.11],"r":4.9778,"img":"img/L5/walk/p031_20_01.jpg","say":"'도달 실패가 문제가 아닌 경우'. 초록 글씨로 강조돼 있어요."},{"b":[0.09,0.216,0.86,0.075],"c":[0.047,0.1579,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p031_20_02.jpg","say":"'인용 네트워크와 소셜 네트워크: 동질성이 높아요. 2층 GCN이 잘 되는 이유예요.'"},{"b":[0.055,0.343,0.28,0.04],"c":[0.041,0.308,0.308,0.11],"r":4.9778,"img":"img/L5/walk/p031_20_03.jpg","say":"'도달 실패가 치명적인 경우'. 빨간 글씨로 강조돼 있어요."},{"b":[0.09,0.414,0.68,0.04],"c":[0.056,0.3584,0.748,0.1511],"r":8.8006,"img":"img/L5/walk/p031_20_04.jpg","say":"'분자 화학: 멀리 떨어진 두 작용기가 상호작용하는 성질 예측.'"},{"b":[0.09,0.541,0.68,0.04],"c":[0.056,0.4854,0.748,0.1511],"r":8.8006,"img":"img/L5/walk/p031_20_05.jpg","say":"'알고리즘 과제: 외판원 문제, 불 만족 문제, 최단 경로 찾기.'"},{"b":[0.09,0.669,0.62,0.04],"c":[0.059,0.6201,0.682,0.1378],"r":8.7986,"img":"img/L5/walk/p031_20_06.jpg","say":"'이질 그래프: 비슷한 노드가 이질적인 연결로 떨어져 있는 경우.'"}]}},{"p":32,"title":"구분: 최적화 문제","terms":["Vanishing Gradient","Overfitting","Over-smoothing","Residual Connection","DropEdge"],"pass1":[{"kind":"say","lines":["**과적합(Overfitting)**과 **기울기 소실(Vanishing Gradient)**은 그래프만의 문제가 아니에요.","모든 깊은 신경망이 겪는 일반적인 문제예요.","그래서 좋은 소식이 하나 있어요. 이미 풀린 문제거든요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"compare","head":"그래프 특유의 문제인가","cols":["고장","그래프 특유?","해법"],"rows":[["**과도한 평활화(Over-smoothing)**","예","그래프 전용 처방 필요"],["과도한 압착","예","그래프 전용 처방 필요"],["도달 실패","예","그래프 전용 처방 필요"],["**과적합(Overfitting)**","아니오","**DropEdge** 등 일반 규제"],["**기울기 소실(Vanishing Gradient)**","아니오","**잔차 연결(Residual Connection)** 등 일반 기법"]]},{"kind":"points","head":"좋은 소식과 나쁜 소식","items":["좋은 소식은 뒤쪽 두 가지가 이미 딥러닝에서 풀린 문제라는 거예요.","ResNet 의 **잔차 연결(Residual Connection)**이 **기울기 소실(Vanishing Gradient)**을 풀었어요.","드롭아웃이 **과적합(Overfitting)**을 풀었고, 그래프 버전이 **DropEdge**예요.","나쁜 소식은 그것들을 가져와도 평활화와 압착과 도달 실패는 그대로라는 거예요."]}],"pass3":[{"kind":"check","q":"다음 중 **그래프 특유**의 문제가 **아닌** 것은 무엇인가요?","choices":["과도한 평활화","과도한 압착","도달 실패","**기울기 소실(Vanishing Gradient)**"],"a":3,"why":"기울기 소실과 **과적합(Overfitting)**은 모든 깊은 신경망의 문제예요. 이 구분을 묻기 좋아요."}],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.048,0.364,0.24,0.07],"c":[0.036,0.344,0.264,0.11],"r":4.2667,"img":"img/L5/walk/p032_11_01.jpg","say":"큰 제목: '최적화 문제'."},{"b":[0.045,0.475,0.56,0.08],"c":[0.017,0.4528,0.616,0.1245],"r":8.7961,"img":"img/L5/walk/p032_11_02.jpg","say":"'과도한 평활화와 달리 이 실패들은 그래프만의 문제가 아니에요.'"}]}},{"p":33,"title":"과적합: 파라미터는 많고 레이블은 적다","terms":["Overfitting","DropEdge","Over-smoothing","GCN","Depth"],"pass1":[{"kind":"say","lines":["깊은 **GCN**은 **과적합(Overfitting)**을 겪어요.","파라미터는 많은데 레이블 붙은 노드가 몇 개뿐이거든요.","증상은 이래요. 훈련 손실은 낮은데 검증 손실이 올라가요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.055,"y":0.138,"w":0.32,"h":0.042,"say":"'과적합: GNN도 과적합을 겪어요.'","c":[0.039,0.104,0.352,0.11],"r":5.6889,"img":"img/L5/walk/p033_20_01.jpg"},{"x":0.09,"y":0.204,"w":0.43,"h":0.038,"say":"'파라미터는 너무 많은데 데이터 점은 몇 개뿐이에요.'","c":[0.0685,0.168,0.473,0.11],"r":7.6444,"img":"img/L5/walk/p033_20_02.jpg"},{"x":0.177,"y":0.315,"w":0.316,"h":0.426,"say":"왼쪽이 훈련 손실이에요. 주황 점선이 가장 낮게 0.1 근처예요.","c":[0.1612,0.2937,0.3476,0.4686],"r":1.3187,"img":"img/L5/walk/p033_20_03.jpg"},{"x":0.507,"y":0.315,"w":0.319,"h":0.426,"say":"오른쪽이 검증 손실이에요. 같은 주황 점선이 0.75 까지 올라가요.","c":[0.491,0.2937,0.3509,0.4686],"r":1.3312,"img":"img/L5/walk/p033_20_04.jpg"},{"x":0.38,"y":0.38,"w":0.18,"h":0.08,"say":"범례 네 줄이에요. 점선이 DropEdge 없음, 실선이 DropEdge 적용이에요.","c":[0.368,0.364,0.204,0.112],"r":3.2381,"img":"img/L5/walk/p033_20_05.jpg"}]},{"kind":"compare","head":"같은 4층 모델, 두 가지 학습","cols":["항목","**DropEdge** 없음","**DropEdge** 적용"],"rows":[["훈련 손실","0.1 로 아주 낮음","0.25"],["검증 손실","0.75 로 다시 올라감","0.4 로 낮게 유지"],["해석","외웠어요","배웠어요"]]},{"kind":"steps","head":"파라미터와 레이블 수를 세어 보기","steps":["입력 특징 500 개, 숨은 차원 64, 클래스 3 개인 8층 **GCN**을 생각해요.","첫 층은 $500 \\times 64 = 32{,}000$ 개예요.","2층부터 7층까지는 $64 \\times 64 = 4{,}096$ 개가 여섯 번이라 24,576 개예요.","마지막 층은 $64 \\times 3 = 192$ 개예요.","모두 더하면 56,768 개예요.","그런데 레이블 붙은 노드는 흔히 120 개 남짓이에요."],"answer":"레이블 하나당 조정할 파라미터가 $56{,}768 \\div 120 \\approx 473$ 개예요. 미지수 473 개에 식이 하나인 셈이죠.","given":"준지도 노드 분류에서는 그래프에 노드가 3,000 개 있어도 레이블은 100 개 남짓이에요."},{"kind":"points","head":"**DropEdge** 가 왜 도움이 되나요","items":["매 학습 반복마다 엣지의 절반을 무작위로 지워요.","그러면 모델이 매번 조금 다른 그래프를 보게 돼요.","특정 엣지 하나에 의존하는 답을 외울 수가 없어요.","데이터를 늘린 것과 비슷한 효과예요. 이것을 데이터 증강이라고 불러요."]}],"pass3":[{"kind":"warn","head":"과적합과 과도한 평활화를 구별하세요","items":["**과적합(Overfitting)**은 훈련 손실이 **아주 낮은데** 검증만 나빠요.","**과도한 평활화(Over-smoothing)**는 훈련 손실**조차** 안 내려가요.","슬라이드 왼쪽 그래프에서 8층 모델의 파란 점선이 훈련 손실조차 안 내려갔죠.","그건 이미 평활화로 망가진 상태라는 증거예요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"DropEdge randomly removes a fraction of the edges at every training epoch, acting as data augmentation.","ko":"DropEdge 는 매 학습 에폭마다 엣지의 일부를 무작위로 제거하여 데이터 증강 역할을 한다.","tip":"acting as data augmentation 이 왜 효과가 있는지를 설명하는 부분이에요."},{"kind":"check","q":"훈련 손실이 낮은데 검증 손실이 올라가면 무엇을 의심해야 하나요?","choices":["**과적합(Overfitting)**","**과도한 평활화(Over-smoothing)**","기울기 폭발","학습률이 너무 작음"],"a":0,"why":"둘 다 나쁘면 평활화, 훈련만 좋으면 **과적합(Overfitting)**이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5036,0.2336],"c":[0,0.0019,0.554,0.2656],"r":3.7082,"img":"img/L5/walk/p033_h.jpg"},"parts":[{"b":[0.507,0.315,0.319,0.426],"c":[0.491,0.2937,0.3509,0.4686],"r":1.3312,"img":"img/L5/walk/p033_11_01.jpg","say":"오른쪽이 검증 손실이에요. 여기가 진짜 이야기예요."},{"b":[0.528,0.543,0.295,0.074],"c":[0.5132,0.525,0.3245,0.11],"r":5.2444,"img":"img/L5/walk/p033_11_02.jpg","say":"빨간 네모 안 주황 점선이 50 근처에서 바닥을 치고 다시 올라가요. 그게 과적합이에요."}]}},{"p":34,"title":"기울기 소실: 1 보다 작은 수를 백 번 곱하면","terms":["Vanishing Gradient","Residual Connection","Depth","DeepGCNs"],"pass1":[{"kind":"say","lines":["역전파는 층마다의 변화율을 계속 곱하는 계산이에요.","각 변화율이 1 보다 작으면 곱이 지수적으로 0 이 돼요.","그러면 앞쪽 층에 기울기가 안 와서 학습이 멈춰요. 이것이 **기울기 소실(Vanishing Gradient)**이에요."]},{"kind":"analogy","head":"복사기로 복사한 것을 또 복사하기","scene":"선생님이 나눠 준 그림을 복사기로 복사해요. 한 번 복사하면 조금 흐려지죠. 그 복사본을 또 복사하면 더 흐려져요. 열 번쯤 반복하면 무슨 그림인지 알아볼 수 있지만, 백 번 반복하면 그냥 하얀 종이가 돼요.","map":[["한 번 복사할 때 흐려지는 정도","층 하나당 변화율 0.9"],["백 번 반복","층 100 개 쌓기"],["하얀 종이","기울기가 사실상 0"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.055,"y":0.136,"w":0.18,"h":0.042,"say":"'기울기 소실'이 이 슬라이드의 주제예요.","c":[0.043,0.102,0.204,0.11],"r":3.297,"img":"img/L5/walk/p034_20_01.jpg"},{"x":0.09,"y":0.204,"w":0.18,"h":0.038,"say":"'l층의 기울기'. 아래 식이 연쇄 법칙이에요.","c":[0.078,0.168,0.204,0.11],"r":3.297,"img":"img/L5/walk/p034_20_02.jpg"},{"x":0.22,"y":0.253,"w":0.53,"h":0.093,"say":"가운데 식이에요. 층마다의 변화율을 계속 곱해요.","c":[0.1935,0.237,0.583,0.125],"r":8.2916,"img":"img/L5/walk/p034_20_03.jpg"},{"x":0.09,"y":0.374,"w":0.62,"h":0.042,"say":"'모델이 깊어질수록 기울기가 사라져요.' 아래첨자가 깨져 있어요.","c":[0.059,0.3261,0.682,0.1378],"r":8.7986,"img":"img/L5/walk/p034_20_04.jpg"},{"x":0.02,"y":0.47,"w":0.94,"h":0.36,"say":"그림 다섯 장. RGB 를 특징으로 썼는데 층이 깊어질수록 검게 변해요.","c":[0,0.452,1,0.396],"r":4.4893,"img":"img/L5/walk/p034_20_05.jpg"}]},{"kind":"compare","head":"층 수에 따른 기울기 크기","cols":["층 수","한 층당 0.9","한 층당 0.99"],"rows":[["10","0.349","0.904"],["50","0.0052","0.605"],["100","0.0000266","0.366"],["500","사실상 0","0.0066"]]},{"kind":"steps","head":"0.9 를 백 번 곱하면","steps":["한 층당 변화율이 0.9 라고 해요.","10층이면 $0.9$ 를 열 번 곱해서 약 0.349 예요. 3분의 1 이죠.","50층이면 약 0.00515 예요. 200분의 1 이에요.","100층이면 약 0.0000266 이에요. 3만 8천 분의 1 이죠.","500층이면 $10^{-23}$ 수준이에요.","32비트 실수의 정밀도가 약 $10^{-7}$ 이니, 컴퓨터 안에서는 그냥 0 이에요."],"answer":"가중치가 전혀 안 움직여요. 슬라이드 그림의 '층 500 RGB = [0,0,0]' 이 정확히 이 상황이에요.","given":"층마다의 변화율 상한이 0.9 라고 두고 계산해요."},{"kind":"figure","head":"잔차 연결이 기울기에 길을 낸다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<line class=\"e\" x1=\"56\" y1=\"180\" x2=\"450\" y2=\"180\"/>\n<line class=\"e\" x1=\"56\" y1=\"40\" x2=\"56\" y2=\"180\"/>\n<text class=\"tm\" x=\"56\" y=\"202\" font-size=\"13\" text-anchor=\"middle\">0<\/text>\n<text class=\"tm\" x=\"140\" y=\"202\" font-size=\"13\" text-anchor=\"middle\">10<\/text>\n<text class=\"tm\" x=\"230\" y=\"202\" font-size=\"13\" text-anchor=\"middle\">50<\/text>\n<text class=\"tm\" x=\"320\" y=\"202\" font-size=\"13\" text-anchor=\"middle\">100<\/text>\n<text class=\"tm\" x=\"430\" y=\"202\" font-size=\"13\" text-anchor=\"middle\">500<\/text>\n<text class=\"tm\" x=\"250\" y=\"226\" font-size=\"14\" text-anchor=\"middle\">층 수<\/text>\n<text class=\"tm\" x=\"26\" y=\"46\" font-size=\"13\" text-anchor=\"middle\">기울기<\/text>\n<polyline class=\"e2 b1\" points=\"56,44 140,132 230,172 320,178 430,180\" fill=\"none\"/>\n<text class=\"tb b1\" x=\"200\" y=\"158\" font-size=\"14\">잔차 없음: 0.9 를 계속 곱해요<\/text>\n<polyline class=\"e2 b2\" points=\"56,44 140,44 230,44 320,44 430,44\" fill=\"none\"/>\n<text class=\"tb b2\" x=\"220\" y=\"36\" font-size=\"14\">잔차 연결 있음: 더하기 1 덕분에 살아남아요<\/text>\n<rect class=\"box2 b3\" x=\"66\" y=\"238\" width=\"360\" height=\"26\" rx=\"6\"/>\n<text class=\"tb b3\" x=\"246\" y=\"256\" font-size=\"14\" text-anchor=\"middle\">100층이면 3만 8천 분의 1 로 줄어요<\/text>\n<\/svg>","caption":"$y = F(x) + x$ 로 두면 미분에 1 이 더해져요. 그러니 곱해 나가도 0 이 되지 않아요.","builds":3},{"kind":"points","head":"그래서 해법이 잔차 연결이에요","items":["$y = F(x) + x$ 를 미분하면 $F$ 의 미분에 **1 이 더해져요**.","$F$ 의 미분이 0 이 되어도 전체는 최소 1 이에요.","그러니 층마다 곱해도 값이 죽지 않아요.","이것이 p.41 의 **DeepGCNs**가 하는 일이에요."]}],"pass3":[{"kind":"warn","head":"이 슬라이드의 수식은 깨진 상태로 인쇄되어 있어요","items":["첫째, 좌변의 연쇄가 중간에 끊겨 있어요. 마지막 두 항 사이에 있어야 할 항 하나가 빠졌어요.","둘째, 부등식 우변 끝에 좌변의 항이 그대로 남아 있어요. 상계를 쓰려면 이것도 상수로 바꿔야 해요.","셋째, 아래 문장의 아래첨자가 위 식과 달라요. 최댓값을 뜻하는 글자가 깨진 것으로 보여요.","바르게 읽으면 '층마다의 변화율 상한이 1 보다 작으면 곱이 지수적으로 0 이 된다'예요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Residual connections add an identity path whose derivative is one, which keeps the gradient from vanishing.","ko":"잔차 연결은 미분이 1 인 항등 경로를 더해서 기울기가 사라지는 것을 막는다.","tip":"an identity path whose derivative is one 이 핵심 구절이에요."},{"kind":"check","q":"**잔차 연결(Residual Connection)**이 **기울기 소실(Vanishing Gradient)**을 막는 원리는 무엇인가요?","choices":["가중치를 크게 만들어서","미분할 때 1 이 더해져서","층을 줄여서","학습률을 키워서"],"a":1,"why":"$y = F(x) + x$ 를 미분하면 $F$ 의 미분에 1 이 붙어요. 최소 1 이 보장되니 곱해도 안 죽어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5397,0.4017],"c":[0,0,0.5937,0.4419],"r":2.3885,"img":"img/L5/walk/p034_h.jpg"},"parts":[{"b":[0.02,0.47,0.94,0.36],"c":[0,0.452,1,0.396],"r":4.4893,"img":"img/L5/walk/p034_12_01.jpg","say":"노드 색이 왼쪽에서 오른쪽으로 갈수록 바래요."},{"b":[0.83,0.864,0.15,0.068],"c":[0.8,0.843,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p034_12_02.jpg","say":"맨 오른쪽 '층 500 RGB = [0,0,0]'. 완전히 검정이 됐어요."}]}},{"p":35,"title":"구분: 해법 갈래","terms":["Skip Connection","Graph Rewiring","Jacobian","DropEdge"],"pass1":[{"kind":"say","lines":["여기서부터 진단이 끝나고 **처방**이 시작돼요.","처방은 세 갈래예요. 구조를 바꾸기, 학습을 바꾸기, 그래프를 바꾸기예요.","세 번째가 특이해요. 신경망이 아니라 **입력 데이터**를 고치는 방법이거든요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"compare","head":"세 갈래가 무엇을 바꾸나","cols":["갈래","무엇을 바꾸나","예시"],"rows":[["구조적","신경망의 연결 방식","**스킵 연결(Skip Connection)**, 다중 홉 집계"],["학습적","학습 과정","정규화, **DropEdge**"],["그래프 수준","그래프 자체","**그래프 재배선(Graph Rewiring)**, 가상 노드"]]},{"kind":"points","head":"왜 그래프 자체를 고치는 갈래가 필요한가요","items":["p.22 에서 **야코비안(Jacobian)** 상계가 두 항의 곱이라고 했죠.","그중 그래프 구조 항은 **학습으로 절대 못 고쳐요**.","그러니 그 항을 고치려면 그래프 자체를 바꾸는 수밖에 없어요.","그것이 **그래프 재배선(Graph Rewiring)** 갈래예요."]}],"pass3":[],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.048,0.364,0.2,0.07],"c":[0.036,0.344,0.224,0.11],"r":3.6202,"img":"img/L5/walk/p035_11_01.jpg","say":"큰 제목: '해법 갈래'."},{"b":[0.045,0.475,0.47,0.045],"c":[0.0215,0.4425,0.517,0.11],"r":8.3556,"img":"img/L5/walk/p035_11_02.jpg","say":"'GNN을 더 깊게 만들어 주는 구조, 학습, 그래프 수준의 기법들.'"}]}},{"p":36,"title":"처방 표: 다섯 가족","terms":["Skip Connection","DeepGCNs","GCNII","PairNorm","DropEdge","Graph Rewiring","Virtual Node","JKNet","Over-smoothing","Over-squashing","Under-reaching"],"pass1":[{"kind":"say","lines":["처방 가족이 다섯 개예요.","**스킵 연결(Skip Connection)**, 정규화와 규제, **그래프 재배선(Graph Rewiring)**, **가상 노드(Virtual Node)**, 다중 홉 집계예요.","각각 겨냥하는 고장이 달라요. p.14 의 장애물 표와 짝을 이루는 처방 표예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"표의 마지막 열이 겨냥하는 고장이에요","boxes":[{"x":0.69,"y":0.286,"w":0.277,"h":0.097,"say":"스킵 연결의 표적: 최적화와 **과도한 평활화(Over-smoothing)**.","c":[0.6762,0.27,0.3047,0.129],"r":4.1991,"img":"img/L5/walk/p036_20_01.jpg"},{"x":0.69,"y":0.383,"w":0.277,"h":0.098,"say":"정규화와 규제의 표적: 평활화와 과적합.","c":[0.6762,0.367,0.3047,0.13],"r":4.1668,"img":"img/L5/walk/p036_20_02.jpg"},{"x":0.69,"y":0.481,"w":0.277,"h":0.097,"say":"그래프 재배선의 표적: **과도한 압착(Over-squashing)**.","c":[0.6762,0.465,0.3047,0.129],"r":4.1991,"img":"img/L5/walk/p036_20_03.jpg"},{"x":0.69,"y":0.578,"w":0.277,"h":0.095,"say":"가상 노드의 표적: 압착과 **도달 실패(Under-reaching)**.","c":[0.6762,0.562,0.3047,0.127],"r":4.2653,"img":"img/L5/walk/p036_20_04.jpg"},{"x":0.69,"y":0.673,"w":0.277,"h":0.102,"say":"다중 홉 집계의 표적: 도달 실패와 평활화.","c":[0.6762,0.657,0.3047,0.134],"r":4.0425,"img":"img/L5/walk/p036_20_05.jpg"}]},{"kind":"figure","head":"처방과 고장의 대응표","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tm\" x=\"300\" y=\"30\" font-size=\"13\" text-anchor=\"middle\">평활화<\/text>\n<text class=\"tm\" x=\"356\" y=\"30\" font-size=\"13\" text-anchor=\"middle\">압착<\/text>\n<text class=\"tm\" x=\"410\" y=\"30\" font-size=\"13\" text-anchor=\"middle\">도달실패<\/text>\n<text class=\"tm\" x=\"462\" y=\"30\" font-size=\"13\" text-anchor=\"middle\">최적화<\/text>\n<text class=\"t\" x=\"12\" y=\"58\" font-size=\"13\">스킵 연결<\/text>\n<text class=\"t\" x=\"12\" y=\"98\" font-size=\"13\">정규화, 규제<\/text>\n<text class=\"t\" x=\"12\" y=\"138\" font-size=\"13\">그래프 재배선<\/text>\n<text class=\"t\" x=\"12\" y=\"178\" font-size=\"13\">가상 노드<\/text>\n<text class=\"t\" x=\"12\" y=\"218\" font-size=\"13\">다중 홉 집계<\/text>\n<rect class=\"box2 b1\" x=\"278\" y=\"44\" width=\"44\" height=\"20\" rx=\"4\"/>\n<rect class=\"box2 b1\" x=\"440\" y=\"44\" width=\"44\" height=\"20\" rx=\"4\"/>\n<rect class=\"box2 b2\" x=\"278\" y=\"84\" width=\"44\" height=\"20\" rx=\"4\"/>\n<rect class=\"box2 b2\" x=\"440\" y=\"84\" width=\"44\" height=\"20\" rx=\"4\"/>\n<rect class=\"box2 b3\" x=\"334\" y=\"124\" width=\"44\" height=\"20\" rx=\"4\"/>\n<rect class=\"box2 b4\" x=\"334\" y=\"164\" width=\"44\" height=\"20\" rx=\"4\"/>\n<rect class=\"box2 b4\" x=\"388\" y=\"164\" width=\"44\" height=\"20\" rx=\"4\"/>\n<rect class=\"box2 b5\" x=\"278\" y=\"204\" width=\"44\" height=\"20\" rx=\"4\"/>\n<rect class=\"box2 b5\" x=\"388\" y=\"204\" width=\"44\" height=\"20\" rx=\"4\"/>\n<text class=\"tm b5\" x=\"240\" y=\"254\" font-size=\"13\" text-anchor=\"middle\">색칠된 칸이 그 처방이 겨냥하는 고장이에요<\/text>\n<\/svg>","caption":"세로로 읽으면 평활화를 겨냥하는 가족이 셋으로 가장 많아요. 어느 한 가족도 네 칸을 다 채우지 못해요.","builds":5},{"kind":"points","head":"다섯 가족을 한 줄씩","items":["**스킵 연결(Skip Connection)**은 층을 건너뛰어 값을 그대로 전달해요. **DeepGCNs**와 **GCNII**가 여기 속해요.","정규화와 규제는 값의 분포를 맞추거나 모델을 억제해요. **PairNorm**과 **DropEdge**예요.","**그래프 재배선(Graph Rewiring)**은 엣지를 더하거나 빼서 그래프 모양을 고쳐요.","**가상 노드(Virtual Node)**는 모든 노드와 이어진 가짜 노드를 하나 넣어 2홉으로 잇는 방법이에요."]},{"kind":"points","head":"다중 홉 집계는 무엇인가요","items":["한 층에서 여러 홉을 동시에 보는 방법이에요.","층을 쌓지 않고도 멀리 볼 수 있으니 **도달 실패(Under-reaching)**가 완화돼요.","각 홉의 정보를 따로 보관하니 평활화도 덜해요.","**JKNet**이 대표예요. 층마다의 결과를 모아 두었다가 마지막에 골라 써요."]},{"kind":"compare","head":"압착과 도달 실패를 겨냥하는 처방의 공통점","cols":["겨냥하는 고장","처방 가족","공통점"],"rows":[["**과도한 압착(Over-squashing)**","재배선, **가상 노드(Virtual Node)**","그래프 구조를 건드려요"],["**도달 실패(Under-reaching)**","**가상 노드(Virtual Node)**, 다중 홉","깊이를 안 늘리고 멀리 봐요"],["**과도한 평활화(Over-smoothing)**","스킵, 정규화, 다중 홉","가장 많은 처방이 몰려 있어요"]]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 7번 (JK Network)","q":"Explain how Jumping Knowledge Networks help mitigate the over-smoothing problem in deep GCNs, then compute the layer-2 output.","qko":"**JKNet**이 깊은 GCN의 **과도한 평활화(Over-smoothing)**를 어떻게 완화하는지 설명하고, 층 2 의 출력을 계산하세요.","solve":["(a) 는 서술이에요. 층마다의 결과를 모아 두었다가 마지막에 고른다는 점을 쓰면 돼요.","(b) 는 정규화 인접행렬을 만들라는 문제예요. 각 행을 그 행의 합으로 나누면 돼요.","(c) 의 식은 층별 결과에 최댓값을 취하는 형태예요.","즉 층 0, 층 1 의 결과를 각각 계산해 두고 성분마다 큰 값을 고르면 돼요."],"answer":"핵심은 '깊은 층의 결과만 쓰지 않고 얕은 층의 결과도 남겨 두었다가 고른다'는 점이에요. 그래서 평활화된 값에 갇히지 않아요."},{"kind":"exam","src":"2025 가을 중간 8번 (GCNII)","q":"What are the two major components introduced in GCNII to overcome the depth limitation problem in GCNs?","qko":"**GCNII**가 깊이 제한 문제를 극복하려고 도입한 두 가지 주요 구성 요소는 무엇인가요?","solve":["**GCNII**의 식은 초기 잔차와 항등 사상 두 가지를 담고 있어요.","초기 잔차는 **맨 처음 입력**을 층마다 다시 섞어 주는 것이에요.","항등 사상은 가중치 행렬에 단위행렬을 더해 주는 것이에요.","계산 문제에서는 정규화 인접행렬을 먼저 만들고, 알파와 베타를 0.5 로 넣어 계산해요."],"answer":"두 구성 요소는 initial residual connection 과 identity mapping 이에요. 이 두 영어 표현을 그대로 쓰면 돼요."},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Remedies for deep GNNs fall into skip connections, normalization, graph rewiring, virtual nodes and multi-hop aggregation.","ko":"깊은 GNN의 처방은 스킵 연결, 정규화, 그래프 재배선, 가상 노드, 다중 홉 집계로 나뉜다.","tip":"다섯 가족 이름을 이 순서로 외워 두면 서술형에서 빠뜨리지 않아요."},{"kind":"warn","head":"표를 기계적으로 외우면 함정에 빠져요","items":["**스킵 연결(Skip Connection)**의 표적이 '최적화, 평활화'로 되어 있지만, p.12 는 '잔차만으로는 부족하다'고 못 박았어요.","정확히 말하면 최적화는 확실히 고치고, 평활화는 **늦출 뿐 없애지는 못해요**.","원래 특징이 층마다 다시 더해지니 완전히 같아지지는 않지만, 이웃 정보가 계속 섞이는 것 자체는 그대로거든요."]},{"kind":"check","q":"**과도한 압착(Over-squashing)**을 겨냥하는 처방들의 공통점은 무엇인가요?","choices":["가중치를 바꾼다","그래프 구조를 건드린다","층을 줄인다","학습률을 바꾼다"],"a":1,"why":"**야코비안(Jacobian)**의 구조 항은 학습으로 못 고쳐요. 그래서 재배선과 **가상 노드(Virtual Node)**가 나왔어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.8509,0.2661],"c":[0,0.0019,0.936,0.2981],"r":5.582,"img":"img/L5/walk/p036_h.jpg"},"parts":[{"b":[0.033,0.286,0.277,0.097],"c":[0.0192,0.27,0.3047,0.129],"r":4.1991,"img":"img/L5/walk/p036_11_01.jpg","say":"'스킵 연결'. 대표 모델이 **DeepGCNs** 와 **GCNII** 예요."},{"b":[0.033,0.383,0.277,0.098],"c":[0.0192,0.367,0.3047,0.13],"r":4.1668,"img":"img/L5/walk/p036_11_02.jpg","say":"'정규화, 규제'. 대표가 **PairNorm** 과 **DropEdge** 예요."},{"b":[0.033,0.481,0.277,0.097],"c":[0.0192,0.465,0.3047,0.129],"r":4.1991,"img":"img/L5/walk/p036_11_03.jpg","say":"'그래프 재배선'. 대표가 SDRF, FoSR, DIGL 이에요."},{"b":[0.033,0.578,0.277,0.095],"c":[0.0192,0.562,0.3047,0.127],"r":4.2653,"img":"img/L5/walk/p036_11_04.jpg","say":"'가상 노드, 전역 어텐션'. 대표가 **가상 노드(Virtual Node)** 와 GraphGPS 예요."},{"b":[0.033,0.673,0.277,0.102],"c":[0.0192,0.657,0.3047,0.134],"r":4.0425,"img":"img/L5/walk/p036_11_05.jpg","say":"'다중 홉 집계'. 대표가 MixHop, SIGN, APPNP, GPR-GNN, **JKNet** 이에요."}]}},{"p":37,"title":"스킵 연결: 앞 층 값을 날라 주는 지름길","terms":["Residual Connection","Over-smoothing","GCN"],"pass1":[{"kind":"say","lines":["여기서부터 새 묶음이 시작돼요. 제목은 **스킵 연결** 이에요.","스킵은 건너뛴다는 뜻이에요. 층을 하나 건너뛰어서 값을 그대로 날라 주는 길이에요.","앞으로 나올 네 모델은 전부 이 지름길을 어디서 끌어오느냐만 다릅니다."]},{"kind":"analogy","head":"받아쓰기를 옮겨 적는 아이들","scene":"아이 열 명이 한 줄로 앉아 있어요. 맨 앞 아이가 쓴 문장을 뒷사람에게 차례로 옮겨 적게 해요. 열 번쯤 옮기면 글자가 조금씩 바뀌어서 처음 문장을 알아볼 수 없게 돼요. 그래서 맨 앞 아이의 종이를 복사해서 중간중간 나눠 줘요. 그러면 뒷사람도 원래 문장을 볼 수 있어요.","map":[["한 번 옮겨 적기","GNN 한 층"],["글자가 뭉개지는 것","**과도한 평활화(Over-smoothing)**"],["원본 종이를 나눠 주기","스킵 연결, 즉 지름길"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"points","head":"네 가지 지름길의 이름만 먼저 외워요","items":["**잔차(residual)**: 바로 앞 층 하나만 날라 와요. 모델 이름은 ResGCN 이에요","**덴스(dense)**: 앞의 모든 층을 다 날라 와요. 모델 이름은 DenseGCN 이에요","**초기 잔차(initial residual)**: 맨 처음 입력만 날라 와요. 모델 이름은 GCNII 예요","**점프 지식(jumping knowledge)**: 중간에는 안 하고 맨 끝에서 한 번만 모아요. 모델 이름은 JKNet 이에요"]},{"kind":"compare","head":"지름길이 고치는 병","cols":["무엇을 고치나","어떻게"],"rows":[["기울기 소실","역전파 신호가 지름길을 타고 그대로 뒤로 흘러요"],["**과도한 평활화(Over-smoothing)**","섞이지 않은 옛 값이 계속 들어와서 다 같아지지 못해요"]]},{"kind":"warn","head":"스킵 연결은 만병통치가 아니에요","items":["지름길은 학습을 쉽게 해 주지만, 이웃 평균을 반복하는 일 자체는 그대로예요","그래서 뒤에 나올 정규화, 재배선, 멀티홉 집계가 따로 필요해요"]}],"pass3":[{"kind":"check","q":"네 가지 스킵 연결 중 **맨 처음 입력**을 층마다 다시 섞어 주는 것은?","choices":["잔차","덴스","초기 잔차","점프 지식"],"a":2,"why":"초기 잔차는 바로 앞 층이 아니라 $H^{(0)}$ 을 날라 와요. GCNII 가 쓰는 방식이에요."}],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.04,0.38,0.22,0.09],"c":[0.028,0.364,0.244,0.122],"r":3.5556,"img":"img/L5/walk/p037_12_01.jpg","say":"제목이 **스킵 연결** 이에요. 이 묶음에서 다룰 네 모델의 공통 생각이에요."},{"b":[0.04,0.5,0.52,0.09],"c":[0.014,0.484,0.572,0.122],"r":8.3352,"img":"img/L5/walk/p037_12_02.jpg","say":"아래 한 줄에 네 가지 이름이 나와요. 잔차, 덴스, 초기 잔차, 점프 지식이에요."}]}},{"p":38,"title":"네 가지 스킵 연결을 표 하나로 비교하기","terms":["Residual Connection","Concatenation","GCNII","JKNet","DenseGCN","GCN"],"pass1":[{"kind":"say","lines":["앞 장에서 이름만 들은 네 가지를 **표 한 장**으로 나란히 놓은 슬라이드예요.","칸이 네 개예요. 지름길이 어디서 오는지, 어떻게 합치는지, 식, 쓰는 모델이에요.","여기만 외워 두면 이 묶음의 절반은 끝난 셈이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"네 줄을 하나씩 짚어요","boxes":[{"x":0.03,"y":0.25,"w":0.44,"h":0.1,"say":"첫 줄 **잔차** 예요. 바로 앞 층을 가져와 **더하기** 로 합쳐요. ResGCN 이에요.","c":[0.008,0.234,0.484,0.132],"r":6.5185,"img":"img/L5/walk/p038_20_01.jpg"},{"x":0.03,"y":0.4,"w":0.44,"h":0.1,"say":"둘째 줄 **덴스** 예요. 앞의 모든 층을 **이어 붙이기** 로 합쳐요. DenseGCN 이에요.","c":[0.008,0.384,0.484,0.132],"r":6.5185,"img":"img/L5/walk/p038_20_02.jpg"},{"x":0.03,"y":0.55,"w":0.44,"h":0.12,"say":"셋째 줄 **초기 잔차** 예요. 입력 층을 **볼록 혼합** 으로 섞어요. GCNII 예요.","c":[0.008,0.534,0.484,0.152],"r":5.6608,"img":"img/L5/walk/p038_20_03.jpg"},{"x":0.03,"y":0.72,"w":0.44,"h":0.12,"say":"넷째 줄 **점프 지식** 이에요. 모든 층을 **출력에서만** 모아요. JKNet 이에요.","c":[0.008,0.704,0.484,0.152],"r":5.6608,"img":"img/L5/walk/p038_20_04.jpg"}]},{"kind":"compare","head":"합치는 방법이 다르면 결과도 달라요","cols":["합치는 방법","하는 일","출력 길이"],"rows":[["더하기","같은 자리끼리 숫자를 더해요","그대로예요"],["**이어 붙이기(Concatenation)**","벡터를 옆으로 나란히 붙여요","길어져요"],["볼록 혼합","$(1-\\alpha)$ 와 $\\alpha$ 로 비율을 나눠 섞어요","그대로예요"],["AGG","최댓값이나 LSTM 으로 하나를 골라요","방식마다 달라요"]]},{"kind":"formula","head":"잔차와 초기 잔차는 한 글자 차이예요","tex":"H^{(\\ell+1)} = \\sigma\\!\\left(\\tilde P H^{(\\ell)} W^{(\\ell)}\\right) + H^{(\\ell)}\\qquad\\text{vs}\\qquadH^{(\\ell+1)} = \\sigma\\!\\left(\\left((1-\\alpha)\\tilde P H^{(\\ell)} + \\alpha H^{(0)}\\right) W^{(\\ell)}\\right)","parts":[{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"}],"whole":"왼쪽은 괄호 **밖에서** 더하고 오른쪽은 괄호 **안에서** 섞어요. 이 자리 차이가 두 모델을 가릅니다."},{"kind":"figure","head":"지름길이 어디서 오느냐","svg":"<svg viewBox=\"0 0 480 270\">\n <text class=\"tb\" x=\"120\" y=\"22\" text-anchor=\"middle\" font-size=\"15\">잔차: 바로 앞 층 하나<\/text>\n <rect class=\"box\" x=\"20\" y=\"40\" width=\"54\" height=\"30\" rx=\"5\"/>\n <text class=\"t\" x=\"47\" y=\"60\" text-anchor=\"middle\" font-size=\"13\">앞 층<\/text>\n <rect class=\"box\" x=\"96\" y=\"40\" width=\"54\" height=\"30\" rx=\"5\"/>\n <text class=\"t\" x=\"123\" y=\"60\" text-anchor=\"middle\" font-size=\"13\">GCN<\/text>\n <rect class=\"box2 b1\" x=\"172\" y=\"40\" width=\"54\" height=\"30\" rx=\"5\"/>\n <text class=\"tl b1\" x=\"199\" y=\"60\" text-anchor=\"middle\" font-size=\"13\">더하기<\/text>\n <line class=\"e2 b1\" x1=\"47\" y1=\"38\" x2=\"199\" y2=\"38\"/>\n <text class=\"tb\" x=\"360\" y=\"22\" text-anchor=\"middle\" font-size=\"15\">덴스: 앞의 모든 층<\/text>\n <rect class=\"box\" x=\"250\" y=\"40\" width=\"44\" height=\"30\" rx=\"5\"/>\n <text class=\"t\" x=\"272\" y=\"60\" text-anchor=\"middle\" font-size=\"13\">0층<\/text>\n <rect class=\"box\" x=\"306\" y=\"40\" width=\"44\" height=\"30\" rx=\"5\"/>\n <text class=\"t\" x=\"328\" y=\"60\" text-anchor=\"middle\" font-size=\"13\">1층<\/text>\n <rect class=\"box2 b2\" x=\"380\" y=\"40\" width=\"74\" height=\"30\" rx=\"5\"/>\n <text class=\"tl b2\" x=\"417\" y=\"60\" text-anchor=\"middle\" font-size=\"13\">이어 붙이기<\/text>\n <line class=\"e2 b2\" x1=\"272\" y1=\"38\" x2=\"417\" y2=\"38\"/>\n <line class=\"e2 b2\" x1=\"328\" y1=\"38\" x2=\"417\" y2=\"38\"/>\n <text class=\"tb\" x=\"120\" y=\"150\" text-anchor=\"middle\" font-size=\"15\">초기 잔차: 입력 층<\/text>\n <rect class=\"box\" x=\"20\" y=\"166\" width=\"54\" height=\"30\" rx=\"5\"/>\n <text class=\"t\" x=\"47\" y=\"186\" text-anchor=\"middle\" font-size=\"13\">입력<\/text>\n <rect class=\"box\" x=\"96\" y=\"166\" width=\"54\" height=\"30\" rx=\"5\"/>\n <text class=\"t\" x=\"123\" y=\"186\" text-anchor=\"middle\" font-size=\"13\">GCN<\/text>\n <rect class=\"box2 b3\" x=\"172\" y=\"166\" width=\"54\" height=\"30\" rx=\"5\"/>\n <text class=\"tl b3\" x=\"199\" y=\"186\" text-anchor=\"middle\" font-size=\"13\">섞기<\/text>\n <line class=\"e2 b3\" x1=\"47\" y1=\"164\" x2=\"199\" y2=\"164\"/>\n <text class=\"tb\" x=\"360\" y=\"150\" text-anchor=\"middle\" font-size=\"15\">점프 지식: 출력에서만<\/text>\n <rect class=\"box\" x=\"250\" y=\"166\" width=\"44\" height=\"30\" rx=\"5\"/>\n <text class=\"t\" x=\"272\" y=\"186\" text-anchor=\"middle\" font-size=\"13\">1층<\/text>\n <rect class=\"box\" x=\"306\" y=\"166\" width=\"44\" height=\"30\" rx=\"5\"/>\n <text class=\"t\" x=\"328\" y=\"186\" text-anchor=\"middle\" font-size=\"13\">L층<\/text>\n <rect class=\"box2 b4\" x=\"364\" y=\"166\" width=\"90\" height=\"30\" rx=\"5\"/>\n <text class=\"tl b4\" x=\"409\" y=\"186\" text-anchor=\"middle\" font-size=\"13\">AGG 한 번<\/text>\n <line class=\"e2 b4\" x1=\"272\" y1=\"212\" x2=\"409\" y2=\"212\"/>\n <line class=\"e2 b4\" x1=\"328\" y1=\"212\" x2=\"409\" y2=\"212\"/>\n <text class=\"t\" x=\"240\" y=\"250\" text-anchor=\"middle\" font-size=\"14\">지름길이 어디서 오느냐가 네 모델을 가릅니다<\/text>\n<\/svg>","caption":"왼쪽 위부터 잔차, 덴스, 초기 잔차, 점프 지식이에요.","builds":4}],"pass3":[{"kind":"warn","head":"표에서 가장 자주 틀리는 두 가지","items":["**덴스는 출력이 길어져요.** 이어 붙이기라서 층을 지날수록 차원이 늘어나요","**점프 지식은 중간 층에서는 아무 일도 안 해요.** 맨 끝에서 한 번만 모아요","잔차의 더하기는 괄호 밖, 초기 잔차의 섞기는 괄호 안이에요"]},{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"Residual connections add the previous layer, dense connections concatenate all previous layers, initial residual connections mix in the input layer, and jumping knowledge aggregates every layer only at the output.","ko":"잔차 연결은 바로 앞 층을 더하고, 덴스 연결은 앞의 모든 층을 이어 붙이고, 초기 잔차 연결은 입력 층을 섞어 넣고, 점프 지식은 모든 층을 출력에서만 모아요.","tip":"네 가지를 한 문장에 줄줄이 늘어놓는 틀이에요. 동사만 바꿔 쓰면 돼요."},{"kind":"check","q":"출력 벡터의 길이가 층을 지날수록 **길어지는** 것은?","choices":["잔차","**덴스**","초기 잔차","점프 지식"],"a":1,"why":"덴스는 **이어 붙이기(Concatenation)** 라서 붙일 때마다 차원이 늘어나요. 나머지는 길이가 그대로예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.1281,0.0757],"c":[0,0.0019,0.2,0.1077],"r":3.3014,"img":"img/L5/walk/p038_h.jpg"},"parts":[{"b":[0.17,0.18,0.19,0.05],"c":[0.158,0.15,0.214,0.11],"r":3.4586,"img":"img/L5/walk/p038_11_01.jpg","say":"둘째 칸 이름이 **지름길이 오는 곳** 이에요. 네 모델을 가르는 핵심이에요."},{"b":[0.36,0.18,0.11,0.05],"c":[0.315,0.15,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p038_11_02.jpg","say":"셋째 칸은 **합치는 방법** 이에요. 더하기냐 이어 붙이기냐가 갈려요."},{"b":[0.83,0.18,0.13,0.05],"c":[0.795,0.15,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p038_11_03.jpg","say":"마지막 칸이 **쓰는 모델** 이름이에요. 시험에 이름으로 물어요."}]}},{"p":39,"title":"네 가지 구조를 그림으로 보기","terms":["Residual Connection","DenseGCN","GCNII","JKNet"],"pass1":[{"kind":"say","lines":["앞 장의 표를 **그림 네 개**로 다시 보여 주는 슬라이드예요.","화면이 네 칸으로 나뉘어 있고 칸마다 상자와 화살표로 흐름이 그려져 있어요.","표가 안 외워지면 이 그림의 **파란 화살표가 어디서 출발하는지**만 보면 돼요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"각 칸 안의 글자를 읽어요","boxes":[{"x":0.17,"y":0.27,"w":0.12,"h":0.05,"say":"잔차 칸의 화살표 위에 **항등** 이라고 적혀 있어요. 아무것도 안 바꾸고 그대로 보낸다는 뜻이에요.","c":[0.13,0.24,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p039_20_01.jpg"},{"x":0.28,"y":0.37,"w":0.09,"h":0.06,"say":"잔차 칸 끝의 파란 상자는 **더하기** 예요. 두 값을 같은 자리끼리 더해요.","c":[0.225,0.345,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p039_20_02.jpg"},{"x":0.22,"y":0.69,"w":0.05,"h":0.05,"say":"초기 잔차 칸 화살표 위의 그리스 글자가 **알파** 예요. 처음 입력을 섞는 비율이에요.","c":[0.145,0.66,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p039_20_03.jpg"},{"x":0.53,"y":0.77,"w":0.27,"h":0.06,"say":"점프 지식 칸의 긴 파란 띠에 **AGG: 이어 붙이기 / 최댓값 / LSTM** 이라고 적혀 있어요.","c":[0.5165,0.745,0.297,0.11],"r":4.8,"img":"img/L5/walk/p039_20_04.jpg"}]},{"kind":"points","head":"그림에서 꼭 읽어 낼 것 네 가지","items":["잔차의 화살표는 **한 칸짜리** 예요. 바로 앞 층만 건너뛰어요","덴스의 화살표는 **여러 개** 예요. 그리고 끝의 상자가 더하기가 아니라 **이어 붙이기** 예요","초기 잔차의 화살표는 **맨 왼쪽 끝** 에서 나와요. 아무리 깊어져도 출발점이 같아요","점프 지식은 **가로 흐름과 세로 흐름이 따로** 예요. 가로는 보통 GCN, 세로가 모으기예요"]},{"kind":"compare","head":"몇 층짜리 지름길인가","cols":["구조","건너뛰는 거리","층이 50개일 때"],"rows":[["잔차","늘 1층","지름길도 50개 생겨요"],["덴스","1층부터 전부","마지막 층이 50개를 다 받아요"],["초기 잔차","늘 입력까지","50층에서도 출발점은 0층이에요"],["점프 지식","출력에서 한 번","중간에는 지름길이 없어요"]]}],"pass3":[{"kind":"check","q":"그림에서 **화살표가 가장 멀리서 출발하는** 구조는 어느 것인가요?","choices":["잔차","덴스","초기 잔차","넷 다 같다"],"a":2,"why":"초기 잔차는 층이 아무리 깊어져도 늘 $H^{(0)}$ 에서 출발해요. 거리가 층 수만큼 벌어져요."},{"kind":"warn","head":"그림을 볼 때 헷갈리는 점","items":["덴스 칸의 $F(\\cdot)$ 은 GCN 층을 줄여 쓴 것이에요. 새 기호가 아니에요","점프 지식 칸의 가로 화살표는 지름길이 아니라 **보통 층 흐름** 이에요"]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2761,0.0757],"c":[0,0.0019,0.3037,0.1077],"r":5.0131,"img":"img/L5/walk/p039_h.jpg"},"parts":[{"b":[0.03,0.12,0.46,0.4],"c":[0.007,0.1,0.506,0.44],"r":2.0444,"img":"img/L5/walk/p039_11_01.jpg","say":"왼쪽 위가 **잔차** 예요. 파란 화살표가 바로 앞 상자 하나에서만 나와요."},{"b":[0.51,0.12,0.46,0.4],"c":[0.487,0.1,0.506,0.44],"r":2.0444,"img":"img/L5/walk/p039_11_02.jpg","say":"오른쪽 위가 **덴스** 예요. 화살표가 여러 상자에서 한꺼번에 나와요."},{"b":[0.03,0.53,0.46,0.42],"c":[0.007,0.509,0.506,0.462],"r":1.9471,"img":"img/L5/walk/p039_11_03.jpg","say":"왼쪽 아래가 **초기 잔차** 예요. 맨 왼쪽 상자에서만 화살표가 나와요."},{"b":[0.51,0.53,0.46,0.42],"c":[0.487,0.509,0.506,0.462],"r":1.9471,"img":"img/L5/walk/p039_11_04.jpg","say":"오른쪽 아래가 **점프 지식** 이에요. 화살표가 전부 아래 긴 띠로 모여요."}]}},{"p":40,"title":"DeepGCNs: 깊이가 막히는 지점을 짚다","terms":["Vanishing Gradient","Over-smoothing","GCN","Residual Connection"],"pass1":[{"kind":"say","lines":["**DeepGCNs** 는 CNN 처럼 GCN 도 깊게 쌓을 수 있을까를 물은 연구예요.","이 슬라이드는 **왜 그냥 쌓으면 안 되는지** 를 먼저 보여 줘요.","아래 두 그래프가 잔차 연결이 있을 때와 없을 때의 학습 손실이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"가운데 식과 아래 그래프","boxes":[{"x":0.4,"y":0.36,"w":0.18,"h":0.05,"say":"가운데 식은 층과 층 사이를 옮겨 가는 사상 $F$ 하나예요. 보통 신경망이 배우는 것이 이것이에요.","c":[0.388,0.33,0.204,0.11],"r":3.297,"img":"img/L5/walk/p040_20_01.jpg"},{"x":0.2,"y":0.51,"w":0.25,"h":0.33,"say":"왼쪽 그래프 (a) 는 **잔차 연결이 없을 때** 예요. 층이 7, 14, 28, 56 으로 깊어질수록 선이 위에 있어요.","c":[0.1875,0.4935,0.275,0.363],"r":1.3468,"img":"img/L5/walk/p040_20_02.jpg"},{"x":0.5,"y":0.51,"w":0.25,"h":0.33,"say":"오른쪽 그래프 (b) 는 **잔차 연결이 있을 때** 예요. 네 선이 거의 포개져 있어요.","c":[0.4875,0.4935,0.275,0.363],"r":1.3468,"img":"img/L5/walk/p040_20_03.jpg"}]},{"kind":"points","head":"두 그래프를 읽는 법","items":["세로축은 **학습 손실** 이에요. 낮을수록 잘 배운 거예요","왼쪽에서 56층 빨간 선이 가장 위에 있어요. **깊을수록 더 못 배운다** 는 뜻이에요","오른쪽에서는 7층과 56층 선이 겹쳐요. **깊이를 바꿔도 똑같이 잘 배운다** 는 뜻이에요","즉 잔차 연결 하나로 **깊이가 더는 방해물이 아니게** 됐어요"]},{"kind":"formula","head":"표준 GCN 층이 배우는 것","tex":"G_{\\ell+1} = F\\!\\left(G_\\ell, W_\\ell\\right)","parts":[{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"}],"whole":"보통 신경망은 이 $F$ 를 통째로 배워요. 잔차 연결은 $F$ 대신 **원래 값과의 차이** 만 배우게 바꿔요."},{"kind":"analogy","head":"원본과 차이만 적기","scene":"친구에게 긴 글을 베껴 쓰라고 하면 열 번쯤 반복했을 때 원문과 많이 달라져요. 대신 원본을 옆에 두고 **고칠 곳만 빨간 펜으로 적게** 하면 어떨까요. 고칠 것이 없으면 아무것도 안 적으면 되니까 아무리 여러 번 거쳐도 원문이 안 망가져요.","map":[["글을 통째로 베끼기","사상 $F$ 를 통째로 배우기"],["빨간 펜으로 차이만 적기","**잔차 연결(Residual Connection)** 로 차이만 배우기"],["원본이 안 망가지는 것","56층에서도 손실이 안 오르는 것"]]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"DeepGCNs showed that plain GCNs suffer from vanishing gradients and over-smoothing as depth grows, and that adding residual connections lets a 56-layer GCN converge as well as a 7-layer one.","ko":"DeepGCNs 는 평범한 GCN 이 깊어질수록 기울기 소실과 과도한 평활화를 겪는다는 것을 보였고, 잔차 연결을 넣으면 56층 GCN 도 7층만큼 잘 수렴한다는 것을 보였어요.","tip":"숫자 7 과 56 을 그대로 쓰면 실험을 읽었다는 표가 나요."},{"kind":"check","q":"오른쪽 그래프에서 네 선이 거의 겹쳐 있는 것은 무엇을 뜻하나요?","choices":["깊은 모델이 더 좋다","깊이를 바꿔도 학습이 똑같이 잘 된다","학습이 안 된다","과적합이 생겼다"],"a":1,"why":"선이 겹친다는 것은 7층이든 56층이든 **같은 손실로 수렴한다**는 뜻이에요. 깊이가 더는 방해물이 아니라는 증거예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2988,0.0757],"c":[0,0.0019,0.3286,0.1077],"r":5.4241,"img":"img/L5/walk/p040_h.jpg"},"parts":[{"b":[0.02,0.15,0.3,0.05],"c":[0.005,0.12,0.33,0.11],"r":5.3333,"img":"img/L5/walk/p040_11_01.jpg","say":"맨 위 굵은 줄이 **그래프 표현 학습에서 깊이가 막히는 지점** 이에요."},{"b":[0.06,0.19,0.88,0.08],"c":[0.016,0.1322,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p040_11_02.jpg","say":"첫 불릿이 **기울기 소실 문제** 예요. 깊은 GCN 을 거꾸로 타고 내려가며 학습하면 특징이 다 같아진대요."},{"b":[0.06,0.4,0.88,0.05],"c":[0.016,0.3272,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p040_11_03.jpg","say":"셋째 불릿이 **그 결과** 예요. 학습 수렴과 추론 정확도가 크게 나빠진다고 해요."}]}},{"p":41,"title":"DeepGCNs: 원래 입력을 그대로 더한다","terms":["DeepGCNs","Residual Connection","Vanishing Gradient","ReLU","Skip Connection","PlainGCN","ResGCN","DenseGCN","Adjacency Matrix"],"pass1":[{"kind":"say","lines":["**DeepGCNs**의 핵심은 딱 하나예요. 층의 출력에 **원래 입력을 그대로 더해요**.","이것이 **잔차 연결(Residual Connection)**이에요. ResNet 을 그래프로 옮긴 것이죠.","시험에 나오는 형태는 이거예요. 층 결과에 이전 층을 더하면 끝이에요."]},{"kind":"analogy","head":"원본을 항상 옆에 두고 베끼기","scene":"그림을 여러 사람이 차례로 베껴 그려요. 앞사람 그림만 보고 베끼면 열 번째쯤에는 원본과 딴판이 되죠. 그래서 규칙을 바꿔요. 베낄 때마다 **원본도 같이 옆에 붙여 주는** 거예요. 그러면 아무리 여러 번 베껴도 원본이 사라지지 않아요.","map":[["앞사람 그림만 보고 베끼기","**PlainGCN**, 스킵 연결 없음"],["원본도 같이 붙여 주기","**잔차 연결(Residual Connection)**"],["원본이 끝까지 남는 것","**기울기 소실(Vanishing Gradient)**이 막히는 이유"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.04,"y":0.148,"w":0.52,"h":0.043,"say":"'GCN에 잔차 학습을 써서 기울기 소실 문제를 푼다.'","c":[0.014,0.1117,0.572,0.1156],"r":8.7966,"img":"img/L5/walk/p041_20_01.jpg"},{"x":0.09,"y":0.253,"w":0.337,"h":0.309,"say":"왼쪽 전체 구조. 노란 백본, 파란 융합, 분홍 MLP 예측 세 블록이에요.","c":[0.0731,0.237,0.3707,0.341],"r":1.9326,"img":"img/L5/walk/p041_20_02.jpg"},{"x":0.479,"y":0.247,"w":0.465,"h":0.451,"say":"오른쪽 등뼈 세 종류. 왼쪽부터 Plain, Res, Dense 예요.","c":[0.4557,0.2245,0.5115,0.4961],"r":1.833,"img":"img/L5/walk/p041_20_03.jpg"},{"x":0.598,"y":0.3,"w":0.11,"h":0.35,"say":"가운데 **ResGCN**. 상자를 감싸고 돌아오는 곡선이 덧셈 스킵이에요.","c":[0.553,0.2825,0.2,0.385],"r":0.9235,"img":"img/L5/walk/p041_20_04.jpg"},{"x":0.755,"y":0.3,"w":0.11,"h":0.35,"say":"오른쪽 **DenseGCN**. 곡선이 더 많고 나비 넥타이 기호로 들어가요.","c":[0.71,0.2825,0.2,0.385],"r":0.9235,"img":"img/L5/walk/p041_20_05.jpg"},{"x":0.28,"y":0.759,"w":0.41,"h":0.05,"say":"잔차 학습 식. 층이 배운 것에 입력을 그대로 더해요.","c":[0.2595,0.729,0.451,0.11],"r":7.2889,"img":"img/L5/walk/p041_20_06.jpg"}]},{"kind":"formula","head":"시험에 나오는 형태","tex":"H^{(k)} = \\sigma\\left(A \\cdot H^{(k-1)}\\right) + H^{(k-1)}","parts":[{"sym":"A","say":"**인접행렬(Adjacency Matrix)**이에요. 문제에 자기 고리나 정규화가 없으면 그대로 써요."},{"sym":"H^{(k-1)}","say":"이전 층의 노드 특징 행렬이에요."},{"sym":"\\sigma","say":"**렐루(ReLU)**예요. 음수를 0 으로 깎아요."},{"sym":"+ H^{(k-1)}","say":"이것이 **잔차 연결(Residual Connection)**이에요. 가중치 없이 그대로 더해요."}],"whole":"가중치가 없다는 점이 중요해요. 원래 값이 손상 없이 다음 층까지 전달되거든요."},{"kind":"figure","head":"펼쳐 보면 원래 입력이 끝까지 남는다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<rect class=\"box2\" x=\"16\" y=\"78\" width=\"54\" height=\"34\" rx=\"7\"/>\n<text class=\"tb\" x=\"43\" y=\"100\" font-size=\"14\" text-anchor=\"middle\">H0<\/text>\n<rect class=\"box b1\" x=\"118\" y=\"56\" width=\"84\" height=\"34\" rx=\"7\"/>\n<text class=\"t b1\" x=\"160\" y=\"78\" font-size=\"13\" text-anchor=\"middle\">층 1 계산<\/text>\n<circle class=\"n2 b1\" cx=\"248\" cy=\"95\" r=\"14\"/>\n<text class=\"tl b1\" x=\"248\" y=\"100\" font-size=\"15\" text-anchor=\"middle\">+<\/text>\n<rect class=\"box b2\" x=\"284\" y=\"56\" width=\"84\" height=\"34\" rx=\"7\"/>\n<text class=\"t b2\" x=\"326\" y=\"78\" font-size=\"13\" text-anchor=\"middle\">층 2 계산<\/text>\n<circle class=\"n2 b2\" cx=\"412\" cy=\"95\" r=\"14\"/>\n<text class=\"tl b2\" x=\"412\" y=\"100\" font-size=\"15\" text-anchor=\"middle\">+<\/text>\n<rect class=\"box2 b2\" x=\"440\" y=\"78\" width=\"36\" height=\"34\" rx=\"7\"/>\n<text class=\"tb b2\" x=\"458\" y=\"100\" font-size=\"14\" text-anchor=\"middle\">H2<\/text>\n<line class=\"e b1\" x1=\"72\" y1=\"92\" x2=\"114\" y2=\"76\"/>\n<line class=\"e b1\" x1=\"204\" y1=\"76\" x2=\"240\" y2=\"90\"/>\n<line class=\"e b2\" x1=\"262\" y1=\"94\" x2=\"280\" y2=\"82\"/>\n<line class=\"e b2\" x1=\"370\" y1=\"76\" x2=\"404\" y2=\"90\"/>\n<line class=\"e b2\" x1=\"426\" y1=\"95\" x2=\"438\" y2=\"95\"/>\n<path class=\"e2 b3\" d=\"M43 116 L43 152 L248 152 L248 112\" fill=\"none\"/>\n<path class=\"e2 b3\" d=\"M248 120 L248 178 L412 178 L412 112\" fill=\"none\"/>\n<text class=\"tb b3\" x=\"120\" y=\"146\" font-size=\"14\">잔차 경로: 값이 그대로 지나가요<\/text>\n<text class=\"tb b3\" x=\"268\" y=\"200\" font-size=\"14\">미분하면 1 이 더해져요<\/text>\n<rect class=\"box2 b4\" x=\"38\" y=\"220\" width=\"404\" height=\"34\" rx=\"7\"/>\n<text class=\"tb b4\" x=\"240\" y=\"242\" font-size=\"15\" text-anchor=\"middle\">H0 이 결과 안에 그대로 살아남아요<\/text>\n<\/svg>","caption":"두 층을 펼치면 층 2 계산에 층 1 계산과 맨 처음 입력이 모두 더해져 있어요. 그래서 원래 특징이 사라지지 않아요.","builds":4},{"kind":"steps","head":"노드 넷으로 층 2 까지 계산","steps":["노드 넷을 한 줄로 잇고 시작 값을 (2,-1), (-3,1), (1,0), (0,2) 라고 해요.","$A H^{(0)}$ 는 이웃 행의 합이에요. 차례로 (-3,1), (3,-1), (-3,3), (1,0) 이에요.","**렐루(ReLU)**를 씌우면 (0,1), (3,0), (0,3), (1,0) 이에요.","여기에 시작 값을 더하면 $H^{(1)}$ 은 (2,0), (0,1), (1,3), (1,2) 예요.","다시 $A H^{(1)}$ 을 구하면 (0,1), (3,3), (1,3), (1,3) 이에요. 전부 양수라 **렐루(ReLU)** 후에도 그대로예요.","$H^{(1)}$ 을 더하면 (2,1), (3,4), (2,6), (2,5) 예요."],"answer":"$H^{(2)}$ 는 (2,1), (3,4), (2,6), (2,5) 예요. 펼친 식으로 검산하면 세 항의 합이 정확히 같아요.","given":"노드 네 개를 한 줄로 이었어요. 특징은 두 칸짜리예요."},{"kind":"points","head":"기울기 쪽도 확인해요","items":["이 식을 이전 층으로 미분하면 두 항이 나와요.","하나는 **렐루(ReLU)**와 **인접행렬(Adjacency Matrix)**에서 오는 항이고, 다른 하나가 단위행렬이에요.","단위행렬이 붙어 있으니 앞의 항이 아무리 작아도 최소 1 이 남아요.","그래서 100 번 곱해도 0 이 되지 않아요. p.34 의 **기울기 소실(Vanishing Gradient)**이 막히는 거예요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 9번 (DeepGCN, 10점), 2024 가을 중간에도 같은 형태","q":"(a) How does DeepGCN mitigate the over-smoothing problem as depth increases? (b) Calculate the output of the GCN model at layer k=2.","qko":"(a) **DeepGCNs**가 깊이가 늘어날 때 **과도한 평활화(Over-smoothing)**를 어떻게 완화하는지 쓰세요. (b) 층 $k=2$ 의 출력을 계산하세요.","solve":["(a) 는 3점짜리 서술이에요. 세 가지를 나열하면 돼요.","모범 답안: DeepGCN mitigates over-smoothing by using residual connections, normalization layers, and dilated or dynamic aggregation.","뜻은 '잔차 연결, **층 정규화(Layer Normalization)** 같은 정규화 층, 확장 또는 동적 집계를 써서 완화한다'예요.","이어서 which help preserve feature diversity and stable information flow in deep layers 를 붙이면 만점이에요.","(b) 는 7점짜리 계산이에요. 먼저 이웃 목록을 적고 $A H^{(0)}$ 를 구해요.","그다음 **렐루(ReLU)**를 **성분마다** 씌워요. (3,-1) 이면 (3,0) 이에요.","마지막으로 $H^{(k-1)}$ 를 더해요. 순서를 바꾸면 틀려요. 같은 절차를 $k=2$ 까지 두 번 반복해요."],"answer":"위 손계산 예에서 답은 (2,1), (3,4), (2,6), (2,5) 예요. 시간이 남으면 펼친 식으로 검산하세요."},{"kind":"english","head":"서술형에 쓸 한 줄","en":"DeepGCN mitigates over-smoothing by using residual connections, normalization layers, and dilated or dynamic aggregation.","ko":"DeepGCN 은 잔차 연결, 정규화 층, 확장 또는 동적 집계를 써서 과도한 평활화를 완화한다.","tip":"2025 가을 중간 9번 (a) 의 모범 답안이에요. 세 가지를 모두 적어야 만점이에요."},{"kind":"warn","head":"슬라이드 식의 기호에 주의하세요","items":["식에서 더해지는 것이 **그래프**로 적혀 있는데, 그래프는 원래 더할 수 있는 대상이 아니에요.","실제로 더해지는 것은 노드 특징 행렬이에요. 논문 표기를 압축하면서 생긴 느슨한 표현이에요.","답안에는 특징 행렬 형태로 쓰는 것이 안전해요.","그리고 문제의 $A$ 에 자기 고리나 정규화가 없으면 **문제가 준 그대로** 계산하세요."]},{"kind":"check","q":"**잔차 연결(Residual Connection)**에서 이전 층을 더할 때 가중치를 곱하나요?","choices":["곱해요","곱하지 않고 그대로 더해요","절반만 곱해요","문제마다 달라요"],"a":1,"why":"가중치가 없으니 원래 값이 손상 없이 전달돼요. 그래서 기울기도 특징도 살아남아요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2988,0.0757],"c":[0,0.0019,0.3286,0.1077],"r":5.4241,"img":"img/L5/walk/p041_h.jpg"},"parts":[{"b":[0.28,0.759,0.41,0.05],"c":[0.2595,0.729,0.451,0.11],"r":7.2889,"img":"img/L5/walk/p041_12_01.jpg","say":"가운데 줄이 잔차 학습 식이에요. 뒤에 입력 그래프가 그대로 더해져 있어요."},{"b":[0.04,0.148,0.52,0.043],"c":[0.014,0.1117,0.572,0.1156],"r":8.7966,"img":"img/L5/walk/p041_12_02.jpg","say":"맨 위 한 줄: 'GCN에 잔차 학습을 써서 기울기 소실 문제를 푼다.'"}]}},{"p":42,"title":"Plain, Res, Dense 세 등뼈","terms":["PlainGCN","ResGCN","DenseGCN","Skip Connection","Concatenation","Residual Connection","Vanishing Gradient","Over-smoothing","JKNet"],"pass1":[{"kind":"say","lines":["등뼈 세 종류의 차이는 **스킵 연결 하나**뿐이에요.","**PlainGCN**은 스킵이 없고, **ResGCN**은 더하기, **DenseGCN**은 **이어 붙이기(Concatenation)**예요.","p.7 에서 본 '더하기 대 이어 붙이기'가 층 사이에도 그대로 나와요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"figure","head":"연결선 모양이 세 모델의 전부","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"76\" y=\"26\" font-size=\"14\" text-anchor=\"middle\">PlainGCN<\/text>\n<text class=\"tb\" x=\"240\" y=\"26\" font-size=\"14\" text-anchor=\"middle\">ResGCN<\/text>\n<text class=\"tb\" x=\"404\" y=\"26\" font-size=\"14\" text-anchor=\"middle\">DenseGCN<\/text>\n<rect class=\"box\" x=\"42\" y=\"44\" width=\"70\" height=\"28\" rx=\"5\"/>\n<rect class=\"box\" x=\"42\" y=\"104\" width=\"70\" height=\"28\" rx=\"5\"/>\n<rect class=\"box\" x=\"42\" y=\"164\" width=\"70\" height=\"28\" rx=\"5\"/>\n<text class=\"t\" x=\"76\" y=\"63\" font-size=\"13\" text-anchor=\"middle\">층 1<\/text>\n<text class=\"t\" x=\"76\" y=\"123\" font-size=\"13\" text-anchor=\"middle\">층 2<\/text>\n<text class=\"t\" x=\"76\" y=\"183\" font-size=\"13\" text-anchor=\"middle\">층 3<\/text>\n<line class=\"e\" x1=\"76\" y1=\"74\" x2=\"76\" y2=\"102\"/>\n<line class=\"e\" x1=\"76\" y1=\"134\" x2=\"76\" y2=\"162\"/>\n<rect class=\"box\" x=\"206\" y=\"44\" width=\"70\" height=\"28\" rx=\"5\"/>\n<rect class=\"box\" x=\"206\" y=\"104\" width=\"70\" height=\"28\" rx=\"5\"/>\n<rect class=\"box\" x=\"206\" y=\"164\" width=\"70\" height=\"28\" rx=\"5\"/>\n<text class=\"t\" x=\"240\" y=\"63\" font-size=\"13\" text-anchor=\"middle\">층 1<\/text>\n<text class=\"t\" x=\"240\" y=\"123\" font-size=\"13\" text-anchor=\"middle\">층 2<\/text>\n<text class=\"t\" x=\"240\" y=\"183\" font-size=\"13\" text-anchor=\"middle\">층 3<\/text>\n<line class=\"e\" x1=\"240\" y1=\"74\" x2=\"240\" y2=\"102\"/>\n<line class=\"e\" x1=\"240\" y1=\"134\" x2=\"240\" y2=\"162\"/>\n<path class=\"e2 b1\" d=\"M278 56 Q314 88 278 114\" fill=\"none\"/>\n<path class=\"e2 b1\" d=\"M278 116 Q314 148 278 174\" fill=\"none\"/>\n<rect class=\"box\" x=\"370\" y=\"44\" width=\"70\" height=\"28\" rx=\"5\"/>\n<rect class=\"box\" x=\"370\" y=\"104\" width=\"70\" height=\"28\" rx=\"5\"/>\n<rect class=\"box\" x=\"370\" y=\"164\" width=\"70\" height=\"28\" rx=\"5\"/>\n<text class=\"t\" x=\"404\" y=\"63\" font-size=\"13\" text-anchor=\"middle\">층 1<\/text>\n<text class=\"t\" x=\"404\" y=\"123\" font-size=\"13\" text-anchor=\"middle\">층 2<\/text>\n<text class=\"t\" x=\"404\" y=\"183\" font-size=\"13\" text-anchor=\"middle\">층 3<\/text>\n<line class=\"e\" x1=\"404\" y1=\"74\" x2=\"404\" y2=\"102\"/>\n<line class=\"e\" x1=\"404\" y1=\"134\" x2=\"404\" y2=\"162\"/>\n<path class=\"e2 b2\" d=\"M442 56 Q474 88 442 114\" fill=\"none\"/>\n<path class=\"e2 b2\" d=\"M442 116 Q474 148 442 174\" fill=\"none\"/>\n<path class=\"e2 b2\" d=\"M442 52 Q478 118 442 176\" fill=\"none\"/>\n<text class=\"t b3\" x=\"76\" y=\"216\" font-size=\"13\" text-anchor=\"middle\">스킵 없음<\/text>\n<text class=\"t b3\" x=\"240\" y=\"216\" font-size=\"13\" text-anchor=\"middle\">덧셈 스킵<\/text>\n<text class=\"t b3\" x=\"404\" y=\"216\" font-size=\"13\" text-anchor=\"middle\">이어 붙이기 스킵<\/text>\n<text class=\"tm b3\" x=\"76\" y=\"240\" font-size=\"13\" text-anchor=\"middle\">차원 고정<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"240\" font-size=\"13\" text-anchor=\"middle\">차원 고정<\/text>\n<text class=\"tm b3\" x=\"404\" y=\"240\" font-size=\"13\" text-anchor=\"middle\">차원이 늘어남<\/text>\n<\/svg>","caption":"**PlainGCN**은 직선뿐, **ResGCN**은 돌아오는 곡선 하나, **DenseGCN**은 앞선 모든 층에서 곡선이 나와요.","builds":3},{"kind":"compare","head":"세 등뼈를 나란히","cols":["등뼈","층의 출력","차원 변화"],"rows":[["**PlainGCN**","층이 계산한 것만","일정"],["**ResGCN**","층이 계산한 것 더하기 입력","일정"],["**DenseGCN**","이전 모든 층을 **이어 붙이기(Concatenation)**","계속 늘어남"]]},{"kind":"steps","head":"DenseGCN 의 차원이 얼마나 늘어나나","steps":["입력이 64 차원이고 각 층이 새로 32 차원을 만든다고 해요.","층 1 을 지나면 $64 + 32 = 96$ 차원이에요.","층 2 를 지나면 $96 + 32 = 128$ 차원이에요.","층 10 이면 $64 + 10 \\times 32 = 384$ 차원이에요.","층 27 이면 $64 + 27 \\times 32 = 928$ 차원이에요."],"answer":"**DenseGCN**은 메모리를 많이 먹지만 각 층의 정보가 섞이지 않고 따로 보관돼요. 그래서 평활화에 더 강해요.","given":"**ResGCN**은 층을 아무리 지나도 차원이 64 로 일정해요."},{"kind":"compare","head":"세 등뼈의 장단점","cols":["항목","**PlainGCN**","**ResGCN**","**DenseGCN**"],"rows":[["**기울기 소실(Vanishing Gradient)**","심각","해결","해결"],["**과도한 평활화(Over-smoothing)**","심각","늦춤","더 잘 늦춤"],["메모리","적음","적음","많음"]]},{"kind":"points","head":"확장이라는 말은 무슨 뜻인가요","items":["확장은 이웃을 한 칸씩 건너뛰며 고르는 것이에요.","같은 개수를 고르면서도 더 넓은 범위를 볼 수 있어요.","슬라이드 그림에서 d 값이 1, 1, 2 에서 26, 27 로 늘어나는 것이 그거예요.","깊은 층일수록 더 멀리 건너뛰어 이웃을 골라요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"ResGCN adds a residual graph connection, while DenseGCN concatenates the outputs of all previous layers.","ko":"ResGCN 은 잔차 그래프 연결을 더하고, DenseGCN 은 이전 모든 층의 출력을 이어 붙인다.","tip":"adds 와 concatenates 를 대비시키면 두 모델이 한 문장에 정리돼요."},{"kind":"warn","head":"DenseGCN 과 JKNet 을 헷갈리지 마세요","items":["둘 다 층별 결과를 모은다는 점에서 비슷해 보여요.","차이는 **언제 합치느냐**예요.","**DenseGCN**은 **층마다** 이어 붙여서 다음 층이 그걸 다 받아요.","**JKNet**은 **마지막에 한 번만** 층별 결과를 모아 골라요. 그래서 계산이 훨씬 가벼워요."]},{"kind":"check","q":"**ResGCN**과 **DenseGCN**의 차이는 무엇인가요?","choices":["층 수","스킵을 더하기로 하느냐 이어 붙이기로 하느냐","활성 함수","학습률"],"a":1,"why":"**ResGCN**은 더하기라 차원이 일정하고, **DenseGCN**은 **이어 붙이기(Concatenation)**라 차원이 늘어나요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2988,0.0757],"c":[0,0.0019,0.3286,0.1077],"r":5.4241,"img":"img/L5/walk/p042_h.jpg"},"parts":[{"b":[0.06,0.157,0.42,0.042],"c":[0.039,0.123,0.462,0.11],"r":7.4667,"img":"img/L5/walk/p042_11_01.jpg","say":"'PlainGCN: 융합 블록과 MLP 예측 블록.' 스킵이 없는 기본형이에요."},{"b":[0.06,0.232,0.66,0.042],"c":[0.027,0.1797,0.726,0.1467],"r":8.798,"img":"img/L5/walk/p042_11_02.jpg","say":"'ResGCN: PlainGCN에 동적 확장 k-NN과 잔차 그래프 연결을 더해서 만들어요.'"},{"b":[0.06,0.37,0.64,0.042],"c":[0.028,0.3199,0.704,0.1422],"r":8.8014,"img":"img/L5/walk/p042_11_03.jpg","say":"'DenseGCN: PlainGCN에 동적 확장 k-NN과 조밀 그래프 연결을 더해요.'"}]}},{"p":43,"title":"팽창 그래프 합성곱: 이웃을 건너뛰며 고르기","terms":["Receptive Field","GCN"],"pass1":[{"kind":"say","lines":["**팽창(dilated)** 은 띄엄띄엄 고른다는 뜻이에요.","가까운 이웃만 보지 말고 **몇 칸씩 건너뛰며** 골라서 멀리까지 보자는 생각이에요.","CNN 의 팽창 합성곱을 그래프로 옮겨 온 것이에요."]},{"kind":"analogy","head":"도서관에서 책 고르기","scene":"책꽂이에 책이 백 권 꽂혀 있어요. 맨 앞에서 네 권만 뽑으면 전부 비슷한 주제예요. 대신 열두 권을 눈으로 훑은 다음 **세 권마다 한 권씩** 뽑으면 역시 네 권인데 주제가 훨씬 다양해요. 뽑는 개수는 같은데 훑는 범위가 넓어진 거예요.","map":[["책 백 권","그래프의 노드들"],["세 권마다 하나씩 뽑기","팽창률 $d$ 만큼 건너뛰며 고르기"],["주제가 다양해지는 것","**수용 영역(Receptive Field)** 이 넓어지는 것"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"formula","head":"팽창 이웃 집합","tex":"N^{(d)}(v) = \\left\\{u_1,\\, u_{1+d},\\, u_{1+2d},\\, \\ldots,\\, u_{1+(k-1)d}\\right\\}","parts":[{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"}],"whole":"가까운 순으로 $k \\times d$ 개를 줄 세운 뒤 $d$ 칸마다 하나씩 집어요. 뽑는 개수는 $k$ 그대로인데 닿는 거리는 $d$ 배가 돼요."},{"kind":"steps","head":"팽창률이 3 이고 이웃 4개를 고를 때","steps":["먼저 가까운 순서로 $k \\times d = 4 \\times 3 = 12$ 개를 찾아요.","줄 세운 번호가 1번부터 12번까지예요.","1번을 집고, 거기서 3칸 뛰어 4번을 집어요.","다시 3칸 뛰어 7번, 또 3칸 뛰어 10번을 집어요.","고른 것은 1, 4, 7, 10 번 네 개예요."],"answer":"이웃은 4개 그대로인데 가장 먼 것이 10번이라서, 그냥 4개를 골랐을 때(1~4번)보다 훨씬 멀리 닿아요.","given":"팽창률 $d = 3$, 고를 이웃 수 $k = 4$ 예요."},{"kind":"figure","head":"같은 개수를 골라도 닿는 거리가 달라요","svg":"<svg viewBox=\"0 0 480 220\">\n <text class=\"tb\" x=\"120\" y=\"24\" text-anchor=\"middle\" font-size=\"15\">보통 k-NN: 가까운 4개<\/text>\n <circle class=\"n2\" cx=\"120\" cy=\"110\" r=\"16\"/>\n <circle class=\"n b1\" cx=\"70\" cy=\"80\" r=\"11\"/>\n <circle class=\"n b1\" cx=\"70\" cy=\"140\" r=\"11\"/>\n <circle class=\"n b1\" cx=\"120\" cy=\"60\" r=\"11\"/>\n <circle class=\"n b1\" cx=\"120\" cy=\"160\" r=\"11\"/>\n <circle class=\"n3\" cx=\"40\" cy=\"110\" r=\"11\"/>\n <circle class=\"n3\" cx=\"170\" cy=\"75\" r=\"11\"/>\n <circle class=\"n3\" cx=\"180\" cy=\"145\" r=\"11\"/>\n <circle class=\"n3\" cx=\"200\" cy=\"110\" r=\"11\"/>\n <text class=\"t\" x=\"120\" y=\"200\" text-anchor=\"middle\" font-size=\"13\">바로 옆만 봐서 시야가 좁아요<\/text>\n <text class=\"tb\" x=\"360\" y=\"24\" text-anchor=\"middle\" font-size=\"15\">팽창: 12개 중 3칸마다<\/text>\n <circle class=\"n2\" cx=\"360\" cy=\"110\" r=\"16\"/>\n <circle class=\"n3\" cx=\"310\" cy=\"80\" r=\"11\"/>\n <circle class=\"n b2\" cx=\"310\" cy=\"140\" r=\"11\"/>\n <circle class=\"n3\" cx=\"360\" cy=\"60\" r=\"11\"/>\n <circle class=\"n3\" cx=\"360\" cy=\"160\" r=\"11\"/>\n <circle class=\"n b2\" cx=\"280\" cy=\"110\" r=\"11\"/>\n <circle class=\"n3\" cx=\"410\" cy=\"75\" r=\"11\"/>\n <circle class=\"n b2\" cx=\"420\" cy=\"145\" r=\"11\"/>\n <circle class=\"n b2\" cx=\"440\" cy=\"110\" r=\"11\"/>\n <text class=\"t\" x=\"360\" y=\"200\" text-anchor=\"middle\" font-size=\"13\">같은 4개를 골라도 훨씬 멀리 닿아요<\/text>\n<\/svg>","caption":"왼쪽은 바로 옆 4개, 오른쪽은 3칸마다 고른 4개예요.","builds":2}],"pass3":[{"kind":"warn","head":"자주 헷갈리는 점","items":["**$k \\times d$ 개를 먼저 찾는다**는 순서를 빠뜨리면 안 돼요. 바로 $d$ 칸씩 뛰는 것이 아니에요","팽창은 **고르는 개수를 늘리지 않아요.** 계산 비용은 그대로인데 시야만 넓어지는 것이 장점이에요","확률적 팽창은 **학습할 때만** 켜요"]},{"kind":"check","q":"팽창률 $d = 2$ 로 이웃 3개를 고르려면 먼저 몇 개를 줄 세워야 하나요?","choices":["3개","5개","6개","9개"],"a":2,"why":"$k \\times d = 3 \\times 2 = 6$ 개를 찾은 뒤 1번, 3번, 5번을 집어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2988,0.1501],"c":[0,0.0019,0.3286,0.1821],"r":3.208,"img":"img/L5/walk/p043_h.jpg"},"parts":[{"b":[0.06,0.17,0.9,0.07],"c":[0.01,0.105,0.99,0.2],"r":8.8,"img":"img/L5/walk/p043_20_01.jpg","say":"첫 불릿 **개념** 이에요. CNN 의 풀링은 공간 정보를 잃는데, 팽창 합성곱은 해상도를 안 잃고 넓힌대요."},{"b":[0.06,0.26,0.9,0.05],"c":[0.01,0.185,0.99,0.2],"r":8.8,"img":"img/L5/walk/p043_20_02.jpg","say":"둘째 불릿 **팽창 k-NN 탐색** 이에요. $k$ 개를 바로 고르지 않고 $k \\times d$ 개를 찾은 다음 $d$ 개마다 하나씩 골라요."},{"b":[0.06,0.35,0.9,0.05],"c":[0.01,0.275,0.99,0.2],"r":8.8,"img":"img/L5/walk/p043_20_03.jpg","say":"셋째 불릿이 **수식** 이에요. 팽창률을 $d$ 라 할 때의 이웃 집합이에요."},{"b":[0.06,0.5,0.9,0.07],"c":[0.01,0.435,0.99,0.2],"r":8.8,"img":"img/L5/walk/p043_20_04.jpg","say":"넷째 불릿 **확률적 팽창** 이에요. 학습할 때는 확률을 섞어서 일반화를 튼튼하게 해요."}]}},{"p":44,"title":"DeepGCNs: 세 블록 구조","terms":["DeepGCNs","PlainGCN","ResGCN","DenseGCN","Skip Connection","Concatenation","Over-squashing"],"pass1":[{"kind":"say","lines":["**DeepGCNs**는 세 덩어리로 되어 있어요.","GCN 백본 블록, 융합 블록, MLP 예측 블록이에요.","그리고 백본에는 **PlainGCN**, **ResGCN**, **DenseGCN** 세 종류가 있어요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.055,"y":0.146,"w":0.89,"h":0.04,"say":"'프레임워크는 세 블록으로 이루어져요.'","c":[0.0105,0.0671,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p044_20_01.jpg"},{"x":0.055,"y":0.244,"w":0.64,"h":0.04,"say":"'GCN 백본 블록은 세 종류가 있어요.' Plain, Res, Dense 예요.","c":[0.023,0.1929,0.704,0.1422],"r":8.8014,"img":"img/L5/walk/p044_20_02.jpg"},{"x":0.055,"y":0.296,"w":0.89,"h":0.072,"say":"'GCN 스킵 연결에는 두 가지가 있어요. 꼭짓점별 덧셈과 꼭짓점별 이어 붙이기예요.'","c":[0.0105,0.2331,0.979,0.1978],"r":8.799,"img":"img/L5/walk/p044_20_03.jpg"},{"x":0.472,"y":0.469,"w":0.459,"h":0.445,"say":"오른쪽 등뼈 세 종류를 다시 보세요. 연결선 모양만 달라요.","c":[0.4491,0.4467,0.5049,0.4895],"r":1.8337,"img":"img/L5/walk/p044_20_04.jpg"}]},{"kind":"points","head":"세 블록이 하는 일","items":["백본 블록은 **메시지 패싱**을 여러 층 반복해요. 입력은 노드 특징, 출력은 층별 노드 특징이에요.","융합 블록은 층별 결과를 합치고 전역 최대 풀링으로 그래프 전체를 벡터 하나로 요약해요.","MLP 예측 블록은 그것을 클래스 점수로 바꿔요.","'꼭짓점별'이란 '노드마다 따로'라는 뜻이에요. 노드 1 은 노드 1 끼리 짝지어 더해요."]},{"kind":"steps","head":"전역 최대 풀링을 손으로 해 보기","steps":["노드 넷, 특징 세 칸이라고 해요.","노드 1 은 (2, 5, 1), 노드 2 는 (7, 0, 3) 이에요.","노드 3 은 (1, 4, 9), 노드 4 는 (3, 2, 0) 이에요.","첫째 칸의 최댓값은 2, 7, 1, 3 중 7 이에요.","둘째 칸은 5, 0, 4, 2 중 5 이고, 셋째 칸은 1, 3, 9, 0 중 9 예요."],"answer":"결과는 (7, 5, 9) 예요. 노드가 넷이든 4천이든 결과는 항상 세 칸이에요. 그게 융합 블록의 목적이에요.","given":"노드 네 개의 특징을 전역 최대 풀링으로 요약해요."},{"kind":"warn","head":"여기가 압착이 일어나는 지점이기도 해요","items":["노드 수천 개의 정보를 길이 1024 짜리 벡터 하나로 줄이는 거예요.","p.21 에서 본 **과도한 압착(Over-squashing)** 이야기가 여기서 다시 나와요.","요약은 편리하지만 대가가 있어요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"The DeepGCNs framework has a GCN backbone block, a fusion block, and an MLP prediction block.","ko":"DeepGCNs 프레임워크는 GCN 백본 블록, 융합 블록, MLP 예측 블록으로 이루어진다.","tip":"세 블록 이름을 영어로 정확히 쓰는 것이 채점 포인트예요."},{"kind":"warn","head":"슬라이드의 k 와 클래스 13 은 데이터셋 사정이에요","items":["'k 는 가장 가까운 이웃의 개수'라고 적혀 있는데, 이건 **DeepGCNs**가 점구름 문제에서 나왔기 때문이에요.","점구름은 3차원 공간에 흩어진 점들이라 엣지가 원래 없어요. 그래서 이웃을 직접 만들어야 해요.","보통 그래프에서는 엣지가 이미 있으니 그럴 필요가 없어요.","시험에서 **DeepGCNs**를 물으면 답은 '**잔차 연결(Residual Connection)**'이지 'k개 최근접 이웃'이 아니에요."]},{"kind":"check","q":"**DeepGCNs**의 세 블록이 아닌 것은 무엇인가요?","choices":["GCN 백본 블록","융합 블록","MLP 예측 블록","어텐션 블록"],"a":3,"why":"세 블록은 백본, 융합, 예측이에요. 어텐션은 다른 처방 가족인 GraphGPS 쪽이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.9647,0.4265],"c":[0,0,1,0.4692],"r":3.789,"img":"img/L5/walk/p044_h.jpg"},"parts":[{"b":[0.082,0.469,0.115,0.315],"c":[0.0395,0.453,0.2,0.347],"r":1.0247,"img":"img/L5/walk/p044_11_01.jpg","say":"노란 'GCN Backbone Block'. 메시지 패싱을 반복하는 부분이에요."},{"b":[0.2,0.469,0.12,0.315],"c":[0.16,0.453,0.2,0.347],"r":1.0247,"img":"img/L5/walk/p044_11_02.jpg","say":"파란 'Fusion Block'. 층별 결과를 합치고 그래프 전체를 요약해요."},{"b":[0.325,0.469,0.1,0.315],"c":[0.275,0.453,0.2,0.347],"r":1.0247,"img":"img/L5/walk/p044_11_03.jpg","say":"분홍 'MLP Prediction Block'. 최종 분류를 해요."}]}},{"p":45,"title":"DeepGCNs 예제 코드","terms":["DeepGCNs","Residual Connection","Layer Normalization","ReLU","PlainGCN","DenseGCN","Over-smoothing"],"pass1":[{"kind":"say","lines":["**DeepGCNs**가 실제 코드로 어떻게 생겼는지 봐요.","파이썬이 서툴러도 괜찮아요. **어느 줄이 잔차 연결인지** 하나만 찾으면 돼요.","답을 미리 말하면 `block='res+'` 라고 적힌 딱 한 줄이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"points","head":"이 슬라이드에서 확인할 것","items":["왼쪽 코드에서 **잔차 연결(Residual Connection)**을 켜는 스위치를 찾아요.","오른쪽 그림은 학습이 끝난 뒤의 노드 임베딩이에요.","같은 색끼리 덩어리를 이루고 있으면 클래스가 잘 구별된다는 뜻이에요.","만약 **과도한 평활화(Over-smoothing)**가 심했다면 색이 다 뒤섞이거나 한 점으로 모였을 거예요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"A DeepGCN is built by wrapping a convolution, a normalization and an activation in a layer with a residual block.","ko":"DeepGCN 은 합성곱, 정규화, 활성화를 잔차 블록으로 감싸서 만든다.","tip":"wrapping ... in a layer with a residual block 이라는 구조가 코드 그대로예요."}],"pass4":[{"kind":"pyterm","name":"클래스(class)와 self","say":["`class` 는 '설계도'를 만드는 문법이에요. 붕어빵 틀이라고 보면 돼요.","`self` 는 '나 자신'이에요. 설계도로 찍어 낸 물건 하나를 가리켜요.","`__init__` 은 물건을 처음 만들 때 한 번 실행되는 준비 작업이에요."],"example":"class Dog:\n  def __init__(self, name):\n    self.name = name\n\nd = Dog('coco')\nprint(d.name)","out":"coco"},{"kind":"pyterm","name":"파이토치 모델의 뼈대","say":["`torch.nn.Module` 을 물려받으면 파이토치가 학습을 도와줘요.","`__init__` 에서 층을 만들어 두고, `forward` 에서 데이터를 통과시켜요.","`super().__init__()` 은 '물려받은 준비 작업도 해 줘'라는 뜻이에요."],"example":"class Net(torch.nn.Module):\n  def __init__(self):\n    super().__init__()\n    self.fc = Linear(3, 2)\n  def forward(self, x):\n    return self.fc(x)"},{"kind":"code","head":"DeepGCN 모델 정의","file":"L5 p.45 슬라이드에 인쇄된 코드 (PyTorch Geometric)","code":"class DeepGCN(torch.nn.Module):\n  def __init__(self,num_features, num_classes, dim =16, num_layers =2, drop=0.5):\n    super().__init__()\n\n    self.node_encoder = Linear(num_features, dim)\n    #self.edge_encoder = Linear(data.edge_attr.size(-1), hidden_channels)\n    self.h = None\n    self.layers = torch.nn.ModuleList()\n    for i in range(1, num_layers + 1):\n      conv = GENConv(dim, dim, aggr='softmax', t=1.0, learn_t=True, num_layers=2, norm='layer')\n      norm = LayerNorm(dim, elementwise_affine=True)\n      act = ReLU(inplace=True)\n\n      layer = DeepGCNLayer(conv, norm, act, block='res+', dropout=0.1,ckpt_grad=i % 3)\n      self.layers.append(layer)\n    self.mlp = Linear(dim, num_classes)\n    self.optimizer = torch.optim.Adam(self.parameters(),lr=0.01,weight_decay=5e-4)\n\n  def forward(self, x, edge_index):\n    x = self.node_encoder(x)\n    x = self.layers[0].conv(x, edge_index)\n\n    for layer in self.layers[1:]:\n      x = layer(x, edge_index)\n\n    x = self.layers[0].act(self.layers[0].norm(x))\n    x = F.dropout(x, p=0.1, training=self.training)\n    x = self.mlp(x)\n    self.h = x\n    return x, F.log_softmax(x, dim=1)","lines":[{"from":1,"to":3,"say":"파이토치 모델 하나를 정의해요. 입력 특징 수, 클래스 수, 숨은 차원 16, 층 수 2, 드롭아웃 0.5 를 받아요."},{"from":5,"to":6,"say":"원래 특징을 16 차원으로 줄이는 선형 변환이에요. 6번 줄은 앞에 우물 정 기호가 있어 실행되지 않는 설명이에요."},{"from":7,"to":8,"say":"결과를 담아 둘 자리와 층들을 담을 빈 목록을 만들어요."},{"from":9,"to":9,"say":"층 수만큼 반복해요. 층 수가 2 면 i 가 1 과 2 로 두 번 돌아요."},{"from":10,"to":10,"say":"메시지 패싱을 담당하는 층이에요. 집계를 소프트맥스 가중평균으로 하고 그 온도까지 학습해요."},{"from":11,"to":12,"say":"**층 정규화(Layer Normalization)**와 **렐루(ReLU)**예요. p.36 표의 정규화 처방이 여기 들어와 있어요."},{"from":14,"to":15,"say":"**이 줄이 핵심이에요.** block 을 res+ 로 두면 **잔차 연결(Residual Connection)**이 켜져요. plain 으로 바꾸면 **PlainGCN**, dense 로 바꾸면 **DenseGCN** 이에요."},{"from":16,"to":17,"say":"마지막 예측 층과 학습 방법이에요. lr 은 학습률, weight_decay 는 가중치가 커지지 않게 억제하는 규제예요."},{"from":19,"to":21,"say":"실제로 데이터를 통과시키는 부분이에요. 특징을 16 차원으로 줄이고 첫 층은 합성곱만 해요."},{"from":23,"to":24,"say":"나머지 층을 차례로 통과시켜요. 각 층 안에서 **잔차 연결(Residual Connection)**이 일어나요."},{"from":26,"to":27,"say":"마지막에 정규화와 활성화를 한 번 하고, 값의 10퍼센트를 무작위로 0 으로 만들어요."},{"from":28,"to":30,"say":"클래스 점수로 바꾸고, 점수와 그 로그 확률을 함께 돌려줘요."}],"link":"14번 줄의 res+ 가 p.41 의 식 '층 계산 더하기 이전 층'에 해당해요."},{"kind":"points","head":"res+ 가 정확히 무엇을 하나요","items":["이름 뒤의 더하기 기호에는 뜻이 있어요. 계산 순서를 가리켜요.","res 는 합성곱을 먼저 하고 정규화와 활성화를 한 뒤 입력을 더해요.","res+ 는 정규화와 활성화를 **먼저** 하고 합성곱을 나중에 해요. 이것을 사전 활성화라고 불러요.","그러면 잔차 경로의 값이 아무 변환 없이 덧셈 지점까지 와서 기울기가 더 잘 흘러요."]},{"kind":"warn","head":"이 코드에 함정이 몇 개 있어요","items":["`num_layers` 가 두 군데 나오는데 뜻이 달라요. 하나는 DeepGCN 층 수, 다른 하나는 층 내부 MLP 의 층 수예요.","`drop=0.5` 를 인자로 받아 놓고 실제로는 0.1 을 직접 써요. 즉 그 인자가 쓰이지 않아요.","기본값이 층 2 개예요. **DeepGCNs**는 깊게 쌓으려고 만든 모델인데 예제 기본값이 얕아요. 효과를 보려면 이 값을 키워야 해요."]},{"kind":"check","q":"코드에서 **잔차 연결(Residual Connection)**을 켜는 곳은 어디인가요?","choices":["GENConv 의 aggr","DeepGCNLayer 의 block","LayerNorm 의 elementwise_affine","Adam 의 lr"],"a":1,"why":"block 을 res+ 로 두면 잔차가 켜져요. plain 이나 dense 로 바꾸면 다른 등뼈가 돼요."}],"walk":{"head":{"b":[0.0131,0.0179,0.2883,0.0757],"c":[0,0.0019,0.3171,0.1077],"r":5.2343,"img":"img/L5/walk/p045_h.jpg"},"parts":[{"b":[0.007,0.154,0.562,0.787],"c":[0,0.1146,0.6182,0.8657],"r":1.2695,"img":"img/L5/walk/p045_11_01.jpg","say":"왼쪽이 코드 화면이에요. 30줄 정도예요."},{"b":[0.597,0.191,0.368,0.747],"c":[0.5786,0.1537,0.4048,0.8217],"r":0.8758,"img":"img/L5/walk/p045_11_02.jpg","say":"오른쪽은 임베딩을 2차원에 그린 그림이에요. 색이 클래스예요."},{"b":[0.64,0.3,0.15,0.15],"c":[0.615,0.284,0.2,0.182],"r":1.9536,"img":"img/L5/walk/p045_11_03.jpg","say":"같은 색끼리 뭉쳐 있죠. 평활화가 억제되어 클래스가 구별된다는 뜻이에요."}]}},{"p":46,"title":"다시 보는 GCN 층: 앞으로 고칠 한 줄","terms":["GCN","Adjacency Matrix","Degree","ReLU","Over-smoothing"],"pass1":[{"kind":"say","lines":["오늘 나올 모델들은 전부 **그래프 합성곱 신경망(GCN)** 의 층 한 줄을 조금씩 고친 것이에요.","그래서 고치기 전의 원본을 먼저 또렷하게 봐 둬요.","한 층이 하는 일은 딱 세 가지예요. 이웃 평균 내기, 특징 비틀기, 음수 자르기."]},{"kind":"analogy","head":"반 친구들 성적표 고치기","scene":"한 반에 아이 다섯 명이 있어요. 각자 자기 점수표를 들고 있어요. 먼저 옆에 앉은 친구들 점수를 모아 평균을 내요. 그다음 선생님이 준 환산표를 곱해서 점수를 바꿔요. 마지막으로 음수가 나온 칸은 0으로 적어요. 이 세 동작이 한 번에 한 층이에요.","map":[["친구들 점수 평균 내기","이웃 표현을 모으는 일"],["선생님의 환산표 곱하기","가중치 행렬 곱하기"],["음수를 0으로 적기","**렐루(ReLU)** 씌우기"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"색칠한 상자 세 개를 하나씩","boxes":[{"x":0.42,"y":0.48,"w":0.17,"h":0.11,"say":"보라 상자는 이전 층의 표현이에요. 지난 층에서 각 노드가 들고 있던 숫자 벡터예요.","c":[0.405,0.464,0.2,0.142],"r":2.5039,"img":"img/L5/walk/p046_20_01.jpg"},{"x":0.19,"y":0.49,"w":0.18,"h":0.09,"say":"초록 상자는 정규화된 **인접행렬(Adjacency Matrix)** 이에요. 누가 누구에게 보내는지를 담아요.","c":[0.178,0.474,0.204,0.122],"r":2.9727,"img":"img/L5/walk/p046_20_02.jpg"},{"x":0.62,"y":0.52,"w":0.16,"h":0.07,"say":"주황 상자는 가중치 행렬이에요. 특징끼리 섞고 차원을 바꾸는 역할이에요.","c":[0.6,0.5,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p046_20_03.jpg"},{"x":0.47,"y":0.72,"w":0.28,"h":0.24,"say":"오른쪽 그림에서 가운데 노드가 빨간 테두리로 바뀌고 옆 숫자가 소수로 변했어요. 이웃 값이 섞인 결과예요.","c":[0.456,0.704,0.308,0.272],"r":2.0131,"img":"img/L5/walk/p046_20_04.jpg"}]},{"kind":"formula","head":"GCN 층 한 줄","tex":"\\mathbf{H}^{(\\ell+1)} = \\sigma\\left(\\tilde{\\mathbf{P}}\\,\\mathbf{H}^{(\\ell)}\\,\\mathbf{W}^{(\\ell)}\\right)","parts":[{"sym":"\\mathbf{H}^{(\\ell)}","say":"층 $\\ell$ 에서 모든 노드의 표현을 한 줄씩 쌓은 표예요. 가로가 특징, 세로가 노드예요."},{"sym":"\\tilde{\\mathbf{P}}","say":"정규화한 **인접행렬(Adjacency Matrix)** 이에요. 누가 누구에게 얼마나 세게 보내는지를 담아요."},{"sym":"\\mathbf{W}^{(\\ell)}","say":"층마다 따로 배우는 가중치 행렬이에요. 특징끼리 섞어요."},{"sym":"\\sigma","say":"활성화 함수예요. 보통 **렐루(ReLU)** 로 음수를 0으로 바꿔요."}],"whole":"이웃끼리 평균을 내고, 가중치로 한 번 비틀고, 음수를 잘라 내는 것이 **그래프 합성곱 신경망(GCN)** 의 한 층이에요."},{"kind":"steps","head":"행 정규화 인접행렬을 손으로 만들어요","steps":["노드는 4개이고 엣지는 1과 2, 1과 3, 2와 3, 3과 4 네 개예요.","각 행에서 1의 개수를 세면 **차수(Degree)** 예요. 차례로 2, 2, 3, 1 이에요.","1행은 2로 나눠요. 그래서 2번 자리와 3번 자리가 각각 $1/2$ 이에요.","3행은 3으로 나눠요. 1번, 2번, 4번 자리가 각각 $1/3$ 이에요.","4행은 1로 나눠요. 3번 자리가 1 이에요."],"answer":"$\\tilde{A} = D^{-1}A$ 를 구하면 모든 행의 합이 1 이에요. 1이 아니면 계산을 틀린 거예요.","given":"인접행렬 $A$ 의 각 행을 그 행의 **차수(Degree)** 로 나눠요."},{"kind":"figure","head":"층 하나가 하는 세 동작","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"26\" font-size=\"17\" text-anchor=\"middle\">GCN 층 한 줄이 하는 세 가지 일<\/text>\n<rect class=\"box\" x=\"16\" y=\"60\" width=\"96\" height=\"56\" rx=\"8\"/>\n<text class=\"t\" x=\"64\" y=\"84\" font-size=\"15\" text-anchor=\"middle\">이전 층 표현<\/text>\n<text class=\"tm\" x=\"64\" y=\"104\" font-size=\"14\" text-anchor=\"middle\">노드마다 벡터<\/text>\n<polygon class=\"arrow b1\" points=\"118,80 134,88 118,96\"/>\n<rect class=\"box2 b1\" x=\"138\" y=\"60\" width=\"96\" height=\"56\" rx=\"8\"/>\n<text class=\"t b1\" x=\"186\" y=\"84\" font-size=\"15\" text-anchor=\"middle\">이웃 평균<\/text>\n<text class=\"tm b1\" x=\"186\" y=\"104\" font-size=\"14\" text-anchor=\"middle\">P 를 곱해요<\/text>\n<polygon class=\"arrow b2\" points=\"240,80 256,88 240,96\"/>\n<rect class=\"box2 b2\" x=\"260\" y=\"60\" width=\"96\" height=\"56\" rx=\"8\"/>\n<text class=\"t b2\" x=\"308\" y=\"84\" font-size=\"15\" text-anchor=\"middle\">특징 비틀기<\/text>\n<text class=\"tm b2\" x=\"308\" y=\"104\" font-size=\"14\" text-anchor=\"middle\">W 를 곱해요<\/text>\n<polygon class=\"arrow b3\" points=\"362,80 378,88 362,96\"/>\n<rect class=\"box2 b3\" x=\"382\" y=\"60\" width=\"86\" height=\"56\" rx=\"8\"/>\n<text class=\"t b3\" x=\"425\" y=\"84\" font-size=\"15\" text-anchor=\"middle\">음수는 0<\/text>\n<text class=\"tm b3\" x=\"425\" y=\"104\" font-size=\"14\" text-anchor=\"middle\">렐루를 씌워요<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"164\" font-size=\"16\" text-anchor=\"middle\">왼쪽 곱은 노드끼리 섞고 오른쪽 곱은 특징끼리 섞어요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"196\" font-size=\"14\" text-anchor=\"middle\">앞으로 나올 모델은 이 세 칸 중 어디를 고쳤는지로 외우면 돼요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"226\" font-size=\"14\" text-anchor=\"middle\">GCNII 는 가운데와 오른쪽에 원본과 단위행렬을 섞어요<\/text>\n<\/svg>","caption":"왼쪽 곱은 노드끼리, 오른쪽 곱은 특징끼리 섞어요.","builds":3}],"pass3":[{"kind":"warn","head":"여기서 헷갈리기 쉬워요","items":["자기 고리를 더한 $\\tilde{A} = A + I$ 와 정규화까지 마친 $\\tilde{P}$ 는 다른 것이에요.","시험은 $\\tilde{A} = D^{-1}A$ 라고 문제에 적어 줘요. 주어진 $A$ 를 그대로 쓰세요.","행렬 곱 순서를 바꾸면 안 돼요. 왼쪽 곱과 오른쪽 곱의 역할이 달라요."]},{"kind":"check","q":"행 정규화 인접행렬 $\\tilde{A} = D^{-1}A$ 를 구한 뒤 반드시 해야 하는 검산은 무엇인가요?","choices":["열의 합이 1인지 본다","행의 합이 1인지 본다","대각선이 0인지 본다","행렬식이 1인지 본다"],"a":1,"why":"각 행을 그 행의 **차수(Degree)** 로 나눴으니 행의 합은 항상 1 이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2615,0.0757],"c":[0.0001,0.0019,0.2876,0.1077],"r":4.7473,"img":"img/L5/walk/p046_h.jpg"},"parts":[{"b":[0.03,0.14,0.42,0.08],"c":[0.009,0.124,0.462,0.112],"r":7.3333,"img":"img/L5/walk/p046_12_01.jpg","say":"위 불릿이 그래프 합성곱 층이에요. Kipf 가 2017년에 낸 **GCN** 이라는 뜻이에요."},{"b":[0.24,0.33,0.4,0.11],"c":[0.22,0.314,0.44,0.142],"r":5.5086,"img":"img/L5/walk/p046_12_02.jpg","say":"가운데 큰 식이 오늘의 원본이에요. 색칠한 상자 세 개가 각각 무엇인지 아래에서 알려 줘요."},{"b":[0.18,0.72,0.3,0.24],"c":[0.165,0.704,0.33,0.272],"r":2.1569,"img":"img/L5/walk/p046_12_03.jpg","say":"왼쪽 그림에서 초록 화살표가 이웃에서 가운데 노드로 들어와요. 이것이 모으는 동작이에요."}]}},{"p":47,"title":"GCNII: 깊어져도 안 망가지게 하는 두 장치","terms":["GCNII","Initial Residual Connection","Identity Mapping","Over-smoothing","Residual Connection","Identity Matrix","GCN"],"pass1":[{"kind":"say","lines":["층을 깊이 쌓으면 모든 노드 표현이 비슷해져요. 이것을 **과평활화(Over-smoothing)** 라고 해요.","**지씨엔 투(GCNII)** 는 이 문제를 풀려고 딱 두 가지를 더해요.","첫째는 맨 처음 특징을 매 층에 다시 섞어 주는 **초기 잔차 연결(Initial Residual Connection)** 이에요.","둘째는 가중치에 단위행렬을 섞는 **항등 사상(Identity Mapping)** 이에요."]},{"kind":"analogy","head":"소문이 도는 교실","scene":"한 반에서 이야기 하나가 사람을 거쳐 돌아요. 다섯 명쯤 거치면 원래 이야기가 뭐였는지 아무도 몰라요. 그래서 규칙을 하나 정했어요. 이야기를 전할 때마다 처음 적어 둔 쪽지를 다시 꺼내 읽고 섞는 거예요. 그러면 열 명을 거쳐도 원본이 안 지워져요.","map":[["사람을 거쳐 도는 이야기","층을 지나며 섞이는 노드 표현"],["원본이 사라지는 일","**과평활화(Over-smoothing)**"],["처음 쪽지를 매번 다시 읽기","**초기 잔차 연결(Initial Residual Connection)**"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"두 장치가 맡은 고장이 달라요","items":["**초기 잔차 연결(Initial Residual Connection)** 은 표현이 뭉개지는 것을 막아요.","**항등 사상(Identity Mapping)** 은 가중치가 망가지는 것을 막아요.","초기 잔차만 쓰면 층마다 가중치가 곱해져서 깊어질수록 학습이 흔들려요.","항등 사상만 쓰면 이웃끼리 섞이는 것을 못 막아요. 그래서 둘 다 필요해요."]},{"kind":"compare","head":"잔차 연결 두 가지를 구별해요","cols":["항목","DeepGCN 의 **잔차 연결(Residual Connection)**","**초기 잔차 연결(Initial Residual Connection)**"],"rows":[["무엇을 더하나","바로 앞 층 $H^{(k-1)}$","맨 처음 $H^{(0)}$"],["층이 깊어지면","원본 비중이 점점 작아져요","원본 비중이 항상 $\\alpha$ 로 같아요"],["나온 강의","5주차 앞부분","5주차 이 슬라이드"]]},{"kind":"formula","head":"항등 사상이 바꾸는 자리","tex":"(1-\\beta_\\ell)\\mathbf{I}_n + \\beta_\\ell \\mathbf{W}^{(\\ell)}","parts":[{"sym":"\\mathbf{I}_n","say":"**단위행렬(Identity Matrix)** 이에요. 대각선만 1이라 곱해도 값이 그대로예요."},{"sym":"\\beta_\\ell","say":"층 $\\ell$ 에서 가중치를 얼마나 쓸지 정하는 0과 1 사이 숫자예요."},{"sym":"1-\\beta_\\ell","say":"반대로 아무것도 안 하는 쪽을 얼마나 쓸지예요. 깊은 층일수록 커요."}],"whole":"가중치를 통째로 쓰지 않고 **단위행렬(Identity Matrix)** 을 섞어서 층을 얌전하게 만들어요."}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"GCNII introduces initial residual connections and identity mapping to preserve original features and enable deeper, more stable GCN training.","ko":"GCNII 는 초기 잔차 연결과 항등 사상을 도입해 원래 특징을 보존하고, 더 깊고 안정적인 GCN 학습을 가능하게 한다.","tip":"2025 가을 중간 8번 a 의 모범 답안 그대로예요. 두 이름을 영어로 정확히 쓰는 것이 점수예요."},{"kind":"warn","head":"이름을 헷갈리지 마세요","items":["**초기 잔차 연결(Initial Residual Connection)** 은 $H^{(0)}$ 을 더하고, 보통 잔차는 $H^{(k-1)}$ 을 더해요.","**항등 사상(Identity Mapping)** 은 가중치를 단위행렬로 바꾸는 것이 아니라 섞는 것이에요.","**지씨엔 투(GCNII)** 의 II 는 숫자 2가 아니라 Initial 과 Identity 의 머리글자 I 두 개예요."]},{"kind":"check","q":"**지씨엔 투(GCNII)** 가 깊이 한계를 풀려고 넣은 두 가지는 무엇인가요?","choices":["드롭아웃과 배치 정규화","**초기 잔차 연결(Initial Residual Connection)** 과 **항등 사상(Identity Mapping)**","어텐션과 게이트","샘플링과 군집화"],"a":1,"why":"2025 가을 중간 8번 a 문항이 정확히 이것을 물어요. 영어로 initial residual connection 과 identity mapping 이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4865,0.0757],"c":[0,0.0019,0.5351,0.1077],"r":8.8328,"img":"img/L5/walk/p047_h.jpg"},"parts":[{"b":[0.02,0.14,0.62,0.06],"c":[0,0.1011,0.682,0.1378],"r":8.7986,"img":"img/L5/walk/p047_20_01.jpg","say":"첫 줄은 아이디어예요. 과평활화를 풀려고 두 가지 핵심 변경을 넣는다고 적혀 있어요."},{"b":[0.06,0.22,0.88,0.1],"c":[0.016,0.1722,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p047_20_02.jpg","say":"빨간 글씨 첫 항목이 **초기 잔차 연결(Initial Residual Connection)** 이에요. 입력 층에서 모든 층으로 스킵 연결을 더해요."},{"b":[0.06,0.37,0.88,0.08],"c":[0.016,0.3122,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p047_20_03.jpg","say":"빨간 글씨 둘째 항목이 **항등 사상(Identity Mapping)** 이에요. 가중치 행렬에 단위행렬을 더해요."},{"b":[0.02,0.93,0.56,0.05],"c":[0,0.8755,0.616,0.1245],"r":8.7961,"img":"img/L5/walk/p047_20_04.jpg","say":"맨 아래는 출처예요. Chen 외, Simple and Deep Graph Convolutional Networks, ICML 2020 이에요."}]}},{"p":48,"title":"GCNII 층 식 전체와 기호 다섯 개","terms":["GCNII","Initial Residual Connection","Identity Mapping","Identity Matrix","GCN"],"pass1":[{"kind":"say","lines":["**GCNII** 의 식을 괄호까지 모두 펼쳐서 보여 주는 슬라이드예요.","괄호가 두 쌍이고 각각 안에 두 덩이가 들어 있어요.","앞 괄호가 **초기 잔차**, 뒤 괄호가 **항등 사상** 이에요. 이 둘만 알면 식이 읽혀요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"formula","head":"GCNII 층 식","tex":"H^{(\\ell+1)} = \\sigma\\!\\left(\\Big((1-\\alpha_\\ell)\\tilde P H^{(\\ell)} + \\alpha_\\ell H^{(0)}\\Big)\\Big((1-\\beta_\\ell) I_n + \\beta_\\ell W^{(\\ell)}\\Big)\\right)","parts":[{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"}],"whole":"**앞 괄호가 초기 잔차**, **뒤 괄호가 항등 사상** 이에요. 두 괄호를 곱해서 활성화 함수에 넣어요."},{"kind":"points","head":"괄호 두 쌍을 따로 읽어요","items":["앞 괄호는 **이웃 평균 값** 과 **처음 입력** 을 $\\alpha$ 비율로 섞어요","$\\alpha = 0$ 이면 처음 입력을 아예 안 쓰는 보통 GCN 이 돼요","뒤 괄호는 **항등 행렬** 과 **가중치 행렬** 을 $\\beta$ 비율로 섞어요","$\\beta = 0$ 이면 가중치를 안 쓰고 값을 그대로 통과시켜요"]},{"kind":"compare","head":"$\\alpha$ 와 $\\beta$ 를 양 끝으로 밀면","cols":["값","앞 괄호가 되는 것","뒤 괄호가 되는 것"],"rows":[["0","보통 GCN 의 이웃 평균","항등 행렬만, 즉 그대로 통과"],["1","처음 입력만","가중치 행렬만, 즉 보통 GCN"]]},{"kind":"figure","head":"두 장치가 각각 막는 것","svg":"<svg viewBox=\"0 0 480 230\">\n <text class=\"tb\" x=\"240\" y=\"22\" text-anchor=\"middle\" font-size=\"16\">GCNII 의 두 장치가 막는 것<\/text>\n <rect class=\"box2 b1\" x=\"24\" y=\"44\" width=\"200\" height=\"62\" rx=\"6\"/>\n <text class=\"tl b1\" x=\"124\" y=\"68\" text-anchor=\"middle\" font-size=\"14\">초기 잔차 연결<\/text>\n <text class=\"t b1\" x=\"124\" y=\"90\" text-anchor=\"middle\" font-size=\"13\">처음 입력까지 늘 이어진 지름길<\/text>\n <rect class=\"box2 b2\" x=\"256\" y=\"44\" width=\"200\" height=\"62\" rx=\"6\"/>\n <text class=\"tl b2\" x=\"356\" y=\"68\" text-anchor=\"middle\" font-size=\"14\">항등 사상<\/text>\n <text class=\"t b2\" x=\"356\" y=\"90\" text-anchor=\"middle\" font-size=\"13\">가중치에 항등 행렬을 섞기<\/text>\n <line class=\"arrow b3\" x1=\"124\" y1=\"108\" x2=\"124\" y2=\"140\"/>\n <line class=\"arrow b3\" x1=\"356\" y1=\"108\" x2=\"356\" y2=\"140\"/>\n <rect class=\"box b3\" x=\"24\" y=\"142\" width=\"200\" height=\"56\" rx=\"6\"/>\n <text class=\"t b3\" x=\"124\" y=\"165\" text-anchor=\"middle\" font-size=\"13\">정상 벡터로 무너지는 것을<\/text>\n <text class=\"t b3\" x=\"124\" y=\"185\" text-anchor=\"middle\" font-size=\"13\">막아요<\/text>\n <rect class=\"box b3\" x=\"256\" y=\"142\" width=\"200\" height=\"56\" rx=\"6\"/>\n <text class=\"t b3\" x=\"356\" y=\"165\" text-anchor=\"middle\" font-size=\"13\">깊은 모델이 얕은 모델보다<\/text>\n <text class=\"t b3\" x=\"356\" y=\"185\" text-anchor=\"middle\" font-size=\"13\">못하지 않게 해요<\/text>\n <text class=\"t\" x=\"240\" y=\"220\" text-anchor=\"middle\" font-size=\"13\">왼쪽은 과평활, 오른쪽은 성능 퇴화를 맡습니다<\/text>\n<\/svg>","caption":"초기 잔차는 과평활을, 항등 사상은 성능 퇴화를 맡아요.","builds":3}],"pass3":[{"kind":"warn","head":"식을 쓸 때 가장 흔한 실수","items":["$(1-\\beta_\\ell) I_n$ 앞의 계수를 빠뜨리는 것이에요. 항등 행렬에도 계수가 붙어 있어요","두 괄호는 **곱하기** 예요. 더하기가 아니에요","$\\alpha$ 와 $\\beta$ 는 층마다 다를 수 있어서 아래첨자 $\\ell$ 이 붙어 있어요"]},{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"GCNII combines an initial residual connection, which mixes the input representation into every layer, with an identity mapping that adds the identity matrix to the weight matrix.","ko":"GCNII 는 입력 표현을 층마다 섞어 넣는 초기 잔차 연결과, 가중치 행렬에 항등 행렬을 더하는 항등 사상을 함께 씁니다.","tip":"두 장치를 which 와 that 절로 각각 설명하는 틀이에요."},{"kind":"check","q":"GCNII 식에서 $\\alpha_\\ell = 0$ 으로 두면 무엇이 되나요?","choices":["JKNet","처음 입력만 쓰는 모델","초기 잔차가 사라진 보통 GCN 쪽","DenseGCN"],"a":2,"why":"앞 괄호가 $\\tilde P H^{(\\ell)}$ 만 남아요. 처음 입력을 안 섞게 되니 초기 잔차가 꺼진 셈이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.7897,0.2886],"c":[0,0.0019,0.8687,0.3206],"r":4.8171,"img":"img/L5/walk/p048_h.jpg"},"parts":[{"b":[0.2,0.31,0.57,0.08],"c":[0.1715,0.2867,0.627,0.1267],"r":8.7977,"img":"img/L5/walk/p048_11_01.jpg","say":"가운데 긴 식이 GCNII 한 층이에요. 괄호 두 쌍이 나란히 곱해져 있어요."},{"b":[0.06,0.46,0.55,0.06],"c":[0.0325,0.4289,0.605,0.1222],"r":8.8016,"img":"img/L5/walk/p048_11_02.jpg","say":"아래 목록의 첫 줄은 평소대로 매끄럽게 만든 그래프 표현이에요."},{"b":[0.06,0.54,0.55,0.06],"c":[0.0325,0.5089,0.605,0.1222],"r":8.8016,"img":"img/L5/walk/p048_11_03.jpg","say":"둘째 줄이 처음 노드 특징이에요. 첫 MLP 층의 출력이라고 적혀 있어요."}]}},{"p":49,"title":"식 세 줄 비교: 기본 GCN, 초기 잔차, GCNII","terms":["GCNII","Initial Residual Connection","Identity Mapping","GCN","ReLU","Adjacency Matrix","Degree","Identity Matrix"],"pass1":[{"kind":"warn","head":"이 쪽은 시험에 나옵니다","items":["교수님이 시험을 5주차에서 낸다고 했고 이 슬라이드를 짚었어요. 이 쪽은 확정이에요.","슬라이드에서 파란 네모로 묶은 $H^{(0)}$ 과 빨간 네모로 묶은 $I_n$ 이 바로 그 두 조각이에요.","세 식 중 맨 아래 GCNII 식을 외우고, 작은 그래프로 층 하나를 손으로 굴려 보세요."]},{"kind":"say","lines":["같은 그래프에 식 세 줄을 나란히 적어 놓은 슬라이드예요.","위에서 아래로 내려가면서 항이 하나씩 붙어요.","둘째 줄에서 원본 항이 붙고, 셋째 줄에서 단위행렬 항이 붙어요.","세 식은 따로가 아니라 한 식의 특수한 경우예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"식 안에서 새로 붙은 항만 콕 집어요","boxes":[{"x":0.6,"y":0.44,"w":0.09,"h":0.07,"say":"둘째 식의 파란 네모가 $H^{(0)}$ 이에요. 맨 처음 입력 특징이고, 층이 깊어져도 늘 같은 값이에요.","c":[0.545,0.42,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p049_20_01.jpg"},{"x":0.67,"y":0.71,"w":0.05,"h":0.06,"say":"셋째 식의 빨간 네모가 **단위행렬(Identity Matrix)** 이에요. 이것이 **항등 사상(Identity Mapping)** 이에요.","c":[0.595,0.685,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p049_20_02.jpg"},{"x":0.24,"y":0.43,"w":0.34,"h":0.09,"say":"그 앞의 $(1-\\alpha_\\ell)$ 이 이웃에서 온 값을 얼마나 쓸지 정해요.","c":[0.223,0.414,0.374,0.122],"r":5.4499,"img":"img/L5/walk/p049_20_03.jpg"}]},{"kind":"formula","head":"시험 확정: 이 GCNII 식이 그대로 나와요","tex":"H^{(k)} = \\sigma\\left[\\left((1-\\beta)I_n\\right)\\cdot\\left((1-\\alpha)\\tilde{A}H^{(k-1)} + \\alpha H^{(0)}\\right)\\right]","parts":[{"sym":"\\tilde{A}","say":"행 정규화 **인접행렬(Adjacency Matrix)**, 즉 $D^{-1}A$ 예요."},{"sym":"\\alpha","say":"원본을 얼마나 섞을지예요. 시험에서는 0.5 로 줘요."},{"sym":"H^{(0)}","say":"맨 처음 입력이에요. $k=3$ 을 구할 때도 언제나 이 값이에요."},{"sym":"(1-\\beta)I_n","say":"**항등 사상(Identity Mapping)** 자리예요. $\\beta=0.5$ 면 전체에 0.5 를 곱해요."},{"sym":"\\sigma","say":"**렐루(ReLU)** 예요. 맨 마지막에 딱 한 번 씌워요."}],"whole":"이웃 값과 원본을 섞고, 그 결과에 $(1-\\beta)$ 를 곱한 뒤, 음수를 잘라 내요."},{"kind":"steps","head":"작은 그래프로 층 1의 값을 구해요","steps":["$\\tilde{A}H^{(0)}$ 을 먼저 구해요. 노드 1은 $\\tfrac12(-4)+\\tfrac12(4)=0$ 이에요.","노드 2는 $\\tfrac12(-2)+\\tfrac12(4)=1$, 노드 3은 $\\tfrac13(-2-4+6)=0$, 노드 4는 $1\\times4=4$ 예요.","괄호 안을 섞어요. $0.5\\times[0,1,0,4] + 0.5\\times[-2,-4,4,6] = [-1,\\ -1.5,\\ 2,\\ 5]$ 예요.","$(1-\\beta)I_n$ 을 곱해요. 전체에 0.5 를 곱해서 $[-0.5,\\ -0.75,\\ 1,\\ 2.5]$ 가 돼요.","마지막에 **렐루(ReLU)** 를 씌워 음수를 0으로 바꿔요."],"answer":"$H^{(1)} = [0,\\ 0,\\ 1,\\ 2.5]$ 예요.","given":"엣지는 1과 2, 1과 3, 2과 3, 3과 4 이고 $H^{(0)} = [-2, -4, 4, 6]$, $\\alpha = \\beta = 0.5$ 예요."},{"kind":"figure","head":"세 식을 같은 숫자로 비교","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"17\" text-anchor=\"middle\">같은 입력에 세 식을 돌린 결과<\/text>\n<text class=\"tm\" x=\"52\" y=\"58\" font-size=\"14\" text-anchor=\"middle\">노드<\/text>\n<text class=\"tm\" x=\"160\" y=\"58\" font-size=\"14\" text-anchor=\"middle\">기본 GCN<\/text>\n<text class=\"tm b1\" x=\"286\" y=\"58\" font-size=\"14\" text-anchor=\"middle\">초기 잔차<\/text>\n<text class=\"tm b2\" x=\"410\" y=\"58\" font-size=\"14\" text-anchor=\"middle\">GCNII<\/text>\n<text class=\"t\" x=\"52\" y=\"92\" font-size=\"15\" text-anchor=\"middle\">1<\/text>\n<text class=\"t\" x=\"52\" y=\"126\" font-size=\"15\" text-anchor=\"middle\">2<\/text>\n<text class=\"t\" x=\"52\" y=\"160\" font-size=\"15\" text-anchor=\"middle\">3<\/text>\n<text class=\"t\" x=\"52\" y=\"194\" font-size=\"15\" text-anchor=\"middle\">4<\/text>\n<rect class=\"box\" x=\"108\" y=\"74\" width=\"104\" height=\"26\" rx=\"5\"/>\n<text class=\"t\" x=\"160\" y=\"93\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<rect class=\"box\" x=\"108\" y=\"108\" width=\"104\" height=\"26\" rx=\"5\"/>\n<text class=\"t\" x=\"160\" y=\"127\" font-size=\"15\" text-anchor=\"middle\">1<\/text>\n<rect class=\"hl\" x=\"108\" y=\"142\" width=\"104\" height=\"26\" rx=\"5\"/>\n<text class=\"tb\" x=\"160\" y=\"161\" font-size=\"15\" text-anchor=\"middle\">0 정보 사라짐<\/text>\n<rect class=\"box\" x=\"108\" y=\"176\" width=\"104\" height=\"26\" rx=\"5\"/>\n<text class=\"t\" x=\"160\" y=\"195\" font-size=\"15\" text-anchor=\"middle\">4<\/text>\n<rect class=\"box2 b1\" x=\"234\" y=\"74\" width=\"104\" height=\"26\" rx=\"5\"/>\n<text class=\"t b1\" x=\"286\" y=\"93\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<rect class=\"box2 b1\" x=\"234\" y=\"108\" width=\"104\" height=\"26\" rx=\"5\"/>\n<text class=\"t b1\" x=\"286\" y=\"127\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<rect class=\"box2 b1\" x=\"234\" y=\"142\" width=\"104\" height=\"26\" rx=\"5\"/>\n<text class=\"tb b1\" x=\"286\" y=\"161\" font-size=\"15\" text-anchor=\"middle\">2 원본 살아남<\/text>\n<rect class=\"box2 b1\" x=\"234\" y=\"176\" width=\"104\" height=\"26\" rx=\"5\"/>\n<text class=\"t b1\" x=\"286\" y=\"195\" font-size=\"15\" text-anchor=\"middle\">5<\/text>\n<rect class=\"box b2\" x=\"360\" y=\"74\" width=\"100\" height=\"26\" rx=\"5\"/>\n<text class=\"t b2\" x=\"410\" y=\"93\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<rect class=\"box b2\" x=\"360\" y=\"108\" width=\"100\" height=\"26\" rx=\"5\"/>\n<text class=\"t b2\" x=\"410\" y=\"127\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<rect class=\"box b2\" x=\"360\" y=\"142\" width=\"100\" height=\"26\" rx=\"5\"/>\n<text class=\"t b2\" x=\"410\" y=\"161\" font-size=\"15\" text-anchor=\"middle\">1<\/text>\n<rect class=\"box b2\" x=\"360\" y=\"176\" width=\"100\" height=\"26\" rx=\"5\"/>\n<text class=\"t b2\" x=\"410\" y=\"195\" font-size=\"15\" text-anchor=\"middle\">2.5<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"230\" font-size=\"16\" text-anchor=\"middle\">GCNII 는 가운데 열의 정확히 절반이에요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"254\" font-size=\"14\" text-anchor=\"middle\">항등 사상의 1 빼기 베타, 즉 0.5 를 곱했기 때문이에요<\/text>\n<\/svg>","caption":"초기 잔차가 노드 3의 사라진 정보를 되살려요.","builds":3}],"pass3":[{"kind":"exam","src":"2025 가을 중간 8번 (GCNII, 10점)","q":"a) (2p) What are the two major components introduced in GCNII to overcome the depth limitation problem in GCNs?","qko":"b 는 4점으로 $\\tilde{A}$ 를, c 는 4점으로 층 1의 출력을 구해요. 식은 $H^{(k)} = \\sigma[((1-\\beta)I_n)\\cdot((1-\\alpha)\\tilde{A}H^{(k-1)} + \\alpha H^{(0)})]$ 이고 $\\alpha = \\beta = 0.5$ 예요.","solve":["a 는 두 이름을 영어로 씁니다. initial residual connection 과 identity mapping 이에요.","b 는 주어진 $A$ 의 각 행을 그 행의 **차수(Degree)** 로 나눠요. 행의 합이 1인지 검산해요.","c 는 먼저 $\\tilde{A}H^{(0)}$ 을 구해요.","다음으로 $0.5\\tilde{A}H^{(0)} + 0.5H^{(0)}$ 을 구해요.","여기에 $(1-\\beta) = 0.5$ 를 한 번 더 곱해요. 이 단계를 가장 많이 빠뜨려요.","마지막에 **렐루(ReLU)** 로 음수를 0으로 바꿔요."],"answer":"a 는 initial residual connection, identity mapping. b 와 c 는 위 네 단계를 그대로 따르면 돼요."},{"kind":"warn","head":"계산에서 가장 많이 틀리는 곳","items":["$(1-\\beta)I_n$ 은 단위행렬이라 그냥 넘어가면 안 돼요. 앞에 붙은 0.5 가 살아 있어요.","2025 가을 중간 해설지의 GCNII 답안은 이 0.5 를 곱하지 않은 값을 적어 두었어요. 식대로면 그 절반이 맞아요.","$\\alpha H^{(0)}$ 의 $H^{(0)}$ 은 언제나 맨 처음 입력이에요. 앞 층 값이 아니에요.","**렐루(ReLU)** 는 맨 마지막에 한 번만 씌워요."]},{"kind":"check","q":"**지씨엔 투(GCNII)** 식에서 $\\alpha H^{(0)}$ 의 $H^{(0)}$ 은 무엇인가요?","choices":["바로 앞 층의 출력","맨 처음 입력 특징","마지막 층의 출력","가중치 행렬"],"a":1,"why":"**초기 잔차 연결(Initial Residual Connection)** 이라는 이름이 여기서 나와요. 언제나 0층 값이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4865,0.0757],"c":[0,0.0019,0.5351,0.1077],"r":8.8328,"img":"img/L5/walk/p049_h.jpg"},"parts":[{"b":[0.04,0.14,0.18,0.07],"c":[0.028,0.12,0.204,0.11],"r":3.297,"img":"img/L5/walk/p049_12_01.jpg","say":"첫 줄은 기본 GCN 이에요. 우리가 p.46 에서 본 그 식이에요."},{"b":[0.04,0.35,0.34,0.07],"c":[0.023,0.33,0.374,0.11],"r":6.0444,"img":"img/L5/walk/p049_12_02.jpg","say":"둘째 줄은 GCN 에 **초기 잔차 연결(Initial Residual Connection)** 을 더한 것이에요."},{"b":[0.04,0.61,0.46,0.08],"c":[0.017,0.594,0.506,0.112],"r":8.0317,"img":"img/L5/walk/p049_12_03.jpg","say":"셋째 줄이 **지씨엔 투(GCNII)** 예요. 여기에 **항등 사상(Identity Mapping)** 까지 더했어요."}]}},{"p":50,"title":"GCNII 가 과평활을 막는 두 가지 이유","terms":["GCNII","Initial Residual Connection","Identity Mapping","Over-smoothing","Stationary Distribution"],"pass1":[{"kind":"say","lines":["앞 장의 두 장치가 **왜** 듣는지를 말로 풀어 주는 슬라이드예요.","번호 1번이 초기 잔차 연결, 2번이 항등 사상이에요.","각각 **이론** 과 **효과** 로 나뉘어 있어요. 이 네 칸이 서술형 답안 그대로예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"1번 안의 이론과 효과","boxes":[{"x":0.1,"y":0.21,"w":0.86,"h":0.06,"say":"이론 부분이에요. 바로 앞 층만 날라 주는 보통 잔차 연결과 달리, 처음 입력까지 늘 이어지는 지름길을 유지한대요.","c":[0.054,0.1444,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p050_20_01.jpg"},{"x":0.1,"y":0.28,"w":0.86,"h":0.1,"say":"효과 부분이에요. 깊이가 무한으로 가도 최종 분포가 원래 입력 정보를 품고 있게 해서, 그래프의 **정상 벡터** 로 무너지는 것을 막는대요.","c":[0.054,0.2344,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p050_20_02.jpg"}]},{"kind":"look","head":"2번 안의 이론과 효과","boxes":[{"x":0.1,"y":0.56,"w":0.86,"h":0.07,"say":"이론 부분이에요. 가중치 행렬에 항등 행렬을 더해요. 층이 쌓일수록 규제 없는 가중치를 거듭 곱하면 특징 분포가 망가지거든요.","c":[0.054,0.4994,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p050_21_01.jpg"},{"x":0.1,"y":0.63,"w":0.86,"h":0.08,"say":"효과 부분이에요. 깊은 모델이 적어도 얕은 모델만큼은 하도록 보장해요. 그리고 $\\beta$ 가 층이 깊어질수록 줄어든다고 적혀 있어요.","c":[0.054,0.5744,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p050_21_02.jpg"}]},{"kind":"formula","head":"층마다 줄어드는 베타","tex":"\\beta_\\ell \\approx \\ln\\!\\left(\\frac{\\lambda}{\\ell} + 1\\right)","parts":[{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"}],"whole":"층이 깊어질수록 $\\ell$ 이 커져서 $\\lambda/\\ell$ 이 작아지고, 따라서 $\\beta_\\ell$ 도 0 에 가까워져요. **깊은 층일수록 가중치를 덜 쓰고 값을 그대로 통과시킨다**는 뜻이에요."},{"kind":"steps","head":"$\\lambda = 0.5$ 일 때 층마다 베타 구하기","steps":["1층이면 $0.5/1 + 1 = 1.5$ 이고 자연로그를 씌우면 약 0.405 예요.","2층이면 $0.5/2 + 1 = 1.25$ 이고 로그를 씌우면 약 0.223 이에요.","8층이면 $0.5/8 + 1 = 1.0625$ 이고 로그를 씌우면 약 0.061 이에요.","32층이면 $0.5/32 + 1 = 1.015625$ 이고 로그를 씌우면 약 0.0155 예요."],"answer":"0.405 에서 0.0155 까지 줄어요. 깊은 층은 가중치를 거의 안 쓰고 값을 그냥 흘려보내요.","given":"$\\beta_\\ell = \\ln(\\lambda/\\ell + 1)$ 이고 $\\lambda = 0.5$ 예요."},{"kind":"points","head":"두 이유를 한 줄씩","items":["초기 잔차는 **입력 정보가 끝까지 남게** 해서 정상 벡터로 무너지는 것을 막아요","항등 사상은 **가중치를 거듭 곱하는 해악** 을 줄여서 성능 퇴화를 막아요","**정상 분포(Stationary Distribution)** 는 랜덤워크를 아주 오래 돌렸을 때의 머무를 확률이에요. 거기로 빨려 들어가면 노드 구별이 사라져요","두 장치는 **고치는 병이 달라요.** 하나는 과평활, 하나는 성능 퇴화예요"]}],"pass3":[{"kind":"warn","head":"계산할 때 주의할 점","items":["$\\beta_\\ell$ 식의 로그는 **자연로그** 예요. 상용로그가 아니에요","$\\ell$ 은 1 부터 세요. 0 을 넣으면 분모가 0 이 돼요","서술형에서 두 장치의 효과를 **바꿔 쓰면 틀려요.** 초기 잔차가 과평활, 항등 사상이 퇴화예요"]},{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"The initial residual connection keeps a path to the input representation at every depth, so the output cannot collapse onto the stationary vector of the graph, while the identity mapping guarantees that a deep model performs at least as well as a shallow one.","ko":"초기 잔차 연결은 어느 깊이에서도 입력 표현으로 가는 길을 남겨 두어 출력이 그래프의 정상 벡터로 무너지지 못하게 하고, 항등 사상은 깊은 모델이 적어도 얕은 모델만큼은 하도록 보장해요.","tip":"while 로 두 장치를 한 문장에 묶는 틀이에요."},{"kind":"check","q":"$\\beta_\\ell$ 이 층이 깊어질수록 작아진다는 것은 무엇을 뜻하나요?","choices":["깊은 층일수록 가중치를 더 많이 쓴다","깊은 층일수록 가중치를 덜 쓰고 값을 그대로 통과시킨다","깊은 층일수록 학습률이 커진다","깊은 층일수록 이웃을 더 많이 본다"],"a":1,"why":"뒤 괄호는 $(1-\\beta)I_n + \\beta W$ 예요. $\\beta$ 가 0 에 가까우면 거의 항등 행렬만 남아서 값이 그대로 지나가요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4865,0.0757],"c":[0,0.0019,0.5351,0.1077],"r":8.8328,"img":"img/L5/walk/p050_h.jpg"},"parts":[{"b":[0.02,0.15,0.28,0.05],"c":[0.006,0.12,0.308,0.11],"r":4.9778,"img":"img/L5/walk/p050_11_01.jpg","say":"맨 위 굵은 줄이 **GCNII 가 과도한 평활화를 막는 이유** 예요."},{"b":[0.06,0.21,0.3,0.05],"c":[0.045,0.18,0.33,0.11],"r":5.3333,"img":"img/L5/walk/p050_11_02.jpg","say":"1번이 **초기 잔차 연결** 이에요."},{"b":[0.06,0.56,0.3,0.05],"c":[0.045,0.53,0.33,0.11],"r":5.3333,"img":"img/L5/walk/p050_11_03.jpg","say":"2번이 **항등 사상** 이에요."}]}},{"p":51,"title":"제거 실험: 두 장치를 하나씩 빼 보면","terms":["GCNII","Initial Residual Connection","Identity Mapping","Over-smoothing","GCN"],"pass1":[{"kind":"say","lines":["**제거 실험(ablation)** 은 장치를 하나씩 빼 보면서 각각이 얼마나 기여하는지 재는 실험이에요.","그래프가 세 개예요. Cora, Citeseer, Pubmed 라는 세 데이터셋이에요.","선이 네 개인데 **빨간 삼각형이 GCNII**, 파란 동그라미가 보통 GCN 이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"세 그래프에서 같은 모양을 찾아요","boxes":[{"x":0.08,"y":0.35,"w":0.27,"h":0.3,"say":"Cora 예요. 파란 GCN 선이 8층부터 뚝 떨어져서 64층에서는 0.15 근처까지 내려가요.","c":[0.0665,0.334,0.297,0.332],"r":1.5904,"img":"img/L5/walk/p051_20_01.jpg"},{"x":0.36,"y":0.35,"w":0.27,"h":0.3,"say":"Citeseer 예요. 역시 파란 선이 가파르게 떨어져요.","c":[0.3465,0.334,0.297,0.332],"r":1.5904,"img":"img/L5/walk/p051_20_02.jpg"},{"x":0.64,"y":0.35,"w":0.27,"h":0.3,"say":"Pubmed 예요. 모양이 똑같아요. 세 데이터에서 같은 결과라서 믿을 만해요.","c":[0.6265,0.334,0.297,0.332],"r":1.5904,"img":"img/L5/walk/p051_20_03.jpg"}]},{"kind":"compare","head":"네 선을 64층에서 비교하면","cols":["선","무엇을 켰나","64층에서"],"rows":[["파란 동그라미","아무것도 안 켬 (보통 GCN)","완전히 무너져요"],["초록 네모","항등 사상만","많이 떨어져요"],["주황 십자","초기 잔차만","거의 안 떨어져요"],["빨간 삼각형","둘 다 (GCNII)","오히려 조금 올라가요"]]},{"kind":"points","head":"이 그림에서 읽어 낼 것 네 가지","items":["**초기 잔차가 더 중요해요.** 주황 선이 초록 선보다 훨씬 덜 떨어져요","**항등 사상 혼자로는 부족해요.** 초록 선도 결국 내려가요","**둘을 같이 쓰면 64층까지 올라가요.** 빨간 선만 오른쪽 끝에서 가장 높아요","세 데이터에서 **같은 모양** 이 나와요. 우연이 아니라는 증거예요"]},{"kind":"analogy","head":"우산과 장화","scene":"비 오는 날 밖에 나가요. 우산만 들면 머리는 안 젖지만 발이 젖어요. 장화만 신으면 발은 괜찮지만 머리가 젖어요. 둘 다 하면 거의 안 젖어요. 그런데 비가 세게 올 때는 우산이 장화보다 훨씬 중요해요.","map":[["우산","**초기 잔차 연결(Initial Residual Connection)**"],["장화","**항등 사상(Identity Mapping)**"],["비가 세게 오는 것","층을 64개까지 깊게 쌓는 것"]]}],"pass3":[{"kind":"check","q":"제거 실험에서 **혼자 썼을 때 더 효과가 큰** 장치는 어느 것인가요?","choices":["항등 사상","초기 잔차 연결","둘이 같다","둘 다 효과 없다"],"a":1,"why":"주황 선(초기 잔차만)이 초록 선(항등 사상만)보다 64층에서 훨씬 덜 떨어져요."},{"kind":"warn","head":"그래프를 읽을 때 주의할 점","items":["가로축이 $2^1$ 부터 $2^6$ 이에요. **두 배씩** 늘어나는 눈금이라 오른쪽 끝이 64층이에요","GCNII 가 깊어져도 **조금 올라가는** 것이 중요해요. 보통은 깊으면 내려가는데 반대예요","제거 실험은 **각 장치의 기여를 재는** 것이지 최고 성능을 보이려는 것이 아니에요"]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4865,0.0757],"c":[0,0.0019,0.5351,0.1077],"r":8.8328,"img":"img/L5/walk/p051_h.jpg"},"parts":[{"b":[0.07,0.36,0.05,0.14],"c":[0,0.344,0.2,0.172],"r":2.0672,"img":"img/L5/walk/p051_11_01.jpg","say":"세로축이 **정확도(Accuracy)** 예요. 높을수록 좋아요."},{"b":[0.17,0.66,0.12,0.04],"c":[0.13,0.625,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p051_11_02.jpg","say":"가로축이 **층 수(Layers)** 예요. 2, 4, 8, 16, 32, 64 로 두 배씩 늘어나요."},{"b":[0.1,0.54,0.14,0.09],"c":[0.07,0.524,0.2,0.122],"r":2.9144,"img":"img/L5/walk/p051_11_03.jpg","say":"왼쪽 아래 범례에 선 네 개의 이름이 있어요. GCN, 초기 잔차만, 항등 사상만, GCNII 예요."}]}},{"p":52,"title":"GCNII 예제 코드: GCN2Conv","terms":["GCNII","Initial Residual Connection","Identity Mapping","Dropout","ReLU"],"pass1":[{"kind":"say","lines":["**지씨엔 투(GCNII)** 층은 PyTorch Geometric 에 이미 들어 있어요.","이름이 GCN2Conv 예요. 2가 바로 II 예요.","식을 직접 짜 넣을 필요 없이 숫자 몇 개만 넘겨 주면 돼요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"코드 상자를 네 덩어리로","boxes":[{"x":0.22,"y":0.24,"w":0.6,"h":0.13,"say":"맨 위는 클래스 이름과 준비 함수의 인자들이에요. 은닉 차원 16, 층 2개가 기본값이에요.","c":[0.19,0.224,0.66,0.162],"r":7.2428,"img":"img/L5/walk/p052_20_01.jpg"},{"x":0.24,"y":0.29,"w":0.3,"h":0.09,"say":"선형층 두 개를 만들어요. 하나는 입구, 하나는 출구예요.","c":[0.225,0.274,0.33,0.122],"r":4.8087,"img":"img/L5/walk/p052_20_02.jpg"},{"x":0.24,"y":0.41,"w":0.44,"h":0.1,"say":"여기서 층 수만큼 GCN2Conv 를 만들어 리스트에 담아요.","c":[0.218,0.394,0.484,0.132],"r":6.5185,"img":"img/L5/walk/p052_20_03.jpg"},{"x":0.24,"y":0.71,"w":0.3,"h":0.05,"say":"데이터가 흐를 때 이 한 줄이 원본 x_0 을 층마다 다시 넘겨 줘요.","c":[0.225,0.68,0.33,0.11],"r":5.3333,"img":"img/L5/walk/p052_20_04.jpg"}]},{"kind":"compare","head":"GCN2Conv 에 준 값과 수식의 짝","cols":["코드에 적힌 값","수식의 무엇","뜻"],"rows":[["hidden_channels","차원","속에서 쓸 특징 칸 수, 여기서는 16 이에요"],["0.1","$\\alpha$","**초기 잔차 연결(Initial Residual Connection)** 의 비율이에요"],["0.5","$\\theta$","여기서 층별 $\\beta_\\ell$ 이 계산돼요"],["layer + 1","층 번호 $\\ell$","깊은 층일수록 **항등 사상(Identity Mapping)** 쪽으로 기울어요"]]},{"kind":"points","head":"코드에서 수식이 보이는 자리","items":["`x_0 = x.relu()` 로 만든 `x_0` 이 수식의 $H^{(0)}$ 이에요.","`conv(x, x_0, edge_index)` 처럼 인자가 세 개인 것이 중요해요.","보통 GNN 층은 인자가 두 개인데, 여기는 원본을 매번 같이 넘겨요.","이 한 줄이 **초기 잔차 연결(Initial Residual Connection)** 그 자체예요."]}],"pass3":[{"kind":"warn","head":"코드에서 헷갈리기 쉬운 점","items":["둘째 인자 alpha 와 셋째 인자 theta 를 헷갈리지 마세요. 역할이 달라요.","`self.proj = Linear(1, 64)` 는 만들어만 놓고 쓰이지 않는 줄이에요.","`conv(x, x_0, edge_index)` 의 인자 순서를 바꾸면 완전히 다른 계산이 돼요."]}],"pass4":[{"kind":"code","head":"슬라이드에 인쇄된 코드 전체 (1/2)","file":"L5 슬라이드 p.52","code":"from torch_geometric.nn import GCN2Conv\n\nclass GCNII(torch.nn.Module):\n  def __init__(self, num_features, num_classes, hidden_channels = 16, num_layers =2, shared_weights=True, dropout=0.0):\n    super().__init__()\n    self.lins = torch.nn.ModuleList()\n    self.proj = Linear(1, 64)\n    self.lins1 = Linear(num_features, hidden_channels)\n    self.lins2  = Linear(hidden_channels, num_classes)\n\n    self.convs = torch.nn.ModuleList()\n    for layer in range(num_layers):\n      self.convs.append(\n        GCN2Conv(hidden_channels, 0.1, 0.5, layer + 1, shared_weights, normalize=False))\n    self.h = None\n    self.dropout = dropout\n    self.optimizer = torch.optim.Adam(self.parameters(),lr=0.01,weight_decay=5e-4)\n\n  def forward(self, x, edge_index):\n\n    x = F.dropout(x, self.dropout, training=self.training)\n    x =  self.lins1(x)\n    x = x_0 = x.relu()\n\n    for conv in self.convs:\n      x = F.dropout(x, self.dropout, training=self.training)\n      x = conv(x, x_0, edge_index)\n      x = x.relu()\n    x = F.dropout(x, self.dropout, training=self.training)\n    x = self.lins2(x)\n    self.h =x\n    return x, x.log_softmax(dim=-1)","lines":[{"from":1,"to":1,"say":"torch_geometric.nn 에서 GCN2Conv 를 꺼내 와요. 남이 만든 도구를 가져오는 줄이에요."},{"from":3,"to":4,"say":"클래스와 준비 함수예요. 등호가 붙은 것은 안 줘도 되는 기본값이고, 은닉 16 차원에 층 2개가 기본이에요."},{"from":5,"to":9,"say":"부모 준비 함수를 먼저 돌리고, 빈 리스트와 선형층들을 만들어요. 7번 줄 proj 는 아래에서 한 번도 안 써요."},{"from":11,"to":14,"say":"층 수만큼 GCN2Conv 를 만들어 리스트에 담아요. 0.1 이 $\\alpha$, 0.5 가 $\\theta$ 예요."},{"from":15,"to":17,"say":"은닉 표현을 꺼내 볼 자리와 **드롭아웃(Dropout)** 확률, 그리고 학습률 0.01 짜리 최적화기를 준비해요."}],"link":"11번부터 14번 줄이 p.49 식의 $\\alpha$ 와 $\\beta$ 를 정하는 자리예요."},{"kind":"code","head":"슬라이드에 인쇄된 코드 전체 (2/2)","file":"L5 슬라이드 p.52","code":"from torch_geometric.nn import GCN2Conv\n\nclass GCNII(torch.nn.Module):\n  def __init__(self, num_features, num_classes, hidden_channels = 16, num_layers =2, shared_weights=True, dropout=0.0):\n    super().__init__()\n    self.lins = torch.nn.ModuleList()\n    self.proj = Linear(1, 64)\n    self.lins1 = Linear(num_features, hidden_channels)\n    self.lins2  = Linear(hidden_channels, num_classes)\n\n    self.convs = torch.nn.ModuleList()\n    for layer in range(num_layers):\n      self.convs.append(\n        GCN2Conv(hidden_channels, 0.1, 0.5, layer + 1, shared_weights, normalize=False))\n    self.h = None\n    self.dropout = dropout\n    self.optimizer = torch.optim.Adam(self.parameters(),lr=0.01,weight_decay=5e-4)\n\n  def forward(self, x, edge_index):\n\n    x = F.dropout(x, self.dropout, training=self.training)\n    x =  self.lins1(x)\n    x = x_0 = x.relu()\n\n    for conv in self.convs:\n      x = F.dropout(x, self.dropout, training=self.training)\n      x = conv(x, x_0, edge_index)\n      x = x.relu()\n    x = F.dropout(x, self.dropout, training=self.training)\n    x = self.lins2(x)\n    self.h =x\n    return x, x.log_softmax(dim=-1)","lines":[{"from":19,"to":19,"say":"데이터가 실제로 흐르는 함수예요. x 는 노드 특징, edge_index 는 엣지 목록이에요."},{"from":21,"to":21,"say":"입력에 **드롭아웃(Dropout)** 을 걸어요. 학습 중일 때만 작동해요."},{"from":22,"to":23,"say":"입구 선형층으로 16 차원으로 줄이고 **렐루(ReLU)** 를 씌워요. 그 결과를 x_0 에도 저장해요."},{"from":25,"to":28,"say":"층을 하나씩 돌아요. conv 에 x 와 x_0 을 같이 넘기는 것이 **초기 잔차 연결(Initial Residual Connection)** 이에요."},{"from":29,"to":30,"say":"마지막으로 드롭아웃을 한 번 더 걸고 출구 선형층으로 클래스 수만큼 줄여요."},{"from":31,"to":32,"say":"은닉 표현을 저장하고, 점수와 확률의 로그를 같이 돌려줘요."}],"link":"23번 줄의 x_0 이 수식의 $H^{(0)}$ 이고, 27번 줄이 매 층에서 그것을 다시 섞는 자리예요."},{"kind":"pyterm","name":"클래스(class)와 self","say":["파이썬에서 class 는 설계도예요. 그 설계도로 만든 물건 하나를 객체라고 해요.","self 는 그 물건 자신을 가리켜요. self.conv1 이라고 쓰면 그 물건이 들고 있는 층이에요.","__init__ 은 물건을 만들 때 한 번 실행되는 준비 함수예요."],"example":"class Dog:\n    def __init__(self, name):\n        self.name = name\n\nd = Dog(\"바둑이\")\nprint(d.name)","out":"바둑이"},{"kind":"pyterm","name":"반복문(for)과 리스트","say":["for 는 같은 일을 여러 번 되풀이할 때 써요. range(3) 이면 0, 1, 2 세 번 돌아요.","리스트는 물건을 순서대로 담는 상자예요. append 로 하나씩 넣어요.","슬라이드 코드는 층 수만큼 돌면서 층을 리스트에 담았어요."],"example":"box = []\nfor i in range(3):\n    box.append(i * 2)\nprint(box)","out":"[0, 2, 4]"},{"kind":"warn","head":"5주차 코드에 대한 안내","items":["5주차에는 실습 노트북이 없어요. 여기 코드는 슬라이드에 인쇄된 그대로예요.","그래서 돌려 보려면 GCNConv 예제처럼 데이터셋과 학습 함수를 따로 붙여야 해요.","시험에 코드를 그대로 쓰라는 문제는 없었어요. 식과의 짝만 확실히 알아 두세요."]}],"walk":{"head":{"b":[0.0131,0.0179,0.2189,0.0757],"c":[0.0011,0.0019,0.2429,0.1077],"r":4.0095,"img":"img/L5/walk/p052_h.jpg"},"parts":[{"b":[0.22,0.14,0.6,0.07],"c":[0.19,0.1083,0.66,0.1333],"r":8.8022,"img":"img/L5/walk/p052_11_01.jpg","say":"위 검은 띠가 불러오기 한 줄이에요. torch_geometric.nn 에서 GCN2Conv 를 꺼내 와요."},{"b":[0.22,0.23,0.6,0.67],"c":[0.19,0.1965,0.66,0.737],"r":1.592,"img":"img/L5/walk/p052_11_02.jpg","say":"아래 큰 검은 상자가 모델 클래스 전체예요. 위쪽은 준비, 아래쪽은 데이터가 흐르는 부분이에요."}]}},{"p":53,"title":"JK-Net: 모든 층을 마지막에 모아 골라 쓴다","terms":["JK-Net","Layer Aggregation","Influence Distribution","Receptive Field","Over-smoothing","GCN","GCNII"],"pass1":[{"kind":"say","lines":["다시 모델 구조를 고치는 처방으로 돌아와요.","**제이케이넷(JK-Net)** 은 마지막 층의 결과만 쓰지 않아요.","1층부터 마지막 층까지 모든 중간 표현을 마지막으로 점프시켜요.","그리고 노드마다 알맞은 것을 골라 쓰게 해요."]},{"kind":"analogy","head":"줌을 여러 단계로 찍어 두기","scene":"사진을 찍는데 줌을 얼마나 당길지는 찍을 대상마다 달라요. 가까이 있는 꽃은 조금만 당기면 되고, 멀리 있는 새는 많이 당겨야 해요. 그래서 사진사가 여러 배율로 다 찍어 둬요. 나중에 대상마다 제일 잘 나온 것을 고르면 돼요.","map":[["여러 배율로 다 찍어 두기","층마다의 표현을 전부 들고 있기"],["대상마다 다른 배율","노드마다 다른 **수용 영역(Receptive Field)**"],["제일 잘 나온 것 고르기","**층 집계(Layer Aggregation)**"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"왜 노드마다 다른 깊이가 필요한가요","items":["그래프 한가운데 허브 노드는 2홉만 가도 그래프 절반을 봐요. 금방 뭉개져요.","가장자리 외딴 노드는 5홉을 가야 겨우 쓸 만한 정보를 만나요.","보통 **그래프 합성곱 신경망(GCN)** 은 모든 노드에 같은 깊이를 강요해요.","**제이케이넷(JK-Net)** 은 층별 표현을 다 들고 있다가 노드마다 고르게 해요."]},{"kind":"compare","head":"어디서 가져와 어디로 보내나","cols":["방법","어디서 가져오나","어디로 보내나"],"rows":[["DeepGCN 의 잔차","바로 앞 층","바로 다음 층"],["**지씨엔 투(GCNII)** 의 초기 잔차","0층","모든 층"],["**제이케이넷(JK-Net)** 의 점프","모든 층","마지막 **층 집계(Layer Aggregation)**"]]},{"kind":"figure","head":"층마다의 표현이 마지막으로 점프해요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"22\" font-size=\"17\" text-anchor=\"middle\">모든 층이 마지막 집계로 점프해요<\/text>\n<text class=\"tm\" x=\"300\" y=\"252\" font-size=\"14\" text-anchor=\"middle\">입력 특징<\/text>\n<rect class=\"box\" x=\"238\" y=\"196\" width=\"124\" height=\"28\" rx=\"6\"/>\n<text class=\"t\" x=\"300\" y=\"216\" font-size=\"15\" text-anchor=\"middle\">GNN 층 1<\/text>\n<rect class=\"box\" x=\"238\" y=\"158\" width=\"124\" height=\"28\" rx=\"6\"/>\n<text class=\"t\" x=\"300\" y=\"178\" font-size=\"15\" text-anchor=\"middle\">GNN 층 2<\/text>\n<rect class=\"box\" x=\"238\" y=\"120\" width=\"124\" height=\"28\" rx=\"6\"/>\n<text class=\"t\" x=\"300\" y=\"140\" font-size=\"15\" text-anchor=\"middle\">GNN 층 3<\/text>\n<polygon class=\"arrow\" points=\"294,192 306,192 300,182\"/>\n<polygon class=\"arrow\" points=\"294,154 306,154 300,144\"/>\n<polygon class=\"arrow\" points=\"294,116 306,116 300,106\"/>\n<rect class=\"box2\" x=\"190\" y=\"64\" width=\"220\" height=\"40\" rx=\"8\"/>\n<text class=\"t\" x=\"300\" y=\"82\" font-size=\"15\" text-anchor=\"middle\">층 집계<\/text>\n<text class=\"tm\" x=\"300\" y=\"98\" font-size=\"14\" text-anchor=\"middle\">이어 붙이기 / 최대 풀링 / LSTM<\/text>\n<polygon class=\"arrow\" points=\"294,60 306,60 300,48\"/>\n<text class=\"tb\" x=\"300\" y=\"42\" font-size=\"15\" text-anchor=\"middle\">최종 표현<\/text>\n<polyline class=\"e2 b1\" points=\"236,210 140,210 140,84 186,84\" fill=\"none\"/>\n<polyline class=\"e2 b2\" points=\"236,172 160,172 160,88 186,88\" fill=\"none\"/>\n<polyline class=\"e2 b3\" points=\"236,134 180,134 180,92 186,92\" fill=\"none\"/>\n<text class=\"tb b3\" x=\"80\" y=\"140\" font-size=\"16\" text-anchor=\"middle\">점프<\/text>\n<text class=\"tm b3\" x=\"80\" y=\"164\" font-size=\"14\" text-anchor=\"middle\">연결<\/text>\n<text class=\"tm b3\" x=\"80\" y=\"200\" font-size=\"14\" text-anchor=\"middle\">노드마다<\/text>\n<text class=\"tm b3\" x=\"80\" y=\"220\" font-size=\"14\" text-anchor=\"middle\">따로 골라요<\/text>\n<\/svg>","caption":"층 자체는 평범한 GNN 층이고 합치는 방법만 바꿔요.","builds":3}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"JK networks mitigate over-smoothing by combining representations from multiple layers, allowing each node to adaptively use information from both shallow and deep layers, preserving feature diversity.","ko":"JK 네트워크는 여러 층의 표현을 결합해 각 노드가 얕은 층과 깊은 층의 정보를 적응적으로 쓰게 해서 특징의 다양성을 보존하고 과평활화를 완화한다.","tip":"2025 가을 중간 7번 a 의 모범 답안이에요. 세 표현을 꼭 넣으세요. combining representations, adaptively, feature diversity."},{"kind":"warn","head":"여기서 헷갈리기 쉬워요","items":["**제이케이넷(JK-Net)** 은 층 안을 고치지 않아요. 층은 평범한 GCN 그대로예요.","점프는 잔차 연결과 달라요. 잔차는 다음 층으로, 점프는 마지막 집계로 가요.","노드마다 독립적으로 고른다는 것이 핵심 단어예요. 그래서 적응성이라고 불러요."]},{"kind":"check","q":"**제이케이넷(JK-Net)** 이 고치는 것은 무엇인가요?","choices":["층 안의 계산","층들을 합치는 방법","그래프의 엣지","학습률"],"a":1,"why":"층은 그대로 두고 **층 집계(Layer Aggregation)** 만 바꿔요. 그래서 어느 GNN 층에나 붙일 수 있어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2209,0.1573],"c":[0.0011,0.0019,0.2449,0.1893],"r":2.2999,"img":"img/L5/walk/p053_h.jpg"},"parts":[{"b":[0.07,0.2,0.54,0.09],"c":[0.043,0.184,0.594,0.122],"r":8.6557,"img":"img/L5/walk/p053_20_01.jpg","say":"번호 1은 각 층이 앞 층들의 이웃을 모아 **영향 분포(Influence Distribution)** 를 키운다는 말이에요."},{"b":[0.07,0.36,0.48,0.05],"c":[0.046,0.33,0.528,0.11],"r":8.5333,"img":"img/L5/walk/p053_20_02.jpg","say":"번호 2는 앞 층들의 표현 가운데 일부를 노드마다 따로 합친다는 말이에요."},{"b":[0.04,0.54,0.56,0.09],"c":[0.012,0.5228,0.616,0.1245],"r":8.7961,"img":"img/L5/walk/p053_20_03.jpg","say":"그 아래는 마지막 층에서 중간 표현들이 점프한다는 말이에요."},{"b":[0.68,0.26,0.28,0.08],"c":[0.666,0.244,0.308,0.112],"r":4.8889,"img":"img/L5/walk/p053_20_04.jpg","say":"오른쪽 그림 맨 위 넓적한 상자가 **층 집계(Layer Aggregation)** 예요."},{"b":[0.69,0.36,0.06,0.42],"c":[0.62,0.339,0.2,0.462],"r":0.7696,"img":"img/L5/walk/p053_20_05.jpg","say":"왼쪽 곡선 화살표들이 각 층에서 그 상자로 곧장 올라가요. 이것이 점프예요."}]}},{"p":54,"title":"층 집계 세 가지와 시험에 나오는 최대 풀링","terms":["JK-Net","Layer Aggregation","Concatenation","Max Pooling","LSTM Attention","Adjacency Matrix","Degree","ReLU"],"pass1":[{"kind":"say","lines":["점프해 온 표현들을 합치는 방법이 세 가지예요.","**이어 붙이기(Concatenation)** 는 전부 옆으로 붙여요.","**최대 풀링(Max Pooling)** 은 같은 자리끼리 가장 큰 값만 남겨요.","**엘에스티엠 어텐션(LSTM Attention)** 은 어느 층을 볼지 학습으로 정해요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"compare","head":"세 방법을 한 줄로","cols":["방법","출력 차원","학습 파라미터"],"rows":[["**이어 붙이기(Concatenation)**","층 수만큼 커져요","없어요"],["**최대 풀링(Max Pooling)**","그대로예요","없어요"],["**엘에스티엠 어텐션(LSTM Attention)**","그대로예요","있어요"]]},{"kind":"formula","head":"시험에 나오는 JK 식","tex":"H^{(k)} = \\max\\left(\\sigma(\\tilde{A}H^{(0)}),\\ \\sigma(\\tilde{A}H^{(1)}),\\ \\ldots,\\ \\sigma(\\tilde{A}H^{(k-1)})\\right)","parts":[{"sym":"\\tilde{A}","say":"행 정규화 **인접행렬(Adjacency Matrix)**, 즉 $D^{-1}A$ 예요."},{"sym":"\\sigma","say":"**렐루(ReLU)** 예요. 음수를 0 으로 바꿔요."},{"sym":"H^{(m)}","say":"$m$ 층의 표현 행렬이에요."},{"sym":"\\max(\\cdot)","say":"원소별 최댓값이에요. 같은 자리끼리 비교해요. 행렬 하나를 고르는 게 아니에요."}],"whole":"층마다 이웃 집계와 **렐루(ReLU)** 를 한 뒤, 같은 자리끼리 가장 큰 값을 남겨요."},{"kind":"steps","head":"노드 4개 일렬 그래프로 $k=2$ 를 구해요","steps":["**차수(Degree)** 가 1, 2, 2, 1 이라 $\\tilde{A}$ 의 1행은 2번 자리만 1 이에요.","2행은 1번과 3번 자리가 각각 $1/2$, 3행은 2번과 4번 자리가 각각 $1/2$, 4행은 3번 자리가 1 이에요.","$\\tilde{A}H^{(0)}$ 은 차례로 $(-4,2)$, $(4,-1)$, $(-3,3)$, $(6,-2)$ 예요.","**렐루(ReLU)** 를 씌우면 $H^{(1)}$ 은 $(0,2)$, $(4,0)$, $(0,3)$, $(6,0)$ 이에요.","$\\tilde{A}H^{(1)}$ 에 렐루를 씌우면 $(4,0)$, $(0,2.5)$, $(5,0)$, $(0,3)$ 이에요.","두 결과를 같은 자리끼리 비교해 큰 값을 남겨요."],"answer":"$H^{(2)}$ 는 $(4,2)$, $(4,2.5)$, $(5,3)$, $(6,3)$ 이에요.","given":"엣지는 1과 2, 2와 3, 3과 4 이고 $H^{(0)}$ 은 $(2,0)$, $(-4,2)$, $(6,-2)$, $(-2,4)$ 예요."},{"kind":"figure","head":"원소별 최댓값이 무엇인지","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"17\" text-anchor=\"middle\">칸마다 다른 층에서 값을 가져와요<\/text>\n<text class=\"tm\" x=\"66\" y=\"52\" font-size=\"14\" text-anchor=\"middle\">1층 결과<\/text>\n<rect class=\"box\" x=\"24\" y=\"60\" width=\"84\" height=\"132\" rx=\"6\"/>\n<text class=\"t\" x=\"45\" y=\"84\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<text class=\"tb\" x=\"87\" y=\"84\" font-size=\"15\" text-anchor=\"middle\">2<\/text>\n<text class=\"tb\" x=\"45\" y=\"114\" font-size=\"15\" text-anchor=\"middle\">4<\/text>\n<text class=\"t\" x=\"87\" y=\"114\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<text class=\"t\" x=\"45\" y=\"144\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<text class=\"tb\" x=\"87\" y=\"144\" font-size=\"15\" text-anchor=\"middle\">3<\/text>\n<text class=\"tb\" x=\"45\" y=\"174\" font-size=\"15\" text-anchor=\"middle\">6<\/text>\n<text class=\"t\" x=\"87\" y=\"174\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<text class=\"tm b1\" x=\"198\" y=\"52\" font-size=\"14\" text-anchor=\"middle\">2층 결과<\/text>\n<rect class=\"box b1\" x=\"156\" y=\"60\" width=\"84\" height=\"132\" rx=\"6\"/>\n<text class=\"tb b1\" x=\"177\" y=\"84\" font-size=\"15\" text-anchor=\"middle\">4<\/text>\n<text class=\"t b1\" x=\"219\" y=\"84\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<text class=\"t b1\" x=\"177\" y=\"114\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<text class=\"tb b1\" x=\"219\" y=\"114\" font-size=\"15\" text-anchor=\"middle\">2.5<\/text>\n<text class=\"tb b1\" x=\"177\" y=\"144\" font-size=\"15\" text-anchor=\"middle\">5<\/text>\n<text class=\"t b1\" x=\"219\" y=\"144\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<text class=\"t b1\" x=\"177\" y=\"174\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<text class=\"tb b1\" x=\"219\" y=\"174\" font-size=\"15\" text-anchor=\"middle\">3<\/text>\n<polygon class=\"arrow b2\" points=\"252,118 272,126 252,134\"/>\n<text class=\"tm b2\" x=\"262\" y=\"110\" font-size=\"14\" text-anchor=\"middle\">최댓값<\/text>\n<text class=\"tm b2\" x=\"340\" y=\"52\" font-size=\"14\" text-anchor=\"middle\">원소별 최댓값<\/text>\n<rect class=\"box2 b2\" x=\"298\" y=\"60\" width=\"84\" height=\"132\" rx=\"6\"/>\n<text class=\"t b2\" x=\"319\" y=\"84\" font-size=\"15\" text-anchor=\"middle\">4<\/text>\n<text class=\"t b2\" x=\"361\" y=\"84\" font-size=\"15\" text-anchor=\"middle\">2<\/text>\n<text class=\"t b2\" x=\"319\" y=\"114\" font-size=\"15\" text-anchor=\"middle\">4<\/text>\n<text class=\"t b2\" x=\"361\" y=\"114\" font-size=\"15\" text-anchor=\"middle\">2.5<\/text>\n<text class=\"t b2\" x=\"319\" y=\"144\" font-size=\"15\" text-anchor=\"middle\">5<\/text>\n<text class=\"t b2\" x=\"361\" y=\"144\" font-size=\"15\" text-anchor=\"middle\">3<\/text>\n<text class=\"t b2\" x=\"319\" y=\"174\" font-size=\"15\" text-anchor=\"middle\">6<\/text>\n<text class=\"t b2\" x=\"361\" y=\"174\" font-size=\"15\" text-anchor=\"middle\">3<\/text>\n<text class=\"tm b3\" x=\"430\" y=\"110\" font-size=\"14\" text-anchor=\"middle\">노드<\/text>\n<text class=\"tm b3\" x=\"430\" y=\"132\" font-size=\"14\" text-anchor=\"middle\">1 2 3 4<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"224\" font-size=\"16\" text-anchor=\"middle\">굵은 숫자가 이긴 값이에요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"250\" font-size=\"14\" text-anchor=\"middle\">같은 줄 안에서도 왼쪽 칸과 오른쪽 칸의 출처가 달라요<\/text>\n<\/svg>","caption":"같은 노드 안에서도 칸마다 고른 층이 달라요.","builds":3},{"kind":"points","head":"칸마다 고른다는 말의 뜻","items":["노드 1 을 봐요. 첫 칸의 4 는 2층에서, 둘째 칸의 2 는 1층에서 왔어요.","노드 2 는 반대예요. 첫 칸이 1층, 둘째 칸이 2층이에요.","슬라이드가 말한 특징 좌표마다 가장 정보가 많은 층을 고른다가 이것이에요.","그래서 **최대 풀링(Max Pooling)** 은 진짜로 노드 적응적이에요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 7번 (JK Network, 10점)","q":"a) (2p) Explain how Jumping Knowledge Networks help mitigate the over-smoothing problem in deep GCNs. b) (4p) Calculate A tilde. c) (4p) Calculate the output representations at layer k = 2.","qko":"**제이케이넷(JK-Net)** 문제예요. 식은 원소별 최댓값 형태이고 $\\tilde{A} = D^{-1}A$, $\\sigma$ 는 렐루예요. 2024 가을 중간 5번에도 같은 형태로 나왔어요.","solve":["a 는 p.53 의 영어 문장을 그대로 쓰면 돼요.","b 는 주어진 $A$ 의 각 행을 그 행의 **차수(Degree)** 로 나눠요. 행 합이 1 인지 검산해요.","c 는 먼저 $\\sigma(\\tilde{A}H^{(0)})$ 을 구해 $H^{(1)}$ 을 얻어요.","다음으로 $\\sigma(\\tilde{A}H^{(1)})$ 을 구해요.","마지막으로 두 결과를 같은 자리끼리 비교해 큰 값을 남겨요."],"answer":"$k=2$ 이면 max 안에 항이 두 개예요. $\\sigma(\\tilde{A}H^{(2)})$ 은 들어가지 않아요."},{"kind":"warn","head":"계산에서 가장 많이 틀리는 곳","items":["max 는 원소별이에요. 행렬 하나를 통째로 고르는 것이 아니에요. 이걸 틀리면 4점을 통째로 날려요.","$k=2$ 면 max 안에 항이 두 개예요. 식의 마지막 항이 $H^{(k-1)}$ 인 것을 보세요.","$H^{(1)}$ 은 max 안에 항이 하나뿐이라 그냥 $\\sigma(\\tilde{A}H^{(0)})$ 이에요.","2025 가을 중간 해설지의 JK 답안에는 $\\tilde{A}$ 1행에 $1/3$ 이어야 할 자리에 $1/2$ 이 적혀 있어요. 행 합을 꼭 검산하세요."]},{"kind":"check","q":"**최대 풀링(Max Pooling)** 방식의 JK 식에서 max 는 어떻게 계산하나요?","choices":["행렬 중 하나를 통째로 고른다","같은 자리끼리 비교해 큰 값을 남긴다","모두 더한다","평균을 낸다"],"a":1,"why":"그래서 같은 노드 안에서도 칸마다 다른 층에서 값이 올 수 있어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4574,0.0757],"c":[0,0.0019,0.5031,0.1077],"r":8.3045,"img":"img/L5/walk/p054_h.jpg"},"parts":[{"b":[0.04,0.14,0.16,0.06],"c":[0.02,0.115,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p054_11_01.jpg","say":"첫 항목이 **이어 붙이기(Concatenation)** 예요. 아래 대괄호 식이 그 뜻이에요."},{"b":[0.04,0.31,0.14,0.06],"c":[0.01,0.285,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p054_11_02.jpg","say":"둘째 항목이 **최대 풀링(Max Pooling)** 이에요. 특징 좌표마다 가장 정보가 많은 층을 골라요."},{"b":[0.04,0.5,0.2,0.06],"c":[0.028,0.475,0.224,0.11],"r":3.6202,"img":"img/L5/walk/p054_11_03.jpg","say":"셋째 항목이 **엘에스티엠 어텐션(LSTM Attention)** 이에요. 양방향 LSTM 을 써요."}]}},{"p":55,"title":"6층 JK-Net 예시: 동네마다 퍼지는 속도가 다르다","terms":["JK-Net","Influence Distribution","Receptive Field","Over-smoothing","Degree","Over-squashing"],"pass1":[{"kind":"say","lines":["실제 그래프에서 **영향 분포(Influence Distribution)** 가 층마다 어떻게 퍼지는지 그린 그림이에요.","같은 층 수라도 동네가 조밀하면 훨씬 빨리 퍼져요.","그래서 모두에게 같은 깊이를 강요하면 누군가는 손해를 봐요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"윗줄과 아랫줄을 비교해요","boxes":[{"x":0.1,"y":0.28,"w":0.12,"h":0.25,"say":"윗줄 2층은 노드 네 개예요. 이 노드는 아주 성긴 동네에 있어요.","c":[0.06,0.264,0.2,0.282],"r":1.2608,"img":"img/L5/walk/p055_20_01.jpg"},{"x":0.09,"y":0.57,"w":0.14,"h":0.22,"say":"아랫줄 2층은 노드 열 개쯤이에요. 같은 2층인데 두 배 넘게 넓어요.","c":[0.06,0.554,0.2,0.252],"r":1.4109,"img":"img/L5/walk/p055_20_02.jpg"},{"x":0.5,"y":0.65,"w":0.16,"h":0.18,"say":"아랫줄 4층은 백 개가 넘어요. 두 번 늘렸을 뿐인데 폭발했어요.","c":[0.48,0.634,0.2,0.212],"r":1.6771,"img":"img/L5/walk/p055_20_03.jpg"}]},{"kind":"steps","head":"**수용 영역(Receptive Field)** 이 얼마나 커지나요","steps":["평균 **차수(Degree)** 가 $d$ 이고 층이 $K$ 개면 대략 $1+d+d^2+\\cdots+d^K$ 개를 봐요.","$d=2$ 인 성긴 동네에서 2층이면 7개, 4층이면 31개예요.","$d=4$ 인 조밀한 동네에서 2층이면 21개, 4층이면 341개예요.","6층까지 가면 $d=2$ 는 127개, $d=4$ 는 5461개예요.","그래프 전체가 만 개라면 절반 이상을 본 셈이에요."],"answer":"같은 6층인데 한쪽은 멀쩡하고 한쪽은 그래프 평균이 되어 버려요.","given":"**제이케이넷(JK-Net)** 이 필요한 이유가 이 표에 다 들어 있어요."},{"kind":"points","head":"그림을 읽는 법","items":["층이 늘수록 색이 연해지면서 넓게 퍼져요.","같은 양의 영향이 더 많은 노드에 나뉘어 담기기 때문이에요.","이것은 **과압착(Over-squashing)** 의 그림이기도 해요. 멀리서 온 정보가 너무 희미해요.","그리고 전부가 비슷해지면 그게 **과평활화(Over-smoothing)** 예요."]}],"pass3":[{"kind":"warn","head":"슬라이드 그림에서 주의할 점","items":["범례와 그림의 색이 완전히 맞지는 않아요. 3층과 4층 그림의 사각형은 노란색과 연두색이에요.","원 논문 그림은 색 농도로 **영향 분포(Influence Distribution)** 의 세기를 나타낸 것이에요.","제목은 6층인데 소제목은 2층, 3층, 4층이에요. 6층 모델 안에서 각 시점의 분포를 그린 것이에요.","윗줄과 아랫줄은 서로 다른 대상 노드예요. 같은 그래프 안의 두 노드를 비교한 거예요."]},{"kind":"check","q":"같은 층 수인데 두 노드의 **수용 영역(Receptive Field)** 이 다른 이유는 무엇인가요?","choices":["층 수가 달라서","동네의 **차수(Degree)** 가 달라서","라벨이 달라서","가중치가 달라서"],"a":1,"why":"조밀한 동네는 금방 폭발하고 성긴 동네는 천천히 퍼져요. 그래서 알맞은 깊이가 노드마다 달라요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.6685,0.1957],"c":[0,0.0019,0.7353,0.2277],"r":5.7409,"img":"img/L5/walk/p055_h.jpg"},"parts":[{"b":[0.1,0.28,0.12,0.25],"c":[0.06,0.264,0.2,0.282],"r":1.2608,"img":"img/L5/walk/p055_11_01.jpg","say":"왼쪽 위 2층 그림이에요. 노드가 네 개뿐이에요."},{"b":[0.52,0.32,0.14,0.2],"c":[0.49,0.304,0.2,0.232],"r":1.5326,"img":"img/L5/walk/p055_11_02.jpg","say":"오른쪽 위 4층 그림이에요. 노드가 백 개 가까이 빽빽해요."},{"b":[0.72,0.41,0.18,0.28],"c":[0.708,0.394,0.204,0.312],"r":1.1624,"img":"img/L5/walk/p055_11_03.jpg","say":"오른쪽 범례예요. 빨간 사각형이 목표 노드, 빨간 원이 1홉, 초록 원이 2홉이에요."}]}},{"p":56,"title":"JumpingKnowledge 문서 읽기","terms":["JK-Net","Layer Aggregation","Concatenation","Max Pooling","LSTM Attention"],"pass1":[{"kind":"say","lines":["PyTorch Geometric 문서에서 JumpingKnowledge 모듈의 설명을 그대로 가져온 슬라이드예요.","mode 라는 인자에 세 글자 중 하나를 넣으면 돼요.","cat 은 **이어 붙이기(Concatenation)**, max 는 **최대 풀링(Max Pooling)**, lstm 은 **엘에스티엠 어텐션(LSTM Attention)** 이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"세 방식의 식을 하나씩","boxes":[{"x":0.29,"y":0.49,"w":0.42,"h":0.04,"say":"첫 방식은 연결이에요. 괄호 안에 cat 이라고 적혀 있어요.","c":[0.269,0.455,0.462,0.11],"r":7.4667,"img":"img/L5/walk/p056_20_01.jpg"},{"x":0.45,"y":0.53,"w":0.14,"h":0.05,"say":"그 아래 식이 두 개의 세로 막대로 이어 붙이는 모양이에요.","c":[0.42,0.5,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p056_20_02.jpg"},{"x":0.29,"y":0.6,"w":0.2,"h":0.04,"say":"둘째 방식은 최대 풀링이에요. 괄호 안에 max 라고 적혀 있어요.","c":[0.278,0.565,0.224,0.11],"r":3.6202,"img":"img/L5/walk/p056_20_03.jpg"},{"x":0.29,"y":0.71,"w":0.24,"h":0.04,"say":"셋째 방식은 가중 합이에요. 시그마 식이 아래에 있어요.","c":[0.278,0.675,0.264,0.11],"r":4.2667,"img":"img/L5/walk/p056_20_04.jpg"},{"x":0.29,"y":0.85,"w":0.44,"h":0.04,"say":"맨 아래에서 그 가중치를 양방향 LSTM 으로 얻는다고 했어요.","c":[0.268,0.815,0.484,0.11],"r":7.8222,"img":"img/L5/walk/p056_20_05.jpg"}]},{"kind":"compare","head":"모드마다 인자와 출력","cols":["mode","필요한 인자","출력 차원"],"rows":[["cat","mode 만","층 수만큼 커져요"],["max","mode 만","그대로예요"],["lstm","mode, channels, num_layers","그대로예요"]]},{"kind":"points","head":"어느 모드를 골라야 하나요","items":["처음에는 max 로 시작하세요. 파라미터가 안 늘고 노드 적응적이에요.","층이 3, 4개로 적으면 cat 도 좋아요. 아무 정보도 안 버리거든요.","라벨이 많고 그래프가 클 때만 lstm 이 유리해요. 파라미터가 늘어 과적합할 수 있어요.","시험 계산 문제는 언제나 **최대 풀링(Max Pooling)** 이에요."]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"Concatenation keeps all layers, max pooling selects the largest value per feature coordinate, and LSTM attention learns per-node weights.","ko":"연결은 모든 층을 그대로 유지하고, 최대 풀링은 특징 좌표마다 가장 큰 값을 고르며, LSTM 주의집중은 노드마다 가중치를 학습한다.","tip":"세 가지 **층 집계(Layer Aggregation)** 를 설명하라는 문제에 그대로 쓰면 돼요."},{"kind":"warn","head":"문서에서 헷갈리기 쉬운 점","items":["문서는 lstm 모드를 가중 합이라고 불러요. p.54 의 LSTM 어텐션과 같은 것이에요.","channels 와 num_layers 는 lstm 에서만 필요해요.","cat 을 쓰면 출력 차원이 층 수만큼 커져요. 뒤에 오는 층 크기도 같이 바꿔야 해요."]}],"pass4":[{"kind":"code","head":"슬라이드에 인쇄된 클래스 서명","file":"L5 슬라이드 p.56","code":"class JumpingKnowledge ( mode: str, channels: Optional[int] = None, num_layers: Optional[int] = None )","lines":[{"from":1,"to":1,"say":"인자가 세 개예요. mode 는 필수이고 나머지 둘은 값을 안 주면 None 이 돼요."}],"link":"mode 에 넣는 세 글자가 p.54 에서 배운 세 가지 **층 집계(Layer Aggregation)** 예요."},{"kind":"pyterm","name":"Optional 과 None","say":["None 은 아무 값도 없다는 뜻의 특별한 값이에요.","Optional[int] 는 정수이거나 아무 값도 없을 수 있다는 표시예요.","이런 표시를 타입 힌트라고 하고, 사람이 읽기 쉬우라고 붙여 놓은 것이에요."],"example":"def f(n=None):\n    if n is None:\n        print(\"값이 없어요\")\n    else:\n        print(n)\n\nf()","out":"값이 없어요"}],"walk":{"head":{"b":[0.0131,0.0179,0.3438,0.1723],"c":[0,0.0019,0.3781,0.2043],"r":3.2902,"img":"img/L5/walk/p056_h.jpg"},"parts":[{"b":[0.27,0.24,0.46,0.05],"c":[0.247,0.21,0.506,0.11],"r":8.1778,"img":"img/L5/walk/p056_11_01.jpg","say":"맨 위가 모듈 이름이에요. models.JumpingKnowledge 예요."},{"b":[0.27,0.32,0.46,0.05],"c":[0.247,0.29,0.506,0.11],"r":8.1778,"img":"img/L5/walk/p056_11_02.jpg","say":"그 아래가 클래스 서명이에요. mode 와 channels 와 num_layers 를 받아요."},{"b":[0.28,0.49,0.44,0.4],"c":[0.258,0.47,0.484,0.44],"r":1.9556,"img":"img/L5/walk/p056_11_03.jpg","say":"그 아래로 세 가지 방식의 식이 차례로 나와요."}]}},{"p":57,"title":"JK-Net 예제 코드: 리스트에 담아 두기","terms":["JK-Net","Layer Aggregation","Max Pooling","Concatenation","GCN","ReLU"],"pass1":[{"kind":"say","lines":["**제이케이넷(JK-Net)** 코드의 요령은 하나예요.","층마다 나온 결과를 리스트에 차곡차곡 담아 둬요.","그리고 마지막에 그 리스트를 통째로 집계 모듈에 넘겨요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"코드에서 핵심 세 줄","boxes":[{"x":0.31,"y":0.5,"w":0.24,"h":0.03,"say":"여기서 집계 모듈을 만들어요. mode 를 그대로 넘겨요.","c":[0.298,0.46,0.264,0.11],"r":4.2667,"img":"img/L5/walk/p057_20_01.jpg"},{"x":0.31,"y":0.74,"w":0.1,"h":0.03,"say":"여기가 빈 리스트를 만드는 줄이에요. 이것이 핵심 장치예요.","c":[0.26,0.7,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p057_20_02.jpg"},{"x":0.32,"y":0.86,"w":0.14,"h":0.03,"say":"층마다 결과를 리스트에 담아요. 이 한 줄이 점프 연결 전부예요.","c":[0.29,0.82,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p057_20_03.jpg"},{"x":0.31,"y":0.91,"w":0.2,"h":0.03,"say":"마지막에 리스트를 통째로 넘겨 한 덩어리로 합쳐요.","c":[0.298,0.87,0.224,0.11],"r":3.6202,"img":"img/L5/walk/p057_20_04.jpg"}]},{"kind":"points","head":"mode 에 따라 뒤 층 크기가 달라져요","items":["**최대 풀링(Max Pooling)** 이면 출력 차원이 그대로라 선형층 입력이 hidden 이에요.","**이어 붙이기(Concatenation)** 면 차원이 층 수만큼 커져요.","그래서 선형층 입력이 num_layers 곱하기 hidden 이 돼요.","코드에 if 와 elif 로 나뉘어 있는 이유가 이것이에요."]},{"kind":"compare","head":"코드의 이름과 개념의 짝","cols":["코드","개념","어디서 배웠나"],"rows":[["layer_out","층별 표현을 담아 두는 곳","p.53 의 점프 연결"],["self.jk","**층 집계(Layer Aggregation)** 모듈","p.54 과 p.56"],["mode='max'","**최대 풀링(Max Pooling)**","p.54 의 시험 식"],["GCNConv","평범한 **그래프 합성곱 신경망(GCN)** 층","p.46"]]}],"pass3":[{"kind":"warn","head":"코드에서 헷갈리기 쉬운 점","items":["리스트에 담는 줄이 반복문 안에 있어야 해요. 밖에 두면 마지막 층 것만 담겨요.","그러면 **제이케이넷(JK-Net)** 이 아니라 그냥 6층 GCN 이 돼요.","코드에 mode 가 lstm 인 경우가 빠져 있어요. 그대로 쓰면 선형층이 안 만들어져 에러가 나요.","층 자체는 평범한 GCNConv 예요. JK-Net 은 합치는 방법만 바꿔요."]},{"kind":"check","q":"코드의 `layer_out` 리스트는 슬라이드의 무엇에 해당하나요?","choices":["가중치 행렬","층마다의 표현이 마지막으로 점프하는 통로","엣지 목록","학습률"],"a":1,"why":"p.53 그림의 빨간 곡선 화살표 전부가 이 리스트 한 줄이에요."}],"pass4":[{"kind":"code","head":"슬라이드에 인쇄된 코드 전체 (1/2)","file":"L5 슬라이드 p.57","code":"from torch_geometric.nn import JumpingKnowledge\n\nclass JKNet(torch.nn.Module):\n    def __init__(self, dataset, mode='max', num_layers=6, hidden=16):\n        super(JKNet, self).__init__()\n        self.num_layers = num_layers\n        self.mode = mode\n\n        self.conv0 = GCNConv(dataset.num_node_features, hidden)\n        self.dropout0 = torch.nn.Dropout(p=0.5)\n\n        for i in range(1, self.num_layers):\n            setattr(self, 'conv{}'.format(i), GCNConv(hidden, hidden))\n            setattr(self, 'dropout{}'.format(i), torch.nn.Dropout(p=0.5))\n\n        self.jk = JumpingKnowledge(mode=mode)\n        if mode == 'max':\n            self.fc = torch.nn.Linear(hidden, dataset.num_classes)\n        elif mode == 'cat':\n            self.fc = torch.nn.Linear(num_layers * hidden, dataset.num_classes)\n        self.optimizer = torch.optim.Adam(self.parameters(),\n                                          lr=0.01,\n                                          weight_decay=5e-4)\n    def forward(self, x, edge_index):\n\n        layer_out = []\n        for i in range(self.num_layers):\n            conv = getattr(self, 'conv{}'.format(i))\n            dropout = getattr(self, 'dropout{}'.format(i))\n            x = dropout(F.relu(conv(x, edge_index)))\n            layer_out.append(x)\n\n        h = self.jk(layer_out)\n        h = self.fc(h)\n        return h, F.log_softmax(h, dim=1)","lines":[{"from":1,"to":1,"say":"torch_geometric.nn 에서 JumpingKnowledge 를 꺼내 와요."},{"from":3,"to":4,"say":"클래스와 준비 함수예요. 기본값이 **최대 풀링(Max Pooling)**, 층 6개, 은닉 16 차원이에요."},{"from":5,"to":7,"say":"부모 준비 함수를 돌리고 층 수와 모드를 저장해요."},{"from":9,"to":10,"say":"첫 층과 그 뒤에 붙일 드롭아웃을 만들어요. 첫 층만 입력 차원이 달라서 따로 만들어요."},{"from":12,"to":14,"say":"나머지 다섯 층을 만들어요. setattr 은 이름을 문자열로 만들어 붙이는 함수예요."},{"from":16,"to":16,"say":"여기서 **층 집계(Layer Aggregation)** 모듈을 만들어요. p.56 의 그 모듈이에요."},{"from":17,"to":20,"say":"모드에 따라 마지막 선형층의 입력 차원을 다르게 잡아요. cat 이면 층 수만큼 커져요."},{"from":21,"to":23,"say":"학습률 0.01 짜리 Adam 최적화기를 만들어요."}],"link":"16번 줄 하나가 p.54 에서 배운 세 가지 합치기 방법을 전부 담고 있어요."},{"kind":"code","head":"슬라이드에 인쇄된 코드 전체 (2/2)","file":"L5 슬라이드 p.57","code":"from torch_geometric.nn import JumpingKnowledge\n\nclass JKNet(torch.nn.Module):\n    def __init__(self, dataset, mode='max', num_layers=6, hidden=16):\n        super(JKNet, self).__init__()\n        self.num_layers = num_layers\n        self.mode = mode\n\n        self.conv0 = GCNConv(dataset.num_node_features, hidden)\n        self.dropout0 = torch.nn.Dropout(p=0.5)\n\n        for i in range(1, self.num_layers):\n            setattr(self, 'conv{}'.format(i), GCNConv(hidden, hidden))\n            setattr(self, 'dropout{}'.format(i), torch.nn.Dropout(p=0.5))\n\n        self.jk = JumpingKnowledge(mode=mode)\n        if mode == 'max':\n            self.fc = torch.nn.Linear(hidden, dataset.num_classes)\n        elif mode == 'cat':\n            self.fc = torch.nn.Linear(num_layers * hidden, dataset.num_classes)\n        self.optimizer = torch.optim.Adam(self.parameters(),\n                                          lr=0.01,\n                                          weight_decay=5e-4)\n    def forward(self, x, edge_index):\n\n        layer_out = []\n        for i in range(self.num_layers):\n            conv = getattr(self, 'conv{}'.format(i))\n            dropout = getattr(self, 'dropout{}'.format(i))\n            x = dropout(F.relu(conv(x, edge_index)))\n            layer_out.append(x)\n\n        h = self.jk(layer_out)\n        h = self.fc(h)\n        return h, F.log_softmax(h, dim=1)","lines":[{"from":24,"to":24,"say":"데이터가 실제로 흐르는 함수예요."},{"from":26,"to":26,"say":"빈 리스트를 만들어요. 이것이 **제이케이넷(JK-Net)** 코드의 핵심 장치예요."},{"from":27,"to":29,"say":"층 수만큼 돌면서 setattr 로 붙여 둔 층과 드롭아웃을 이름으로 꺼내요."},{"from":30,"to":30,"say":"안에서 밖으로 읽어요. 층 통과, **렐루(ReLU)**, 드롭아웃 순서예요."},{"from":31,"to":31,"say":"이번 층 결과를 리스트에 담아요. 이 한 줄이 점프 연결이에요."},{"from":33,"to":35,"say":"리스트를 통째로 넘겨 합치고, 선형층으로 클래스 수만큼 줄여 내보내요."}],"link":"31번 줄이 p.53 그림의 빨간 점프 화살표 전부예요."},{"kind":"pyterm","name":"setattr 과 getattr","say":["setattr 은 이름을 문자열로 주면서 속성을 붙이는 함수예요.","getattr 은 반대로 이름을 문자열로 주고 꺼내 오는 함수예요.","층 수가 미리 정해지지 않을 때 이름을 만들어 가며 쓸 수 있어요."],"example":"class A: pass\n\na = A()\nsetattr(a, 'x1', 10)\nprint(getattr(a, 'x1'))","out":"10"},{"kind":"warn","head":"5주차 코드에 대한 안내","items":["5주차에는 실습 노트북이 없어요. 여기 코드는 슬라이드에 인쇄된 그대로예요.","더 흔한 방식은 torch.nn.ModuleList 에 담는 것이에요. p.52 의 GCNII 코드가 그 방식이에요.","코드를 외울 필요는 없어요. 리스트 한 줄이 어디인지만 알면 돼요."]}],"walk":{"head":{"b":[0.0131,0.0179,0.3438,0.0757],"c":[0,0.0019,0.3781,0.1077],"r":6.2412,"img":"img/L5/walk/p057_h.jpg"},"parts":[{"b":[0.27,0.11,0.46,0.06],"c":[0.247,0.085,0.506,0.11],"r":8.1778,"img":"img/L5/walk/p057_11_01.jpg","say":"위 검은 띠가 불러오기 한 줄이에요. JumpingKnowledge 를 꺼내 와요."},{"b":[0.27,0.18,0.46,0.8],"c":[0.247,0.12,0.506,0.88],"r":1.0222,"img":"img/L5/walk/p057_11_02.jpg","say":"아래 큰 상자가 클래스 전체예요. 코드는 영어 그대로 인쇄돼 있어요."}]}},{"p":58,"title":"정규화와 규제: 다시 벌리거나 일부러 떼어 내거나","terms":["Over-smoothing","Overfitting","Regularization","PairNorm","Dropout","DropEdge","DropNode"],"pass1":[{"kind":"say","lines":["새 묶음이 시작돼요. 제목은 **정규화와 규제** 예요.","**정규화** 는 무너진 값을 다시 벌려 놓는 일이에요.","**규제** 는 일부러 일부를 떼어 내서 모델이 한 신호에만 기대지 못하게 하는 일이에요."]},{"kind":"analogy","head":"무너진 줄 다시 세우기와 한 명씩 빼 보기","scene":"운동장에 아이 서른 명이 줄을 서 있어요. 시간이 지나니까 다들 가운데로 몰려서 누가 누군지 모르게 됐어요. 선생님이 다시 넓게 퍼지라고 해요. 이것이 정규화예요. 한편 달리기 연습을 할 때는 매번 몇 명씩 빼고 시켜요. 그러면 한 사람에게만 기대는 팀이 안 생겨요. 이것이 규제예요.","map":[["가운데로 몰리는 것","**과도한 평활화(Over-smoothing)**"],["다시 넓게 퍼지라고 하기","정규화, 즉 **PairNorm**"],["몇 명씩 빼고 연습하기","**규제(Regularization)**, 즉 Dropout 과 DropEdge"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"compare","head":"두 갈래가 고치는 병이 달라요","cols":["갈래","고치는 병","하는 일","대표"],"rows":[["정규화","**과도한 평활화(Over-smoothing)**","값이 모이면 억지로 다시 벌림","**PairNorm**"],["규제","**과적합(Overfitting)**","학습 때 일부를 지워 의존을 막음","**Dropout**, **DropEdge**, **DropNode**"]]},{"kind":"points","head":"떼어 내는 대상이 셋이에요","items":["**Dropout** 은 특징 벡터의 **칸** 을 0 으로 꺼요. 그래프는 안 건드려요","**DropEdge** 는 그래프의 **엣지** 를 지워요","**DropNode** 는 **노드** 를 통째로 지워요. 그러면 붙어 있던 엣지도 같이 사라져요","셋 다 **학습할 때만** 켜요. 평가할 때는 꺼요"]},{"kind":"warn","head":"DropEdge 만 두 병에 다 들어요","items":["엣지를 지우면 과적합이 줄어요. 매 에폭 그래프가 달라지니까 데이터 증강 효과예요","동시에 이웃이 줄어서 평균이 덜 섞이니 **과도한 평활화(Over-smoothing)** 도 늦춰져요","그래서 DropEdge 논문 제목에 oversmoothing 이 들어가 있어요"]}],"pass3":[{"kind":"check","q":"정규화가 겨냥하는 병과 규제가 겨냥하는 병을 바르게 짝지은 것은?","choices":["정규화는 과적합, 규제는 과평활","정규화는 과평활, 규제는 과적합","둘 다 과평활","둘 다 과적합"],"a":1,"why":"정규화는 값이 한 점으로 무너지는 **과도한 평활화(Over-smoothing)** 를, 규제는 외워 버리는 **과적합(Overfitting)** 을 겨냥해요."}],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.04,0.38,0.32,0.09],"c":[0.024,0.364,0.352,0.122],"r":5.1293,"img":"img/L5/walk/p058_12_01.jpg","say":"제목이 **정규화와 규제** 예요."},{"b":[0.04,0.5,0.56,0.09],"c":[0.012,0.4828,0.616,0.1245],"r":8.7961,"img":"img/L5/walk/p058_12_02.jpg","say":"아래 한 줄에 네 가지 동작이 적혀 있어요. 임베딩 정규화, 특징, 엣지, 노드 떨어뜨리기예요."}]}},{"p":59,"title":"정규화와 규제를 표와 그림으로 비교하기","terms":["PairNorm","Dropout","DropEdge","DropNode","Regularization","Overfitting"],"pass1":[{"kind":"say","lines":["앞 장의 두 갈래를 **표 하나와 그림 네 개** 로 보여 주는 슬라이드예요.","그림만 봐도 둘의 차이가 바로 보여요.","오른쪽 위 작은 글씨에 **점선은 학습 때 떼어 낸 것** 이라는 범례가 있어요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"아래 그림 네 개","boxes":[{"x":0.04,"y":0.5,"w":0.42,"h":0.42,"say":"왼쪽 덩어리가 **정규화** 예요. 뭉친 점들이 오른쪽에서 넓게 퍼져 있어요. PairNorm 이 하는 일의 전부예요.","c":[0.019,0.479,0.462,0.462],"r":1.7778,"img":"img/L5/walk/p059_20_01.jpg"},{"x":0.5,"y":0.5,"w":0.15,"h":0.42,"say":"**Dropout** 이에요. 네모 격자에서 점선 칸이 0 으로 꺼진 특징이에요.","c":[0.475,0.479,0.2,0.462],"r":0.7696,"img":"img/L5/walk/p059_20_02.jpg"},{"x":0.66,"y":0.5,"w":0.16,"h":0.42,"say":"**DropEdge** 예요. 점선이 지워진 엣지인데 노드는 전부 그대로 있어요.","c":[0.64,0.479,0.2,0.462],"r":0.7696,"img":"img/L5/walk/p059_20_03.jpg"},{"x":0.83,"y":0.5,"w":0.15,"h":0.42,"say":"**DropNode** 예요. 노드 하나가 점선이고 거기 붙은 선들도 전부 점선이에요.","c":[0.8,0.479,0.2,0.462],"r":0.7696,"img":"img/L5/walk/p059_20_04.jpg"}]},{"kind":"figure","head":"떼어 내는 대상이 다르면 사라지는 범위도 달라요","svg":"<svg viewBox=\"0 0 480 230\">\n <text class=\"tb\" x=\"80\" y=\"22\" text-anchor=\"middle\" font-size=\"15\">Dropout: 특징<\/text>\n <rect class=\"box b1\" x=\"24\" y=\"40\" width=\"26\" height=\"22\"/>\n <rect class=\"box2 b1\" x=\"54\" y=\"40\" width=\"26\" height=\"22\"/>\n <rect class=\"box b1\" x=\"84\" y=\"40\" width=\"26\" height=\"22\"/>\n <rect class=\"box2 b1\" x=\"114\" y=\"40\" width=\"26\" height=\"22\"/>\n <rect class=\"box2 b1\" x=\"24\" y=\"66\" width=\"26\" height=\"22\"/>\n <rect class=\"box b1\" x=\"54\" y=\"66\" width=\"26\" height=\"22\"/>\n <rect class=\"box2 b1\" x=\"84\" y=\"66\" width=\"26\" height=\"22\"/>\n <rect class=\"box b1\" x=\"114\" y=\"66\" width=\"26\" height=\"22\"/>\n <text class=\"t b1\" x=\"82\" y=\"110\" text-anchor=\"middle\" font-size=\"13\">벡터의 칸을 끔<\/text>\n <text class=\"t b1\" x=\"82\" y=\"128\" text-anchor=\"middle\" font-size=\"13\">그래프는 그대로<\/text>\n <text class=\"tb\" x=\"240\" y=\"22\" text-anchor=\"middle\" font-size=\"15\">DropEdge: 엣지<\/text>\n <circle class=\"n b2\" cx=\"196\" cy=\"50\" r=\"12\"/>\n <circle class=\"n b2\" cx=\"272\" cy=\"42\" r=\"12\"/>\n <circle class=\"n b2\" cx=\"272\" cy=\"90\" r=\"12\"/>\n <circle class=\"n b2\" cx=\"330\" cy=\"66\" r=\"12\"/>\n <line class=\"e b2\" x1=\"207\" y1=\"47\" x2=\"261\" y2=\"43\"/>\n <line class=\"e2 b2\" x1=\"205\" y1=\"56\" x2=\"262\" y2=\"85\"/>\n <line class=\"e b2\" x1=\"283\" y1=\"46\" x2=\"320\" y2=\"61\"/>\n <line class=\"e b2\" x1=\"283\" y1=\"86\" x2=\"320\" y2=\"71\"/>\n <text class=\"t b2\" x=\"262\" y=\"110\" text-anchor=\"middle\" font-size=\"13\">선 하나만 사라짐<\/text>\n <text class=\"t b2\" x=\"262\" y=\"128\" text-anchor=\"middle\" font-size=\"13\">노드는 모두 남음<\/text>\n <text class=\"tb\" x=\"240\" y=\"158\" text-anchor=\"middle\" font-size=\"15\">DropNode: 노드와 그 선 전부<\/text>\n <circle class=\"n b3\" cx=\"150\" cy=\"190\" r=\"12\"/>\n <circle class=\"n3 b3\" cx=\"226\" cy=\"182\" r=\"12\"/>\n <circle class=\"n b3\" cx=\"226\" cy=\"214\" r=\"12\"/>\n <circle class=\"n b3\" cx=\"300\" cy=\"198\" r=\"12\"/>\n <line class=\"e2 b3\" x1=\"161\" y1=\"187\" x2=\"215\" y2=\"183\"/>\n <line class=\"e b3\" x1=\"159\" y1=\"196\" x2=\"216\" y2=\"211\"/>\n <line class=\"e2 b3\" x1=\"237\" y1=\"186\" x2=\"290\" y2=\"195\"/>\n <line class=\"e b3\" x1=\"237\" y1=\"212\" x2=\"290\" y2=\"202\"/>\n <text class=\"t b3\" x=\"390\" y=\"200\" text-anchor=\"middle\" font-size=\"13\">노드가 지워지면<\/text>\n <text class=\"t b3\" x=\"390\" y=\"218\" text-anchor=\"middle\" font-size=\"13\">붙은 선도 같이<\/text>\n<\/svg>","caption":"Dropout 은 칸을, DropEdge 는 선을, DropNode 는 노드와 선을 함께 지워요.","builds":3},{"kind":"points","head":"표에서 꼭 읽어 낼 두 단어","items":["정규화 줄의 **중심 다시 맞추기** 와 **크기 다시 맞추기** 가 PairNorm 의 1단계와 2단계예요","규제 줄의 **학습하는 동안** 이라는 조건이 중요해요. 평가할 때는 아무것도 안 지워요","파이토치에서는 `model.train()` 과 `model.eval()` 로 자동 전환돼요","**DropNode** 는 **DropEdge** 보다 센 조치예요. 노드를 지우면 엣지도 같이 사라지니까요"]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"Dropout randomly zeroes entries of node feature vectors, DropEdge removes edges, and DropNode removes nodes together with all their incident edges; all three are applied only during training.","ko":"Dropout 은 노드 특징 벡터의 칸을 무작위로 0 으로 만들고, DropEdge 는 엣지를 지우고, DropNode 는 노드와 그에 붙은 엣지를 함께 지워요. 셋 다 학습할 때만 적용돼요.","tip":"세미콜론 뒤에 공통 조건을 붙이는 틀이에요."},{"kind":"check","q":"**Dropout** 이 바꾸는 것은 무엇인가요?","choices":["그래프의 엣지","그래프의 노드","특징 벡터의 칸","가중치 행렬"],"a":2,"why":"**Dropout** 은 그래프 구조를 전혀 안 건드려요. 노드가 들고 있는 벡터의 칸을 0 으로 끄는 것이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.1786,0.0757],"c":[0.0011,0.0019,0.2026,0.1077],"r":3.3443,"img":"img/L5/walk/p059_h.jpg"},"parts":[{"b":[0.04,0.15,0.14,0.05],"c":[0.01,0.12,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p059_11_01.jpg","say":"첫 칸 이름이 **갈래** 예요."},{"b":[0.2,0.2,0.76,0.08],"c":[0.162,0.1556,0.836,0.1689],"r":8.7994,"img":"img/L5/walk/p059_11_02.jpg","say":"첫 줄 **정규화** 예요. 층을 지날 때마다 중심과 크기를 다시 맞춰 한 점으로 무너지지 못하게 한대요."},{"b":[0.2,0.3,0.76,0.1],"c":[0.162,0.2656,0.836,0.1689],"r":8.7994,"img":"img/L5/walk/p059_11_03.jpg","say":"둘째 줄 **규제** 예요. 학습하는 동안 특징, 엣지, 노드를 무작위로 떼어 낸대요."}]}},{"p":60,"title":"과평활을 두 방향에서 보기: 행과 열","terms":["Over-smoothing","Row-diff","Col-diff","GCN"],"pass1":[{"kind":"say","lines":["지금까지 과평활을 뭉뚱그려 말했는데, 여기서부터 **두 종류로 쪼개요.**","하나는 **행(노드)이 같아지는 것**, 다른 하나는 **열(특징)이 같아지는 것** 이에요.","이 슬라이드는 제목만 던져 놓는 장이에요. 내용은 다음 두 장에 있어요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"points","head":"표현 행렬 $H$ 를 떠올려요","items":["가로줄 하나가 **노드 하나** 예요. 노드 $i$ 가 들고 있는 숫자 벡터예요","세로줄 하나가 **특징 하나** 예요. 모든 노드가 그 칸에 적어 놓은 값들이에요","행이 다 같아지면 **노드를 구별할 수 없어요**","열이 다 같아지면 **칸 수만큼의 정보가 없어요.** 차원 낭비예요"]},{"kind":"figure","head":"행이 무너지는 것과 열이 무너지는 것","svg":"<svg viewBox=\"0 0 480 200\">\n <text class=\"tb\" x=\"86\" y=\"22\" text-anchor=\"middle\" font-size=\"15\">정상<\/text>\n <rect class=\"box\" x=\"30\" y=\"34\" width=\"36\" height=\"24\"/>\n <rect class=\"box2\" x=\"68\" y=\"34\" width=\"36\" height=\"24\"/>\n <rect class=\"box\" x=\"106\" y=\"34\" width=\"36\" height=\"24\"/>\n <rect class=\"box2\" x=\"30\" y=\"60\" width=\"36\" height=\"24\"/>\n <rect class=\"box\" x=\"68\" y=\"60\" width=\"36\" height=\"24\"/>\n <rect class=\"box2\" x=\"106\" y=\"60\" width=\"36\" height=\"24\"/>\n <rect class=\"box\" x=\"30\" y=\"86\" width=\"36\" height=\"24\"/>\n <rect class=\"box2\" x=\"68\" y=\"86\" width=\"36\" height=\"24\"/>\n <rect class=\"box\" x=\"106\" y=\"86\" width=\"36\" height=\"24\"/>\n <text class=\"t\" x=\"86\" y=\"130\" text-anchor=\"middle\" font-size=\"13\">행도 열도 서로 달라요<\/text>\n <text class=\"tb\" x=\"240\" y=\"22\" text-anchor=\"middle\" font-size=\"15\">행 방향 무너짐<\/text>\n <rect class=\"box2 b1\" x=\"184\" y=\"34\" width=\"36\" height=\"24\"/>\n <rect class=\"box2 b1\" x=\"222\" y=\"34\" width=\"36\" height=\"24\"/>\n <rect class=\"box2 b1\" x=\"260\" y=\"34\" width=\"36\" height=\"24\"/>\n <rect class=\"box2 b1\" x=\"184\" y=\"60\" width=\"36\" height=\"24\"/>\n <rect class=\"box2 b1\" x=\"222\" y=\"60\" width=\"36\" height=\"24\"/>\n <rect class=\"box2 b1\" x=\"260\" y=\"60\" width=\"36\" height=\"24\"/>\n <rect class=\"box2 b1\" x=\"184\" y=\"86\" width=\"36\" height=\"24\"/>\n <rect class=\"box2 b1\" x=\"222\" y=\"86\" width=\"36\" height=\"24\"/>\n <rect class=\"box2 b1\" x=\"260\" y=\"86\" width=\"36\" height=\"24\"/>\n <text class=\"t b1\" x=\"240\" y=\"130\" text-anchor=\"middle\" font-size=\"13\">가로줄이 전부 같아요<\/text>\n <text class=\"t b1\" x=\"240\" y=\"148\" text-anchor=\"middle\" font-size=\"13\">재는 법 Row-diff<\/text>\n <text class=\"tb\" x=\"396\" y=\"22\" text-anchor=\"middle\" font-size=\"15\">열 방향 무너짐<\/text>\n <rect class=\"box b2\" x=\"340\" y=\"34\" width=\"36\" height=\"24\"/>\n <rect class=\"box b2\" x=\"378\" y=\"34\" width=\"36\" height=\"24\"/>\n <rect class=\"box b2\" x=\"416\" y=\"34\" width=\"36\" height=\"24\"/>\n <rect class=\"box2 b2\" x=\"340\" y=\"60\" width=\"36\" height=\"24\"/>\n <rect class=\"box2 b2\" x=\"378\" y=\"60\" width=\"36\" height=\"24\"/>\n <rect class=\"box2 b2\" x=\"416\" y=\"60\" width=\"36\" height=\"24\"/>\n <rect class=\"box b2\" x=\"340\" y=\"86\" width=\"36\" height=\"24\"/>\n <rect class=\"box b2\" x=\"378\" y=\"86\" width=\"36\" height=\"24\"/>\n <rect class=\"box b2\" x=\"416\" y=\"86\" width=\"36\" height=\"24\"/>\n <text class=\"t b2\" x=\"396\" y=\"130\" text-anchor=\"middle\" font-size=\"13\">세로줄이 전부 같아요<\/text>\n <text class=\"t b2\" x=\"396\" y=\"148\" text-anchor=\"middle\" font-size=\"13\">재는 법 Col-diff<\/text>\n <text class=\"t\" x=\"240\" y=\"186\" text-anchor=\"middle\" font-size=\"14\">가로줄 하나가 노드 하나, 세로줄 하나가 특징 하나예요<\/text>\n<\/svg>","caption":"같은 행렬도 보는 방향에 따라 다른 무너짐이 보여요.","builds":2},{"kind":"compare","head":"두 방향을 미리 갈라 둬요","cols":["방향","같아지는 것","재는 지표"],"rows":[["노드 방향","표현 행렬의 **행**","**Row-diff**"],["특징 방향","표현 행렬의 **열**","**Col-diff**"]]}],"pass3":[{"kind":"warn","head":"이 슬라이드를 볼 때","items":["**제목만 있는 장** 이에요. 교수님이 같은 제목으로 세 장을 연달아 넘겨요","p.60 이 뼈대, p.61 이 행 방향, p.62 가 열 방향이라고 묶어서 기억하세요"]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4679,0.0757],"c":[0,0.0019,0.5147,0.1077],"r":8.496,"img":"img/L5/walk/p060_h.jpg"},"parts":[{"b":[0.03,0.14,0.4,0.05],"c":[0.01,0.11,0.44,0.11],"r":7.1111,"img":"img/L5/walk/p060_11_01.jpg","say":"맨 위 굵은 줄이 **GCN 에서 나타나는 과평활의 종류** 예요."},{"b":[0.06,0.2,0.4,0.05],"c":[0.04,0.17,0.44,0.11],"r":7.1111,"img":"img/L5/walk/p060_11_02.jpg","say":"화살표 불릿이 **행렬이 무너지는 것을 두 방향에서 보기** 예요."},{"b":[0.09,0.27,0.35,0.05],"c":[0.0725,0.24,0.385,0.11],"r":6.2222,"img":"img/L5/walk/p060_11_03.jpg","say":"1번 **노드 방향 과평활**, 아래 2번이 **특징 방향 과평활** 이에요."}]}},{"p":61,"title":"노드 방향 과평활: 행이 똑같아진다","terms":["Over-smoothing","Row-diff","MAD"],"pass1":[{"kind":"say","lines":["**노드 방향 과평활** 은 표현 행렬의 **행들이 똑같아지는 것** 이에요.","그러면 노드가 어디에 있든 어느 종류든 서로 구별할 수 없게 돼요.","재는 지표는 **Row-diff**, 즉 노드끼리의 평균 거리예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"formula","head":"Row-diff 의 정의","tex":"\\mathrm{row\\text{-}diff}\\!\\left(H^{(k)}\\right) = \\frac{1}{n^2}\\sum_{i,j \\in [n]} \\left\\lVert h_i^{(k)} - h_j^{(k)} \\right\\rVert_2","parts":[{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"}],"whole":"모든 노드 쌍에 대해 거리를 재서 전부 더하고 쌍의 개수로 나눠요. **노드들이 서로 얼마나 떨어져 있는지의 평균** 이에요."},{"kind":"steps","head":"작은 예로 Row-diff 를 직접 구해요","steps":["행이 $(3,0)$, $(0,4)$, $(0,0)$ 인 경우부터 해요.","1번과 2번의 차는 $(3,-4)$ 이고 거리는 $\\sqrt{9+16} = 5$ 예요.","1번과 3번은 $(3,0)$ 이라 거리가 3, 2번과 3번은 $(0,4)$ 라 거리가 4 예요.","같은 쌍은 거리가 0 이고 다른 쌍은 양방향으로 두 번 세니까 합이 $2(5+3+4) = 24$ 예요.","$n^2 = 9$ 로 나누면 약 2.67 이에요.","이번엔 세 행이 전부 $(1,1)$ 인 경우예요. 모든 거리가 0 이라 Row-diff 도 0 이에요."],"answer":"2.67 에서 0 으로 떨어졌어요. **Row-diff 가 0 으로 가면 노드 방향 과평활** 이에요.","given":"노드 3개, 특징 2차원이에요."},{"kind":"points","head":"식에서 눈여겨볼 두 가지","items":["분모가 $n(n-1)$ 이 아니라 **$n^2$** 이에요. 같은 노드끼리의 쌍(거리 0)까지 세고 있어서예요","평균값이 조금 작아지지만 **층끼리 비교하는 데는 지장이 없어요**","**Row-diff 는 크기 변화에 속아요.** 모든 벡터를 반으로 줄이면 값도 반이 돼요","그래서 크기에 안 속는 **MAD(평균 코사인 거리)** 와 같이 봐요"]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"Node-wise over-smoothing means the rows of the representation matrix become identical, so nodes cannot be distinguished; it is measured by row-diff, the average pairwise Euclidean distance between rows.","ko":"노드 방향 과평활은 표현 행렬의 행들이 같아져 노드를 구별할 수 없게 되는 것이고, 행끼리의 평균 유클리드 거리인 row-diff 로 재요.","tip":"정의와 재는 법을 세미콜론으로 잇는 틀이에요."},{"kind":"check","q":"**Row-diff** 값이 0 에 가까워졌어요. 무슨 일이 일어난 것인가요?","choices":["특징 차원이 서로 닮아졌다","모든 노드 벡터가 한 점으로 모였다","엣지가 사라졌다","학습이 잘 되고 있다"],"a":1,"why":"**Row-diff** 는 노드끼리의 평균 거리예요. 0 이면 모두가 같은 자리에 모였다는 뜻이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4679,0.3048],"c":[0,0.0019,0.5147,0.3368],"r":2.7168,"img":"img/L5/walk/p061_h.jpg"},"parts":[{"b":[0.17,0.33,0.78,0.13],"c":[0.131,0.3083,0.858,0.1733],"r":8.8017,"img":"img/L5/walk/p061_11_01.jpg","say":"**정의** 예요. 여러 노드의 표현이 섞여서 완전히 똑같은 벡터 하나로 수렴한대요."},{"b":[0.17,0.5,0.6,0.05],"c":[0.14,0.4583,0.66,0.1333],"r":8.8022,"img":"img/L5/walk/p061_11_02.jpg","say":"**행렬로 보면** 이에요. 표현 행렬 $H$ 의 행들이 똑같아지는 거예요."},{"b":[0.17,0.57,0.78,0.05],"c":[0.131,0.5083,0.858,0.1733],"r":8.8017,"img":"img/L5/walk/p061_11_03.jpg","say":"**재는 법** 이에요. Row-diff 로 재고, 행끼리의 유클리드 거리를 모두 재서 평균 낸 값이래요."}]}},{"p":62,"title":"특징 방향 과평활: 열이 서로 닮아진다","terms":["Over-smoothing","Col-diff","Row-diff","PairNorm"],"pass1":[{"kind":"say","lines":["**특징 방향 과평활** 은 표현 행렬의 **열들이 서로 닮아지는 것** 이에요.","128 칸을 쓰는데 실제로는 3 칸짜리 정보만 들어 있는 상태를 떠올리면 돼요.","재는 지표는 **Col-diff** 예요."]},{"kind":"analogy","head":"색연필 열두 자루","scene":"색연필 열두 자루가 든 통을 받았어요. 그런데 꺼내 보니 열 자루가 거의 같은 파란색이에요. 자루는 열두 개인데 실제로 칠할 수 있는 색은 세 가지뿐인 셈이에요. 통이 커도 쓸 수 있는 색이 적으면 그림을 다양하게 못 그려요.","map":[["색연필 한 자루","특징 차원 하나, 즉 벡터의 칸 하나"],["거의 같은 색이 되는 것","열들이 서로 닮아지는 것"],["쓸 수 있는 색이 세 가지뿐","계수(rank)가 줄어든 상태"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"낯선 말 세 가지를 풀어요","items":["**특징 채널** 은 벡터의 **칸 하나** 예요. 128 차원이면 채널이 128 개예요","**분산** 은 그 칸의 값들이 얼마나 퍼져 있는지예요. 분산을 잃으면 거의 상수가 돼요","**계수(rank)** 는 서로 독립인 줄이 몇 개인지를 세는 숫자예요","열이 3개라도 둘이 서로의 상수배면 독립인 것은 2개이고 계수는 2 예요"]},{"kind":"compare","head":"Row-diff 와 Col-diff 를 나란히","cols":["","**Row-diff**","**Col-diff**"],"rows":[["재는 대상","**행**끼리, 즉 노드 사이","**열**끼리, 즉 특징 사이"],["0 이 되면","모든 노드가 같은 벡터","모든 특징이 같은 패턴"],["잃는 것","노드를 구별하는 힘","차원이 주는 표현력"]]},{"kind":"steps","head":"두 무너짐이 서로 독립이라는 것을 숫자로","steps":["먼저 세 행이 전부 $(2,5)$ 인 경우예요.","행이 모두 같으니 **Row-diff 는 0** 이에요.","그런데 1열은 전부 2, 2열은 전부 5 라서 두 열이 서로 달라요. Col-diff 는 0 이 아니에요.","이번엔 행이 $(1,1)$, $(4,4)$, $(7,7)$ 인 경우예요.","1열과 2열이 완전히 같아서 **Col-diff 는 0** 이에요.","그런데 세 행이 서로 다르니 Row-diff 는 0 이 아니에요."],"answer":"한쪽만 0 인 경우가 둘 다 가능해요. 그래서 **두 지표를 같이 봐야** 해요.","given":"노드 3개, 특징 2차원이에요."}],"pass3":[{"kind":"warn","head":"꼭 기억할 한 가지","items":["**PairNorm 이 직접 막는 것은 행 방향이에요.** 노드끼리의 거리 총합을 유지하니까요","열 방향에 대해서는 보장이 없어요. 이것이 p.68 에서 말하는 한계와 이어져요","슬라이드가 Col-diff 의 식을 따로 안 줘요. Row-diff 식에서 행 대신 열을 넣으면 돼요"]},{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"Feature-wise over-smoothing makes the columns of the representation matrix highly correlated and reduces its rank, so the embedding loses effective dimensions; it is measured by col-diff.","ko":"특징 방향 과평활은 표현 행렬의 열들이 강하게 상관되어 계수가 줄고 유효 차원을 잃게 하는 것이고, col-diff 로 재요.","tip":"앞 장의 Row-diff 문장과 같은 틀이라 둘을 나란히 외우기 좋아요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4679,0.2801],"c":[0,0.0019,0.5147,0.3121],"r":2.9318,"img":"img/L5/walk/p062_h.jpg"},"parts":[{"b":[0.17,0.3,0.78,0.12],"c":[0.131,0.2733,0.858,0.1733],"r":8.8017,"img":"img/L5/walk/p062_20_01.jpg","say":"**정의** 예요. 서로 다른 특징 채널이 저마다의 분산과 표현력을 잃어서, 원래 입력 신호가 씻겨 나간대요."},{"b":[0.17,0.46,0.7,0.06],"c":[0.135,0.4122,0.77,0.1556],"r":8.7975,"img":"img/L5/walk/p062_20_02.jpg","say":"**행렬로 보면** 이에요. 표현 행렬 $H$ 의 열들이 강하게 닮아지고 계수를 잃어요."},{"b":[0.17,0.55,0.78,0.05],"c":[0.131,0.4883,0.858,0.1733],"r":8.8017,"img":"img/L5/walk/p062_20_03.jpg","say":"**재는 법** 이에요. Col-diff 로 재요. 열끼리의 거리를 모두 재서 평균 낸 값이에요."}]}},{"p":63,"title":"PairNorm 의 핵심 발상: 거리 총합을 묶어 둔다","terms":["PairNorm","Over-smoothing","GCN"],"pass1":[{"kind":"say","lines":["생각이 아주 단순해요. **문제가 거리가 줄어드는 것이면, 거리를 못 줄어들게 하면 된다.**","앞에서 과평활이 결국 Row-diff 가 0 으로 가는 것이라고 배웠죠.","그러니 **노드끼리 거리의 총합을 층마다 일정하게 붙잡아 두자** 는 것이 PairNorm 이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"points","head":"세 불릿에서 뽑을 것","items":["거리 제곱의 총합을 **TPD** 라고 불러요. Total Pairwise squared Distance 의 줄임말이에요","**가로챈다** 는 말은 GCN 층 계산을 막지 않고 **결과가 나온 직후에** 손댄다는 뜻이에요","그래서 **PairNorm 은 어떤 GNN 에도 끼워 넣을 수 있어요**","넣는 자리는 **활성화 함수 앞** 이에요. 이 조건이 중요해요"]},{"kind":"look","head":"아래 선 그래프","boxes":[{"x":0.25,"y":0.55,"w":0.5,"h":0.38,"say":"Cora 데이터에서 그래프 합성곱 수 $K$ 를 늘렸을 때의 성능이에요. 학습 데이터가 3% 밖에 없는 설정이에요.","c":[0.225,0.531,0.55,0.418],"r":2.3392,"img":"img/L5/walk/p063_21_01.jpg"}]},{"kind":"points","head":"아래 그래프를 읽는 법","items":["**SGC** 는 활성화 함수를 뺀 아주 단순한 GCN 이에요","$K$ 를 키울수록 PairNorm 없는 쪽은 떨어지고 있는 쪽은 버텨요","학습 데이터가 **3% 밖에 없다** 는 점이 중요해요. 레이블이 적을수록 멀리서 정보를 끌어와야 해요","즉 $K$ 를 키워야만 하는 상황에서 PairNorm 이 꼭 필요한 거예요"]},{"kind":"warn","head":"거리를 일정하게 지킨다는 말의 뜻","items":["**값을 그대로 둔다는 말이 아니에요.** 점들은 움직여요","다만 **서로 떨어진 정도의 총합** 만 고정돼요. 그래서 노드들이 자리를 바꿀 수는 있어요"]}],"pass3":[{"kind":"check","q":"PairNorm 을 한 문장으로 가장 잘 요약한 것은?","choices":["이웃을 더 많이 모은다","엣지를 지운다","거리 총합을 고정해서 한 점으로 무너지지 못하게 한다","층 수를 줄인다"],"a":2,"why":"과평활이 거리가 줄어드는 것이니 거리 총합을 고정하자는 것이 PairNorm 의 전부예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4679,0.1597],"c":[0,0.0019,0.5147,0.1917],"r":4.7732,"img":"img/L5/walk/p063_h.jpg"},"parts":[{"b":[0.06,0.18,0.88,0.07],"c":[0.016,0.1172,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p063_11_01.jpg","say":"**제안** 이에요. 표현을 대놓고 정규화해서 거리의 총합을 일정하게 붙잡아 두면 과평활을 막을 수 있대요."},{"b":[0.06,0.28,0.88,0.06],"c":[0.016,0.2122,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p063_11_02.jpg","say":"**목표** 예요. 모든 노드끼리의 거리 제곱의 합을 모든 층에서 일정하게 묶어 둔대요."},{"b":[0.06,0.37,0.88,0.06],"c":[0.016,0.3022,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p063_11_03.jpg","say":"**방식** 이에요. 메시지 패싱 층의 출력을 가로채서 활성화 함수로 넘기기 전에 다시 벌려 놓는대요."}]}},{"p":64,"title":"PairNorm 1단계: 중심 맞추기","terms":["PairNorm","GCN"],"pass1":[{"kind":"say","lines":["PairNorm 의 1단계는 **중심 맞추기** 예요.","모든 노드 벡터에서 **전체 평균을 빼서** 그래프 전체의 평균을 0 으로 만들어요.","아주 간단하지만 **거리는 하나도 안 바뀌어요.** 위치만 옮기는 평행이동이거든요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"formula","head":"1단계 중심 맞추기","tex":"\\tilde{x}_i = x_i - \\frac{1}{n}\\sum_{j=1}^{n} x_j","parts":[{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"}],"whole":"**내 벡터에서 전체 평균 벡터를 뺀다** 는 뜻이에요. 뭉친 덩어리를 원점으로 옮겨 놓는 일이에요."},{"kind":"steps","head":"손으로 1단계를 해 봐요","steps":["$X$ 의 행이 $(10,2)$, $(12,4)$, $(11,0)$ 이에요.","열마다 평균을 내요. 1열은 $(10+12+11)/3 = 11$ 이에요.","2열은 $(2+4+0)/3 = 2$ 예요. 그래서 평균 벡터는 $(11,2)$ 예요.","각 행에서 평균을 빼요. $(10,2)-(11,2) = (-1,0)$ 이에요.","나머지도 빼면 $(1,2)$ 와 $(0,-2)$ 가 나와요.","검산해요. 새 값들의 열 평균이 1열 0, 2열 0 이에요. 맞아요."],"answer":"값들이 11 근처에서 0 근처로 옮겨졌는데 **서로의 거리는 하나도 안 변했어요.**","given":"노드 3개, 특징 2차원이에요."},{"kind":"look","head":"아래 네 단계 그림","boxes":[{"x":0.22,"y":0.6,"w":0.12,"h":0.3,"say":"맨 왼쪽이 원래 입력 $X$ 예요. 점들이 넓게 흩어져 있어요.","c":[0.18,0.584,0.2,0.332],"r":1.071,"img":"img/L5/walk/p064_22_01.jpg"},{"x":0.4,"y":0.6,"w":0.12,"h":0.3,"say":"합성곱을 지난 뒤예요. 점들이 한 곳에 뭉쳐 있어요.","c":[0.36,0.584,0.2,0.332],"r":1.071,"img":"img/L5/walk/p064_22_02.jpg"},{"x":0.55,"y":0.57,"w":0.14,"h":0.33,"say":"**center** 화살표를 지난 뒤예요. 뭉친 덩어리가 원점으로 옮겨졌어요. 뭉친 정도는 그대로예요.","c":[0.52,0.5535,0.2,0.363],"r":0.9795,"img":"img/L5/walk/p064_22_03.jpg"},{"x":0.72,"y":0.57,"w":0.14,"h":0.33,"say":"**rescale** 까지 지나면 점들이 다시 넓게 퍼져요. 이것은 다음 장에서 봐요.","c":[0.69,0.5535,0.2,0.363],"r":0.9795,"img":"img/L5/walk/p064_22_04.jpg"}]}],"pass3":[{"kind":"warn","head":"1단계에서 틀리기 쉬운 것","items":["평균은 **열마다 따로** 내요. 전체 숫자의 평균이 아니에요. 결과가 벡터 하나예요","**중심 맞추기는 거리를 안 바꿔요.** 모두를 같은 만큼 옮기니까요","그래서 1단계만으로는 과평활을 못 막아요. 실제로 벌리는 일은 2단계가 해요","슬라이드가 이 단계를 **CS** 라고 줄여 써요. p.67 에서 PairNorm-CS 로 다시 나와요"]},{"kind":"check","q":"중심 맞추기를 한 뒤 노드 사이의 거리는 어떻게 되나요?","choices":["모두 0 이 된다","절반이 된다","그대로다","두 배가 된다"],"a":2,"why":"모든 벡터를 같은 만큼 옮기는 평행이동이라 서로의 거리는 전혀 안 바뀌어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4679,0.0757],"c":[0,0.0019,0.5147,0.1077],"r":8.496,"img":"img/L5/walk/p064_h.jpg"},"parts":[{"b":[0.03,0.14,0.4,0.05],"c":[0.01,0.11,0.44,0.11],"r":7.1111,"img":"img/L5/walk/p064_11_01.jpg","say":"맨 위 굵은 줄이 **PairNorm 수식** 이에요."},{"b":[0.06,0.19,0.9,0.06],"c":[0.01,0.12,0.99,0.2],"r":8.8,"img":"img/L5/walk/p064_11_02.jpg","say":"그 아래 문장이 중요해요. **그래프 합성곱을 한 번 거친 뒤** 의 행렬을 $X$ 라 한대요."},{"b":[0.12,0.3,0.72,0.1],"c":[0.084,0.27,0.792,0.16],"r":8.8,"img":"img/L5/walk/p064_11_03.jpg","say":"네모 불릿이 **1단계 중심 맞추기** 예요. 그래프 전체 평균이 0 이 되도록 특징을 옮긴대요."}]}},{"p":65,"title":"PairNorm 2단계: 크기 맞추기","terms":["PairNorm","Over-smoothing"],"pass1":[{"kind":"say","lines":["2단계는 **크기 맞추기** 예요. 여기가 PairNorm 의 진짜 핵심이에요.","벡터 길이 제곱의 평균을 구해서 그 제곱근으로 나눠요.","**뭉칠수록 나누는 수가 작아져서 더 크게 벌어져요.** 자동 보정 장치예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"formula","head":"2단계 크기 맞추기","tex":"x_i^{PN} = s \\cdot \\frac{\\tilde{x}_i}{\\sqrt{\\dfrac{1}{n}\\sum_{j=1}^{n} \\lVert \\tilde{x}_j \\rVert_2^2}}","parts":[{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"}],"whole":"분모가 **모든 노드에 대해 같은 숫자 하나** 라는 점이 핵심이에요. 그 숫자가 지금 얼마나 뭉쳤는지를 나타내니까, 뭉칠수록 작은 수로 나눠서 크게 벌어져요."},{"kind":"steps","head":"앞 장의 결과를 이어서 2단계를 해요","steps":["1단계 결과가 $(-1,0)$, $(1,2)$, $(0,-2)$ 이고 $s = 1$ 이에요.","행마다 길이 제곱을 구해요. $1+0 = 1$, $1+4 = 5$, $0+4 = 4$ 예요.","평균을 내면 $(1+5+4)/3 = 10/3$ 이고 약 3.333 이에요.","제곱근을 씌우면 약 1.826 이에요. 이것이 나눌 수예요.","모든 행을 1.826 으로 나눠요. $(-0.548, 0)$, $(0.548, 1.095)$, $(0, -1.095)$ 가 나와요.","검산해요. 새 값들의 길이 제곱 평균이 약 1.0 이에요."],"answer":"$s = 1$ 이면 **결과의 길이 제곱 평균이 항상 1** 이 돼요. 검산에 꼭 쓰세요.","given":"노드 3개, 특징 2차원이에요."},{"kind":"points","head":"왜 이것이 과평활을 막나","items":["다음 층에서 더 뭉쳐서 길이 제곱 평균이 0.01 로 줄었다고 해 봐요","그러면 분모가 $\\sqrt{0.01} = 0.1$ 이 되어 **모든 값을 10배로 키워요**","뭉칠수록 더 세게 벌려 주는 **자동 보정 장치** 예요","괄호 속 말대로 길이만 재면 되니까 쌍을 다 재는 것보다 훨씬 싸요"]}],"pass3":[{"kind":"warn","head":"2단계에서 가장 많이 틀리는 것","items":["**분모는 모든 노드가 공유하는 숫자 하나예요.** 노드마다 자기 길이로 나누는 것이 아니에요","자기 길이로 나누면 모든 벡터 길이가 1 이 되어 노드 사이의 크기 차이가 사라져요","**길이의 평균이 아니라 길이 제곱의 평균** 이고 그다음에 제곱근을 씌워요","$s$ 가 안 주어지면 1 로 두면 돼요"]},{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"PairNorm has two steps: centering subtracts the graph-wide mean, and scaling divides every centered vector by a single shared constant, which keeps the total pairwise squared distance fixed across layers.","ko":"PairNorm 은 두 단계예요. 중심 맞추기는 전체 평균을 빼고, 크기 맞추기는 모든 벡터를 공유하는 상수 하나로 나누어 층 사이에서 거리 제곱 총합을 일정하게 유지해요.","tip":"콜론으로 두 단계를 소개하고 which 절로 효과를 붙이는 틀이에요."},{"kind":"check","q":"PairNorm 2단계에서 분모로 쓰는 값은 무엇인가요?","choices":["각 노드 자기 벡터의 길이","모든 노드 길이 제곱의 평균의 제곱근","노드 개수","가장 긴 벡터의 길이"],"a":1,"why":"모든 노드가 **같은 숫자 하나** 로 나눠요. 노드마다 다른 값으로 나누면 크기 차이가 사라져요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4679,0.1598],"c":[0,0.0019,0.5147,0.1918],"r":4.7707,"img":"img/L5/walk/p065_h.jpg"},"parts":[{"b":[0.12,0.19,0.84,0.08],"c":[0.076,0.1367,0.924,0.1867],"r":8.7984,"img":"img/L5/walk/p065_11_01.jpg","say":"**2단계 크기 맞추기** 예요. 길이 제곱의 평균이 노드끼리 거리 제곱의 평균에 비례한다고 괄호에 적혀 있어요."},{"b":[0.33,0.29,0.26,0.13],"c":[0.317,0.274,0.286,0.162],"r":3.1385,"img":"img/L5/walk/p065_11_02.jpg","say":"가운데 식이 2단계예요. 분모에 제곱근과 평균이 들어 있어요."},{"b":[0.13,0.44,0.82,0.08],"c":[0.089,0.3889,0.902,0.1822],"r":8.8011,"img":"img/L5/walk/p065_11_03.jpg","say":"괄호 설명이에요. $s$ 는 일정한 크기를 정하는 값이고 보통 1 로 둔대요."}]}},{"p":66,"title":"PairNorm 두 단계를 한 장에 모아 보기","terms":["PairNorm","GCN","ReLU"],"pass1":[{"kind":"say","lines":["앞의 두 슬라이드를 **한 장에 합쳐 놓은** 장이에요.","1단계와 2단계가 나란히 있어서 전체 흐름을 복습하기 좋아요.","새로 추가된 내용은 없어요. 아래 그림의 주황 점선 네모 위치만 달라요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"compare","head":"한 층의 전체 흐름","cols":["걸음","하는 일","거리에 미치는 영향"],"rows":[["그래프 합성곱","이웃 평균","거리가 **줄어들어요**"],["1단계 중심 맞추기","평균을 0 으로 평행이동","**변화 없어요**"],["2단계 크기 맞추기","공유 상수로 나누기","거리를 **원래 크기로 되돌려요**"],["활성화 함수","**렐루(ReLU)** 등","여기는 PairNorm 바깥이에요"]]},{"kind":"figure","head":"PairNorm 한 층의 흐름","svg":"<svg viewBox=\"0 0 480 170\">\n <text class=\"tb\" x=\"240\" y=\"22\" text-anchor=\"middle\" font-size=\"16\">PairNorm 한 층의 흐름<\/text>\n <rect class=\"box\" x=\"14\" y=\"52\" width=\"76\" height=\"40\" rx=\"5\"/>\n <text class=\"t\" x=\"52\" y=\"77\" text-anchor=\"middle\" font-size=\"13\">GCN 층<\/text>\n <line class=\"arrow\" x1=\"90\" y1=\"72\" x2=\"112\" y2=\"72\"/>\n <rect class=\"box2 b1\" x=\"114\" y=\"52\" width=\"88\" height=\"40\" rx=\"5\"/>\n <text class=\"tl b1\" x=\"158\" y=\"70\" text-anchor=\"middle\" font-size=\"13\">1단계 중심<\/text>\n <text class=\"t b1\" x=\"158\" y=\"86\" text-anchor=\"middle\" font-size=\"12\">거리 그대로<\/text>\n <line class=\"arrow b1\" x1=\"202\" y1=\"72\" x2=\"224\" y2=\"72\"/>\n <rect class=\"box2 b2\" x=\"226\" y=\"52\" width=\"88\" height=\"40\" rx=\"5\"/>\n <text class=\"tl b2\" x=\"270\" y=\"70\" text-anchor=\"middle\" font-size=\"13\">2단계 크기<\/text>\n <text class=\"t b2\" x=\"270\" y=\"86\" text-anchor=\"middle\" font-size=\"12\">거리 되돌림<\/text>\n <line class=\"arrow b2\" x1=\"314\" y1=\"72\" x2=\"336\" y2=\"72\"/>\n <rect class=\"box b3\" x=\"338\" y=\"52\" width=\"76\" height=\"40\" rx=\"5\"/>\n <text class=\"t b3\" x=\"376\" y=\"77\" text-anchor=\"middle\" font-size=\"13\">ReLU<\/text>\n <line class=\"arrow b3\" x1=\"414\" y1=\"72\" x2=\"436\" y2=\"72\"/>\n <text class=\"t b3\" x=\"452\" y=\"77\" text-anchor=\"middle\" font-size=\"12\">다음 층<\/text>\n <text class=\"tb b2\" x=\"214\" y=\"128\" text-anchor=\"middle\" font-size=\"14\">PairNorm 은 이 두 칸이에요<\/text>\n <text class=\"t b3\" x=\"240\" y=\"152\" text-anchor=\"middle\" font-size=\"13\">활성화 함수보다 반드시 앞이어야 해요<\/text>\n<\/svg>","caption":"거리를 실제로 되돌리는 것은 2단계뿐이에요.","builds":3},{"kind":"formula","head":"두 단계를 한 줄로 이어 쓰면","tex":"x_i^{PN} = s \\cdot \\frac{x_i - \\frac{1}{n}\\sum_{j} x_j}{\\sqrt{\\frac{1}{n}\\sum_{j} \\left\\lVert x_j - \\frac{1}{n}\\sum_{l} x_l \\right\\rVert_2^2}}","parts":[{"sym":"sym","say":"say"},{"sym":"sym","say":"say"},{"sym":"sym","say":"say"}],"whole":"보기에는 복잡하지만 **분자는 1단계, 분모는 1단계 결과의 길이 제곱 평균의 제곱근** 일 뿐이에요. 시험에서는 두 단계로 나눠 푸는 것이 훨씬 안전해요."}],"pass3":[{"kind":"warn","head":"이 장을 볼 때","items":["**p.64 와 p.65 를 그대로 다시 보여 주는 복습 장** 이에요. 새 정보는 없어요","세 장(p.64, p.65, p.66)마다 **주황 점선 네모가 감싸는 자리** 가 달라요","교수님이 단계를 하나씩 짚어 가며 설명하려고 그렇게 만든 거예요","**합친 식은 외우지 않아도 돼요.** 두 단계로 나눠서 쓰세요"]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4679,0.1598],"c":[0,0.0019,0.5147,0.1918],"r":4.7707,"img":"img/L5/walk/p066_h.jpg"},"parts":[{"b":[0.06,0.19,0.9,0.06],"c":[0.01,0.12,0.99,0.2],"r":8.8,"img":"img/L5/walk/p066_11_01.jpg","say":"첫째는 $X$ 를 정의하는 문장이에요. p.64 와 같아요."},{"b":[0.12,0.28,0.84,0.12],"c":[0.076,0.2467,0.924,0.1867],"r":8.7984,"img":"img/L5/walk/p066_11_02.jpg","say":"둘째가 1단계와 그 식이에요."},{"b":[0.12,0.42,0.84,0.14],"c":[0.076,0.3967,0.924,0.1867],"r":8.7984,"img":"img/L5/walk/p066_11_03.jpg","say":"셋째가 2단계와 그 식이에요."},{"b":[0.4,0.57,0.5,0.35],"c":[0.375,0.5525,0.55,0.385],"r":2.5397,"img":"img/L5/walk/p066_11_04.jpg","say":"아래 그림에서 주황 점선이 **center 와 rescale 두 단계** 를 감싸고 있어요. PairNorm 이 그 둘이라는 표시예요."}]}},{"p":67,"title":"PairNorm 의 성질, 변형, 넣는 자리","terms":["PairNorm","ReLU","GCN"],"pass1":[{"kind":"say","lines":["PairNorm 이 **무엇을 보장하고, 어떤 선택지가 있고, 어디에 넣는지** 를 정리하는 장이에요.","보장되는 것은 **노드끼리 거리 제곱 총합(TPD)의 보존** 이에요.","변형은 **CS** 와 **S** 두 가지이고, 넣는 자리는 **집계 뒤, 활성화 함수 앞** 이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"compare","head":"변형 두 가지","cols":["이름","하는 일","언제 쓰나"],"rows":[["**PairNorm-CS**","중심 맞추기 + 크기 맞추기","기본형이에요"],["**PairNorm-S**","크기 맞추기만","특징이 이미 중심에 있거나 절대 위치가 뜻을 가질 때"]]},{"kind":"compare","head":"넣는 자리가 왜 중요한가","cols":["순서","결과"],"rows":[["집계 → **PairNorm** → ReLU","**올바름.** 벌려 놓은 다음 음수를 잘라요"],["집계 → ReLU → **PairNorm**","ReLU 가 먼저 음수를 잘라 평균이 0 일 수 없어요"]]},{"kind":"points","head":"PairNorm-S 를 쓰는 두 경우","items":["**특징이 이미 중심에 있을 때** 예요. 입력을 미리 표준화했다면 1단계가 거의 아무 일도 안 해요","**절대 위치가 뜻을 가질 때** 예요. 중심을 옮기면 원점에서 얼마나 떨어졌는지가 사라져요","거리 보존 보장은 **크기 맞추기** 에서 와요. 그래서 1단계를 빼도 보장은 그대로예요","이름은 **글자 수가 많은 쪽이 단계가 많다** 고 외우면 쉬워요"]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"PairNorm is inserted right after the aggregation and update step and before the non-linearity, because ReLU would clip negative values and make a zero mean impossible.","ko":"PairNorm 은 집계와 갱신 직후, 비선형 함수 앞에 넣어요. ReLU 가 음수를 잘라 평균 0 을 불가능하게 만들기 때문이에요.","tip":"after A and before B 구조와 because 절을 묶는 틀이에요."},{"kind":"check","q":"**PairNorm-S** 는 어떤 단계를 건너뛰나요?","choices":["크기 맞추기","중심 맞추기","활성화 함수","집계"],"a":1,"why":"S 는 Scale only 의 줄임말이에요. 중심 맞추기를 빼고 크기 맞추기만 해요."},{"kind":"warn","head":"자주 헷갈리는 점","items":["**TPD 보존 보장은 크기 맞추기에서 와요.** 중심 맞추기가 아니에요","CS 는 Center and Scale, S 는 Scale only 예요","영어로는 after aggregation, before non-linearity 라고 그대로 쓰면 좋아요"]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4679,0.1601],"c":[0,0.0019,0.5147,0.1921],"r":4.7633,"img":"img/L5/walk/p067_h.jpg"},"parts":[{"b":[0.06,0.18,0.88,0.07],"c":[0.016,0.1172,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p067_11_01.jpg","say":"**노드끼리 거리와의 관계** 예요. 크기 맞추기 단계가 거리 총합을 그대로 지켜 준다는 것이 수식으로 보장된대요."},{"b":[0.06,0.3,0.88,0.16],"c":[0.016,0.2822,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p067_11_02.jpg","say":"**변형** 이에요. PairNorm-CS 와 PairNorm-S 두 가지예요."},{"b":[0.06,0.52,0.88,0.06],"c":[0.016,0.4522,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p067_11_03.jpg","say":"**넣는 자리** 예요. 집계와 갱신 단계 바로 뒤, 비선형 함수 앞이래요."}]}},{"p":68,"title":"PairNorm 의 효과와 한계","terms":["PairNorm","GCNII","Over-smoothing","GCN"],"pass1":[{"kind":"say","lines":["PairNorm 이 **얻는 것과 못 얻는 것** 을 정직하게 정리하는 장이에요.","평범한 GCN 과 GAT 가 **15층에서 30층까지** 버티게 돼요.","다만 **벌려 놓은 특징이 쓸모 있다는 보장은 없어요.** 이 한계가 시험에 중요해요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"points","head":"한계를 풀어서 생각해요","items":["PairNorm 은 100개 점이 한 곳에 뭉치지 않게 해 줘요","그런데 **어떻게 흩어져야 좋은지는 안 알려 줘요**","같은 종류끼리 모이고 다른 종류끼리 떨어지는 것이 좋은 배치인데, PairNorm 은 총 거리만 맞춰요","같은 종류 노드를 서로 멀리 떼어 놓아도 거리 총합은 똑같아요. 그래서 정확도가 좋아진다는 보장이 없어요"]},{"kind":"analogy","head":"교실에 흩어지라고만 말하기","scene":"선생님이 아이들에게 한 구석에 몰리지 말고 흩어지라고 해요. 아이들은 교실 곳곳에 퍼져요. 그런데 선생님이 원한 것은 키 순서로 줄을 서는 것이었어요. 흩어지기는 했지만 쓸모 있게 흩어진 것은 아니에요.","map":[["한 구석에 몰리는 것","**과도한 평활화(Over-smoothing)**"],["흩어지라고 말하기","**PairNorm**"],["키 순서로 줄 서기","분류에 도움이 되는 배치"]]},{"kind":"compare","head":"다른 처방들과 나란히","cols":["방법","버티는 깊이","보장하는 것"],"rows":[["기본 GCN","2에서 3층","없어요"],["**PairNorm**","**15에서 30층**","거리 총합 보존"],["**GCNII**","64층","입력 정보 유지, 얕은 모델 이상"]]}],"pass3":[{"kind":"warn","head":"서술형에서 꼭 챙길 것","items":["첫 불릿의 계수 이야기는 **행 방향** 이야기예요. 열 방향 무너짐은 별개고 보장이 없어요","15에서 30층은 **PairNorm 만 썼을 때** 예요. 다른 처방과 같이 쓰면 더 깊게도 가요","**한계 문장을 꼭 외우세요.** 장점만 쓰면 점수를 다 못 받아요","핵심 문장은 거리는 지키지만 그 거리가 과제에 유용한지는 보장하지 않는다 예요"]},{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"PairNorm guarantees that node features cannot collapse to a single point, but preventing collapse does not guarantee that the separated representations are useful for the downstream task.","ko":"PairNorm 은 노드 특징이 한 점으로 무너질 수 없음을 보장하지만, 무너짐을 막는 것이 그 결과가 뒤에 할 일에 쓸모 있음을 보장하지는 않아요.","tip":"but 으로 보장과 한계를 한 문장에 담는 틀이에요. 이 한 문장이면 장단점 문제를 덮어요."},{"kind":"check","q":"**PairNorm** 의 한계를 바르게 말한 것은?","choices":["깊이를 전혀 못 늘린다","추가 파라미터가 너무 많다","거리는 지키지만 그 배치가 쓸모 있다는 보장은 없다","그래프를 바꿔 버린다"],"a":2,"why":"PairNorm 은 거리 총합만 지켜요. 어떻게 흩어져야 분류에 좋은지는 보장하지 않아요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4679,0.1715],"c":[0,0.0019,0.5147,0.2035],"r":4.4964,"img":"img/L5/walk/p068_h.jpg"},"parts":[{"b":[0.06,0.2,0.88,0.08],"c":[0.016,0.1422,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p068_11_01.jpg","say":"**이론적 보장** 이에요. 정의상 계수가 완전히 무너질 수 없고, 한 점으로 줄어드는 것이 수식으로 금지된대요."},{"b":[0.06,0.32,0.88,0.08],"c":[0.016,0.2622,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p068_11_02.jpg","say":"**실험에서의 효과** 예요. GCN 이나 GAT 도 정확도가 크게 안 떨어지면서 15에서 30층까지 쌓을 수 있대요."},{"b":[0.06,0.44,0.88,0.08],"c":[0.016,0.3822,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p068_11_03.jpg","say":"**한계** 예요. 빨간 글씨로 **보장하지는 않습니다** 라고 강조돼 있어요."}]}},{"p":69,"title":"드롭아웃: 학습할 때 뉴런을 무작위로 끄기","terms":["Dropout","Overfitting","Regularization","Bernoulli Distribution","Epoch"],"pass1":[{"kind":"say","lines":["**드롭아웃(Dropout)** 은 학습할 때 숫자 칸 일부를 무작위로 0 으로 만드는 기법이에요.","목적은 **과적합(Overfitting)** 을 막는 것이에요.","과적합은 학습에 쓴 답만 통째로 외워서 새 문제를 틀리는 현상이에요."]},{"kind":"analogy","head":"결석이 있는 조별 과제","scene":"여섯 명이 조별 과제를 해요. 늘 같은 두 명만 붙어서 일을 나눠 하면, 그중 한 명이 결석한 날 아무것도 못 해요. 그래서 선생님이 매 시간 주사위를 굴려 몇 명을 빼고 수업을 해요. 그러면 모두가 누가 없어도 돌아가도록 준비하게 돼요.","map":[["매 시간 몇 명을 빼기","**드롭아웃(Dropout)** 으로 칸을 0으로 만들기"],["둘만 붙어서 일하기","몇몇 뉴런끼리만 서로 기대는 일"],["누가 없어도 돌아가기","**과적합(Overfitting)** 이 줄어드는 효과"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"steps","head":"드롭아웃을 숫자로 한 번 해 봐요","steps":["입력 벡터가 2, 4, 6, 8 네 칸이고 끌 확률 p 는 0.5 예요.","칸마다 동전을 던져요. 1번과 4번이 뒷면이 나와 0 이 됐어요.","그러면 0, 4, 6, 0 이 돼요.","살아남은 값은 $1/(1-p)$ 배, 즉 2배로 키워요.","그래서 0, 8, 12, 0 이 돼요. 원래 합 20 과 평균이 맞아요."],"answer":"다음 **에폭(Epoch)** 에는 동전을 다시 던져서 다른 조합이 꺼져요.","given":"**베르누이 분포(Bernoulli Distribution)** 는 동전 던지기처럼 결과가 둘뿐인 분포예요."},{"kind":"points","head":"왜 값을 2배로 키울까요","items":["평가할 때는 **드롭아웃(Dropout)** 을 꺼요. 그러면 모든 칸이 살아 있어요.","학습 때 절반을 끄면 합이 평균적으로 절반이 돼요.","그래서 살아남은 값을 $1/(1-p)$ 배로 키워 크기를 맞춰 줘요.","이렇게 해야 학습 때와 평가 때의 숫자 크기가 어긋나지 않아요."]},{"kind":"mining","src":"마이닝 1강 Intro","lines":["그래프 마이닝에서도 **과적합(Overfitting)** 이라는 말이 나왔어요.","데이터가 적을수록 모델이 답을 외우기 쉬워요.","노드 분류에서는 라벨이 붙은 노드가 아주 적어요.","그래서 **규제(Regularization)** 장치가 특히 필요해요."]}],"pass3":[{"kind":"warn","head":"드롭아웃에서 헷갈리기 쉬운 점","items":["p 는 끌 확률이에요. 0.5 면 절반을 끈다는 뜻이지 절반을 살린다는 뜻이 아니에요.","학습할 때만 켜고 평가할 때는 꺼요. 코드에서 model.train 과 model.eval 이 그 스위치예요.","**드롭아웃(Dropout)** 은 **과적합(Overfitting)** 을 막는 기법이지 과평활화를 직접 막지는 않아요."]},{"kind":"check","q":"**드롭아웃(Dropout)** 의 확률 p 는 무엇을 뜻하나요?","choices":["살릴 확률","끌 확률","학습률","층의 개수"],"a":1,"why":"p 는 각 칸이 0 이 될 확률이에요. **베르누이 분포(Bernoulli Distribution)** 에서 뽑아요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.3444,0.0757],"c":[0,0.0019,0.3789,0.1077],"r":6.2544,"img":"img/L5/walk/p069_h.jpg"},"parts":[{"b":[0.03,0.14,0.94,0.09],"c":[0.0,0.0805,1,0.2089],"r":8.5102,"img":"img/L5/walk/p069_20_01.jpg","say":"첫 줄은 **드롭아웃(Dropout)** 이 **규제(Regularization)** 기법이라는 말이에요. 유닛들이 서로 의존하지 않게 해요."},{"b":[0.03,0.26,0.86,0.05],"c":[0,0.1894,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p069_20_02.jpg","say":"둘째 줄은 학습 중에 **베르누이 분포(Bernoulli Distribution)** 표본으로 원소를 확률 p 로 0 으로 만든다는 말이에요."},{"b":[0.25,0.37,0.24,0.45],"c":[0.238,0.3475,0.264,0.495],"r":0.9481,"img":"img/L5/walk/p069_20_03.jpg","say":"왼쪽 그림이 표준 신경망이에요. 모든 동그라미가 위층 전부와 화살표로 이어져 있어요."},{"b":[0.52,0.37,0.24,0.45],"c":[0.508,0.3475,0.264,0.495],"r":0.9481,"img":"img/L5/walk/p069_20_04.jpg","say":"오른쪽 그림이 드롭아웃을 적용한 뒤예요. X 표시된 동그라미에는 화살표가 하나도 안 붙어 있어요."}]}},{"p":70,"title":"드롭아웃 예제 코드: 층과 층 사이에 한 줄","terms":["Dropout","GCN","ReLU","Overfitting"],"pass1":[{"kind":"say","lines":["**드롭아웃(Dropout)** 코드는 두 줄이면 끝나요.","준비 함수에서 스위치를 하나 만들고, 데이터가 흐를 때 한 번 부르면 돼요.","넣는 자리는 **그래프 합성곱 신경망(GCN)** 층과 층 사이예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"코드 상자에서 핵심 두 줄","boxes":[{"x":0.13,"y":0.6,"w":0.34,"h":0.04,"say":"준비 함수 안의 이 줄이 스위치를 만드는 줄이에요. 아직 아무 일도 안 해요.","c":[0.113,0.565,0.374,0.11],"r":6.0444,"img":"img/L5/walk/p070_20_01.jpg"},{"x":0.13,"y":0.75,"w":0.16,"h":0.04,"say":"데이터가 흐를 때 이 줄이 실제로 절반을 0 으로 만들어요.","c":[0.11,0.715,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p070_20_02.jpg"},{"x":0.13,"y":0.71,"w":0.36,"h":0.04,"say":"그 바로 위가 1층 GCN 과 **렐루(ReLU)** 예요.","c":[0.112,0.675,0.396,0.11],"r":6.4,"img":"img/L5/walk/p070_20_03.jpg"},{"x":0.13,"y":0.79,"w":0.3,"h":0.04,"say":"그 바로 아래가 2층 GCN 이에요. 드롭아웃이 두 층 사이에 끼어 있어요.","c":[0.115,0.755,0.33,0.11],"r":5.3333,"img":"img/L5/walk/p070_20_04.jpg"}]},{"kind":"points","head":"왜 층과 층 사이에 넣나요","items":["1층 결과의 절반이 비어 있으면 2층은 빈칸이 있어도 답을 내는 법을 배워요.","맨 마지막에 넣으면 출력 점수를 직접 망가뜨려서 학습이 흔들려요.","보통은 입력 직후와 층 사이에 넣어요.","p.52 의 **지씨엔 투(GCNII)** 코드도 층 사이마다 드롭아웃을 넣었어요."]},{"kind":"compare","head":"드롭아웃을 쓰는 두 가지 방법","cols":["방식","만들기","학습과 평가 전환"],"rows":[["torch.nn.Dropout","준비 함수에서 한 번 만들어요","model.eval 을 부르면 저절로 꺼져요"],["F.dropout","만들 필요가 없어요","training 인자를 매번 직접 줘야 해요"]]}],"pass3":[{"kind":"warn","head":"코드에서 헷갈리기 쉬운 점","items":["**드롭아웃(Dropout)** 이 끄는 것은 특징 벡터의 칸이에요. 노드나 엣지가 아니에요.","스위치를 만드는 줄과 실제로 부르는 줄은 역할이 달라요.","forward 의 인자 g 와 Kindices 는 이 코드 안에서 한 번도 쓰이지 않아요."]},{"kind":"check","q":"`torch.nn.Dropout` 이 0 으로 만드는 것은 무엇인가요?","choices":["그래프의 엣지","특징 벡터의 칸","노드 전체","가중치 행렬"],"a":1,"why":"엣지나 노드를 지우는 것은 다음 슬라이드의 **드롭엣지(DropEdge)** 와 **드롭노드(DropNode)** 예요."}],"pass4":[{"kind":"code","head":"슬라이드에 인쇄된 코드 전체","file":"L5 슬라이드 p.70","code":"class GCN(torch.nn.Module):\n    def __init__(self, num_features, num_classes, dim=16, drop=0.5):\n        super(GCN, self).__init__()\n        self.conv1 = GCNConv(num_features, dim)\n        self.conv2 = GCNConv(dim, num_classes)\n        self.drop = torch.nn.Dropout(p=drop)\n        self.h = None\n    def forward(self, x, edge_index, g, Kindices):\n        x = F.relu(self.conv1(x, edge_index))\n        x = self.drop(x)\n        x = self.conv2(x, edge_index)\n        self.h = x\n        return F.log_softmax(x, dim=1)","lines":[{"from":1,"to":1,"say":"평범한 2층 **그래프 합성곱 신경망(GCN)** 클래스를 만들어요."},{"from":2,"to":2,"say":"준비 함수예요. dim 은 속에서 쓸 차원 16, drop 은 끌 확률 0.5 가 기본값이에요."},{"from":3,"to":3,"say":"부모 클래스의 준비 함수를 먼저 돌려 줘요."},{"from":4,"to":5,"say":"GCN 층 두 개를 만들어요. 입력 차원에서 16 으로, 16 에서 클래스 수로 줄여요."},{"from":6,"to":6,"say":"여기가 **드롭아웃(Dropout)** 스위치를 만드는 줄이에요. 확률 0.5 짜리예요."},{"from":7,"to":7,"say":"나중에 은닉 표현을 꺼내 볼 자리를 비워 둬요."},{"from":8,"to":8,"say":"데이터가 흐르는 함수예요. g 와 Kindices 는 이 안에서 쓰이지 않아요."},{"from":9,"to":9,"say":"1층 GCN 을 통과시키고 **렐루(ReLU)** 를 씌워요."},{"from":10,"to":10,"say":"여기가 실제로 절반을 0 으로 만드는 줄이에요. 딱 한 줄이에요."},{"from":11,"to":11,"say":"구멍이 뚫린 표현으로 2층 GCN 을 돌려요."},{"from":12,"to":13,"say":"은닉 표현을 저장하고, 노드마다 클래스 확률의 로그를 내보내요."}],"link":"10번 줄 하나가 p.69 에서 배운 드롭아웃 전부예요."},{"kind":"pyterm","name":"함수 인자의 기본값","say":["함수를 만들 때 이름=값 처럼 적으면 그 값이 기본값이 돼요.","부를 때 안 넘기면 기본값이 쓰이고, 넘기면 넘긴 값이 쓰여요.","슬라이드 코드의 dim=16, drop=0.5 가 바로 이것이에요."],"example":"def hi(name, times=2):\n    print(name * times)\n\nhi(\"안녕\")\nhi(\"안녕\", 3)","out":"안녕안녕\n안녕안녕안녕"}],"walk":{"head":{"b":[0.0131,0.0179,0.46,0.0757],"c":[0,0.0019,0.5061,0.1077],"r":8.3541,"img":"img/L5/walk/p070_h.jpg"},"parts":[{"b":[0.03,0.14,0.9,0.24],"c":[0,0.124,0.99,0.272],"r":6.4706,"img":"img/L5/walk/p070_11_01.jpg","say":"위쪽은 문서 설명이에요. 학습 중에 확률 p 로 0 으로 만들고, 순전파마다 채널이 따로 0 이 된다고 적혀 있어요."},{"b":[0.03,0.4,0.94,0.52],"c":[0.0,0.374,1,0.572],"r":3.108,"img":"img/L5/walk/p070_11_02.jpg","say":"아래 검은 상자가 2층 GCN 클래스 전체예요. 코드는 영어 그대로 인쇄돼 있어요."}]}},{"p":71,"title":"DropEdge 와 DropNode: 선과 점을 지운다","terms":["DropEdge","DropNode","Dropout","Data Augmentation","Epoch","Over-smoothing","Overfitting"],"pass1":[{"kind":"say","lines":["**드롭아웃(Dropout)** 은 숫자 칸을 지웠죠.","이번에는 지우는 대상이 그래프 자체예요.","**드롭엣지(DropEdge)** 는 선을, **드롭노드(DropNode)** 는 점을 무작위로 지워요.","이것은 **과적합(Overfitting)** 뿐 아니라 **과평활화(Over-smoothing)** 까지 덜어 줘요."]},{"kind":"analogy","head":"길을 몇 개 막고 다니는 연습","scene":"동네에 길이 여러 갈래 있어요. 매일 아침 주사위를 굴려 길 몇 개를 막아요. 아이들은 그날 다른 길로 돌아가야 해요. 날마다 막히는 길이 달라요. 그래서 한 길에만 의존하지 않고 동네 전체를 알게 돼요. 소문이 퍼지는 속도도 느려져요.","map":[["매일 길 몇 개 막기","**드롭엣지(DropEdge)** 로 엣지 지우기"],["한 길에만 의존하지 않기","**과적합(Overfitting)** 이 줄어드는 효과"],["소문이 느리게 퍼지기","**과평활화(Over-smoothing)** 가 늦춰지는 효과"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"compare","head":"셋을 한 줄로 구별해요","cols":["기법","지우는 대상","효과"],"rows":[["**드롭아웃(Dropout)**","특징 벡터의 칸","**과적합(Overfitting)** 완화"],["**드롭엣지(DropEdge)**","그래프의 엣지","과적합과 **과평활화(Over-smoothing)** 완화"],["**드롭노드(DropNode)**","노드와 그 노드의 엣지 전부","같은 효과이지만 더 셈"]]},{"kind":"steps","head":"엣지를 지우면 무엇이 달라지나요","steps":["노드 4개에 엣지 1과 2, 1과 3, 2와 3, 3과 4 가 있어요.","이번 **에폭(Epoch)** 에 엣지 1과 3, 그리고 3과 4 가 지워졌다고 해요.","남은 엣지는 1과 2, 2와 3 두 개예요.","차수가 2, 2, 3, 1 에서 1, 2, 1, 0 으로 바뀌어요.","노드 4 는 이웃이 하나도 없어서 이 판에서는 완전히 혼자예요."],"answer":"노드 4 는 이 판에서 아무와도 섞이지 않아요. 다음 판에는 다시 이어질 수 있어요.","given":"**드롭엣지(DropEdge)** 를 확률 0.5 로 돌린 한 판이에요."},{"kind":"figure","head":"선만 지우기와 점까지 지우기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"70\" y=\"26\" font-size=\"16\" text-anchor=\"middle\">원본<\/text>\n<line class=\"e\" x1=\"36\" y1=\"70\" x2=\"104\" y2=\"70\"/>\n<line class=\"e\" x1=\"36\" y1=\"70\" x2=\"70\" y2=\"124\"/>\n<line class=\"e\" x1=\"104\" y1=\"70\" x2=\"70\" y2=\"124\"/>\n<line class=\"e\" x1=\"70\" y1=\"124\" x2=\"122\" y2=\"156\"/>\n<circle class=\"n\" cx=\"36\" cy=\"70\" r=\"15\"/><text class=\"tl\" x=\"36\" y=\"75\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<circle class=\"n\" cx=\"104\" cy=\"70\" r=\"15\"/><text class=\"tl\" x=\"104\" y=\"75\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<circle class=\"n2\" cx=\"70\" cy=\"124\" r=\"15\"/><text class=\"tl\" x=\"70\" y=\"129\" font-size=\"14\" text-anchor=\"middle\">3<\/text>\n<circle class=\"n\" cx=\"122\" cy=\"156\" r=\"15\"/><text class=\"tl\" x=\"122\" y=\"161\" font-size=\"14\" text-anchor=\"middle\">4<\/text>\n<text class=\"tm\" x=\"70\" y=\"196\" font-size=\"14\" text-anchor=\"middle\">엣지 4개<\/text>\n<text class=\"tb b1\" x=\"240\" y=\"26\" font-size=\"16\" text-anchor=\"middle\">DropEdge<\/text>\n<line class=\"e b1\" x1=\"206\" y1=\"70\" x2=\"274\" y2=\"70\"/>\n<line class=\"hl b1\" x1=\"206\" y1=\"70\" x2=\"240\" y2=\"124\"/>\n<line class=\"e b1\" x1=\"274\" y1=\"70\" x2=\"240\" y2=\"124\"/>\n<line class=\"e b1\" x1=\"240\" y1=\"124\" x2=\"292\" y2=\"156\"/>\n<circle class=\"n b1\" cx=\"206\" cy=\"70\" r=\"15\"/><text class=\"tl b1\" x=\"206\" y=\"75\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<circle class=\"n b1\" cx=\"274\" cy=\"70\" r=\"15\"/><text class=\"tl b1\" x=\"274\" y=\"75\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<circle class=\"n2 b1\" cx=\"240\" cy=\"124\" r=\"15\"/><text class=\"tl b1\" x=\"240\" y=\"129\" font-size=\"14\" text-anchor=\"middle\">3<\/text>\n<circle class=\"n b1\" cx=\"292\" cy=\"156\" r=\"15\"/><text class=\"tl b1\" x=\"292\" y=\"161\" font-size=\"14\" text-anchor=\"middle\">4<\/text>\n<text class=\"tm b1\" x=\"240\" y=\"196\" font-size=\"14\" text-anchor=\"middle\">선 하나만 사라져요<\/text>\n<text class=\"tb b2\" x=\"404\" y=\"26\" font-size=\"16\" text-anchor=\"middle\">DropNode<\/text>\n<line class=\"e b2\" x1=\"370\" y1=\"70\" x2=\"438\" y2=\"70\"/>\n<line class=\"hl b2\" x1=\"370\" y1=\"70\" x2=\"404\" y2=\"124\"/>\n<line class=\"hl b2\" x1=\"438\" y1=\"70\" x2=\"404\" y2=\"124\"/>\n<line class=\"hl b2\" x1=\"404\" y1=\"124\" x2=\"456\" y2=\"156\"/>\n<circle class=\"n b2\" cx=\"370\" cy=\"70\" r=\"15\"/><text class=\"tl b2\" x=\"370\" y=\"75\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<circle class=\"n b2\" cx=\"438\" cy=\"70\" r=\"15\"/><text class=\"tl b2\" x=\"438\" y=\"75\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<circle class=\"n4 b2\" cx=\"404\" cy=\"124\" r=\"15\"/><text class=\"tl b2\" x=\"404\" y=\"129\" font-size=\"14\" text-anchor=\"middle\">3<\/text>\n<circle class=\"n b2\" cx=\"456\" cy=\"156\" r=\"15\"/><text class=\"tl b2\" x=\"456\" y=\"161\" font-size=\"14\" text-anchor=\"middle\">4<\/text>\n<text class=\"tm b2\" x=\"404\" y=\"196\" font-size=\"14\" text-anchor=\"middle\">점과 선 세 개가 같이 사라져요<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"232\" font-size=\"16\" text-anchor=\"middle\">노드를 지우면 붙은 엣지가 전부 따라 사라져요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"256\" font-size=\"14\" text-anchor=\"middle\">그래서 DropNode 는 확률을 더 작게 잡아요<\/text>\n<\/svg>","caption":"노드를 지우면 붙은 엣지가 전부 따라 사라져요.","builds":3}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"DropEdge randomly removes a fraction of edges at every training epoch, which acts as data augmentation and slows down message passing.","ko":"DropEdge 는 매 학습 에폭마다 엣지 일부를 무작위로 제거하는데, 이것은 데이터 증강처럼 작동하고 메시지 전달을 늦춘다.","tip":"**드롭아웃(Dropout)** 과의 차이를 한 줄 덧붙이면 좋아요. 드롭아웃은 특징 칸, DropEdge 는 엣지예요."},{"kind":"warn","head":"여기서 헷갈리기 쉬워요","items":["**드롭엣지(DropEdge)** 는 학습 판마다 새로 뽑아요. 한 번 지우고 끝이 아니에요.","평가할 때는 원래 그래프 전체를 써요.","슬라이드 그림의 빨간 선은 잘못된 엣지가 아니라 지우기로 고른 엣지를 강조한 표시예요."]},{"kind":"check","q":"**드롭엣지(DropEdge)** 가 **과평활화(Over-smoothing)** 까지 덜어 주는 이유는 무엇인가요?","choices":["가중치가 줄어서","섞임이 일어나는 통로인 엣지가 줄어서","노드 수가 줄어서","학습률이 낮아져서"],"a":1,"why":"엣지가 20 퍼센트 줄면 그 판에서는 섞임도 그만큼 덜 일어나요. 메시지 전달 속도가 느려지는 거예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2437,0.0757],"c":[0.0009,0.0019,0.2681,0.1077],"r":4.4255,"img":"img/L5/walk/p071_h.jpg"},"parts":[{"b":[0.03,0.14,0.86,0.06],"c":[0,0.0744,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p071_20_01.jpg","say":"첫 줄은 학습 **에폭(Epoch)** 마다 엣지나 노드를 무작위로 지운다는 말이에요."},{"b":[0.03,0.24,0.94,0.1],"c":[0.0,0.1855,1,0.2089],"r":8.5102,"img":"img/L5/walk/p071_20_02.jpg","say":"둘째 줄은 이것을 **데이터 증강(Data Augmentation)** 으로 볼 수 있다는 말이에요."},{"b":[0.43,0.44,0.12,0.13],"c":[0.39,0.424,0.2,0.162],"r":2.1948,"img":"img/L5/walk/p071_20_03.jpg","say":"위쪽 화살표가 Drop Nodes 예요. 도착한 그림에서 오른쪽 점 하나가 회색 점선으로 사라졌어요."},{"b":[0.42,0.66,0.12,0.14],"c":[0.38,0.644,0.2,0.172],"r":2.0672,"img":"img/L5/walk/p071_20_04.jpg","say":"아래쪽 화살표가 Drop Edges 예요. 도착한 그림에서 빨간 선 하나가 회색 점선이 됐어요."}]}},{"p":72,"title":"dropout_node 와 dropout_edge 함수","terms":["DropEdge","DropNode","Dropout","Bernoulli Distribution"],"pass1":[{"kind":"say","lines":["PyTorch Geometric 안에 이미 함수 두 개가 준비돼 있어요.","이름이 dropout_node 와 dropout_edge 예요.","둘 다 엣지 목록을 받아서, 일부가 빠진 엣지 목록을 돌려줘요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.04,"y":0.16,"w":0.42,"h":0.06,"say":"굵은 머리글이에요. 그런데 이 줄에는 문제가 있어요. 3회독 주의 카드에서 설명할게요.","c":[0.019,0.135,0.462,0.11],"r":7.4667,"img":"img/L5/walk/p072_20_01.jpg"},{"x":0.06,"y":0.23,"w":0.8,"h":0.05,"say":"첫 항목은 엣지 목록에서 **베르누이 분포(Bernoulli Distribution)** 표본으로 노드를 지운다는 말이에요.","c":[0.02,0.1661,0.88,0.1778],"r":8.7989,"img":"img/L5/walk/p072_20_02.jpg"},{"x":0.06,"y":0.59,"w":0.82,"h":0.05,"say":"둘째 항목은 같은 방식으로 엣지를 지운다는 말이에요.","c":[0.019,0.5239,0.902,0.1822],"r":8.8011,"img":"img/L5/walk/p072_20_03.jpg"},{"x":0.02,"y":0.94,"w":0.42,"h":0.04,"say":"맨 아래 출처가 PyTorch Geometric 의 utils 문서예요. 여기가 중요해요.","c":[0,0.89,0.462,0.11],"r":7.4667,"img":"img/L5/walk/p072_20_04.jpg"}]},{"kind":"compare","head":"인자 하나씩","cols":["인자","뜻","어느 함수"],"rows":[["edge_index","엣지 목록. 첫 줄이 출발, 둘째 줄이 도착이에요","둘 다"],["p","지울 확률. 기본값 0.5 예요","둘 다"],["training","참이면 실제로 지우고 거짓이면 그대로 둬요","둘 다"],["relabel_nodes","노드를 지운 뒤 번호를 0부터 다시 매길지","dropout_node"],["force_undirected","양방향 짝을 맞춰 지울지","dropout_edge"]]},{"kind":"steps","head":"같은 그래프에 두 함수를 돌려 봐요","steps":["무방향 엣지 4개를 양방향으로 적으면 줄이 8개예요.","**드롭엣지(DropEdge)** 로 엣지 0과 2, 2와 3 이 뽑히면 줄 4개가 빠져요.","남는 줄은 4개이고 노드 3 만 혼자가 돼요.","**드롭노드(DropNode)** 로 노드 2 가 뽑히면 노드 2 가 나오는 줄이 전부 빠져요.","노드 2 는 차수가 3 이라 줄 6개가 한꺼번에 사라져요."],"answer":"남는 줄이 2개뿐이에요. 노드를 지우는 쪽이 훨씬 세게 그래프를 바꿔요.","given":"노드는 0, 1, 2, 3 이고 엣지는 0과 1, 0과 2, 1과 2, 2와 3 이에요."},{"kind":"points","head":"돌려주는 값이 달라요","items":["dropout_edge 는 값 두 개를 돌려줘요. 새 엣지 목록과 엣지 마스크예요.","dropout_node 는 값 세 개를 돌려줘요. 여기에 노드 마스크가 더 붙어요.","마스크는 참과 거짓이 줄줄이 늘어선 표예요. 누가 살아남았는지 알려 줘요.","보통은 안 쓰니 밑줄 하나로 받아 버려요."]}],"pass3":[{"kind":"warn","head":"슬라이드에 잘못된 부분이 있어요","items":["이 슬라이드의 머리글이 torch.nn.Dropout 에서 라고 적혀 있는데 틀렸어요.","dropout_node 와 dropout_edge 는 torch_geometric.utils 에 들어 있는 함수예요.","p.70 의 머리글을 그대로 옮겨 온 것으로 보여요. 맨 아래 출처 링크가 utils 문서를 가리켜요.","그리고 edge_index 를 인접행렬이라고 불렀지만 실제로는 엣지 목록이에요."]},{"kind":"check","q":"dropout_edge 함수는 어느 모듈에 들어 있나요?","choices":["torch.nn.Dropout","torch_geometric.utils","torch.optim","torch_geometric.datasets"],"a":1,"why":"슬라이드 머리글은 틀렸고, 맨 아래 출처 링크가 정답을 알려 줘요."}],"pass4":[{"kind":"code","head":"슬라이드에 인쇄된 함수 서명 두 개","file":"L5 슬라이드 p.72","code":"dropout_node ( edge_index: Tensor, p: float = 0.5, num_nodes: Optional[int] = None, training: bool =\nTrue, relabel_nodes: bool = False ) -> Tuple[Tensor, Tensor, Tensor]\n\ndropout_edge ( edge_index: Tensor, p: float = 0.5, force_undirected: bool = False, training: bool =\nTrue ) -> Tuple[Tensor, Tensor]","lines":[{"from":1,"to":2,"say":"dropout_node 의 서명이에요. 엣지 목록과 확률, 노드 수, 학습 여부, 번호 다시 매기기를 받아요."},{"from":4,"to":5,"say":"dropout_edge 의 서명이에요. 엣지 목록과 확률, 무방향 강제, 학습 여부를 받아요."}],"link":"둘 다 p.71 에서 배운 **드롭엣지(DropEdge)** 와 **드롭노드(DropNode)** 를 그대로 구현한 함수예요."},{"kind":"pyterm","name":"돌려주는 값이 여러 개일 때","say":["파이썬 함수는 값을 여러 개 한 번에 돌려줄 수 있어요.","받을 때는 쉼표로 나란히 적어요. 안 쓸 값은 밑줄 하나로 받는 것이 관습이에요.","p.73 코드의 edge_index1, _ = dropout_edge(...) 가 바로 이 모양이에요."],"example":"def two():\n    return 10, 20\n\na, _ = two()\nprint(a)","out":"10"}],"walk":{"head":{"b":[0.0131,0.0179,0.8075,0.2637],"c":[0,0.0019,0.8883,0.2957],"r":5.3405,"img":"img/L5/walk/p072_h.jpg"},"parts":[{"b":[0.17,0.37,0.56,0.16],"c":[0.142,0.354,0.616,0.192],"r":5.7037,"img":"img/L5/walk/p072_11_01.jpg","say":"위 하늘색 상자가 dropout_node 함수의 설명이에요. 노드를 확률 p 로 지워요."},{"b":[0.18,0.72,0.58,0.16],"c":[0.151,0.704,0.638,0.192],"r":5.9074,"img":"img/L5/walk/p072_11_02.jpg","say":"아래 상자가 dropout_edge 함수의 설명이에요. 엣지를 확률 p 로 지워요."}]}},{"p":73,"title":"DropEdge 학습 루프: 에폭마다 새로 지운다","terms":["DropEdge","Epoch","Dropout","Overfitting"],"pass1":[{"kind":"say","lines":["학습 반복문 안에서 **드롭엣지(DropEdge)** 를 한 번 부르면 끝이에요.","핵심은 그 한 줄이 **에폭(Epoch)** 마다 다시 실행된다는 점이에요.","그래서 판마다 그래프가 조금씩 달라져요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"코드에서 딱 두 줄만","boxes":[{"x":0.11,"y":0.51,"w":0.38,"h":0.04,"say":"이 줄이 **드롭엣지(DropEdge)** 예요. 반복문 안에 있으니 판마다 새로 지워요.","c":[0.091,0.475,0.418,0.11],"r":6.7556,"img":"img/L5/walk/p073_20_01.jpg"},{"x":0.11,"y":0.54,"w":0.3,"h":0.04,"say":"바로 아래에서 원본이 아니라 새 엣지 목록을 모델에 넣어요.","c":[0.095,0.505,0.33,0.11],"r":5.3333,"img":"img/L5/walk/p073_20_02.jpg"},{"x":0.09,"y":0.42,"w":0.28,"h":0.04,"say":"그 위가 반복문 시작이에요. 0부터 15까지 돌아요.","c":[0.076,0.385,0.308,0.11],"r":4.9778,"img":"img/L5/walk/p073_20_03.jpg"},{"x":0.09,"y":0.9,"w":0.14,"h":0.04,"say":"맨 아래에서 학습이 끝난 모델을 돌려줘요.","c":[0.06,0.865,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p073_20_04.jpg"}]},{"kind":"points","head":"한 바퀴의 순서를 외워요","items":["먼저 기울기를 0 으로 비워요.","그다음 **드롭엣지(DropEdge)** 로 새 엣지 목록을 만들어요.","그 목록으로 순전파를 하고 손실을 계산해요.","마지막으로 역전파를 하고 파라미터를 고쳐요."]},{"kind":"steps","head":"화면에 찍히는 줄을 읽는 법","steps":["Train Loss 가 내려가면 학습이 되고 있다는 뜻이에요.","Train Acc 가 올라가면 학습에 쓴 노드를 잘 맞힌다는 뜻이에요.","Val Loss 와 Val Acc 는 학습에 안 쓴 노드에서 잰 값이에요.","Train Acc 는 오르는데 Val Acc 가 멈추면 그때가 **과적합(Overfitting)** 이 시작되는 지점이에요.","그래서 **드롭엣지(DropEdge)** 로 이 격차를 줄이려는 거예요."],"answer":"진짜 실력은 언제나 Val 쪽 숫자예요.","given":"epochs 가 15 라 열여섯 줄이 찍혀요."}],"pass3":[{"kind":"warn","head":"코드에서 헷갈리기 쉬운 점","items":["dropout_edge 호출이 반복문 안에 있어야 해요. 밖에 두면 한 번 지운 그래프로 끝까지 학습해요.","모델에 새 엣지 목록을 넣는 것을 잊으면 아무 효과가 없어요.","슬라이드 코드는 엣지가 지워진 그래프로 검증까지 해요. 원래는 원본으로 다시 순전파해야 정확해요.","주석은 10 에폭마다 출력한다고 했지만 조건이 1 로 나눈 나머지라 매번 출력해요."]},{"kind":"check","q":"**드롭엣지(DropEdge)** 호출을 학습 반복문 밖에 두면 어떻게 되나요?","choices":["더 빨라진다","한 번 지운 그래프로 끝까지 학습해서 DropEdge 가 아니게 된다","정확도가 오른다","아무 차이가 없다"],"a":1,"why":"핵심은 **에폭(Epoch)** 마다 다른 엣지가 지워지는 것이에요. 밖에 두면 그 성질이 사라져요."}],"pass4":[{"kind":"code","head":"슬라이드에 인쇄된 학습 함수 전체","file":"L5 슬라이드 p.73","code":"def train_dropEdges(model, data):\n    \"\"\"Train a GNN model and return the trained model.\"\"\"\n    criterion = torch.nn.CrossEntropyLoss()\n    optimizer = model.optimizer\n    epochs = 15\n    model.train()\n    for epoch in range(epochs+1):\n        # Training\n        optimizer.zero_grad()\n        edge_index1, _ = dropout_edge(data.edge_index, p=0.5)\n        _, out = model(data.x, edge_index1 )\n        loss = criterion(out[data.train_mask], data.y[data.train_mask])\n        acc = accuracy(out[data.train_mask].argmax(dim=1), data.y[data.train_mask])\n        loss.backward()\n        optimizer.step()\n        # Validation\n        val_loss = criterion(out[data.val_mask], data.y[data.val_mask])\n        val_acc = accuracy(out[data.val_mask].argmax(dim=1), data.y[data.val_mask])\n        # Print metrics every 10 epochs\n        if(epoch % 1 == 0):\n            print(f'Epoch {epoch:>3} | Train Loss: {loss:.3f} | Train Acc: '\n                  f'{acc*100:>6.2f}% | Val Loss: {val_loss:.2f} | '\n                  f'Val Acc: {val_acc*100:.2f}%')\n    return model","lines":[{"from":1,"to":2,"say":"모델과 데이터를 받아 학습시키는 함수예요. 둘째 줄은 설명글이라 실행에 영향이 없어요."},{"from":3,"to":4,"say":"손실 함수와 최적화기를 꺼내요. 손실 함수는 예측과 정답이 얼마나 다른지를 재요."},{"from":5,"to":6,"say":"열다섯 바퀴를 돌겠다고 정하고, 학습 모드로 바꿔요. 이 줄이 있어야 **드롭아웃(Dropout)** 이 작동해요."},{"from":7,"to":9,"say":"반복문 시작이에요. 지난 바퀴에 쌓인 기울기를 0 으로 비워요."},{"from":10,"to":10,"say":"여기가 **드롭엣지(DropEdge)** 예요. 원본은 그대로 두고 절반이 빠진 새 목록을 만들어요."},{"from":11,"to":11,"say":"원본이 아니라 새 목록으로 순전파해요. 여기를 원본으로 쓰면 효과가 없어요."},{"from":12,"to":13,"say":"학습용으로 표시된 노드만 골라 손실과 정확도를 계산해요."},{"from":14,"to":15,"say":"역전파로 기울기를 구하고, 그 기울기로 파라미터를 실제로 고쳐요."},{"from":16,"to":18,"say":"학습에 쓰지 않은 검증 노드에서 손실과 정확도를 재요."},{"from":19,"to":23,"say":"매 **에폭(Epoch)** 마다 네 숫자를 한 줄로 찍어요. 중괄호 안의 값이 자리에 들어가요."},{"from":24,"to":24,"say":"학습이 끝난 모델을 돌려줘요."}],"link":"10번 줄 하나가 p.71 에서 배운 **드롭엣지(DropEdge)** 의 전부예요."},{"kind":"pyterm","name":"에프 문자열(f-string)","say":["따옴표 앞에 f 를 붙이면 중괄호 안의 값이 그 자리에 들어가요.","콜론 뒤는 모양을 정해요. 점 3 f 는 소수점 셋째 자리까지라는 뜻이에요.","부등호 3 은 오른쪽 정렬로 세 칸을 쓰라는 뜻이에요."],"example":"epoch = 7\nloss = 1.23456\nprint(f'Epoch {epoch:>3} | Loss: {loss:.3f}')","out":"Epoch   7 | Loss: 1.235"},{"kind":"warn","head":"5주차 코드에 대한 안내","items":["5주차에는 실습 노트북이 없어요. 여기 코드는 슬라이드에 인쇄된 그대로예요.","accuracy 함수는 슬라이드 밖에서 따로 만들어 둔 것이라 여기에는 안 보여요.","코드를 외울 필요는 없어요. 반복문 안의 한 줄이 어디인지만 알면 돼요."]}],"walk":{"head":{"b":[0.0131,0.0179,0.4788,0.0757],"c":[0,0.0019,0.5267,0.1077],"r":8.6941,"img":"img/L5/walk/p073_h.jpg"},"parts":[{"b":[0.04,0.13,0.42,0.06],"c":[0.019,0.105,0.462,0.11],"r":7.4667,"img":"img/L5/walk/p073_11_01.jpg","say":"첫 줄은 에폭마다 엣지와 노드를 무작위로 지운다는 말이에요."},{"b":[0.04,0.2,0.32,0.06],"c":[0.024,0.175,0.352,0.11],"r":5.6889,"img":"img/L5/walk/p073_11_02.jpg","say":"둘째 줄은 예제 코드를 같이 해 보자는 말이에요."},{"b":[0.03,0.26,0.94,0.66],"c":[0.0,0.227,1,0.726],"r":2.4487,"img":"img/L5/walk/p073_11_03.jpg","say":"아래 검은 상자가 학습 함수 전체예요. 코드는 영어 그대로 인쇄돼 있어요."}]}},{"p":74,"title":"그래프 재배선: 그래프의 모양 자체를 고친다","terms":["Over-squashing","Bottleneck","Over-smoothing"],"pass1":[{"kind":"say","lines":["새 묶음이 시작돼요. 제목은 **그래프 재배선** 이에요.","지금까지는 모델을 고쳤는데, 이번에는 **그래프를 고쳐요.**","엣지를 더하거나 지워서 **병목** 을 푸는 일이에요."]},{"kind":"analogy","head":"마을 두 개와 다리 하나","scene":"강을 사이에 두고 마을이 둘 있어요. 왼쪽 마을에 사람이 천 명 살아요. 두 마을을 잇는 것은 좁은 다리 하나뿐이에요. 왼쪽 사람들이 오른쪽에 소식을 전하려면 모두 그 다리를 건너야 해요. 다리가 좁으니 천 개의 소식이 몇 마디로 뭉개져서 넘어가요. 그래서 다리를 몇 개 더 놓자는 것이 재배선이에요.","map":[["좁은 다리 하나","**병목(Bottleneck)**"],["소식이 뭉개지는 것","**과도한 압착(Over-squashing)**"],["다리를 더 놓기","엣지를 더하는 재배선"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"compare","head":"과평활과 과압착은 다른 병이에요","cols":["","**과도한 평활화(Over-smoothing)**","**과도한 압착(Over-squashing)**"],"rows":[["무슨 일","노드 표현이 서로 같아져요","먼 정보가 뭉개져 도착해요"],["원인","이웃 평균을 너무 많이 반복","그래프에 좁은 길이 있음"],["고치는 법","스킵 연결, 정규화","**재배선**"],["그래프를 바꾸나","아니요","**예**"]]},{"kind":"figure","head":"병목이 있는 그래프와 길을 넓힌 그래프","svg":"<svg viewBox=\"0 0 480 200\">\n <text class=\"tb\" x=\"118\" y=\"22\" text-anchor=\"middle\" font-size=\"15\">재배선 전: 다리 하나<\/text>\n <circle class=\"n\" cx=\"36\" cy=\"60\" r=\"12\"/>\n <circle class=\"n\" cx=\"36\" cy=\"96\" r=\"12\"/>\n <circle class=\"n\" cx=\"36\" cy=\"132\" r=\"12\"/>\n <circle class=\"n\" cx=\"86\" cy=\"96\" r=\"12\"/>\n <line class=\"e\" x1=\"46\" y1=\"65\" x2=\"76\" y2=\"90\"/>\n <line class=\"e\" x1=\"46\" y1=\"96\" x2=\"74\" y2=\"96\"/>\n <line class=\"e\" x1=\"46\" y1=\"127\" x2=\"76\" y2=\"102\"/>\n <circle class=\"n3\" cx=\"162\" cy=\"96\" r=\"12\"/>\n <line class=\"e2 b1\" x1=\"98\" y1=\"96\" x2=\"150\" y2=\"96\"/>\n <text class=\"tb b1\" x=\"124\" y=\"86\" text-anchor=\"middle\" font-size=\"14\">병목<\/text>\n <circle class=\"n3\" cx=\"206\" cy=\"60\" r=\"12\"/>\n <circle class=\"n3\" cx=\"206\" cy=\"96\" r=\"12\"/>\n <circle class=\"n3\" cx=\"206\" cy=\"132\" r=\"12\"/>\n <line class=\"e\" x1=\"172\" y1=\"91\" x2=\"196\" y2=\"66\"/>\n <line class=\"e\" x1=\"174\" y1=\"96\" x2=\"194\" y2=\"96\"/>\n <line class=\"e\" x1=\"172\" y1=\"101\" x2=\"196\" y2=\"126\"/>\n <text class=\"t b1\" x=\"118\" y=\"172\" text-anchor=\"middle\" font-size=\"13\">왼쪽 정보 전부가 선 하나로 눌려 가요<\/text>\n <text class=\"tb\" x=\"364\" y=\"22\" text-anchor=\"middle\" font-size=\"15\">재배선 후: 길이 늘어남<\/text>\n <circle class=\"n\" cx=\"282\" cy=\"60\" r=\"12\"/>\n <circle class=\"n\" cx=\"282\" cy=\"96\" r=\"12\"/>\n <circle class=\"n\" cx=\"282\" cy=\"132\" r=\"12\"/>\n <circle class=\"n\" cx=\"332\" cy=\"96\" r=\"12\"/>\n <line class=\"e\" x1=\"292\" y1=\"65\" x2=\"322\" y2=\"90\"/>\n <line class=\"e\" x1=\"292\" y1=\"96\" x2=\"320\" y2=\"96\"/>\n <line class=\"e\" x1=\"292\" y1=\"127\" x2=\"322\" y2=\"102\"/>\n <circle class=\"n3\" cx=\"408\" cy=\"96\" r=\"12\"/>\n <line class=\"e\" x1=\"344\" y1=\"96\" x2=\"396\" y2=\"96\"/>\n <line class=\"e2 b2\" x1=\"290\" y1=\"56\" x2=\"442\" y2=\"56\"/>\n <line class=\"e2 b2\" x1=\"290\" y1=\"136\" x2=\"442\" y2=\"136\"/>\n <circle class=\"n3\" cx=\"452\" cy=\"60\" r=\"12\"/>\n <circle class=\"n3\" cx=\"452\" cy=\"96\" r=\"12\"/>\n <circle class=\"n3\" cx=\"452\" cy=\"132\" r=\"12\"/>\n <line class=\"e\" x1=\"418\" y1=\"91\" x2=\"442\" y2=\"66\"/>\n <line class=\"e\" x1=\"420\" y1=\"96\" x2=\"440\" y2=\"96\"/>\n <line class=\"e\" x1=\"418\" y1=\"101\" x2=\"442\" y2=\"126\"/>\n <text class=\"t b2\" x=\"364\" y=\"172\" text-anchor=\"middle\" font-size=\"13\">굵은 선 둘을 새로 더해 길을 넓혔어요<\/text>\n<\/svg>","caption":"굵은 선 하나로 몰리던 정보가 세 갈래로 나뉘어요.","builds":2},{"kind":"points","head":"이 묶음에서 배울 것","items":["p.75 부터 p.78 까지는 **곡률** 로 그래프 모양을 숫자로 재는 법이에요","p.79 가 **SDRF**, 굽은 곳을 하나씩 펴는 방법이에요","p.80 이 SDRF 의 한계, p.81 부터 p.83 이 배치로 처리하는 **BORF** 예요","큰 줄기는 어디가 좁은지 숫자로 재고, 그 자리에 엣지를 더하고, 쓸모없는 엣지를 빼는 것이에요"]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"Graph rewiring adds and removes edges to change the topology itself, which relieves over-squashing, the compression of information from a large neighborhood through a narrow bottleneck.","ko":"그래프 재배선은 엣지를 더하고 지워 위상 자체를 바꿔서, 넓은 이웃의 정보가 좁은 병목을 지나며 눌리는 과도한 압착을 풀어 줘요.","tip":"which 절로 효과를, 동격 콤마로 용어 뜻을 붙이는 틀이에요."},{"kind":"check","q":"재배선이 겨냥하는 병은 무엇인가요?","choices":["**과도한 평활화(Over-smoothing)**","**과도한 압착(Over-squashing)**","**과적합(Overfitting)**","기울기 소실"],"a":1,"why":"재배선은 그래프의 **병목(Bottleneck)** 을 풀어서 과도한 압착을 다뤄요. 과평활은 앞의 처방들이 맡아요."}],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.04,0.38,0.3,0.09],"c":[0.025,0.364,0.33,0.122],"r":4.8087,"img":"img/L5/walk/p074_12_01.jpg","say":"제목이 **그래프 재배선** 이에요."},{"b":[0.04,0.5,0.52,0.06],"c":[0.014,0.4722,0.572,0.1156],"r":8.7966,"img":"img/L5/walk/p074_12_02.jpg","say":"아래 한 줄이에요. 병목을 풀려고 엣지를 더하거나 지우는 일이래요."}]}},{"p":75,"title":"SDRF: 그래프의 모양을 숫자로 재기","terms":["SDRF","Rewiring","Curvature","Over-squashing","Over-smoothing","Bottleneck"],"pass1":[{"kind":"say","lines":["지금까지는 모델과 학습을 고쳤어요. 이번에는 그래프 자체를 고쳐요.","이것을 **재배선(Rewiring)** 이라고 해요.","그러려면 여기가 병목이라는 것을 숫자로 알아야 하는데, 그 숫자가 **곡률(Curvature)** 이에요.","첫 모델 이름이 **에스디알에프(SDRF)** 예요."]},{"kind":"analogy","head":"친구 사이의 다리","scene":"나와 친구 하나가 이어져 있어요. 공통 친구가 많으면 우리가 싸워도 소식은 다른 친구를 통해 전해져요. 그런데 공통 친구가 없고 그 친구만이 다른 반과 나를 잇는 통로라면, 그 친구가 빠지는 순간 두 무리가 끊어져요. 이 차이를 숫자로 적은 것이 곡률이에요.","map":[["공통 친구가 많은 사이","양의 **곡률(Curvature)**"],["유일한 통로가 되는 사이","음의 **곡률(Curvature)**, 즉 **병목(Bottleneck)**"],["끊어지면 소식이 안 감","**과압착(Over-squashing)** 이 생기는 자리"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"compare","head":"곡률의 부호가 알려 주는 것","cols":["주변 모양","공통 이웃","**곡률(Curvature)**","GNN 에 생기는 문제"],"rows":[["삼각형","많아요","양수","**과평활화(Over-smoothing)** 를 부추겨요"],["격자","없지만 우회로가 있어요","0","중간이에요"],["다리","없어요","음수","**과압착(Over-squashing)** 을 일으켜요"]]},{"kind":"figure","head":"주변 모양과 곡률의 부호","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"17\" text-anchor=\"middle\">주변 모양이 곡률의 부호를 정해요<\/text>\n<text class=\"tm\" x=\"78\" y=\"54\" font-size=\"14\" text-anchor=\"middle\">삼각형: 양수<\/text>\n<line class=\"e2\" x1=\"44\" y1=\"110\" x2=\"112\" y2=\"110\"/>\n<line class=\"e\" x1=\"44\" y1=\"110\" x2=\"78\" y2=\"72\"/>\n<line class=\"e\" x1=\"112\" y1=\"110\" x2=\"78\" y2=\"72\"/>\n<circle class=\"n\" cx=\"44\" cy=\"110\" r=\"14\"/><text class=\"tl\" x=\"44\" y=\"115\" font-size=\"14\" text-anchor=\"middle\">i<\/text>\n<circle class=\"n\" cx=\"112\" cy=\"110\" r=\"14\"/><text class=\"tl\" x=\"112\" y=\"115\" font-size=\"14\" text-anchor=\"middle\">j<\/text>\n<circle class=\"n3\" cx=\"78\" cy=\"72\" r=\"13\"/>\n<text class=\"tm b1\" x=\"78\" y=\"152\" font-size=\"14\" text-anchor=\"middle\">공통 이웃이 있어요<\/text>\n<text class=\"tb b1\" x=\"78\" y=\"176\" font-size=\"15\" text-anchor=\"middle\">지워도 우회로가 있어요<\/text>\n<text class=\"tm\" x=\"240\" y=\"54\" font-size=\"14\" text-anchor=\"middle\">격자: 0<\/text>\n<line class=\"e2\" x1=\"206\" y1=\"110\" x2=\"274\" y2=\"110\"/>\n<line class=\"e\" x1=\"206\" y1=\"110\" x2=\"206\" y2=\"72\"/>\n<line class=\"e\" x1=\"274\" y1=\"110\" x2=\"274\" y2=\"72\"/>\n<line class=\"e\" x1=\"206\" y1=\"72\" x2=\"274\" y2=\"72\"/>\n<circle class=\"n\" cx=\"206\" cy=\"110\" r=\"14\"/><text class=\"tl\" x=\"206\" y=\"115\" font-size=\"14\" text-anchor=\"middle\">i<\/text>\n<circle class=\"n\" cx=\"274\" cy=\"110\" r=\"14\"/><text class=\"tl\" x=\"274\" y=\"115\" font-size=\"14\" text-anchor=\"middle\">j<\/text>\n<circle class=\"n3\" cx=\"206\" cy=\"72\" r=\"12\"/>\n<circle class=\"n3\" cx=\"274\" cy=\"72\" r=\"12\"/>\n<text class=\"tm b1\" x=\"240\" y=\"152\" font-size=\"14\" text-anchor=\"middle\">두 칸 건너 우회로<\/text>\n<text class=\"tb b1\" x=\"240\" y=\"176\" font-size=\"15\" text-anchor=\"middle\">평평한 격자 모양<\/text>\n<text class=\"tm\" x=\"400\" y=\"54\" font-size=\"14\" text-anchor=\"middle\">다리: 음수<\/text>\n<line class=\"e2\" x1=\"370\" y1=\"110\" x2=\"430\" y2=\"110\"/>\n<line class=\"e\" x1=\"370\" y1=\"110\" x2=\"342\" y2=\"80\"/>\n<line class=\"e\" x1=\"370\" y1=\"110\" x2=\"342\" y2=\"140\"/>\n<line class=\"e\" x1=\"430\" y1=\"110\" x2=\"458\" y2=\"80\"/>\n<line class=\"e\" x1=\"430\" y1=\"110\" x2=\"458\" y2=\"140\"/>\n<circle class=\"n\" cx=\"370\" cy=\"110\" r=\"14\"/><text class=\"tl\" x=\"370\" y=\"115\" font-size=\"14\" text-anchor=\"middle\">i<\/text>\n<circle class=\"n\" cx=\"430\" cy=\"110\" r=\"14\"/><text class=\"tl\" x=\"430\" y=\"115\" font-size=\"14\" text-anchor=\"middle\">j<\/text>\n<circle class=\"n4\" cx=\"342\" cy=\"80\" r=\"11\"/>\n<circle class=\"n4\" cx=\"342\" cy=\"140\" r=\"11\"/>\n<circle class=\"n4\" cx=\"458\" cy=\"80\" r=\"11\"/>\n<circle class=\"n4\" cx=\"458\" cy=\"140\" r=\"11\"/>\n<text class=\"tm b1\" x=\"400\" y=\"170\" font-size=\"14\" text-anchor=\"middle\">공통 이웃이 없어요<\/text>\n<text class=\"tb b1\" x=\"400\" y=\"194\" font-size=\"15\" text-anchor=\"middle\">유일한 통로, 병목<\/text>\n<text class=\"tb b2\" x=\"240\" y=\"230\" font-size=\"16\" text-anchor=\"middle\">음수는 과압착, 양수는 과평활과 이어져요<\/text>\n<text class=\"tm b2\" x=\"240\" y=\"254\" font-size=\"14\" text-anchor=\"middle\">굵은 선이 곡률을 재는 대상 엣지예요<\/text>\n<\/svg>","caption":"굵은 선이 곡률을 재는 대상 엣지예요.","builds":2},{"kind":"points","head":"**에스디알에프(SDRF)** 의 처방 두 줄","items":["음의 **곡률(Curvature)** 이 큰 곳 주변에 엣지를 더해 병목을 넓혀요.","양의 곡률이 너무 큰 엣지는 빼서 중복을 줄여요.","모델은 하나도 안 건드려요. 학습 전에 그래프만 고쳐 놓는 거예요.","이 처방 전체를 **재배선(Rewiring)** 이라고 불러요."]}],"pass3":[{"kind":"warn","head":"슬라이드 출처 표기에 문제가 있어요","items":["p.75 부터 p.79 까지는 출처가 Topping 외, ICLR 2022 로 정확하게 적혀 있어요.","그런데 이 덱의 앞부분 p.24 부터 p.27 은 같은 곡률 이야기를 하면서 출처를 Chung 1997 로 적어 놓았어요.","Chung 의 책은 p.24 의 Cheeger 부등식에만 해당해요.","출처를 묻는 문제가 나오면 곡률 기반 **재배선(Rewiring)** 은 Topping 외 2022 라고 답하세요."]},{"kind":"check","q":"음의 **곡률(Curvature)** 이 큰 엣지에서 생기는 문제는 무엇인가요?","choices":["**과평활화(Over-smoothing)**","**과압착(Over-squashing)**","기울기 폭발","레이블 불균형"],"a":1,"why":"두 집단의 모든 정보가 좁은 다리 하나를 통과해야 해서 눌려 담겨요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2975,0.1593],"c":[0,0.0019,0.3272,0.1913],"r":3.0407,"img":"img/L5/walk/p075_h.jpg"},"parts":[{"b":[0.02,0.19,0.94,0.09],"c":[0,0.1305,1,0.2089],"r":8.5102,"img":"img/L5/walk/p075_20_01.jpg","say":"목적이에요. 단순하고 가중치 없는 그래프에서 조합적이고 엣지에 기반한 곡률을 도입한다고 적혀 있어요."},{"b":[0.09,0.37,0.5,0.05],"c":[0.065,0.3394,0.55,0.1111],"r":8.8009,"img":"img/L5/walk/p075_20_02.jpg","say":"삼각형은 양의 곡률과 관계가 있어요. 이산 구면 기하라고 부릅니다."},{"b":[0.09,0.44,0.5,0.05],"c":[0.065,0.4094,0.55,0.1111],"r":8.8009,"img":"img/L5/walk/p075_20_03.jpg","say":"4-사이클, 즉 격자는 0 곡률과 관계가 있어요."},{"b":[0.09,0.51,0.54,0.05],"c":[0.063,0.475,0.594,0.12],"r":8.8,"img":"img/L5/walk/p075_20_04.jpg","say":"바깥으로 나가는 엣지, 즉 나무 모양은 음의 곡률과 관계가 있어요."},{"b":[0.09,0.64,0.6,0.05],"c":[0.06,0.5983,0.66,0.1333],"r":8.8022,"img":"img/L5/walk/p075_20_05.jpg","say":"해석이에요. 엣지가 두 이웃 사이를 잇는 다리일 때 음의 곡률이 생겨요."},{"b":[0.09,0.71,0.62,0.05],"c":[0.059,0.6661,0.682,0.1378],"r":8.7986,"img":"img/L5/walk/p075_20_06.jpg","say":"양의 곡률은 그 엣지를 지워도 이웃들이 여전히 이어져 있다는 뜻이에요."}]}},{"p":76,"title":"곡률을 재려면 세 가지를 센다","terms":["Curvature","Cycle Degeneracy","SDRF","Degree"],"pass1":[{"kind":"say","lines":["엣지 하나의 **곡률(Curvature)** 을 재려면 주변에서 세 가지를 세어야 해요.","삼각형의 개수, 대각선 없는 4-사이클의 개수, 그리고 **사이클 축퇴도(Cycle Degeneracy)** 예요.","세는 규칙이 까다로우니 천천히 가요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"식과 괄호 설명을 짝지어요","boxes":[{"x":0.35,"y":0.31,"w":0.24,"h":0.06,"say":"삼각형 집합은 $i$ 의 이웃이면서 동시에 $j$ 의 이웃인 노드들이에요. 교집합만 구하면 돼요.","c":[0.338,0.285,0.264,0.11],"r":4.2667,"img":"img/L5/walk/p076_20_01.jpg"},{"x":0.17,"y":0.51,"w":0.64,"h":0.06,"say":"4-사이클 집합의 식이에요. 조건이 세 개라 어려워 보이지만 하나씩 풀면 쉬워요.","c":[0.138,0.4689,0.704,0.1422],"r":8.8014,"img":"img/L5/walk/p076_20_02.jpg"},{"x":0.09,"y":0.58,"w":0.68,"h":0.05,"say":"괄호 설명이에요. $i$ 의 이웃 중, 밑변으로 하고 안쪽 대각선이 없는 4-사이클을 이루는 노드예요.","c":[0.056,0.5294,0.748,0.1511],"r":8.8006,"img":"img/L5/walk/p076_20_03.jpg"},{"x":0.09,"y":0.77,"w":0.66,"h":0.05,"say":"축퇴도의 설명이에요. 한 공통 노드를 지나는 4-사이클의 최대 개수예요.","c":[0.057,0.7217,0.726,0.1467],"r":8.798,"img":"img/L5/walk/p076_20_04.jpg"}]},{"kind":"points","head":"4-사이클 조건 세 개를 풀어서","items":["첫째, 후보 $k$ 는 $i$ 의 이웃이어야 해요.","둘째, $k$ 는 $j$ 의 이웃이 아니어야 해요. 이웃이면 그건 삼각형이라 이미 셌거든요.","셋째, $k$ 의 이웃이면서 $j$ 의 이웃인 노드 $w$ 가 있어야 해요. 단 그 $w$ 는 $i$ 의 이웃이 아니어야 해요.","셋째 조건의 마지막 부분이 안쪽 대각선을 없애는 장치예요."]},{"kind":"steps","head":"작은 고리에서 직접 세어 봐요","steps":["노드는 $i$, $j$, $a$, $b$ 네 개이고 고리 모양이에요. 엣지는 $i$와 $j$, $i$와 $a$, $a$와 $b$, $b$와 $j$ 예요.","삼각형부터 세요. $i$ 의 이웃은 $j$ 와 $a$, $j$ 의 이웃은 $i$ 와 $b$ 라 겹치는 것이 없어요. 0개예요.","$i$ 쪽 4-사이클을 봐요. 후보는 $a$ 하나이고, $a$ 의 이웃 $b$ 가 $j$ 의 이웃이면서 $i$ 의 이웃이 아니에요.","그래서 $i$ 쪽은 1개, 대칭으로 $j$ 쪽도 1개예요.","4-사이클이 하나뿐이니 **사이클 축퇴도(Cycle Degeneracy)** 는 1 이에요."],"answer":"삼각형 0개, 양쪽 4-사이클 각 1개, 축퇴도 1 이에요. 이 숫자들을 p.77 식에 넣어요.","given":"**차수(Degree)** 는 네 노드 모두 2 예요."}],"pass3":[{"kind":"warn","head":"세는 규칙에서 헷갈리기 쉬워요","items":["이웃 집합에는 자기 자신이 들어가지 않아요. 삼각형을 셀 때 $i$ 나 $j$ 를 세면 안 돼요.","삼각형과 4-사이클은 절대 겹치지 않아요. 조건이 서로를 배제하도록 짜여 있어요.","**사이클 축퇴도(Cycle Degeneracy)** 는 4-사이클의 총 개수가 아니에요. 한 노드에 겹치는 최대 개수예요.","사이클이 5개라도 모두 다른 노드를 지나면 축퇴도는 1 이에요."]},{"kind":"check","q":"**사이클 축퇴도(Cycle Degeneracy)** 가 뜻하는 것은 무엇인가요?","choices":["4-사이클의 총 개수","한 공통 노드를 지나는 4-사이클의 최대 개수","삼각형의 개수","노드의 차수"],"a":1,"why":"같은 노드를 지나는 사이클들은 서로 다른 우회로가 아니에요. 그래서 기여를 깎아 내려요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5363,0.227],"c":[0,0.0019,0.5899,0.259],"r":4.0491,"img":"img/L5/walk/p076_h.jpg"},"parts":[{"b":[0.11,0.25,0.1,0.05],"c":[0.06,0.22,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p076_11_01.jpg","say":"첫 항목이 삼각형이에요. 아래 식과 괄호 설명이 붙어 있어요."},{"b":[0.11,0.45,0.28,0.05],"c":[0.096,0.42,0.308,0.11],"r":4.9778,"img":"img/L5/walk/p076_11_02.jpg","say":"둘째 항목이 대각선 없는 4-사이클이에요."},{"b":[0.11,0.64,0.18,0.05],"c":[0.098,0.61,0.204,0.11],"r":3.297,"img":"img/L5/walk/p076_11_03.jpg","say":"셋째 항목이 **사이클 축퇴도(Cycle Degeneracy)** 예요."}]}},{"p":77,"title":"균형 포먼 곡률의 공식","terms":["Balanced Forman Curvature","Curvature","Cycle Degeneracy","Degree","SDRF","Bottleneck"],"pass1":[{"kind":"say","lines":["엣지 하나의 **균형 포먼 곡률(Balanced Forman Curvature)** 을 계산하는 공식이에요.","항이 여섯 개인데 세 덩어리로 나눠 보면 외우기 쉬워요.","**차수(Degree)** 항 셋, 삼각형 항 둘, 4-사이클 항 하나예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"formula","head":"균형 포먼 곡률","tex":"Ric(i,j) := \\frac{2}{d_i} + \\frac{2}{d_j} - 2 + 2\\frac{|\\sharp_\\Delta|}{\\max\\{d_i,d_j\\}} + \\frac{|\\sharp_\\Delta|}{\\min\\{d_i,d_j\\}} + \\frac{\\gamma_{\\max}^{-1}}{\\max\\{d_i,d_j\\}}\\left(|\\sharp_i^{\\square}| + |\\sharp_j^{\\square}|\\right)","parts":[{"sym":"\\frac{2}{d_i} + \\frac{2}{d_j} - 2","say":"**차수(Degree)** 항이에요. 삼각형도 4-사이클도 없으면 이것만 남고 값이 음수예요."},{"sym":"2\\frac{|\\sharp_\\Delta|}{\\max\\{d_i,d_j\\}}","say":"삼각형 개수를 큰 차수로 나눈 것에 2 를 곱해요. 양수 쪽으로 밀어 올려요."},{"sym":"\\frac{|\\sharp_\\Delta|}{\\min\\{d_i,d_j\\}}","say":"같은 삼각형 개수를 이번에는 작은 차수로 나눠요. 2 는 안 곱해요."},{"sym":"\\gamma_{\\max}^{-1}","say":"**사이클 축퇴도(Cycle Degeneracy)** 의 역수예요. 사이클이 한 노드에 몰릴수록 기여가 줄어요."},{"sym":"|\\sharp_i^{\\square}| + |\\sharp_j^{\\square}|","say":"양쪽 4-사이클 개수의 합이에요."}],"whole":"기본값은 차수에서 음수 쪽으로 정해지고, 삼각형과 4-사이클이 있는 만큼 양수 쪽으로 끌어올려요."},{"kind":"steps","head":"세 가지 모양에 공식을 넣어 봐요","steps":["다리 모양부터. 양쪽 차수가 3 이고 삼각형도 4-사이클도 없어요.","$\\frac{2}{3}+\\frac{2}{3}-2 = -\\frac{2}{3}$, 약 -0.667 이에요. 음수라 **병목(Bottleneck)** 이에요.","삼각형만 있는 모양. 양쪽 차수가 2 이고 삼각형이 1개예요.","$1+1-2+1+0.5 = 1.5$ 예요. 양수라 우회로가 있다는 뜻이에요.","무한 격자. 차수가 4 이고 양쪽 4-사이클이 각 2개, 축퇴도는 1 이에요.","$0.5+0.5-2+0+0+\\frac{1}{4}(2+2) = 0$ 이에요. 정확히 0 이 나와요."],"answer":"다리는 -0.667, 격자는 0, 삼각형은 1.5 예요. 이 세 숫자를 감각으로 기억하세요.","given":"**균형 포먼 곡률(Balanced Forman Curvature)** 공식에 그대로 대입해요."}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"Negative balanced Forman curvature marks a bridge edge that carries all the traffic between two neighbourhoods.","ko":"음의 균형 포먼 곡률은 두 이웃 집단 사이의 모든 통행을 떠맡는 다리 엣지를 가리킨다. 바로 그곳에서 과압착이 일어난다.","tip":"**에스디알에프(SDRF)** 가 왜 곡률을 재는지를 한 문장으로 답할 때 쓰면 좋아요."},{"kind":"warn","head":"계산과 슬라이드에서 주의할 점","items":["기본 경우를 먼저 확인하세요. 한쪽 **차수(Degree)** 가 1 이면 공식에 넣지 말고 바로 0 이에요.","삼각형 항 두 개는 서로 달라요. 앞의 것은 2 를 곱하고 큰 차수로, 뒤의 것은 작은 차수로 나눠요.","노드 넷짜리 사각형은 공식에 넣으면 1 이 나와요. 0 곡률은 무한 격자처럼 차수가 4 인 경우예요.","한글 슬라이드에서는 기본 경우 줄의 수식 글꼴과 4-사이클 기호가 깨져 보여요. p.76 의 정의를 보세요."]},{"kind":"check","q":"한쪽 노드의 **차수(Degree)** 가 1 이면 **균형 포먼 곡률(Balanced Forman Curvature)** 은 얼마인가요?","choices":["-2","0","1","공식을 계산해야 알 수 있다"],"a":1,"why":"기본 경우로 정해져 있어요. 공식에 넣으면 엉뚱한 큰 값이 나오니 먼저 확인하세요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.526,0.2612],"c":[0,0.0019,0.5786,0.2932],"r":3.5083,"img":"img/L5/walk/p077_h.jpg"},"parts":[{"b":[0.08,0.32,0.56,0.05],"c":[0.052,0.2828,0.616,0.1245],"r":8.7961,"img":"img/L5/walk/p077_11_01.jpg","say":"기본 경우예요. 한쪽 차수가 1 이면 곡률을 그냥 0 으로 정해요."},{"b":[0.11,0.53,0.72,0.09],"c":[0.074,0.495,0.792,0.16],"r":8.8,"img":"img/L5/walk/p077_11_02.jpg","say":"가운데 큰 식이 일반 공식이에요. 더하기로 이어진 항이 여섯 개예요."},{"b":[0.09,0.68,0.86,0.09],"c":[0.047,0.6294,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p077_11_03.jpg","say":"맨 아래 주의예요. 4-사이클이 없으면 마지막 항이 0 이고, 곡률은 항상 -2 보다 커요."}]}},{"p":78,"title":"곡률 계산 실전: 노드 일곱 개로 세어 보기","terms":["Curvature","Cycle Degeneracy","SDRF","Balanced Forman Curvature","Degree"],"pass1":[{"kind":"say","lines":["실제 그래프 하나를 놓고 4-사이클과 **사이클 축퇴도(Cycle Degeneracy)** 를 직접 세어 봐요.","핵심 규칙은 하나예요. 삼각형이 되는 노드와 대각선이 생기는 노드는 빼야 해요.","정의만 읽으면 어려운데 한 번 세어 보면 훨씬 쉬워져요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 주장 세 개","boxes":[{"x":0.09,"y":0.25,"w":0.32,"h":0.05,"say":"노드 0 쪽 4-사이클 집합이 2 와 3 이라고 적혀 있어요.","c":[0.074,0.22,0.352,0.11],"r":5.6889,"img":"img/L5/walk/p078_20_01.jpg"},{"x":0.09,"y":0.32,"w":0.3,"h":0.05,"say":"노드 1 쪽 4-사이클 집합은 5 하나예요.","c":[0.075,0.29,0.33,0.11],"r":5.3333,"img":"img/L5/walk/p078_20_02.jpg"},{"x":0.09,"y":0.45,"w":0.62,"h":0.05,"say":"노드 4 와 6 은 4-사이클 집합에서 명시적으로 뺀다고 적혀 있어요.","c":[0.059,0.4061,0.682,0.1378],"r":8.7986,"img":"img/L5/walk/p078_20_03.jpg"},{"x":0.09,"y":0.7,"w":0.22,"h":0.05,"say":"축퇴도는 2 라고 적혀 있어요.","c":[0.078,0.67,0.244,0.11],"r":3.9434,"img":"img/L5/walk/p078_20_04.jpg"},{"x":0.09,"y":0.77,"w":0.86,"h":0.09,"say":"이유는 유효한 4-사이클이 두 개이고 둘 다 노드 5 를 공통으로 지나기 때문이에요.","c":[0.047,0.7194,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p078_20_05.jpg"}]},{"kind":"steps","head":"슬라이드 주장을 직접 검산해요","steps":["먼저 이웃을 적어요. 0 은 1, 2, 3, 4, 6 이고 1 은 0, 5, 6 이에요.","삼각형은 두 이웃 집합의 교집합이라 6 하나예요. 삼각형 0-1-6 이 맞아요.","0 쪽 후보는 2, 3, 4 예요. 2 와 3 은 5 를 거쳐 1 에 닿고 5 는 0 의 이웃이 아니라 통과예요.","4 는 6 을 거쳐야 하는데 6 이 0 의 이웃이라 대각선이 생겨요. 그래서 탈락이에요.","1 쪽 후보는 5 하나이고 2 나 3 을 거쳐 0 에 닿으니 통과예요.","4-사이클은 0-2-5-1 과 0-3-5-1 두 개이고 둘 다 5 를 지나요."],"answer":"슬라이드가 말한 세 숫자가 전부 맞아요. 안심하고 외워도 돼요.","given":"노드 7개짜리 슬라이드 그래프에서 엣지 0 과 1 의 곡률을 재요."},{"kind":"figure","head":"두 개의 4-사이클이 모두 노드 5 를 지나요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"17\" text-anchor=\"middle\">엣지 0 과 1 을 둘러싼 4-사이클 두 개<\/text>\n<line class=\"e2\" x1=\"56\" y1=\"150\" x2=\"412\" y2=\"150\"/>\n<line class=\"e b1\" x1=\"56\" y1=\"150\" x2=\"130\" y2=\"72\"/>\n<line class=\"e b1\" x1=\"130\" y1=\"72\" x2=\"348\" y2=\"84\"/>\n<line class=\"e b2\" x1=\"56\" y1=\"150\" x2=\"188\" y2=\"112\"/>\n<line class=\"e b2\" x1=\"188\" y1=\"112\" x2=\"348\" y2=\"84\"/>\n<line class=\"e b1\" x1=\"348\" y1=\"84\" x2=\"412\" y2=\"150\"/>\n<line class=\"e\" x1=\"56\" y1=\"150\" x2=\"120\" y2=\"222\"/>\n<line class=\"e\" x1=\"120\" y1=\"222\" x2=\"236\" y2=\"222\"/>\n<line class=\"e\" x1=\"56\" y1=\"150\" x2=\"236\" y2=\"222\"/>\n<line class=\"e\" x1=\"236\" y1=\"222\" x2=\"412\" y2=\"150\"/>\n<circle class=\"n2\" cx=\"56\" cy=\"150\" r=\"16\"/><text class=\"tl\" x=\"56\" y=\"155\" font-size=\"14\" text-anchor=\"middle\">0<\/text>\n<circle class=\"n2\" cx=\"412\" cy=\"150\" r=\"16\"/><text class=\"tl\" x=\"412\" y=\"155\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<circle class=\"n b1\" cx=\"130\" cy=\"72\" r=\"14\"/><text class=\"tl b1\" x=\"130\" y=\"77\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<circle class=\"n b2\" cx=\"188\" cy=\"112\" r=\"14\"/><text class=\"tl b2\" x=\"188\" y=\"117\" font-size=\"14\" text-anchor=\"middle\">3<\/text>\n<circle class=\"n3 b1\" cx=\"348\" cy=\"84\" r=\"15\"/><text class=\"tl b1\" x=\"348\" y=\"89\" font-size=\"14\" text-anchor=\"middle\">5<\/text>\n<circle class=\"n\" cx=\"120\" cy=\"222\" r=\"14\"/><text class=\"tl\" x=\"120\" y=\"227\" font-size=\"14\" text-anchor=\"middle\">4<\/text>\n<circle class=\"n\" cx=\"236\" cy=\"222\" r=\"14\"/><text class=\"tl\" x=\"236\" y=\"227\" font-size=\"14\" text-anchor=\"middle\">6<\/text>\n<text class=\"tm b3\" x=\"348\" y=\"52\" font-size=\"14\" text-anchor=\"middle\">둘 다 5 를 지나요<\/text>\n<text class=\"tb b3\" x=\"348\" y=\"256\" font-size=\"16\" text-anchor=\"middle\">축퇴도는 2 예요<\/text>\n<text class=\"tm b3\" x=\"120\" y=\"256\" font-size=\"14\" text-anchor=\"middle\">아래 0-4-6-1 은 대각선 때문에 빠져요<\/text>\n<\/svg>","caption":"아래쪽 0-4-6-1 은 0 과 6 사이 대각선 때문에 빠져요.","builds":3},{"kind":"steps","head":"곡률까지 구해 봐요","steps":["**차수(Degree)** 는 노드 0 이 5, 노드 1 이 3 이에요.","삼각형 1개, 0 쪽 4-사이클 2개, 1 쪽 4-사이클 1개, 축퇴도 2 예요.","차수 항은 $\\frac{2}{5}+\\frac{2}{3}-2$ 예요.","삼각형 항은 $2\\cdot\\frac{1}{5} + \\frac{1}{3}$ 이에요.","4-사이클 항은 $\\frac{1/2}{5}\\times(2+1) = 0.3$ 이에요.","다 더하면 $\\frac{4}{5} + 1 - 2 + \\frac{3}{10}$ 이에요."],"answer":"$Ric(0,1) = 0.1$ 이에요. 삼각형과 4-사이클이 차수의 음수를 겨우 상쇄한 값이에요.","given":"p.77 의 **균형 포먼 곡률(Balanced Forman Curvature)** 공식에 넣어요."}],"pass3":[{"kind":"warn","head":"슬라이드 설명 한 줄이 부정확해요","items":["노드 4 와 6 은 제외한다, 이유는 삼각형 1-6-0 을 이루기 때문이다 라고 적혀 있어요.","그런데 노드 4 는 삼각형 1-6-0 의 일부가 아니에요. 두 노드가 빠지는 이유가 서로 달라요.","노드 6 은 0 과 1 의 공통 이웃이라 후보 집합에 아예 들어가지 못해요.","노드 4 는 후보에는 들어가지만 0 과 6 사이 대각선 때문에 탈락해요. 숫자 자체는 전부 맞아요."]},{"kind":"check","q":"슬라이드 그래프에서 노드 4 가 4-사이클 집합에서 빠지는 진짜 이유는 무엇인가요?","choices":["0 의 이웃이 아니라서","고리 0-4-6-1 에 0 과 6 사이 대각선이 생겨서","삼각형을 이루어서","차수가 1 이라서"],"a":1,"why":"안쪽 대각선이 없어야 한다는 조건에 걸려요. 삼각형 때문이 아니에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5734,0.0757],"c":[0,0.0019,0.6308,0.1077],"r":10.4125,"img":"img/L5/walk/p078_h.jpg"},"parts":[{"b":[0.71,0.11,0.24,0.4],"c":[0.698,0.09,0.264,0.44],"r":1.0667,"img":"img/L5/walk/p078_11_01.jpg","say":"노드 0 은 왼쪽 가운데, 1 은 오른쪽 가운데예요. 둘을 잇는 연보라 선이 우리가 잴 엣지예요."},{"b":[0.73,0.12,0.2,0.22],"c":[0.718,0.104,0.224,0.252],"r":1.5802,"img":"img/L5/walk/p078_11_02.jpg","say":"위쪽에 2, 3, 5 가 있어요. 0 에서 2 와 3 으로 가고, 둘 다 5 로 이어져요."},{"b":[0.74,0.4,0.14,0.14],"c":[0.71,0.384,0.2,0.172],"r":2.0672,"img":"img/L5/walk/p078_11_03.jpg","say":"아래쪽에 4 와 6 이 있어요. 0 은 4 와 6 둘 다와 이어져 있어요."}]}},{"p":79,"title":"SDRF 알고리즘: 굽은 곳을 펴는 흐름","terms":["SDRF","Curvature","Rewiring","Over-squashing","Over-smoothing","Bottleneck"],"pass1":[{"kind":"say","lines":["**에스디알에프(SDRF)** 는 두 동작을 반복해요.","곡률이 가장 음수인 엣지 근처에 새 엣지를 하나 더해요.","그리고 곡률이 가장 양수인 엣지를 하나 빼요.","이것을 수렴할 때까지 되풀이해요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"알고리즘을 줄마다","boxes":[{"x":0.14,"y":0.18,"w":0.72,"h":0.04,"say":"입력이에요. 그래프와 온도, 최대 반복 횟수, 그리고 선택 사항인 곡률 상한을 받아요.","c":[0.104,0.12,0.792,0.16],"r":8.8,"img":"img/L5/walk/p079_20_01.jpg"},{"x":0.17,"y":0.25,"w":0.68,"h":0.04,"say":"1번 동작이에요. 곡률이 가장 작은 엣지를 찾아요.","c":[0.136,0.1944,0.748,0.1511],"r":8.8006,"img":"img/L5/walk/p079_20_02.jpg"},{"x":0.2,"y":0.3,"w":0.66,"h":0.09,"say":"그 엣지 양 끝의 1홉 안에서 새 엣지를 하나 골라 더해요. 확률적으로 골라요.","c":[0.167,0.2717,0.726,0.1467],"r":8.798,"img":"img/L5/walk/p079_20_03.jpg"},{"x":0.17,"y":0.42,"w":0.68,"h":0.04,"say":"2번 동작이에요. 곡률이 가장 큰 엣지를 지워요. 상한을 넘을 때만이에요.","c":[0.136,0.3644,0.748,0.1511],"r":8.8006,"img":"img/L5/walk/p079_20_04.jpg"}]},{"kind":"points","head":"알고리즘을 일상어로","items":["먼저 **곡률(Curvature)** 이 가장 음수인 엣지를 찾아요. 그게 가장 심한 **병목(Bottleneck)** 이에요.","그 엣지 자체가 아니라 양 끝 근처에 새 엣지를 하나 놓아요.","어떤 쌍을 고를지는 개선량에 소프트맥스를 씌워 확률적으로 정해요. 그래서 이름에 확률적이 들어가요.","반대쪽에서는 곡률이 가장 양수인 엣지를 빼서 중복을 줄여요."]},{"kind":"steps","head":"다리 하나짜리 그래프에서 한 번 돌려요","steps":["$i$ 와 $j$ 가 다리로 이어져 있고 각각 잎이 둘씩 붙어 있어요. 차수가 둘 다 3 이에요.","지금 곡률은 $\\frac{2}{3}+\\frac{2}{3}-2 = -0.667$ 이에요. 그래프에서 가장 음수예요.","$i$ 쪽 잎 $a$ 와 $j$ 쪽 잎 $c$ 사이에 새 엣지를 놓아요.","이제 고리 $i$-$a$-$c$-$j$ 가 생겨요. 대각선이 없으니 유효한 4-사이클이에요.","양쪽 4-사이클이 각 1개, 축퇴도 1 이라 마지막 항이 $\\frac{1}{3}(1+1)$ 이에요."],"answer":"곡률이 -0.667 에서 0 으로 올라왔어요. 엣지 하나로 병목이 크게 풀렸어요.","given":"**에스디알에프(SDRF)** 의 1단계를 손으로 따라가요."}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"SDRF finds the edge with the most negative curvature and stochastically adds a new edge between the one-hop neighbourhoods of its endpoints.","ko":"SDRF 는 곡률이 가장 음수인 엣지를 찾아 그 양 끝의 1홉 이웃 사이에 새 엣지를 확률적으로 더한다.","tip":"**과압착(Over-squashing)** 을 어떻게 완화하느냐를 묻는 문제에 쓰면 좋아요."},{"kind":"warn","head":"알고리즘에서 헷갈리기 쉬운 점","items":["더하는 엣지는 병목 엣지 자체가 아니에요. 양 끝의 1홉 이웃 사이에 놓아요.","엣지 제거에는 조건이 붙어요. 곡률이 상한을 넘을 때만 지워요.","가장 좋은 쌍을 무조건 고르는 것이 아니라 소프트맥스로 확률적으로 골라요.","리치 흐름이라는 이름은 곡면의 굽은 정도를 시간에 따라 고르게 펴는 기하학 방정식에서 왔어요."]},{"kind":"check","q":"**에스디알에프(SDRF)** 가 새 엣지를 놓는 자리는 어디인가요?","choices":["병목 엣지 자체","병목 엣지 양 끝의 1홉 이웃 사이","그래프에서 가장 먼 두 노드 사이","차수가 가장 큰 두 노드 사이"],"a":1,"why":"같은 두 노드를 다시 잇는 것은 의미가 없어요. 주변에 우회로를 만들어 줘야 해요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5734,0.0757],"c":[0,0.0019,0.6308,0.1077],"r":10.4125,"img":"img/L5/walk/p079_h.jpg"},"parts":[{"b":[0.14,0.13,0.72,0.36],"c":[0.104,0.112,0.792,0.396],"r":3.5556,"img":"img/L5/walk/p079_11_01.jpg","say":"위쪽 흰 상자가 논문의 알고리즘이에요. Repeat 아래에 동작 두 개가 있어요."},{"b":[0.31,0.53,0.3,0.16],"c":[0.295,0.514,0.33,0.192],"r":3.0556,"img":"img/L5/walk/p079_11_02.jpg","say":"아래 위쪽 그림이 잘록한 아령이 통통해지는 모습이에요. 이것이 리치 흐름이에요."},{"b":[0.29,0.71,0.38,0.2],"c":[0.271,0.694,0.418,0.232],"r":3.2031,"img":"img/L5/walk/p079_11_03.jpg","say":"그 아래는 그래프 버전이에요. 다리 하나로 이어진 두 덩어리가 넉넉하게 이어져요."}]}},{"p":80,"title":"SDRF 의 한계 셋: BORF 가 나온 이유","terms":["SDRF","BORF","Balanced Forman Curvature","Ollivier-Ricci Curvature","Over-smoothing","Over-squashing","Curvature"],"pass1":[{"kind":"say","lines":["**에스디알에프(SDRF)** 에는 문제가 세 개 있어요.","느리고, 정확하지 않고, 한쪽으로 치우쳐요.","**보알에프(BORF)** 는 이 셋을 한꺼번에 고치려고 나왔어요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"compare","head":"한계와 처방을 짝지어요","cols":["**에스디알에프(SDRF)** 의 한계","왜 문제인가","**보알에프(BORF)** 의 처방"],"rows":[["엣지를 하나씩 고쳐요","매번 곡률 전체를 다시 계산해요","한 번에 여러 개씩 배치로 고쳐요"],["하한만 써요","정확한 기하가 아니에요","정확한 곡률을 쓰되 드물게 계산해요"],["더하기만 해요","밀도가 올라 과평활이 심해져요","더하기와 빼기를 같은 비중으로 해요"]]},{"kind":"points","head":"약자 두 개를 확실히 구별해요","items":["**올리비에-리치 곡률(Ollivier-Ricci Curvature)** 은 정확하지만 계산이 비싸요.","**균형 포먼 곡률(Balanced Forman Curvature)** 은 싸지만 하한일 뿐이에요.","p.77 에서 배운 공식은 뒤엣것, 즉 값싼 쪽이에요.","하한이라는 말은 실제 값이 이것보다 크거나 같다는 뜻이에요. 정확한 값은 **최적 수송(Optimal Transport)** 을 풀어야 나와요."]},{"kind":"steps","head":"왜 더하기만 하면 나빠질까요","steps":["엣지를 더하면 그래프가 빽빽해져요.","빽빽해지면 삼각형이 늘어나요.","삼각형이 늘면 양의 **곡률(Curvature)** 이 커져요.","p.75 에서 배웠듯 양의 곡률이 크면 **과평활화(Over-smoothing)** 가 심해져요.","결국 **과압착(Over-squashing)** 을 고치다가 반대쪽을 망가뜨려요."],"answer":"한쪽 구멍을 막았더니 다른 쪽이 터지는 셈이에요.","given":"**에스디알에프(SDRF)** 의 주된 동작은 엣지 추가예요."}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"SDRF rewires one edge at a time, uses the balanced Forman curvature only as a cheap lower bound, and mainly adds edges, which accelerates over-smoothing.","ko":"SDRF 는 한 번에 엣지 하나만 고치고, 균형 포먼 곡률을 값싼 하한으로만 쓰며, 주로 엣지를 더해서 과평활화를 가속한다.","tip":"세 가지를 번호로 나눠 쓰면 채점자가 보기 편해요."},{"kind":"check","q":"**균형 포먼 곡률(Balanced Forman Curvature)** 과 **올리비에-리치 곡률(Ollivier-Ricci Curvature)** 의 관계는 무엇인가요?","choices":["같은 것이다","앞엣것이 뒤엣것의 값싼 하한이다","앞엣것이 더 정확하다","서로 관계가 없다"],"a":1,"why":"정확한 값은 최적 수송을 풀어야 나와요. 그래서 세기만 하면 되는 공식을 대신 써요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.613,0.1648],"c":[0,0.0019,0.6743,0.1968],"r":6.0912,"img":"img/L5/walk/p080_h.jpg"},"parts":[{"b":[0.05,0.19,0.9,0.09],"c":[0.005,0.135,0.99,0.2],"r":8.8,"img":"img/L5/walk/p080_11_01.jpg","say":"한계 1은 계산 비효율이에요. 엣지를 하나씩 고쳐서 매번 곡률 분포를 다시 계산해야 해요."},{"b":[0.05,0.42,0.9,0.09],"c":[0.005,0.365,0.99,0.2],"r":8.8,"img":"img/L5/walk/p080_11_02.jpg","say":"한계 2는 곡률 하한에 의존한다는 거예요. 빨간 글씨가 하한 대리값이에요."},{"b":[0.05,0.64,0.9,0.09],"c":[0.005,0.585,0.99,0.2],"r":8.8,"img":"img/L5/walk/p080_11_03.jpg","say":"한계 3은 절충의 실패예요. 엣지를 추가만 해서 과평활 문제를 오히려 가속해요."}]}},{"p":81,"title":"BORF: 배치로 더하고 배치로 빼기","terms":["BORF","SDRF","Optimal Transport","Ollivier-Ricci Curvature","Over-squashing","Over-smoothing","Curvature","Rewiring"],"pass1":[{"kind":"say","lines":["**보알에프(BORF)** 의 한 바퀴는 두 단계예요.","곡률이 가장 음수인 엣지 $h$ 개에 새 통로를 하나씩 더해요.","그리고 곡률이 가장 양수인 엣지 $k$ 개를 지워요.","한 번에 여러 개씩 하는 것이 배치라는 이름의 뜻이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"각 단계 안을 자세히","boxes":[{"x":0.09,"y":0.42,"w":0.5,"h":0.05,"say":"1단계 첫 줄. 곡률이 가장 음수인 엣지 $h$ 개를 한 배치로 골라요.","c":[0.065,0.3894,0.55,0.1111],"r":8.8009,"img":"img/L5/walk/p081_20_01.jpg"},{"x":0.09,"y":0.48,"w":0.66,"h":0.06,"say":"1단계 둘째 줄. 엣지마다 새 통로 연결을 하나 추가해요.","c":[0.057,0.4367,0.726,0.1467],"r":8.798,"img":"img/L5/walk/p081_20_02.jpg"},{"x":0.28,"y":0.58,"w":0.32,"h":0.06,"say":"그 아래 식이 어느 쌍을 고를지 정해요. 최댓값을 고르는 식이에요.","c":[0.264,0.555,0.352,0.11],"r":5.6889,"img":"img/L5/walk/p081_20_03.jpg"},{"x":0.09,"y":0.73,"w":0.68,"h":0.05,"say":"2단계. 이웃이 가장 많이 겹치는 엣지 $k$ 개를 골라요.","c":[0.056,0.6794,0.748,0.1511],"r":8.8006,"img":"img/L5/walk/p081_20_04.jpg"},{"x":0.09,"y":0.84,"w":0.54,"h":0.05,"say":"그 엣지들을 지워서 구조적 중복을 줄여요.","c":[0.063,0.805,0.594,0.12],"r":8.8,"img":"img/L5/walk/p081_20_05.jpg"}]},{"kind":"formula","head":"어느 쌍에 새 통로를 놓을까","tex":"(p^{*}, q^{*}) = \\arg\\max\\ \\pi_j(p,q)\\,d(p,q)","parts":[{"sym":"\\pi_j(p,q)","say":"**최적 수송(Optimal Transport)** 계획에서 $p$ 에서 $q$ 로 옮기는 짐의 양이에요."},{"sym":"d(p,q)","say":"노드 $p$ 와 $q$ 사이의 그래프 거리, 즉 최단 경로 길이예요."},{"sym":"\\pi_j(p,q)\\,d(p,q)","say":"그 한 쌍이 수송 비용 총합에 기여하는 몫이에요."},{"sym":"\\arg\\max","say":"그 몫이 가장 큰 쌍을 고르라는 뜻이에요."}],"whole":"수송 비용에 가장 크게 기여하는 쌍을 찾아 그 둘 사이에 직행 길을 놓아요. 그러면 비용이 가장 많이 줄어요."},{"kind":"steps","head":"왜 배치가 더 빠른가요","steps":["곡률 전체를 한 번 계산하는 데 100초가 걸린다고 해요.","엣지 20개를 고치고 싶어요.","**에스디알에프(SDRF)** 방식으로 하나씩 하면 계산이 20번, 2000초예요.","**보알에프(BORF)** 로 $h+k$ 를 20 으로 잡으면 계산이 1번, 100초예요.","$h+k$ 를 5 로 잡으면 네 배치라 계산이 4번, 400초예요."],"answer":"배치를 키울수록 빨라져요. 대신 배치 안에서는 낡은 곡률 값을 쓰게 돼요.","given":"곡률 계산 횟수만 비교해요."},{"kind":"figure","head":"곡률 순서로 줄 세워 양 끝을 잡아요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"17\" text-anchor=\"middle\">모든 엣지를 곡률 순서로 줄 세워요<\/text>\n<line class=\"e\" x1=\"30\" y1=\"70\" x2=\"450\" y2=\"70\"/>\n<circle class=\"n4\" cx=\"44\" cy=\"70\" r=\"9\"/>\n<circle class=\"n4\" cx=\"68\" cy=\"70\" r=\"9\"/>\n<circle class=\"n4\" cx=\"92\" cy=\"70\" r=\"9\"/>\n<circle class=\"n\" cx=\"170\" cy=\"70\" r=\"9\"/>\n<circle class=\"n\" cx=\"220\" cy=\"70\" r=\"9\"/>\n<circle class=\"n\" cx=\"270\" cy=\"70\" r=\"9\"/>\n<circle class=\"n\" cx=\"320\" cy=\"70\" r=\"9\"/>\n<circle class=\"n3\" cx=\"404\" cy=\"70\" r=\"9\"/>\n<circle class=\"n3\" cx=\"430\" cy=\"70\" r=\"9\"/>\n<text class=\"tm\" x=\"44\" y=\"100\" font-size=\"14\" text-anchor=\"middle\">가장 음수<\/text>\n<text class=\"tm\" x=\"430\" y=\"100\" font-size=\"14\" text-anchor=\"middle\">가장 양수<\/text>\n<rect class=\"hl b1\" x=\"30\" y=\"52\" width=\"76\" height=\"36\" rx=\"6\"/>\n<text class=\"tb b1\" x=\"68\" y=\"128\" font-size=\"15\" text-anchor=\"middle\">h 개를 골라요<\/text>\n<rect class=\"hl b2\" x=\"390\" y=\"52\" width=\"54\" height=\"36\" rx=\"6\"/>\n<text class=\"tb b2\" x=\"416\" y=\"128\" font-size=\"15\" text-anchor=\"middle\">k 개를 골라요<\/text>\n<rect class=\"box2 b1\" x=\"24\" y=\"150\" width=\"200\" height=\"52\" rx=\"8\"/>\n<text class=\"t b1\" x=\"124\" y=\"174\" font-size=\"15\" text-anchor=\"middle\">1단계: 새 통로를 더해요<\/text>\n<text class=\"tm b1\" x=\"124\" y=\"194\" font-size=\"14\" text-anchor=\"middle\">과압착 완화<\/text>\n<rect class=\"box2 b2\" x=\"256\" y=\"150\" width=\"200\" height=\"52\" rx=\"8\"/>\n<text class=\"t b2\" x=\"356\" y=\"174\" font-size=\"15\" text-anchor=\"middle\">2단계: 그 엣지를 지워요<\/text>\n<text class=\"tm b2\" x=\"356\" y=\"194\" font-size=\"14\" text-anchor=\"middle\">과평활 완화<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"236\" font-size=\"16\" text-anchor=\"middle\">양 끝을 같은 바퀴에서 함께 잡아요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"258\" font-size=\"14\" text-anchor=\"middle\">SDRF 는 더하기만 했고 BORF 는 둘 다 해요<\/text>\n<\/svg>","caption":"SDRF 는 더하기만 했고 BORF 는 더하기와 빼기를 함께 해요.","builds":3}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"BORF rewires in batches, adding h edges at the most negatively curved edges and removing k edges at the most positively curved ones.","ko":"BORF 는 배치로 재배선한다. 한 바퀴 안에서 곡률이 가장 음수인 엣지에 h 개를 더하고 가장 양수인 엣지에서 k 개를 제거한다.","tip":"**에스디알에프(SDRF)** 와의 차이를 묻는 문제에 그대로 쓸 수 있어요."},{"kind":"warn","head":"슬라이드 문장과 식이 어긋나 보여요","items":["1단계 둘째 줄은 최적 수송 비용을 가장 작게 만드는 연결을 더한다고 적혀 있어요.","그런데 바로 아래 식은 최댓값을 고르는 argmax 예요. 반대처럼 보이죠.","실제 뜻은 지금 비용에 가장 크게 기여하는 쌍을 고르면 결과적으로 총비용이 가장 많이 줄어든다는 것이에요.","시험에서 식을 그대로 물으면 argmax 라고 답하세요."]},{"kind":"check","q":"**보알에프(BORF)** 가 **에스디알에프(SDRF)** 와 다른 결정적 지점은 무엇인가요?","choices":["곡률을 안 쓴다","엣지 제거가 처음부터 설계에 들어 있다","학습 중에 작동한다","가중치를 바꾼다"],"a":1,"why":"SDRF 에서 제거는 조건부 부록이었어요. BORF 는 $k$ 라는 제거 배치가 설계의 절반이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.613,0.1648],"c":[0,0.0019,0.6743,0.1968],"r":6.0912,"img":"img/L5/walk/p081_h.jpg"},"parts":[{"b":[0.05,0.19,0.9,0.09],"c":[0.005,0.135,0.99,0.2],"r":8.8,"img":"img/L5/walk/p081_11_01.jpg","say":"해결 전략이에요. 정확한 곡률로 스펙트럼의 양 극단을 동시에 묶어 주는 방법이라고 적혀 있어요."},{"b":[0.05,0.34,0.4,0.05],"c":[0.03,0.31,0.44,0.11],"r":7.1111,"img":"img/L5/walk/p081_11_02.jpg","say":"1단계는 **과압착(Over-squashing)** 완화, 즉 엣지 추가예요."},{"b":[0.05,0.66,0.4,0.05],"c":[0.03,0.63,0.44,0.11],"r":7.1111,"img":"img/L5/walk/p081_11_03.jpg","say":"2단계는 **과평활화(Over-smoothing)** 완화, 즉 엣지 제거예요."}]}},{"p":82,"title":"BORF 의사 코드 읽기","terms":["BORF","SDRF","Curvature","Optimal Transport","Rewiring"],"pass1":[{"kind":"say","lines":["앞에서 말로 설명한 **보알에프(BORF)** 를 논문의 알고리즘 상자로 다시 봐요.","읽어 낼 것은 하나예요. 반복문이 두 겹이라는 것.","바깥은 배치를 N 번 돌고, 안쪽은 더할 엣지 h 개를 돌아요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"줄마다 무슨 일을 하나","boxes":[{"x":0.31,"y":0.36,"w":0.4,"h":0.12,"say":"곡률이 가장 작은 엣지 h 개를 찾아요. 여기서 **곡률(Curvature)** 을 한 번만 계산해요.","c":[0.29,0.344,0.44,0.152],"r":5.1462,"img":"img/L5/walk/p082_20_01.jpg"},{"x":0.31,"y":0.44,"w":0.4,"h":0.05,"say":"그때 **최적 수송(Optimal Transport)** 비용의 각 항도 같이 나와요. 공짜로 얻는 정보예요.","c":[0.29,0.41,0.44,0.11],"r":7.1111,"img":"img/L5/walk/p082_20_02.jpg"},{"x":0.31,"y":0.51,"w":0.4,"h":0.08,"say":"곡률이 가장 큰 엣지 k 개도 같은 표에서 뽑아요. 추가 계산이 없어요.","c":[0.29,0.494,0.44,0.112],"r":6.9841,"img":"img/L5/walk/p082_20_03.jpg"},{"x":0.31,"y":0.63,"w":0.4,"h":0.09,"say":"안쪽 반복문 안에서 새 엣지를 하나씩 더해요.","c":[0.29,0.614,0.44,0.122],"r":6.4117,"img":"img/L5/walk/p082_20_04.jpg"},{"x":0.31,"y":0.79,"w":0.4,"h":0.04,"say":"제거는 반복문 밖에서 한꺼번에 해요.","c":[0.29,0.755,0.44,0.11],"r":7.1111,"img":"img/L5/walk/p082_20_05.jpg"}]},{"kind":"figure","head":"두 겹 반복문의 구조","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"17\" text-anchor=\"middle\">찾기는 배치당 한 번, 실행은 여러 번<\/text>\n<rect class=\"box\" x=\"18\" y=\"38\" width=\"444\" height=\"200\" rx=\"10\"/>\n<text class=\"tm\" x=\"34\" y=\"60\" font-size=\"14\">바깥 반복문: 배치 i 는 1 부터 N 까지<\/text>\n<rect class=\"box2\" x=\"40\" y=\"70\" width=\"400\" height=\"36\" rx=\"7\"/>\n<text class=\"t\" x=\"240\" y=\"93\" font-size=\"15\" text-anchor=\"middle\">곡률을 한 번만 계산해 목록 두 개를 만들어요<\/text>\n<polygon class=\"arrow b1\" points=\"232,110 248,118 232,126\"/>\n<rect class=\"box b1\" x=\"40\" y=\"128\" width=\"190\" height=\"62\" rx=\"7\"/>\n<text class=\"t b1\" x=\"135\" y=\"150\" font-size=\"15\" text-anchor=\"middle\">음수 목록 h 개<\/text>\n<text class=\"tm b1\" x=\"135\" y=\"170\" font-size=\"14\" text-anchor=\"middle\">안쪽 반복문에서<\/text>\n<text class=\"tm b1\" x=\"135\" y=\"186\" font-size=\"14\" text-anchor=\"middle\">하나씩 통로를 더해요<\/text>\n<rect class=\"box b2\" x=\"250\" y=\"128\" width=\"190\" height=\"62\" rx=\"7\"/>\n<text class=\"t b2\" x=\"345\" y=\"150\" font-size=\"15\" text-anchor=\"middle\">양수 목록 k 개<\/text>\n<text class=\"tm b2\" x=\"345\" y=\"170\" font-size=\"14\" text-anchor=\"middle\">반복문 밖에서<\/text>\n<text class=\"tm b2\" x=\"345\" y=\"186\" font-size=\"14\" text-anchor=\"middle\">한꺼번에 지워요<\/text>\n<rect class=\"box2 b3\" x=\"40\" y=\"198\" width=\"400\" height=\"30\" rx=\"7\"/>\n<text class=\"t b3\" x=\"240\" y=\"218\" font-size=\"15\" text-anchor=\"middle\">다음 배치에서 비로소 곡률을 다시 계산해요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"258\" font-size=\"14\" text-anchor=\"middle\">장을 한 번 보고 목록대로 다 사 오는 것과 같아요<\/text>\n<\/svg>","caption":"찾기는 배치당 한 번, 실행은 h 더하기 k 번이에요.","builds":3},{"kind":"steps","head":"배치를 세 번 돌리면 엣지가 어떻게 변하나요","steps":["N 은 3, h 는 2, k 는 1 이라고 해요. 처음 엣지는 100개예요.","배치 1 에서 **곡률(Curvature)** 을 한 번 계산하고 2개를 더하고 1개를 빼요. 101개가 돼요.","배치 2 도 같은 방식이라 102개가 돼요.","배치 3 까지 하면 103개예요. 곡률 계산은 모두 3번이에요.","**에스디알에프(SDRF)** 방식으로 하나씩 하면 엣지를 9번 건드리니 계산이 9번 필요해요."],"answer":"배치 크기 3 배만큼 계산이 줄었어요. 엣지 총수는 6 늘고 3 줄어 순증 3 이에요.","given":"더하기만 하는 SDRF 와 달리 밀도가 덜 올라가요."},{"kind":"points","head":"h 와 k 를 어떻게 잡나요","items":["h 가 k 보다 크면 엣지가 늘어나요. **에스디알에프(SDRF)** 와 비슷해져요.","h 와 k 가 같으면 엣지 총수가 변하지 않아요. 밀도를 유지하며 모양만 바꿔요.","h 가 k 보다 작으면 엣지가 줄어요. **과평활화(Over-smoothing)** 완화에 무게를 둔 설정이에요.","셋 다 사람이 정하는 값이에요. 학습으로 배우는 값이 아니에요."]}],"pass3":[{"kind":"warn","head":"의사 코드에서 헷갈리기 쉬운 점","items":["곡률 기호로 카파를 쓰고 있어요. 이것은 정확한 올리비에-리치 곡률이지 균형 포먼 곡률이 아니에요.","추가는 안쪽 반복문 안에서 하나씩, 제거는 반복문 밖에서 한꺼번에 해요.","수송 계획을 따로 계산하는 것이 아니에요. **곡률(Curvature)** 을 구하면 자동으로 나오는 값이에요."]},{"kind":"check","q":"**보알에프(BORF)** 가 곡률을 다시 계산하는 시점은 언제인가요?","choices":["엣지를 하나 고칠 때마다","배치가 끝나고 다음 배치를 시작할 때","한 번만","학습 중에 계속"],"a":1,"why":"이것이 **에스디알에프(SDRF)** 보다 빠른 비결이에요. 장을 한 번 보고 목록대로 다 사 오는 셈이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.613,0.1648],"c":[0,0.0019,0.6743,0.1968],"r":6.0912,"img":"img/L5/walk/p082_h.jpg"},"parts":[{"b":[0.29,0.2,0.42,0.08],"c":[0.269,0.184,0.462,0.112],"r":7.3333,"img":"img/L5/walk/p082_11_01.jpg","say":"맨 위가 입력이에요. 그래프와 배치 수 N, 더할 수 h, 뺄 수 k 를 받아요."},{"b":[0.29,0.32,0.42,0.04],"c":[0.269,0.285,0.462,0.11],"r":7.4667,"img":"img/L5/walk/p082_11_02.jpg","say":"그 아래가 바깥 반복문 시작이에요. 배치를 N 번 돌아요."},{"b":[0.31,0.58,0.4,0.04],"c":[0.29,0.545,0.44,0.11],"r":7.1111,"img":"img/L5/walk/p082_11_03.jpg","say":"가운데쯤에 안쪽 반복문이 있어요. 더할 엣지 h 개를 하나씩 처리해요."}]}},{"p":83,"title":"BORF 의 복잡도와 장점","terms":["BORF","SDRF","Curvature","Optimal Transport","Degree","Over-smoothing","Over-squashing"],"pass1":[{"kind":"say","lines":["**보알에프(BORF)** 의 계산 비용을 식 하나로 적은 슬라이드예요.","핵심은 분모에 배치 크기가 들어 있다는 점이에요.","배치를 키울수록 비용이 줄어요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"formula","head":"BORF 의 계산 복잡도","tex":"\\mathcal{O}\\left(\\frac{R \\cdot |E| \\cdot D^{3}}{h+k}\\right)","parts":[{"sym":"R","say":"재배선 반복 횟수예요. 몇 바퀴 돌 것인가예요."},{"sym":"|E|","say":"엣지 개수예요. **곡률(Curvature)** 을 엣지마다 계산해야 하거든요."},{"sym":"D^{3}","say":"최대 **차수(Degree)** 의 세제곱이에요. 이웃 사이의 **최적 수송(Optimal Transport)** 을 푸는 비용이에요."},{"sym":"h+k","say":"배치 크기예요. 여기로 나누는 것이 절약의 핵심이에요."}],"whole":"엣지마다 수송 문제를 풀고 그것을 몇 바퀴 반복하되, 배치로 묶은 만큼 나눠서 싸진다는 뜻이에요."},{"kind":"steps","head":"배치 크기만 바꿔 가며 비교해요","steps":["$R$ 은 60, 엣지는 1000개, 최대 **차수(Degree)** 는 10 이라고 해요.","분자는 $60 \\times 1000 \\times 1000$ 으로 600만이에요.","배치 크기가 1 이면 600만이에요. **에스디알에프(SDRF)** 와 같은 셈이에요.","배치 크기가 5 면 120만으로 다섯 배 빨라져요.","배치 크기가 20 이면 30만으로 스무 배 빨라져요."],"answer":"배치를 키울수록 싸져요. 대신 배치 안에서는 낡은 곡률 값을 쓰니 정밀도가 떨어져요.","given":"상수는 무시하고 비율만 비교해요."},{"kind":"points","head":"차수가 큰 허브가 있으면 비싸져요","items":["최대 **차수(Degree)** 가 10 에서 20 으로 두 배가 되면 세제곱이라 여덟 배가 돼요.","노드 하나가 허브라서 이웃이 많으면 전체 비용이 확 뛰어요.","그래서 소셜 네트워크처럼 허브가 있는 그래프에서는 **보알에프(BORF)** 도 여전히 무거워요.","이 비용은 학습 전 한 번 내는 전처리 비용이에요. 학습 자체와는 별개예요."]},{"kind":"compare","head":"처방마다 비용이 드는 시점","cols":["처방","언제 드나","대략의 크기"],"rows":[["**지씨엔 투(GCNII)**","학습 내내","보통 GCN 과 거의 같아요"],["**에스디알에프(SDRF)**","학습 전 한 번","비싸요"],["**보알에프(BORF)**","학습 전 한 번","비싸지만 배치 크기만큼 싸요"]]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"BORF calculates exact optimal transport geometry infrequently but effectively, resolving both problems without the overhead of SDRF.","ko":"BORF 는 정확한 최적 수송 기하를 드물게 그러나 효과적으로 계산해서 SDRF 의 큰 부담 없이 두 문제를 함께 해결한다.","tip":"**보알에프(BORF)** 의 슬로건은 정확한 계산을 드물게 예요."},{"kind":"warn","head":"복잡도 식에서 헷갈리기 쉬운 점","items":["$D$ 는 평균 **차수(Degree)** 가 아니라 최대 차수예요. 허브 하나에 비용이 세제곱으로 뛰어요.","배치를 키우면 공짜로 빨라진다고 읽으면 안 돼요. 낡은 곡률 정보로 여러 엣지를 고르게 돼요.","한 번의 곡률 계산 자체는 **보알에프(BORF)** 가 더 비싸요. 횟수를 줄여서 전체가 이득인 거예요."]},{"kind":"check","q":"복잡도 식의 $D^{3}$ 은 어디에서 오나요?","choices":["층 수","이웃 사이의 **최적 수송(Optimal Transport)** 문제를 푸는 비용","엣지 수","배치 크기"],"a":1,"why":"엣지 양 끝의 이웃이 최대 $D$ 명이라 $D$ 곱하기 $D$ 짜리 수송 문제가 되고, 푸는 데 세제곱쯤 들어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.613,0.1648],"c":[0,0.0019,0.6743,0.1968],"r":6.0912,"img":"img/L5/walk/p083_h.jpg"},"parts":[{"b":[0.05,0.19,0.9,0.09],"c":[0.005,0.135,0.99,0.2],"r":8.8,"img":"img/L5/walk/p083_11_01.jpg","say":"알고리즘 효율이에요. 배치로 재배선해서 곡률 재계산 횟수를 크게 줄인다고 적혀 있어요."},{"b":[0.4,0.4,0.22,0.11],"c":[0.388,0.384,0.244,0.142],"r":3.0548,"img":"img/L5/walk/p083_11_02.jpg","say":"가운데 식이 계산 복잡도예요. 분모에 h 더하기 k 가 있어요."},{"b":[0.05,0.57,0.92,0.09],"c":[0,0.5128,1,0.2045],"r":8.6933,"img":"img/L5/walk/p083_11_03.jpg","say":"맨 아래는 SDRF 보다 나은 점이에요. 정확한 기하를 드물게 계산한다고 했어요."}]}},{"p":84,"title":"멀티홉 집계: 여러 거리를 한 번에","terms":["Receptive Field","Over-smoothing","MixHop","GCN"],"pass1":[{"kind":"say","lines":["마지막 묶음이에요. 제목은 **멀티홉, 멀티스케일 집계** 예요.","**층을 쌓지 않고 한 층 안에서 여러 거리의 이웃을 동시에 가져오는** 방식이에요.","깊이 문제를 **옆으로 넓혀서** 피해 가요."]},{"kind":"analogy","head":"계단과 망원경","scene":"높은 곳을 보려고 계단을 한 칸씩 올라가요. 열 칸을 오르면 멀리 보이기는 하는데 다리가 아프고 숨이 차요. 대신 제자리에 서서 배율이 다른 망원경 세 개를 동시에 들면 어떨까요. 가까운 것도 먼 것도 한꺼번에 보이는데 계단은 하나도 안 올라갔어요.","map":[["계단을 한 칸씩 오르기","GNN 층을 하나씩 쌓기"],["다리가 아프고 숨이 차는 것","**과도한 평활화(Over-smoothing)**"],["망원경 세 개를 동시에 들기","한 층에서 여러 홉을 동시에 쓰기"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"points","head":"낯선 말 두 개를 풀어요","items":["**홉(hop)** 은 엣지를 몇 번 건너느냐예요. 1홉 이웃은 바로 옆 노드예요","**스케일(scale)** 은 얼마나 멀리까지 보느냐예요","여러 스케일을 쓴다는 것은 **가까운 것과 먼 것을 함께 본다** 는 말이에요","**수용 영역(Receptive Field)** 이 한 층 안에서 바로 넓어져요"]},{"kind":"figure","head":"깊이로 넓히기와 한 층에서 넓히기","svg":"<svg viewBox=\"0 0 480 210\">\n <text class=\"tb\" x=\"120\" y=\"22\" text-anchor=\"middle\" font-size=\"15\">깊이로 넓히기<\/text>\n <rect class=\"box\" x=\"18\" y=\"36\" width=\"56\" height=\"28\" rx=\"5\"/>\n <text class=\"t\" x=\"46\" y=\"55\" text-anchor=\"middle\" font-size=\"13\">층 1<\/text>\n <line class=\"arrow\" x1=\"74\" y1=\"50\" x2=\"94\" y2=\"50\"/>\n <rect class=\"box\" x=\"96\" y=\"36\" width=\"56\" height=\"28\" rx=\"5\"/>\n <text class=\"t\" x=\"124\" y=\"55\" text-anchor=\"middle\" font-size=\"13\">층 2<\/text>\n <line class=\"arrow\" x1=\"152\" y1=\"50\" x2=\"172\" y2=\"50\"/>\n <rect class=\"box\" x=\"174\" y=\"36\" width=\"56\" height=\"28\" rx=\"5\"/>\n <text class=\"t\" x=\"202\" y=\"55\" text-anchor=\"middle\" font-size=\"13\">층 3<\/text>\n <text class=\"t\" x=\"124\" y=\"82\" text-anchor=\"middle\" font-size=\"13\">3홉 보려면 3층. 깊으면 과평활<\/text>\n <text class=\"tb b1\" x=\"120\" y=\"116\" text-anchor=\"middle\" font-size=\"15\">한 층에서 넓히기<\/text>\n <rect class=\"box2 b1\" x=\"18\" y=\"128\" width=\"212\" height=\"32\" rx=\"5\"/>\n <text class=\"tl b1\" x=\"54\" y=\"149\" text-anchor=\"middle\" font-size=\"13\">A의 1제곱<\/text>\n <text class=\"tl b1\" x=\"124\" y=\"149\" text-anchor=\"middle\" font-size=\"13\">A의 2제곱<\/text>\n <text class=\"tl b1\" x=\"194\" y=\"149\" text-anchor=\"middle\" font-size=\"13\">A의 3제곱<\/text>\n <text class=\"t b1\" x=\"124\" y=\"178\" text-anchor=\"middle\" font-size=\"13\">층 하나로 3홉까지 닿아요<\/text>\n <text class=\"tb\" x=\"364\" y=\"22\" text-anchor=\"middle\" font-size=\"15\">시야 넓이<\/text>\n <circle class=\"n2\" cx=\"356\" cy=\"104\" r=\"9\"/>\n <circle class=\"n b2\" cx=\"356\" cy=\"104\" r=\"26\"/>\n <circle class=\"n3 b2\" cx=\"356\" cy=\"104\" r=\"44\"/>\n <circle class=\"n4 b2\" cx=\"356\" cy=\"104\" r=\"62\"/>\n <text class=\"t b2\" x=\"440\" y=\"70\" font-size=\"13\">1홉<\/text>\n <text class=\"t b2\" x=\"440\" y=\"104\" font-size=\"13\">2홉<\/text>\n <text class=\"t b2\" x=\"440\" y=\"138\" font-size=\"13\">3홉<\/text>\n <text class=\"t b2\" x=\"364\" y=\"196\" text-anchor=\"middle\" font-size=\"13\">세 테두리를 동시에 써요<\/text>\n<\/svg>","caption":"같은 3홉 시야를 층 셋 대신 층 하나로 얻어요.","builds":2},{"kind":"compare","head":"네 갈래 중 어디쯤인가","cols":["묶음","고친 것","쪽"],"rows":[["스킵 연결","모델 안에 지름길","p.37 부터 p.57"],["정규화와 규제","층을 지날 때의 값","p.58 부터 p.73"],["그래프 재배선","그래프의 모양","p.74 부터 p.83"],["**멀티홉 집계**","**깊게 쌓는다는 전제 자체**","p.84 부터 p.96"]]},{"kind":"points","head":"이 묶음에서 배울 세 모델","items":["**MixHop** 은 인접행렬의 거듭제곱들을 한 층에서 섞어요","**APPNP** 는 예측과 전파를 완전히 떼어 놓아요","**GPR-GNN** 은 홉마다의 가중치까지 배우게 해요","세 모델이 점점 발전하는 순서로 나와요"]}],"pass3":[{"kind":"warn","head":"자주 나오는 오해","items":["멀티홉이라고 **층이 꼭 하나인 것은 아니에요.** 실제로는 몇 층 쌓기도 해요","핵심은 **같은 시야를 훨씬 적은 층으로** 얻는다는 것이에요","1층 MixHop 이 3층 GCN 과 비슷한 시야를 가져요"]}],"pass4":[],"walk":{"head":{"b":[0.04,0.2911,0.4445,0.0669],"c":[0.0178,0.2751,0.489,0.0989],"r":8.79,"img":"img/L5/walk/p084_h.jpg"},"parts":[{"b":[0.04,0.36,0.42,0.12],"c":[0.019,0.344,0.462,0.152],"r":5.4035,"img":"img/L5/walk/p084_12_01.jpg","say":"제목이 **멀티 홉 / 멀티 스케일 집계** 예요."},{"b":[0.04,0.5,0.5,0.06],"c":[0.015,0.4744,0.55,0.1111],"r":8.8009,"img":"img/L5/walk/p084_12_02.jpg","say":"아래 한 줄이에요. 여러 홉 거리의 정보를 한 번에 모으는 일이래요."}]}},{"p":85,"title":"MixHop: 층을 쌓아도 못 하는 일이 있다","terms":["MixHop","Delta Operator","GCN","Adjacency Matrix","ReLU"],"pass1":[{"kind":"say","lines":["**믹스홉(MixHop)** 은 **제이케이넷(JK-Net)** 과 비슷하지만 자리가 달라요.","JK-Net 은 층들을 나중에 모으고, MixHop 은 한 층 안에서 여러 홉을 동시에 봐요.","먼저 왜 그래야 하는지부터 봐요.","정리 1 은 기본 GCN 이 층을 무한히 쌓아도 못 하는 일이 있다고 말해요."]},{"kind":"analogy","head":"배율이 다른 사진 두 장","scene":"카메라로 같은 곳을 1배율과 2배율로 찍어서 두 장의 차이를 보고 싶어요. 그런데 이 카메라는 배율을 계속 곱하기만 해요. 두 번 당기면 2배율 사진 한 장만 남아요. 차이를 보려면 두 장을 동시에 손에 들고 있어야 하는데 그게 안 되는 거예요.","map":[["1배율 사진","1홉 이웃 평균"],["2배율 사진","2홉 이웃 평균"],["두 장의 차이를 보기","**델타 연산자(Delta Operator)**"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"steps","head":"왜 층을 쌓아도 안 되나요","steps":["활성화 함수를 잠깐 빼고 두 층을 펼쳐 봐요.","$H^{(2)} = \\hat{A}(\\hat{A}H^{(0)}W^{(0)})W^{(1)}$ 이에요.","이것은 $\\hat{A}^2 H^{(0)}(W^{(0)}W^{(1)})$ 로 정리돼요.","가중치 두 개가 곱해져 하나가 되고, **인접행렬(Adjacency Matrix)** 은 제곱이 됐어요.","$\\ell$ 층을 쌓으면 $\\hat{A}^{\\ell}H^{(0)}W^{*}$ 하나만 남아요."],"answer":"1홉 항이 사라져서 1홉과 2홉의 차이를 만들 수가 없어요.","given":"슬라이드가 말한 중간 단계를 선형으로 대비시킬 힘이 없다가 이것이에요."},{"kind":"points","head":"못 하는 것이 정확히 무엇인가요","items":["2홉 이웃을 못 본다는 뜻이 아니에요. 2홉은 잘 봐요.","못 하는 것은 1홉 것과 2홉 것의 차이를 만드는 일이에요.","결과에는 거듭제곱 하나만 남으니 뺄셈이 불가능해요.","**믹스홉(MixHop)** 의 해결책은 한 층 안에서 여러 거듭제곱을 나란히 계산하는 것이에요."]}],"pass3":[{"kind":"warn","head":"정리 1 을 읽을 때 주의할 점","items":["이 논증은 **렐루(ReLU)** 를 무시한 선형 근사에서 가장 깔끔해요.","슬라이드가 본질적으로 환원된다고 조심스럽게 쓴 이유예요.","$W^{*}$ 의 별표는 최적해가 아니라 여러 가중치가 곱해져 생긴 하나라는 뜻이에요."]},{"kind":"check","q":"정리 1 에 따르면 기본 **그래프 합성곱 신경망(GCN)** 이 못 하는 일은 무엇인가요?","choices":["2홉 이웃을 보는 일","1홉 정보와 2홉 정보의 차이를 만드는 일","노드를 분류하는 일","가중치를 학습하는 일"],"a":1,"why":"층을 쌓으면 거듭제곱 하나로 뭉쳐져서 중간 단계를 따로 들고 뺄 수가 없어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0178,0.2546,0.1593],"c":[0.0004,0.0018,0.2801,0.1913],"r":2.603,"img":"img/L5/walk/p085_h.jpg"},"parts":[{"b":[0.09,0.19,0.28,0.05],"c":[0.076,0.16,0.308,0.11],"r":4.9778,"img":"img/L5/walk/p085_20_01.jpg","say":"첫 줄은 기본 **그래프 합성곱 신경망(GCN)** 갱신 규칙이에요. 아래 식이 그것이에요."},{"b":[0.09,0.32,0.86,0.05],"c":[0.047,0.2494,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p085_20_02.jpg","say":"둘째 줄은 기호 설명이에요. 정규화 **인접행렬(Adjacency Matrix)** 과 노드 특징, 학습되는 가중치예요."},{"b":[0.09,0.42,0.88,0.09],"c":[0.032,0.3672,0.968,0.1956],"r":8.798,"img":"img/L5/walk/p085_20_03.jpg","say":"셋째 줄이 정리 1 이에요. 층을 무한히 쌓아도 2홉 **델타 연산자(Delta Operator)** 를 표현할 수 없어요."},{"b":[0.36,0.58,0.28,0.32],"c":[0.346,0.564,0.308,0.352],"r":1.5556,"img":"img/L5/walk/p085_20_04.jpg","say":"아래 그림은 GCN 층 하나예요. 보는 범위가 딱 1홉인 것이 요점이에요."}]}},{"p":86,"title":"델타 연산자란 무엇인가","terms":["Delta Operator","MixHop","Injective Mapping","Heterophily","Homophily","ReLU"],"pass1":[{"kind":"say","lines":["**델타 연산자(Delta Operator)** 는 홉 거리가 다른 이웃 정보의 차이를 잡아내는 함수예요.","경계에 있는 노드를 찾거나, 가까운 구조와 넓은 구조를 대비할 때 꼭 필요해요.","식으로는 1홉 평균에서 2홉 평균을 뺀 것에 함수를 하나 씌운 모양이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"formula","head":"두 홉 델타 연산자","tex":"f\\left(\\sigma(\\hat{A}X) - \\sigma(\\hat{A}^2 X)\\right)","parts":[{"sym":"\\hat{A}X","say":"1홉 이웃 평균이에요. 이웃들의 특징을 섞은 값이에요."},{"sym":"\\hat{A}^2 X","say":"2홉 이웃 평균이에요. 이웃의 이웃까지 섞은 값이에요."},{"sym":"\\sigma","say":"**렐루(ReLU)** 예요. 뺄셈 전에 각각 먼저 씌워요."},{"sym":"f","say":"**단사 사상(Injective Mapping)** 이에요. 차이가 다르면 결과도 달라야 해요."}],"whole":"1홉 평균과 2홉 평균을 각각 구해 서로 뺀 뒤, 그 차이를 보존하는 함수를 씌워요."},{"kind":"points","head":"왜 홉 차이가 중요한가요","items":["두 커뮤니티가 맞닿은 자리의 노드는 1홉과 2홉이 많이 달라요.","커뮤니티 한가운데 노드는 1홉이든 2홉이든 같은 사람들이라 차이가 거의 0 이에요.","그래서 차이가 크면 경계, 작으면 내부예요.","**이종선호(Heterophily)** 그래프에서도 같은 이유로 중요해요. 이웃의 이웃이 나와 더 비슷하거든요."]},{"kind":"steps","head":"숫자로 델타를 구해 봐요","steps":["노드 4개에 엣지 1과 2, 1과 3, 2와 3, 3과 4 가 있어요. 노드 4 에만 특징 6 이 있어요.","1홉을 구하면 노드 3 만 $\\tfrac13(0+0+6)=2$ 를 받고 나머지는 0 이에요.","2홉을 구하면 노드 1 과 2 가 각각 $\\tfrac12(0)+\\tfrac12(2)=1$ 이 되고 노드 4 는 2 예요.","노드 3 은 이번에는 0 이에요.","둘을 빼면 $-1$, $-1$, $2$, $-2$ 가 나와요."],"answer":"부호만 봐도 신호원에서 한 칸인지 두 칸인지 알 수 있어요. 노드 3 만 양수예요.","given":"**렐루(ReLU)** 를 씌워도 음수가 없어서 값이 그대로예요."},{"kind":"mining","src":"마이닝 5강 Community Detection","lines":["커뮤니티는 안쪽 연결이 유난히 촘촘한 노드 덩어리예요.","그 경계에 있는 노드를 찾는 일이 커뮤니티 탐지에서 늘 문제였어요.","**델타 연산자(Delta Operator)** 는 그 경계를 홉 차이로 잡아내요.","**동질성(Homophily)** 이 약한 그래프일수록 이런 장치가 더 필요해요."]}],"pass3":[{"kind":"warn","head":"식에서 헷갈리기 쉬운 점","items":["뺄셈은 **렐루(ReLU)** 를 씌운 뒤에 해요. 괄호 위치를 잘 보세요.","$\\hat{A}^2$ 는 행렬을 두 번 곱한 것이지 각 원소를 제곱한 것이 아니에요.","$f$ 가 **단사 사상(Injective Mapping)** 이어야 한다는 조건을 빠뜨리지 마세요.","**델타 연산자(Delta Operator)** 는 **믹스홉(MixHop)** 이 만들려는 목표이지 MixHop 자체가 아니에요."]},{"kind":"check","q":"**델타 연산자(Delta Operator)** 가 잘 잡아내는 노드는 어떤 노드인가요?","choices":["차수가 가장 큰 노드","두 커뮤니티가 맞닿은 경계 노드","고립된 노드","라벨이 없는 노드"],"a":1,"why":"경계 노드는 1홉과 2홉의 구성이 크게 달라서 차이가 커요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0178,0.1795,0.1593],"c":[0.0011,0.0018,0.2035,0.1913],"r":1.8912,"img":"img/L5/walk/p086_h.jpg"},"parts":[{"b":[0.04,0.2,0.92,0.09],"c":[0.0,0.1428,1,0.2045],"r":8.6933,"img":"img/L5/walk/p086_11_01.jpg","say":"첫 줄이 이것이 무엇인가예요. 홉 거리가 다른 이웃 사이의 특징 차이를 잡는 함수예요."},{"b":[0.04,0.43,0.92,0.09],"c":[0.0,0.3728,1,0.2045],"r":8.6933,"img":"img/L5/walk/p086_11_02.jpg","say":"둘째 줄이 형식 정의예요. **단사 사상(Injective Mapping)** 과 파라미터 설정이 있으면 표현한다고 해요."},{"b":[0.36,0.58,0.28,0.08],"c":[0.346,0.564,0.308,0.112],"r":4.8889,"img":"img/L5/walk/p086_11_03.jpg","say":"그 아래 가운데 식이 델타 연산자예요."}]}},{"p":87,"title":"MixHop 층: 거듭제곱들을 한 층에서 섞는다","terms":["MixHop","Delta Operator","Concatenation","Adjacency Matrix","GCN","ReLU"],"pass1":[{"kind":"say","lines":["**믹스홉(MixHop)** 층은 0홉, 1홉, 2홉을 각각 계산해요.","그리고 홉마다 다른 가중치를 곱한 뒤 옆으로 이어 붙여요.","조각이 따로 남아 있으니 다음 층이 서로 뺄 수 있어요.","그래서 p.86 의 **델타 연산자(Delta Operator)** 를 만들 수 있게 돼요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"formula","head":"MixHop 층 식","tex":"H^{(i+1)} = \\Big\\|_{j \\in P}\\ \\sigma\\left(\\hat{A}^{j} H^{(i)} W_j^{(i)}\\right)","parts":[{"sym":"P","say":"쓸 거듭제곱들의 집합이에요. 보통 0, 1, 2 예요."},{"sym":"\\hat{A}^{0}","say":"단위행렬이에요. 아무 데도 안 가고 자기 특징 그대로예요."},{"sym":"\\hat{A}^{j}","say":"**인접행렬(Adjacency Matrix)** 을 $j$ 번 곱한 것이에요."},{"sym":"W_j^{(i)}","say":"홉 거리마다 따로 두는 가중치 행렬이에요. 아래첨자 $j$ 가 중요해요."},{"sym":"\\Big\\|_{j \\in P}","say":"열 방향 **이어 붙이기(Concatenation)** 예요. 차원이 늘어나요."}],"whole":"홉마다 이웃 평균을 구하고, 홉마다 다른 가중치를 곱하고, 결과를 옆으로 나란히 붙여요."},{"kind":"steps","head":"숫자로 세 갈래를 구해 봐요","steps":["노드 4개에 엣지 1과 2, 1과 3, 2와 3, 3과 4 가 있어요. 노드 4 에만 특징 6 이 있어요.","0홉 갈래는 그냥 원래 값이라 0, 0, 0, 6 이에요.","1홉 갈래는 0, 0, 2, 0 이에요. 노드 3 만 신호를 받았어요.","2홉 갈래는 1, 1, 0, 2 예요. 신호가 한 칸 더 퍼졌어요.","노드마다 세 값을 옆으로 붙이면 3차원 벡터가 돼요."],"answer":"노드 3 은 $(0, 2, 0)$, 노드 1 과 2 는 $(0, 0, 1)$, 노드 4 는 $(6, 0, 2)$ 예요.","given":"가중치는 전부 1 로 두고 $P$ 는 0, 1, 2 예요."},{"kind":"figure","head":"세 갈래로 나눠 계산하고 옆으로 붙여요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<rect class=\"box\" x=\"180\" y=\"18\" width=\"120\" height=\"30\" rx=\"7\"/>\n<text class=\"t\" x=\"240\" y=\"38\" font-size=\"15\" text-anchor=\"middle\">이전 층 표현<\/text>\n<polygon class=\"arrow\" points=\"96,68 112,60 108,76\"/>\n<polygon class=\"arrow\" points=\"234,68 246,68 240,78\"/>\n<polygon class=\"arrow\" points=\"372,76 368,60 384,68\"/>\n<rect class=\"box b1\" x=\"30\" y=\"78\" width=\"118\" height=\"30\" rx=\"6\"/>\n<text class=\"t b1\" x=\"89\" y=\"98\" font-size=\"15\" text-anchor=\"middle\">0홉: 나 자신<\/text>\n<rect class=\"box b1\" x=\"181\" y=\"78\" width=\"118\" height=\"30\" rx=\"6\"/>\n<text class=\"t b1\" x=\"240\" y=\"98\" font-size=\"15\" text-anchor=\"middle\">1홉 이웃 평균<\/text>\n<rect class=\"box b1\" x=\"332\" y=\"78\" width=\"118\" height=\"30\" rx=\"6\"/>\n<text class=\"t b1\" x=\"391\" y=\"98\" font-size=\"15\" text-anchor=\"middle\">2홉 이웃 평균<\/text>\n<polygon class=\"arrow b2\" points=\"83,112 95,112 89,122\"/>\n<polygon class=\"arrow b2\" points=\"234,112 246,112 240,122\"/>\n<polygon class=\"arrow b2\" points=\"385,112 397,112 391,122\"/>\n<rect class=\"box2 b2\" x=\"30\" y=\"124\" width=\"118\" height=\"30\" rx=\"6\"/>\n<text class=\"t b2\" x=\"89\" y=\"144\" font-size=\"15\" text-anchor=\"middle\">가중치 W0<\/text>\n<rect class=\"box2 b2\" x=\"181\" y=\"124\" width=\"118\" height=\"30\" rx=\"6\"/>\n<text class=\"t b2\" x=\"240\" y=\"144\" font-size=\"15\" text-anchor=\"middle\">가중치 W1<\/text>\n<rect class=\"box2 b2\" x=\"332\" y=\"124\" width=\"118\" height=\"30\" rx=\"6\"/>\n<text class=\"t b2\" x=\"391\" y=\"144\" font-size=\"15\" text-anchor=\"middle\">가중치 W2<\/text>\n<polygon class=\"arrow b3\" points=\"128,164 144,172 128,180\"/>\n<polygon class=\"arrow b3\" points=\"234,164 246,164 240,176\"/>\n<polygon class=\"arrow b3\" points=\"352,180 336,172 352,164\"/>\n<rect class=\"hl b3\" x=\"126\" y=\"184\" width=\"76\" height=\"34\" rx=\"5\"/>\n<text class=\"t b3\" x=\"164\" y=\"206\" font-size=\"15\" text-anchor=\"middle\">0홉 조각<\/text>\n<rect class=\"hl b3\" x=\"202\" y=\"184\" width=\"76\" height=\"34\" rx=\"5\"/>\n<text class=\"t b3\" x=\"240\" y=\"206\" font-size=\"15\" text-anchor=\"middle\">1홉 조각<\/text>\n<rect class=\"hl b3\" x=\"278\" y=\"184\" width=\"76\" height=\"34\" rx=\"5\"/>\n<text class=\"t b3\" x=\"316\" y=\"206\" font-size=\"15\" text-anchor=\"middle\">2홉 조각<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"242\" font-size=\"16\" text-anchor=\"middle\">세 조각을 옆으로 이어 붙여요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"264\" font-size=\"14\" text-anchor=\"middle\">조각이 따로 남아 있어야 다음 층이 서로 뺄 수 있어요<\/text>\n<\/svg>","caption":"차원이 집합 크기만큼 커져요. 여기서는 세 배예요.","builds":3},{"kind":"points","head":"왜 이것이 델타 연산자를 만드나요","items":["층 하나의 출력에 0홉, 1홉, 2홉 조각이 따로 살아 있어요.","그러면 다음 층이 첫 조각에 더하기, 둘째 조각에 빼기 같은 가중치를 배울 수 있어요.","그 순간 **델타 연산자(Delta Operator)** 가 만들어져요.","기본 **그래프 합성곱 신경망(GCN)** 은 조각이 하나로 뭉쳐서 이 뺄셈이 불가능했어요."]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"A MixHop layer computes powers of the adjacency matrix, applies a separate weight matrix to each, and concatenates the results column-wise.","ko":"MixHop 층은 인접행렬의 거듭제곱들을 계산하고 각각에 별도의 가중치 행렬을 적용한 뒤 열 방향으로 이어 붙인다.","tip":"뒤에 한 줄 덧붙이면 좋아요. 조각이 분리된 채 남아 있어서 다음 층이 서로 대비시킬 수 있다."},{"kind":"warn","head":"여기서 헷갈리기 쉬워요","items":["$\\hat{A}^{0}$ 은 0 이 아니라 단위행렬이에요. 그래서 자기 특징 그대로예요.","$W_j$ 는 홉마다 다른 행렬이에요. 같은 $W$ 를 쓰면 **믹스홉(MixHop)** 의 의미가 사라져요.","**이어 붙이기(Concatenation)** 는 열 방향이에요. 노드 수가 아니라 차원이 늘어나요.","**제이케이넷(JK-Net)** 은 층들을 나중에 모으고 MixHop 은 한 층 안에서 동시에 봐요. 자리가 달라요."]},{"kind":"check","q":"**믹스홉(MixHop)** 층의 출력 차원은 어떻게 되나요?","choices":["그대로예요","거듭제곱 집합의 크기만큼 커져요","절반이 돼요","노드 수만큼 커져요"],"a":1,"why":"세 갈래를 옆으로 붙이니 세 배가 돼요. 그만큼 가중치도 세 벌 필요해요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0178,0.1418,0.1593],"c":[0,0.0018,0.2,0.1913],"r":1.8586,"img":"img/L5/walk/p087_h.jpg"},"parts":[{"b":[0.09,0.2,0.64,0.05],"c":[0.058,0.1539,0.704,0.1422],"r":8.8014,"img":"img/L5/walk/p087_11_01.jpg","say":"핵심 혁신 한 가지예요. 표준 층을 거듭제곱들을 대놓고 섞는 층으로 바꿔요."},{"b":[0.36,0.34,0.24,0.06],"c":[0.348,0.315,0.264,0.11],"r":4.2667,"img":"img/L5/walk/p087_11_02.jpg","say":"가운데 식이 **믹스홉(MixHop)** 층 식이에요."},{"b":[0.65,0.34,0.11,0.3],"c":[0.605,0.324,0.2,0.332],"r":1.071,"img":"img/L5/walk/p087_11_03.jpg","say":"오른쪽 (a) 가 보통 GCN 층이에요. 길이 하나뿐이에요."},{"b":[0.78,0.26,0.2,0.38],"c":[0.768,0.241,0.224,0.418],"r":0.9527,"img":"img/L5/walk/p087_11_04.jpg","say":"오른쪽 (b) 가 MixHop 구조예요. 길이 세 갈래로 갈라져요."}]}},{"p":88,"title":"개인화 페이지랭크: 순간이동으로 지역성 지키기","terms":["Personalized PageRank","PageRank","Teleport Probability","Random Walk","Damping Factor","Stationary Distribution","PPNP"],"pass1":[{"kind":"say","lines":["이제 또 다른 접근이에요. 전파를 아예 신경망에서 떼어 내요.","그 출발점이 **개인화 페이지랭크(Personalized PageRank)** 예요.","**랜덤워크(Random Walk)** 에 순간이동을 넣은 것이에요.","매 걸음마다 확률 $\\alpha$ 로 출발 노드로 돌아가요."]},{"kind":"analogy","head":"길을 걷다 집으로 순간이동","scene":"한 아이가 동네를 돌아다녀요. 갈림길마다 아무 길이나 하나 골라 걸어요. 오래 걸으면 자기가 어디서 출발했는지 잊어버려요. 그래서 규칙을 하나 넣었어요. 매 걸음마다 동전을 던져 앞면이 나오면 집으로 순간이동해서 거기서 다시 시작해요.","map":[["아무 길이나 골라 걷기","**랜덤워크(Random Walk)**"],["동전 던져 집으로 가기","**순간이동 확률(Teleport Probability)**"],["출발점을 잊지 않기","지역 이웃을 지키는 효과"]]}],"pass2":[{"kind":"mining","src":"마이닝 3강 Centrality","lines":["**페이지랭크(PageRank)** 는 중요한 페이지에게서 링크된 페이지가 더 중요하다는 점수예요.","자기 점수를 나가는 링크 수로 나눠 똑같이 나눠 줘요.","여기에 **감쇠 인자(Damping Factor)** 를 넣어요. 보통 0.85 로 둬요.","값이 한 번에 안 나와서 반복 계산으로 구해요."]},{"kind":"look","walked":1},{"kind":"formula","head":"PPR 행렬","tex":"\\Pi_{PPR} = \\alpha\\left(I_n - (1-\\alpha)\\hat{\\tilde{A}}\\right)^{-1}","parts":[{"sym":"\\alpha","say":"**순간이동 확률(Teleport Probability)** 이에요. 0 과 1 사이 숫자예요."},{"sym":"1-\\alpha","say":"그냥 이웃으로 한 걸음 갈 확률이에요."},{"sym":"I_n","say":"단위행렬이에요."},{"sym":"(\\cdot)^{-1}","say":"역행렬이에요. 무한 번 걸은 결과를 한 번에 구해 줘요."}],"whole":"한 걸음 가거나 뿌리로 돌아가거나를 무한히 반복한 결과를 한 식으로 적은 것이에요."},{"kind":"steps","head":"삼각형 그래프에서 순간이동의 효과를 봐요","steps":["노드 셋이 삼각형이고 뿌리는 노드 1 이에요. 처음 값은 1, 0, 0 이에요.","순간이동이 없으면 걸음 1 에 0, 0.5, 0.5 가 되고 걸음 2 에 0.5, 0.25, 0.25 가 돼요.","걸음 4 에는 0.375, 0.3125, 0.3125 로 점점 삼분의 일에 가까워져요.","순간이동 확률 0.5 를 넣으면 걸음 1 에 0.5, 0.25, 0.25 예요.","걸음 2 에 0.625, 0.1875, 0.1875, 걸음 4 에 약 0.602, 0.199, 0.199 예요."],"answer":"순간이동이 없으면 0.333 으로 평평해지고, 있으면 노드 1 이 0.6 을 끝까지 유지해요.","given":"평평해진 값이 **정상 분포(Stationary Distribution)** 예요."},{"kind":"figure","head":"순간이동이 있고 없고의 차이","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"17\" text-anchor=\"middle\">뿌리 노드 1 의 값이 어떻게 변하나<\/text>\n<text class=\"tm\" x=\"120\" y=\"52\" font-size=\"14\" text-anchor=\"middle\">순간이동 없음<\/text>\n<line class=\"e\" x1=\"36\" y1=\"200\" x2=\"212\" y2=\"200\"/>\n<rect class=\"box\" x=\"48\" y=\"80\" width=\"30\" height=\"120\" rx=\"3\"/>\n<text class=\"tm\" x=\"63\" y=\"218\" font-size=\"14\" text-anchor=\"middle\">0걸음<\/text>\n<rect class=\"box b1\" x=\"106\" y=\"140\" width=\"30\" height=\"60\" rx=\"3\"/>\n<text class=\"tm b1\" x=\"121\" y=\"218\" font-size=\"14\" text-anchor=\"middle\">2걸음<\/text>\n<rect class=\"box b1\" x=\"164\" y=\"155\" width=\"30\" height=\"45\" rx=\"3\"/>\n<text class=\"tm b1\" x=\"179\" y=\"218\" font-size=\"14\" text-anchor=\"middle\">4걸음<\/text>\n<line class=\"hl b1\" x1=\"36\" y1=\"160\" x2=\"212\" y2=\"160\"/>\n<text class=\"tm b1\" x=\"120\" y=\"242\" font-size=\"14\" text-anchor=\"middle\">삼분의 일로 평평해져요<\/text>\n<text class=\"tm\" x=\"356\" y=\"52\" font-size=\"14\" text-anchor=\"middle\">순간이동 확률 0.5<\/text>\n<line class=\"e\" x1=\"272\" y1=\"200\" x2=\"448\" y2=\"200\"/>\n<rect class=\"box2\" x=\"284\" y=\"80\" width=\"30\" height=\"120\" rx=\"3\"/>\n<text class=\"tm\" x=\"299\" y=\"218\" font-size=\"14\" text-anchor=\"middle\">0걸음<\/text>\n<rect class=\"box2 b2\" x=\"342\" y=\"125\" width=\"30\" height=\"75\" rx=\"3\"/>\n<text class=\"tm b2\" x=\"357\" y=\"218\" font-size=\"14\" text-anchor=\"middle\">2걸음<\/text>\n<rect class=\"box2 b2\" x=\"400\" y=\"128\" width=\"30\" height=\"72\" rx=\"3\"/>\n<text class=\"tm b2\" x=\"415\" y=\"218\" font-size=\"14\" text-anchor=\"middle\">4걸음<\/text>\n<line class=\"hl b2\" x1=\"272\" y1=\"128\" x2=\"448\" y2=\"128\"/>\n<text class=\"tm b2\" x=\"356\" y=\"242\" font-size=\"14\" text-anchor=\"middle\">영점 육을 끝까지 유지해요<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"264\" font-size=\"16\" text-anchor=\"middle\">순간이동이 있으면 출발점을 잊지 않아요<\/text>\n<\/svg>","caption":"뿌리 노드가 누구였는지가 지워지느냐 남느냐의 차이예요.","builds":3}],"pass3":[{"kind":"warn","head":"표기에서 헷갈리기 쉬워요","items":["$\\alpha$ 는 돌아갈 확률이에요. 마이닝의 **감쇠 인자(Damping Factor)** 와 방향이 반대예요.","페이지랭크의 0.85 는 링크를 따라갈 확률이고, 여기 $\\alpha$ 는 보통 0.1 이나 0.2 로 작아요.","보통 **페이지랭크(PageRank)** 는 아무 노드로나 점프하고, 개인화는 정해진 뿌리로만 돌아가요.","그래서 개인화라는 말이 붙은 거예요."]},{"kind":"check","q":"**순간이동 확률(Teleport Probability)** 이 없으면 무한히 걸었을 때 어떻게 되나요?","choices":["출발점 값이 가장 커진다","출발점을 잊고 **정상 분포(Stationary Distribution)** 로 수렴한다","값이 0 이 된다","값이 무한대가 된다"],"a":1,"why":"삼각형 예에서 세 노드가 전부 삼분의 일이 됐어요. 어디서 출발했는지 알 수 없어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.465,0.1593],"c":[0,0.0019,0.5115,0.1913],"r":4.7534,"img":"img/L5/walk/p088_h.jpg"},"parts":[{"b":[0.09,0.2,0.6,0.05],"c":[0.06,0.1583,0.66,0.1333],"r":8.8022,"img":"img/L5/walk/p088_21_01.jpg","say":"개념이에요. 전파 깊이와 상관없이 국소 이웃을 지키도록 랜덤워크를 고쳐요."},{"b":[0.09,0.31,0.86,0.09],"c":[0.047,0.2594,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p088_21_02.jpg","say":"**순간이동 확률(Teleport Probability)** 장치예요. 매 걸음마다 원래 출발 노드로 되돌아가요."},{"b":[0.33,0.48,0.26,0.07],"c":[0.317,0.46,0.286,0.11],"r":4.6222,"img":"img/L5/walk/p088_21_03.jpg","say":"가운데 식이 **개인화 페이지랭크(Personalized PageRank)** 행렬이에요."},{"b":[0.33,0.66,0.36,0.28],"c":[0.312,0.644,0.396,0.312],"r":2.2564,"img":"img/L5/walk/p088_21_04.jpg","say":"아래 그림에서 왼쪽은 신경망 예측, 오른쪽은 그래프 전파예요. 이것이 **피피엔피(PPNP)** 의 구조예요."}]}},{"p":89,"title":"MixHop 이 넘어서는 표준 GCN 의 한계 네 가지","terms":["MixHop","GCN","Over-smoothing","Receptive Field","Adjacency Matrix","Identity Matrix"],"pass1":[{"kind":"say","lines":["MixHop 이 표준 GCN 의 **한계 네 가지** 를 어떻게 넘는지 표 하나로 정리하는 장이에요.","칸이 세 개예요. 한계, 표준 GCN, MixHop 이에요. MixHop 칸만 파란 바탕으로 강조돼 있어요.","마지막 줄, **계산 복잡도가 그대로** 라는 것이 가장 센 주장이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"네 줄을 하나씩","boxes":[{"x":0.03,"y":0.39,"w":0.94,"h":0.14,"say":"첫 줄 **차이 연산자를 배울 수 없다** 예요. GCN 은 2홉 특징에서 1홉 특징을 뺄 수 없는데 MixHop 은 할 수 있대요.","c":[0.0,0.3555,1,0.2089],"r":8.5102,"img":"img/L5/walk/p089_20_01.jpg"},{"x":0.03,"y":0.56,"w":0.94,"h":0.14,"say":"둘째 줄 **과평활과 좁은 수용 영역** 이에요. MixHop 은 한 층 안에서 여러 홉 이웃을 잡는대요.","c":[0.0,0.5255,1,0.2089],"r":8.5102,"img":"img/L5/walk/p089_20_02.jpg"},{"x":0.03,"y":0.73,"w":0.94,"h":0.14,"say":"셋째 줄 **층마다 이웃 범위가 하나로 고정** 이에요. MixHop 은 여러 스케일을 동시에 쓰고 용량 배분도 배운대요.","c":[0.0,0.6955,1,0.2089],"r":8.5102,"img":"img/L5/walk/p089_20_03.jpg"},{"x":0.03,"y":0.88,"w":0.94,"h":0.1,"say":"넷째 줄 **고차 집계의 비용** 이에요. 희소 전파로 간접 계산해서 복잡도가 같대요.","c":[0.0,0.7911,1,0.2089],"r":8.5102,"img":"img/L5/walk/p089_20_04.jpg"}]},{"kind":"compare","head":"표를 한 줄로 압축하면","cols":["한계","MixHop 의 답"],"rows":[["뺄셈을 못 배움","여러 홉을 섞어서 **뺄셈 가능**"],["멀리 보려면 깊어야 함","**한 층에서** 멀리 봄"],["스케일이 하나","**여러 스케일 + 배분도 학습**"],["넓히면 비싸짐","**같은 점근 복잡도**"]]},{"kind":"points","head":"표에서 꼭 짚을 세 가지","items":["**차이 연산자** 는 2홉에서 온 값 빼기 1홉에서 온 값 같은 것이에요. 이웃과 내가 얼마나 다른지를 재는 일이에요","**$\\hat{A}^0$ 은 항등 행렬** 이에요. 어떤 행렬이든 0 제곱은 항등 행렬이거든요","그래서 MixHop 은 **자기 자신, 1홉, 2홉** 을 함께 써요. 사실상 스킵 연결 노릇도 해요","셋째 줄의 **얼마나 용량을 줄지 배운다** 는 홉마다 출력 차원을 다르게 준다는 뜻이에요"]},{"kind":"steps","head":"복잡도가 왜 같은지 괄호를 바꿔 보면","steps":["나쁜 방법은 먼저 $\\hat{A} \\cdot \\hat{A}$ 를 계산해 $\\hat{A}^2$ 를 만드는 것이에요.","인접행렬은 대부분의 칸이 0 인 희소 행렬인데, 제곱하면 칸이 빽빽하게 채워져요.","노드가 백만 개면 그 행렬은 메모리에 올릴 수조차 없어요.","MixHop 은 괄호를 바꿔 묶어요. $\\hat{A}^2 H$ 를 $\\hat{A}(\\hat{A}H)$ 로 계산해요.","먼저 $\\hat{A}H$ 를 구하면 노드 수 곱하기 특징 수 크기예요. 거기에 $\\hat{A}$ 를 한 번 더 곱해요."],"answer":"중간에 큰 행렬이 안 생겨요. **희소 전파를 두 번 하는 것** 일 뿐이에요. 그래서 점근 복잡도가 바닐라 GCN 과 같아요.","given":"행렬 곱은 결합법칙이 성립해서 묶는 순서를 바꿔도 답은 같아요."}],"pass3":[{"kind":"warn","head":"이 장에서 가장 많이 틀리는 것","items":["**같은 점근 복잡도이지 같은 실제 시간은 아니에요.** 전파를 $K$ 번 하니 상수배만큼은 느려요","시험에서 asymptotic 이라는 단어를 빼먹으면 안 돼요","$\\hat{A}^0$ 이 **항등 행렬(Identity Matrix)** 이라는 것을 꼭 기억하세요","논문 제목의 Sparsified 가 바로 희소 전파로 간접 계산한다는 뜻이에요"]},{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"MixHop uses several propagation scales simultaneously and learns how much capacity to allocate to each, and it computes adjacency powers implicitly through repeated sparse propagation, so it keeps the same asymptotic computational complexity as vanilla GCN.","ko":"MixHop 은 여러 전파 스케일을 동시에 쓰고 각각에 줄 용량도 배우며, 인접행렬 거듭제곱을 희소 전파의 반복으로 간접 계산하기 때문에 바닐라 GCN 과 점근 계산 복잡도가 같아요.","tip":"두 절을 and 로 잇고 so 로 결론을 붙이는 틀이에요. 네 줄짜리 표의 셋째와 넷째 줄을 한 문장에 담았어요."},{"kind":"check","q":"MixHop 이 바닐라 GCN 과 **같은 점근 복잡도** 를 유지하는 비결은?","choices":["홉을 하나만 쓴다","$\\hat{A}^2$ 를 미리 계산해 저장한다","$\\hat{A}(\\hat{A}H)$ 로 묶어 희소 전파를 반복한다","노드를 일부만 쓴다"],"a":2,"why":"괄호를 바꿔 묶으면 빽빽한 큰 행렬을 만들지 않고 희소 곱만 반복하면 돼요."}],"pass4":[],"walk":{"head":{"b":[0.0129,0.0178,0.6911,0.2301],"c":[0,0.0018,0.7602,0.2621],"r":5.1563,"img":"img/L5/walk/p089_h.jpg"},"parts":[{"b":[0.03,0.27,0.13,0.05],"c":[0,0.24,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p089_11_01.jpg","say":"첫 칸 이름이 **한계** 예요."},{"b":[0.36,0.27,0.17,0.05],"c":[0.345,0.24,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p089_11_02.jpg","say":"둘째 칸이 **표준 GCN** 이에요."},{"b":[0.85,0.27,0.1,0.05],"c":[0.8,0.24,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p089_11_03.jpg","say":"셋째 칸이 **MixHop** 이에요. 이 칸만 파란 바탕이에요."}]}},{"p":90,"title":"PPNP: 예측과 전파를 떼어 놓는다","terms":["PPNP","Decoupling","Personalized PageRank","Over-smoothing","GCN"],"pass1":[{"kind":"say","lines":["**피피엔피(PPNP)** 의 핵심 발상은 **분리(Decoupling)** 예요.","먼저 신경망으로 노드마다 예측을 만들어요. 이때 그래프를 전혀 안 봐요.","그다음 그 예측을 개인화 페이지랭크 행렬로 그래프에 퍼뜨려요.","그래서 신경망의 깊이와 전파 거리가 완전히 따로 놀아요."]},{"kind":"analogy","head":"혼자 답을 내고 나서 의논하기","scene":"시험 문제를 푸는데 먼저 각자 혼자 답을 적어요. 이때는 옆 사람을 보지 않아요. 그다음에 자리에 앉은 대로 옆 사람들과 답을 나눠 봐요. 여러 번 돌수록 멀리 있는 친구 답까지 전해져요. 혼자 고민하는 시간과 의논하는 횟수가 서로 아무 상관이 없어요.","map":[["혼자 답 적기","신경망 예측 단계"],["옆 사람과 답 나누기","그래프 전파 단계"],["둘이 상관없다는 점","**분리(Decoupling)**"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"분리가 주는 세 가지 이득","items":["첫째, 신경망은 2층으로 얕게 두고 전파는 무한 단계로 할 수 있어요.","둘째, 순간이동 덕분에 노드가 자기 답을 상당히 유지해서 **과평활화(Over-smoothing)** 가 안 생겨요.","셋째, 어떤 예측 모델이든 앞에 끼워 넣을 수 있어요.","슬라이드가 말한 어떤 예측 모델이든 끼워 넣을 수 있다가 셋째 이득이에요."]},{"kind":"steps","head":"작은 예로 전파를 따라가요","steps":["노드 셋이 삼각형이에요. 신경망이 노드 1 에만 점수 3 을 주고 나머지는 0 이에요.","**개인화 페이지랭크(Personalized PageRank)** 행렬의 한 행은 0.6, 0.2, 0.2 예요.","노드 1 의 결과는 $0.6 \\times 3 = 1.8$ 이에요.","노드 2 의 결과는 $0.2 \\times 3 = 0.6$ 이에요.","노드 3 도 대칭이라 0.6 이에요."],"answer":"아무 정보도 없던 노드 2 와 3 이 노드 1 의 확신을 나눠 받았어요. 그래도 노드 1 이 여전히 가장 커요.","given":"신경망이 그래프를 몰라도 전파가 그래프 정보를 넣어 줘요."},{"kind":"compare","head":"보통 GNN 과 무엇이 다른가","cols":["항목","보통 **그래프 합성곱 신경망(GCN)**","**피피엔피(PPNP)**"],"rows":[["한 층이 하는 일","이웃 집계와 가중치 변환이 한 몸","둘이 따로예요"],["10홉을 보려면","층을 10개 쌓아야 해요","전파만 10번 하면 돼요"],["가중치 수","층 수만큼 늘어요","앞쪽 신경망에만 있어요"]]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"PPNP first applies a neural network to each node's own features and then propagates the predictions with the exact personalized PageRank matrix.","ko":"PPNP 는 먼저 각 노드의 특징에만 신경망을 적용하고, 그 예측을 정확한 개인화 페이지랭크 행렬로 전파한다.","tip":"뒤에 한 줄 덧붙이면 좋아요. 신경망 깊이가 전파 범위를 정하지 않으므로 얕은 MLP 로도 무한 전파를 쓸 수 있다."},{"kind":"warn","head":"여기서 헷갈리기 쉬워요","items":["이름이 예측한 다음 전파하기예요. 예측이 먼저이고 전파가 나중이에요.","예측 단계는 그래프를 전혀 안 써요. 그래서 국소 신경망 예측이라고 불러요.","전파 행렬에는 학습할 파라미터가 하나도 없어요. $\\alpha$ 는 사람이 정하는 상수예요.","정확한 PPR 이라는 말이 붙은 이유는 p.91 에서 근사하는 버전이 나오기 때문이에요."]},{"kind":"check","q":"**피피엔피(PPNP)** 에서 학습되는 파라미터는 어디에 있나요?","choices":["전파 행렬 안","앞쪽 신경망 안","둘 다","어디에도 없다"],"a":1,"why":"전파 행렬은 **개인화 페이지랭크(Personalized PageRank)** 로 정해져 있어요. 학습 대상이 아니에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.465,0.1593],"c":[0,0.0019,0.5115,0.1913],"r":4.7534,"img":"img/L5/walk/p090_h.jpg"},"parts":[{"b":[0.09,0.19,0.6,0.05],"c":[0.06,0.1483,0.66,0.1333],"r":8.8022,"img":"img/L5/walk/p090_20_01.jpg","say":"핵심 혁신이에요. 특징 변환과 그래프 전파를 분리한다고 적혀 있어요."},{"b":[0.09,0.26,0.86,0.05],"c":[0.047,0.1894,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p090_20_02.jpg","say":"단계 1 이에요. 노드 특징에 신경망을 바로 적용해 기본 예측을 만들어요."},{"b":[0.09,0.42,0.66,0.05],"c":[0.057,0.3717,0.726,0.1467],"r":8.798,"img":"img/L5/walk/p090_20_03.jpg","say":"단계 2 예요. 그 예측을 정확한 PPR 행렬로 그래프에 퍼뜨려요."},{"b":[0.09,0.61,0.86,0.05],"c":[0.047,0.5394,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p090_20_04.jpg","say":"영향이에요. 신경망 깊이가 전파 범위와 완전히 무관해져요."}]}},{"p":91,"title":"APPNP: 역행렬 대신 거듭제곱 반복","terms":["APPNP","PPNP","Power Iteration","Personalized PageRank","Teleport Probability","GCNII"],"pass1":[{"kind":"say","lines":["**피피엔피(PPNP)** 의 식에는 역행렬이 있어요. 이것이 아주 비싸요.","**에이피피엔피(APPNP)** 는 그것을 **거듭제곱 반복(Power Iteration)** 으로 근사해요.","같은 답에 거의 도달하면서 비용은 비교할 수 없이 싸요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"formula","head":"APPNP 의 반복 식","tex":"Z^{(k+1)} = (1-\\alpha)\\hat{\\tilde{A}}Z^{(k)} + \\alpha H","parts":[{"sym":"Z^{(k)}","say":"$k$ 번째 반복에서의 점수예요. 처음 $Z^{(0)}$ 은 신경망 예측 $H$ 예요."},{"sym":"\\alpha","say":"**순간이동 확률(Teleport Probability)** 이에요."},{"sym":"H","say":"신경망이 낸 처음 예측이에요. 언제나 같은 값이에요."},{"sym":"\\hat{\\tilde{A}}","say":"정규화된 인접행렬이에요. 희소해서 곱셈이 싸요."}],"whole":"지금 값을 이웃과 한 번 섞고, 거기에 처음 예측을 $\\alpha$ 만큼 다시 섞어요."},{"kind":"steps","head":"삼각형 그래프에서 네 번 반복해요","steps":["처음 값은 1, 0, 0 이에요. 순간이동 확률은 0.5 예요.","반복 1: 이웃 평균이 0, 0.5, 0.5 라 결과는 0.5, 0.25, 0.25 예요.","반복 2: 결과는 0.625, 0.1875, 0.1875 예요.","반복 3: 결과는 0.59375, 0.203125, 0.203125 예요.","반복 4: 결과는 약 0.6016, 0.1992, 0.1992 예요."],"answer":"정확한 답 0.6, 0.2, 0.2 에 아주 빠르게 다가가요. 오차가 매번 사분의 일로 줄어요.","given":"$Z^{(0)} = H = [1, 0, 0]$ 이에요."},{"kind":"compare","head":"두 방식의 비용","cols":["방식","무엇을 하나","복잡도"],"rows":[["**피피엔피(PPNP)**","역행렬을 한 번 구해요","노드 수의 세제곱"],["**에이피피엔피(APPNP)**","희소 곱셈을 $K$ 번 해요","$K$ 곱하기 엣지 수"]]},{"kind":"points","head":"왜 반복이 싼가요","items":["정규화 인접행렬은 대부분이 0 인 희소 행렬이에요.","곱할 때 0 이 아닌 자리만 계산하면 되니 한 번에 엣지 수만큼 들어요.","역행렬을 구하면 거의 모든 자리에 값이 생겨 희소성이 깨져요.","노드가 10만 개면 조밀 행렬은 메모리에 올릴 수도 없어요."]},{"kind":"compare","head":"GCNII 와 모양이 닮았어요","cols":["모델","한 단계 식의 모양","차이"],"rows":[["**지씨엔 투(GCNII)**","이웃 값과 원본을 섞고 가중치를 곱해요","$W$ 와 활성화가 있어요"],["**에이피피엔피(APPNP)**","이웃 값과 원본을 섞어요","가중치도 활성화도 없어요"]]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"APPNP replaces the dense matrix inversion of PPNP by K steps of power iteration, which keeps the adjacency matrix sparse.","ko":"APPNP 는 PPNP 의 조밀 행렬 역변환을 K 단계의 거듭제곱 반복으로 대체해서 인접행렬을 희소하게 유지한다.","tip":"복잡도를 묻는 문제에 그대로 쓰면 돼요."},{"kind":"warn","head":"계산에서 헷갈리기 쉬운 점","items":["반복 식의 마지막 항은 언제나 처음 예측 $H$ 예요. 앞 단계 값이 아니에요.","반복 안에는 가중치도 활성화 함수도 없어요. 그래서 $K$ 를 키워도 파라미터가 안 늘어요.","$K$ 는 층 수가 아니라 반복 횟수예요. 깊은 GNN 의 문제가 생기지 않아요.","소프트맥스는 맨 마지막에 한 번만 씌워요."]},{"kind":"check","q":"**에이피피엔피(APPNP)** 에서 $K$ 를 10 에서 20 으로 키우면 파라미터는 어떻게 되나요?","choices":["두 배가 된다","그대로다","절반이 된다","10개 늘어난다"],"a":1,"why":"반복 안에는 학습할 것이 하나도 없어요. 파라미터는 앞쪽 신경망에만 있어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.465,0.1593],"c":[0,0.0019,0.5115,0.1913],"r":4.7534,"img":"img/L5/walk/p091_h.jpg"},"parts":[{"b":[0.09,0.19,0.6,0.09],"c":[0.06,0.1683,0.66,0.1333],"r":8.8022,"img":"img/L5/walk/p091_11_01.jpg","say":"계산상의 벽이에요. 조밀 행렬의 역행렬이 필요하고 노드 수의 세제곱으로 커져요."},{"b":[0.09,0.32,0.7,0.05],"c":[0.055,0.2672,0.77,0.1556],"r":8.7975,"img":"img/L5/walk/p091_11_02.jpg","say":"해법이에요. **거듭제곱 반복(Power Iteration)** 으로 극한 분포를 근사해요."},{"b":[0.36,0.6,0.28,0.06],"c":[0.346,0.575,0.308,0.11],"r":4.9778,"img":"img/L5/walk/p091_11_03.jpg","say":"가운데 식이 반복 한 번의 계산이에요."},{"b":[0.09,0.79,0.86,0.05],"c":[0.047,0.7194,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p091_11_04.jpg","say":"맨 아래가 복잡도예요. 엣지 수에 비례하는 선형 시간으로 떨어져요."}]}},{"p":92,"title":"개인화에서 일반화 페이지랭크로","terms":["Generalized PageRank","APPNP","Personalized PageRank","Low-pass Filter","High-pass Filter","Heterophily","Homophily","Random Walk"],"pass1":[{"kind":"say","lines":["**에이피피엔피(APPNP)** 의 홉 가중치는 항상 양수이고 항상 줄어들어요.","그래서 **저역 통과 필터(Low-pass Filter)** 밖에 못 만들어요.","**일반화 페이지랭크(Generalized PageRank)** 는 그 자리에 학습되는 가중치를 넣어요.","그 가중치는 음수도 될 수 있어요."]},{"kind":"analogy","head":"가까울수록 중요하다는 규칙","scene":"선생님이 모둠 의견을 모을 때 옆자리 친구 말을 가장 많이, 멀리 앉은 친구 말은 조금만 반영해요. 이 규칙이 늘 맞을까요. 어떤 반은 옆자리 친구가 나와 성향이 오히려 반대예요. 그런 반에서는 옆자리 말을 빼고 두 칸 건너 친구 말을 더해야 맞아요.","map":[["가까울수록 많이 반영","**에이피피엔피(APPNP)** 의 고정 가중치"],["옆자리 말을 빼기","음수 가중치"],["옆자리가 오히려 반대","**이종선호(Heterophily)**"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"compare","head":"두 식의 홉 가중치","cols":["모델","가중치","부호"],"rows":[["**에이피피엔피(APPNP)**","$\\alpha(1-\\alpha)^{k}$ 로 고정","항상 양수, 항상 감소"],["**일반화 페이지랭크(Generalized PageRank)**","$\\gamma_k$ 를 학습","아무 실수나 가능, 음수도 가능"]]},{"kind":"steps","head":"가중치를 숫자로 확인해요","steps":["**순간이동 확률(Teleport Probability)** 이 0.2 라고 해요.","0홉 가중치는 0.2 예요.","1홉은 $0.2 \\times 0.8 = 0.16$ 이에요.","2홉은 $0.2 \\times 0.64 = 0.128$ 이에요.","3홉은 약 0.102 예요."],"answer":"전부 양수이고 계속 줄어요. 가까운 이웃일수록 중요하다를 모델이 미리 정해 놓은 거예요.","given":"**동질성(Homophily)** 그래프에서는 이 가정이 맞지만 **이종선호(Heterophily)** 에서는 틀려요."},{"kind":"steps","head":"같은 그래프에 두 가중치를 써 봐요","steps":["노드 4개에 노드 4 만 특징 6 이 있어요. 0홉, 1홉, 2홉 결과는 p.87 에서 구한 것과 같아요.","APPNP 식으로 가중치 0.5, 0.25, 0.125 를 쓰면 결과는 0.125, 0.125, 0.5, 3.25 예요.","전부 양수이고 신호원에서 멀수록 작아져요.","GPR 로 가중치 0.5, 0.3, 마이너스 0.2 를 쓰면 결과는 마이너스 0.2, 마이너스 0.2, 0.6, 2.6 이에요.","노드 1 과 2 가 음수가 됐어요. 노드 3 과 부호가 반대예요."],"answer":"2홉 거리 노드를 반대 방향으로 표시할 수 있게 됐어요. APPNP 로는 절대 못 만드는 출력이에요.","given":"$P$ 는 0, 1, 2 이고 세 홉 결과는 $[0,0,0,6]$, $[0,0,2,0]$, $[1,1,0,2]$ 예요."},{"kind":"figure","head":"가중치 모양이 필터를 정해요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"17\" text-anchor=\"middle\">홉마다 주는 가중치의 모양<\/text>\n<text class=\"tm\" x=\"118\" y=\"52\" font-size=\"14\" text-anchor=\"middle\">APPNP 의 고정 가중치<\/text>\n<line class=\"e\" x1=\"30\" y1=\"160\" x2=\"212\" y2=\"160\"/>\n<rect class=\"box\" x=\"44\" y=\"100\" width=\"26\" height=\"60\" rx=\"3\"/>\n<text class=\"tm\" x=\"57\" y=\"180\" font-size=\"14\" text-anchor=\"middle\">0홉<\/text>\n<rect class=\"box\" x=\"90\" y=\"112\" width=\"26\" height=\"48\" rx=\"3\"/>\n<text class=\"tm\" x=\"103\" y=\"180\" font-size=\"14\" text-anchor=\"middle\">1홉<\/text>\n<rect class=\"box\" x=\"136\" y=\"122\" width=\"26\" height=\"38\" rx=\"3\"/>\n<text class=\"tm\" x=\"149\" y=\"180\" font-size=\"14\" text-anchor=\"middle\">2홉<\/text>\n<rect class=\"box\" x=\"182\" y=\"130\" width=\"26\" height=\"30\" rx=\"3\"/>\n<text class=\"tm\" x=\"195\" y=\"180\" font-size=\"14\" text-anchor=\"middle\">3홉<\/text>\n<text class=\"tm b1\" x=\"118\" y=\"206\" font-size=\"14\" text-anchor=\"middle\">항상 양수, 항상 감소<\/text>\n<text class=\"tb b1\" x=\"118\" y=\"230\" font-size=\"15\" text-anchor=\"middle\">저역 통과만 가능해요<\/text>\n<text class=\"tm\" x=\"362\" y=\"52\" font-size=\"14\" text-anchor=\"middle\">GPR 의 학습된 가중치<\/text>\n<line class=\"e\" x1=\"274\" y1=\"160\" x2=\"456\" y2=\"160\"/>\n<rect class=\"box2\" x=\"288\" y=\"96\" width=\"26\" height=\"64\" rx=\"3\"/>\n<text class=\"tm\" x=\"301\" y=\"180\" font-size=\"14\" text-anchor=\"middle\">0홉<\/text>\n<rect class=\"hl b2\" x=\"334\" y=\"160\" width=\"26\" height=\"30\" rx=\"3\"/>\n<text class=\"tm b2\" x=\"347\" y=\"206\" font-size=\"14\" text-anchor=\"middle\">1홉<\/text>\n<rect class=\"box2 b2\" x=\"380\" y=\"128\" width=\"26\" height=\"32\" rx=\"3\"/>\n<text class=\"tm b2\" x=\"393\" y=\"180\" font-size=\"14\" text-anchor=\"middle\">2홉<\/text>\n<rect class=\"hl b2\" x=\"426\" y=\"160\" width=\"26\" height=\"18\" rx=\"3\"/>\n<text class=\"tm b2\" x=\"439\" y=\"196\" font-size=\"14\" text-anchor=\"middle\">3홉<\/text>\n<text class=\"tb b2\" x=\"362\" y=\"230\" font-size=\"15\" text-anchor=\"middle\">음수도 되니 고역 통과도 가능해요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"258\" font-size=\"14\" text-anchor=\"middle\">가로선 아래로 내려간 막대가 음수 가중치예요<\/text>\n<\/svg>","caption":"가로선 아래로 내려간 막대가 음수 가중치예요.","builds":3},{"kind":"mining","src":"마이닝 10강 Random Walk-based GRL","lines":["DeepWalk 와 node2vec 은 **랜덤워크(Random Walk)** 로 이웃을 정의했어요.","node2vec 의 두 값이 워크가 되돌아갈지 멀리 나갈지를 조절했어요.","그 값들은 사람이 정했지만 **일반화 페이지랭크(Generalized PageRank)** 는 손실로 직접 배워요.","이 그래프에서는 두 걸음짜리가 중요하다는 것을 데이터가 알려 주게 돼요."]}],"pass3":[{"kind":"warn","head":"여기서 헷갈리기 쉬워요","items":["학습되는 가중치는 사람이 정하는 값이 아니에요. 이것이 가장 중요한 차이예요.","가중치의 합이 1 이어야 한다는 제약이 없어요. 확률이 아니라 그냥 실수 계수예요.","비보편적이라는 말은 성능이 나쁘다가 아니라 만들 수 있는 필터의 종류가 제한된다는 뜻이에요.","**동질성(Homophily)** 그래프에서는 **에이피피엔피(APPNP)** 도 아주 잘해요."]},{"kind":"check","q":"**일반화 페이지랭크(Generalized PageRank)** 의 가중치가 음수도 될 수 있어서 좋은 점은 무엇인가요?","choices":["계산이 빨라진다","**고역 통과 필터(High-pass Filter)** 도 만들 수 있다","파라미터가 준다","메모리가 준다"],"a":1,"why":"이웃 정보를 빼는 동작이 가능해져요. **이종선호(Heterophily)** 그래프에 꼭 필요해요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5209,0.1593],"c":[0,0.0019,0.5729,0.1913],"r":5.324,"img":"img/L5/walk/p092_h.jpg"},"parts":[{"b":[0.09,0.19,0.86,0.05],"c":[0.047,0.1194,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p092_20_01.jpg","say":"위쪽은 GNN 에서의 개인화 페이지랭크예요. 고정된 재시작 확률을 쓴다고 했어요."},{"b":[0.33,0.3,0.26,0.11],"c":[0.317,0.284,0.286,0.142],"r":3.5806,"img":"img/L5/walk/p092_20_02.jpg","say":"그 아래 식이 APPNP 를 합 모양으로 펼친 것이에요."},{"b":[0.09,0.44,0.86,0.09],"c":[0.047,0.3894,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p092_20_03.jpg","say":"한계예요. 가중치가 항상 양수이고 단조 감소해서 저역 통과가 강제돼요."},{"b":[0.33,0.68,0.24,0.11],"c":[0.318,0.664,0.264,0.142],"r":3.3052,"img":"img/L5/walk/p092_20_04.jpg","say":"아래쪽 식이 **일반화 페이지랭크(Generalized PageRank)** 예요. 가중치가 자유로워요."}]}},{"p":93,"title":"GPR-GNN 구조도: 가로는 전파, 세로는 학습","terms":["GPR-GNN","Generalized PageRank","Decoupling","JK-Net","Layer Aggregation"],"pass1":[{"kind":"say","lines":["**지피알 지엔엔(GPR-GNN)** 의 전체 그림 한 장이에요.","왼쪽에서 신경망이 특징을 뽑고, 오른쪽에서 인접행렬을 여러 번 곱하며 퍼뜨려요.","그리고 각 단계 결과에 학습되는 가중치를 곱해 위로 더해요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"points","head":"그림의 요점 세 가지","items":["가로 방향에는 가중치도 활성화 함수도 없어요. 인접행렬 곱하기 하나뿐이에요.","학습되는 것은 왼쪽 신경망과 위로 가는 빨간 가중치 둘뿐이에요.","모든 단계가 최종 합에 참여해요.","슬라이드가 말한 가중치 행렬이 그래프 연산자와 얽히지 않게 한다가 이것이에요."]},{"kind":"compare","head":"JK-Net 과 겹쳐 보기","cols":["항목","**제이케이넷(JK-Net)**","**지피알 지엔엔(GPR-GNN)**"],"rows":[["중간 표현 만드는 법","GNN 층으로 만들어요","인접행렬 곱하기만 해요"],["합치는 법","최대 풀링이나 이어 붙이기","학습되는 계수의 가중 합"],["계수의 부호","해당 없음","음수도 가능해요"]]},{"kind":"steps","head":"파라미터가 얼마나 늘까요","steps":["입력 특징 1433 차원, 은닉 64 차원, 클래스 7개, 전파 10단계라고 해요.","신경망 1층은 $1433 \\times 64$ 로 약 9만 1천 개예요.","신경망 2층은 $64 \\times 7$ 로 448개예요.","학습되는 홉 가중치는 0단계부터 10단계까지 11개예요.","전파 부분 자체에는 파라미터가 0개예요."],"answer":"전파를 10단계에서 20단계로 늘려도 파라미터가 10개만 늘어요. 거의 공짜예요.","given":"같은 일을 보통 GCN 으로 하려면 층마다 가중치가 수천 개씩 늘어요."},{"kind":"points","head":"얽힘이라는 말의 뜻","items":["보통 GCN 은 인접행렬과 가중치를 번갈아 곱해요. 이것이 얽힘이에요.","**지피알 지엔엔(GPR-GNN)** 은 가중치를 맨 앞에 몰아넣고 뒤는 인접행렬만 이어져요.","두 종류의 연산이 섞이지 않아요. 이것이 **분리(Decoupling)** 예요.","덕분에 p.95 처럼 전체를 하나의 다항식으로 깔끔하게 쓸 수 있어요."]}],"pass3":[{"kind":"warn","head":"그림에서 헷갈리기 쉬운 점","items":["가로 화살표에 활성화 함수가 없어요. 습관적으로 렐루를 붙이지 마세요.","0단계 값은 원래 특징이 아니라 신경망을 통과한 결과예요.","학습되는 가중치는 0단계부터 마지막까지라 개수가 단계 수보다 하나 많아요.","**층 집계(Layer Aggregation)** 와 비슷해 보이지만 계수가 학습되고 음수도 된다는 점이 달라요."]},{"kind":"check","q":"**지피알 지엔엔(GPR-GNN)** 에서 학습되는 것은 어디인가요?","choices":["전파 단계마다의 가중치 행렬","앞쪽 신경망과 홉별 계수 둘","인접행렬","활성화 함수"],"a":1,"why":"가로 전파에는 학습할 것이 하나도 없어요. 그래서 단계를 늘려도 거의 공짜예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.914,0.226],"c":[0,0.0019,1,0.258],"r":6.8906,"img":"img/L5/walk/p093_h.jpg"},"parts":[{"b":[0.2,0.42,0.2,0.24],"c":[0.188,0.404,0.224,0.272],"r":1.4641,"img":"img/L5/walk/p093_11_01.jpg","say":"왼쪽 파란 상자가 신경망이에요. 원래 특징에서 은닉 상태를 만들어요."},{"b":[0.43,0.68,0.38,0.1],"c":[0.411,0.664,0.418,0.132],"r":5.6296,"img":"img/L5/walk/p093_11_02.jpg","say":"가운데 아래 줄이 전파예요. 인접행렬을 곱하며 오른쪽으로 나아가요."},{"b":[0.47,0.38,0.34,0.24],"c":[0.453,0.364,0.374,0.272],"r":2.4444,"img":"img/L5/walk/p093_11_03.jpg","say":"위로 올라가는 화살표마다 빨간 감마가 붙어 있어요. 이것이 학습되는 가중치예요."},{"b":[0.47,0.38,0.32,0.14],"c":[0.454,0.364,0.352,0.172],"r":3.6382,"img":"img/L5/walk/p093_11_04.jpg","say":"오른쪽 위 파란 상자가 최종 합이에요."}]}},{"p":94,"title":"GPR-GNN 순전파 세 단계","terms":["GPR-GNN","Generalized PageRank","Decoupling","APPNP","PPNP","GCNII","ReLU"],"pass1":[{"kind":"say","lines":["p.93 의 그림을 식 세 줄로 정리한 슬라이드예요.","1단계는 특징 추출, 2단계는 위상 전파, 3단계는 적응형 집계예요.","이 세 줄이 **지피알 지엔엔(GPR-GNN)** 의 전부예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"formula","head":"1단계와 2단계","tex":"H^{(0)} = f_\\theta(X),\\qquad H^{(k)} = \\tilde{A}H^{(k-1)}","parts":[{"sym":"f_\\theta","say":"신경망이에요. 보통 2층 MLP 이고 여기에만 가중치가 있어요."},{"sym":"H^{(0)}","say":"신경망 출력이에요. 그래프를 아직 안 본 예측이에요."},{"sym":"\\tilde{A}H^{(k-1)}","say":"이웃 평균 한 번이에요. 가중치도 **렐루(ReLU)** 도 없어요."},{"sym":"H^{(k)}","say":"$k$ 번 확산한 결과예요. 거듭제곱 형태로 쓰면 $\\tilde{A}^{k}H^{(0)}$ 과 같아요."}],"whole":"먼저 각 노드를 따로 보고 예측을 만들고, 그다음 그것을 그래프에서 여러 번 퍼뜨려요."},{"kind":"formula","head":"3단계 적응형 집계","tex":"Z = \\sum_{k=0}^{K}\\gamma_k H^{(k)}","parts":[{"sym":"\\gamma_k","say":"$k$ 홉에 줄 가중치예요. 학습되고 음수도 될 수 있어요."},{"sym":"\\sum_{k=0}^{K}","say":"0 부터 $K$ 까지 전부 더해요. 0 항을 빠뜨리기 쉬워요."},{"sym":"H^{(k)}","say":"$k$ 번 확산한 표현이에요."},{"sym":"Z","say":"최종 출력이에요."}],"whole":"여러 걸음의 표현을 학습된 계수로 가중 합해요. 이것이 **일반화 페이지랭크(Generalized PageRank)** 예요."},{"kind":"compare","head":"분리 계열 세 모델","cols":["모델","홉 가중치","가중치를 배우나"],"rows":[["**피피엔피(PPNP)**","$\\alpha(1-\\alpha)^{k}$","아니오"],["**에이피피엔피(APPNP)**","$\\alpha(1-\\alpha)^{k}$","아니오"],["**지피알 지엔엔(GPR-GNN)**","$\\gamma_k$","예"]]},{"kind":"steps","head":"세 단계를 한 번에 돌려요","steps":["노드 4개에 노드 4 만 특징 6 이 있는 그래프예요. 학습이 끝나 가중치가 0.5, 0.3, 마이너스 0.2 가 나왔어요.","0걸음 값은 신경망 출력 그대로 $[0,0,0,6]$ 이에요.","1걸음은 $[0,0,2,0]$ 이에요. 노드 3 만 신호를 받았어요.","2걸음은 $[1,1,0,2]$ 예요.","가중 합을 하면 노드 1 과 2 는 마이너스 0.2, 노드 3 은 0.6, 노드 4 는 2.6 이에요."],"answer":"$Z$ 는 마이너스 0.2, 마이너스 0.2, 0.6, 2.6 이에요. 거리에 따라 부호가 달라졌어요.","given":"2단계까지만 하고 $K$ 는 2 로 둬요."},{"kind":"points","head":"**에이피피엔피(APPNP)** 는 특수한 경우예요","items":["가중치를 $\\alpha(1-\\alpha)^{k}$ 로 고정하면 그대로 APPNP 가 돼요.","실제로 논문은 학습되는 가중치를 바로 이 값으로 초기화해요.","잘 알려진 좋은 출발점에서 시작해 필요한 만큼만 벗어나는 방식이에요.","**동질성(Homophily)** 그래프에서는 거의 안 움직이고 **이종선호(Heterophily)** 에서는 크게 움직여요."]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"GPR-GNN propagates without any weight matrix or activation, and combines the multi-step representations with learnable weights that may be negative.","ko":"GPR-GNN 은 가중치 행렬이나 활성화 없이 전파하고, 음수도 될 수 있는 학습 가능한 가중치로 여러 걸음의 표현을 결합한다.","tip":"순전파를 설명하라는 문제에 세 단계를 번호로 적으면 좋아요."},{"kind":"warn","head":"계산에서 헷갈리기 쉬운 점","items":["2단계 전파 식에는 가중치도 **렐루(ReLU)** 도 없어요. 습관적으로 붙이지 마세요.","3단계 합의 범위는 0 부터 $K$ 까지예요. 그래프를 전혀 안 본 0 항도 포함돼요.","여기서 층이라는 말은 파라미터가 있는 층이 아니라 확산 단계예요.","p.93 와 p.94 는 그림 판과 식 판이에요. 중복이 아니라 같은 내용의 두 표현이에요."]},{"kind":"check","q":"**지피알 지엔엔(GPR-GNN)** 의 합에서 빠뜨리기 쉬운 항은 무엇인가요?","choices":["마지막 항","0 걸음 항","가운데 항","없다"],"a":1,"why":"0 걸음 값은 그래프를 전혀 안 본 예측이라 노드 구별이 살아 있어요. p.96 에서 이것이 결정적이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.914,0.226],"c":[0,0.0019,1,0.258],"r":6.8906,"img":"img/L5/walk/p094_h.jpg"},"parts":[{"b":[0.06,0.29,0.86,0.05],"c":[0.017,0.2194,0.946,0.1911],"r":8.8005,"img":"img/L5/walk/p094_11_01.jpg","say":"1단계 특징 추출이에요. 원래 노드 특징에 신경망을 적용해 은닉 상태를 얻어요."},{"b":[0.06,0.46,0.6,0.05],"c":[0.03,0.4183,0.66,0.1333],"r":8.8022,"img":"img/L5/walk/p094_11_02.jpg","say":"2단계 위상 전파예요. 은닉 상태를 K 걸음까지 반복해서 확산시켜요."},{"b":[0.06,0.58,0.62,0.05],"c":[0.029,0.5361,0.682,0.1378],"r":8.7986,"img":"img/L5/walk/p094_11_03.jpg","say":"3단계 적응형 집계예요. 학습되는 가중치로 여러 걸음의 표현을 합쳐요."}]}},{"p":95,"title":"정리 1: 학습되는 다항 스펙트럼 필터","terms":["GPR-GNN","Spectral Filter","Eigenvalue","Low-pass Filter","High-pass Filter","Heterophily","Generalized PageRank"],"pass1":[{"kind":"say","lines":["인접행렬을 고유분해해서 식에 넣으면 재미있는 일이 생겨요.","집계가 **고윳값(Eigenvalue)** 에 대한 다항식 하나로 바뀌어요.","그러니까 가중치를 학습한다는 것은 **스펙트럼 필터(Spectral Filter)** 의 모양 자체를 학습한다는 뜻이에요."]},{"kind":"analogy","head":"이퀄라이저 손잡이","scene":"음악 앱에 이퀄라이저가 있어요. 낮은 음, 중간 음, 높은 음마다 손잡이가 따로 있어요. 손잡이를 올리면 그 대역이 커지고 내리면 작아져요. 곡마다 좋은 설정이 달라요. **지피알 지엔엔(GPR-GNN)** 은 그 손잡이를 사람이 아니라 학습이 돌려요.","map":[["낮은 음과 높은 음","매끈한 신호와 요동치는 신호"],["손잡이를 돌리기","다항식 $P$ 의 모양을 정하기"],["곡마다 좋은 설정","그래프마다 좋은 **스펙트럼 필터(Spectral Filter)**"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"steps","head":"왜 다항식이 되나요","steps":["고유분해는 행렬을 방향들과 그 방향의 세기로 쪼개는 것이에요.","인접행렬을 두 번 곱하면 가운데가 사라지고 세기만 제곱돼요.","$k$ 번 곱하면 세기가 $k$ 제곱이 돼요.","그래서 합 안에서 방향 부분을 밖으로 빼낼 수 있어요.","남는 것은 **고윳값(Eigenvalue)** 의 거듭제곱에 계수를 곱해 더한 다항식이에요."],"answer":"고윳값 $\\lambda$ 를 갖는 방향은 다항식 $P(\\lambda)$ 를 곱한 것이 돼요. 이것이 필터예요.","given":"정규화 인접행렬은 고윳값이 마이너스 1 과 1 사이예요."},{"kind":"steps","head":"계수 세 개로 정반대 필터를 만들어요","steps":["계수가 0.5, 0.25, 0.125 라고 해요. 이것은 APPNP 스타일이에요.","$\\lambda = 1$ 에서 값은 $0.5+0.25+0.125 = 0.875$ 예요.","$\\lambda = -1$ 에서 값은 $0.5-0.25+0.125 = 0.375$ 예요. 작아요. 저역 통과예요.","이번엔 계수를 0.5, 마이너스 0.6, 0.3 으로 바꿔요.","$\\lambda = 1$ 에서 0.2, $\\lambda = -1$ 에서 1.4 예요. 정반대가 됐어요."],"answer":"계수 세 개만 바꿔서 **저역 통과 필터(Low-pass Filter)** 를 **고역 통과 필터(High-pass Filter)** 로 뒤집었어요.","given":"그리고 그 계수를 사람이 아니라 분류 손실이 정해 줘요."},{"kind":"points","head":"필터의 모양을 읽는 법","items":["고윳값이 1 에 가까운 방향은 이웃끼리 비슷한 매끈한 신호예요.","고윳값이 마이너스 1 에 가까운 방향은 이웃끼리 부호가 반대인 요동치는 신호예요.","그래서 1 쪽이 크면 **저역 통과 필터(Low-pass Filter)**, 마이너스 1 쪽이 크면 **고역 통과 필터(High-pass Filter)** 예요.","**이종선호(Heterophily)** 그래프는 마이너스 1 쪽이 커야 한다고 슬라이드가 말해요."]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"The GPR aggregation becomes a degree K polynomial of the eigenvalues, so learning the coefficients means learning the filter itself.","ko":"GPR 집계는 고윳값의 K 차 다항식이 되므로, 계수를 배우는 것은 곧 필터 자체를 배우는 것이다.","tip":"왜 다항 **스펙트럼 필터(Spectral Filter)** 라고 부르냐는 문제에 쓰면 돼요."},{"kind":"warn","head":"여기서 헷갈리기 쉬워요","items":["고유분해를 실제로 계산하지는 않아요. 그렇게 해석할 수 있다는 설명이에요.","구현에서는 그냥 인접행렬을 $K$ 번 곱해요.","**고윳값(Eigenvalue)** 범위가 마이너스 1 과 1 사이인 것은 정규화했기 때문이에요.","$K$ 차 다항식이라는 말은 만들 수 있는 필터의 자유도가 $K+1$ 이라는 뜻이에요."]},{"kind":"check","q":"계수가 전부 양수이고 줄어드는 필터는 어떤 필터인가요?","choices":["**고역 통과 필터(High-pass Filter)**","**저역 통과 필터(Low-pass Filter)**","대역 통과 필터","필터가 아니다"],"a":1,"why":"$\\lambda = 1$ 에서 값이 가장 커져요. 매끈한 신호만 남기는 모양이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2529,0.1593],"c":[0.0005,0.0019,0.2782,0.1913],"r":2.5854,"img":"img/L5/walk/p095_h.jpg"},"parts":[{"b":[0.06,0.19,0.6,0.05],"c":[0.03,0.1483,0.66,0.1333],"r":8.8022,"img":"img/L5/walk/p095_20_01.jpg","say":"첫 줄은 **지피알 지엔엔(GPR-GNN)** 이 스펙트럼 영역에서 다항 필터로 작동한다는 말이에요."},{"b":[0.06,0.27,0.9,0.09],"c":[0.01,0.215,0.99,0.2],"r":8.8,"img":"img/L5/walk/p095_20_02.jpg","say":"둘째 줄은 고유분해 표기예요. **고윳값(Eigenvalue)** 이 마이너스 1 과 1 사이에 있다고 했어요."},{"b":[0.33,0.44,0.26,0.12],"c":[0.317,0.424,0.286,0.152],"r":3.345,"img":"img/L5/walk/p095_20_03.jpg","say":"가운데 식이 스펙트럼 영역에서 다시 쓴 집계예요."},{"b":[0.06,0.6,0.9,0.13],"c":[0.01,0.565,0.99,0.2],"r":8.8,"img":"img/L5/walk/p095_20_04.jpg","say":"맨 아래가 함의예요. 어떤 연속 스펙트럼 모양도 담아낼 수 있다고 했어요."}]}},{"p":96,"title":"정리 2: 정상 상태로 빨려 들어가지 않는다","terms":["GPR-GNN","Stationary Distribution","Over-smoothing","Generalized PageRank","Random Walk"],"pass1":[{"kind":"say","lines":["보통 GNN 은 전파를 무한히 늘리면 출력이 한 점으로 수렴해요.","그 한 점이 **정상 분포(Stationary Distribution)** 예요. 노드 구별이 완전히 사라져요.","**지피알 지엔엔(GPR-GNN)** 은 학습된 가중치가 무한 단계에만 몰리지 않으면 그 상태를 피해요.","이것이 정리 2 예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"points","head":"왜 한 점으로 수렴하면 치명적인가요","items":["수렴한 행렬은 계수가 1 짜리라 결과의 모든 행이 서로 상수배가 돼요.","즉 모든 노드의 표현이 같은 방향을 가리켜요.","노드 분류를 하려면 노드마다 다른 방향을 가리켜야 하는데 그게 사라진 거예요.","이것이 **과평활화(Over-smoothing)** 의 극한 형태예요."]},{"kind":"steps","head":"숫자로 두 방식을 비교해요","steps":["p.88 의 삼각형 그래프에서 처음 값이 1, 0, 0 이에요.","마지막 것만 쓰면 걸음 1 에 0, 0.5, 0.5 예요. 아직 구별이 돼요.","걸음 4 에 0.375, 0.3125, 0.3125 로 거의 같아져요.","걸음 20 이면 셋 다 0.3333 이라 실질적으로 구별 불가능이에요.","전부 섞어 쓰면 0걸음 항이 남아서 노드 1 이 다른 둘과 다르다는 정보가 지워지지 않아요."],"answer":"가중치를 0.5, 0.3, 0.1 로 두면 결과가 0.55, 0.175, 0.175 예요. 걸음을 늘려도 이 값은 안 변해요.","given":"뒤쪽 가중치가 0 이면 그만큼 안 쓰게 되니까요."},{"kind":"figure","head":"마지막 것만 쓰기와 전부 섞어 쓰기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"118\" y=\"26\" font-size=\"16\" text-anchor=\"middle\">마지막 것만 쓰면<\/text>\n<circle class=\"n2\" cx=\"52\" cy=\"72\" r=\"16\"/>\n<circle class=\"n3\" cx=\"118\" cy=\"72\" r=\"16\"/>\n<circle class=\"n4\" cx=\"184\" cy=\"72\" r=\"16\"/>\n<text class=\"tm\" x=\"118\" y=\"108\" font-size=\"14\" text-anchor=\"middle\">걸음 1: 세 노드가 달라요<\/text>\n<polygon class=\"arrow b1\" points=\"112,120 124,120 118,132\"/>\n<circle class=\"n b1\" cx=\"100\" cy=\"164\" r=\"16\"/>\n<circle class=\"n b1\" cx=\"118\" cy=\"164\" r=\"16\"/>\n<circle class=\"n b1\" cx=\"136\" cy=\"164\" r=\"16\"/>\n<text class=\"tm b1\" x=\"118\" y=\"202\" font-size=\"14\" text-anchor=\"middle\">걸음 20: 전부 같아져요<\/text>\n<text class=\"tb b1\" x=\"118\" y=\"228\" font-size=\"15\" text-anchor=\"middle\">정상 분포로 수렴해요<\/text>\n<line class=\"e\" x1=\"240\" y1=\"40\" x2=\"240\" y2=\"240\"/>\n<text class=\"tb\" x=\"362\" y=\"26\" font-size=\"16\" text-anchor=\"middle\">전부 섞어 쓰면<\/text>\n<circle class=\"n2\" cx=\"296\" cy=\"72\" r=\"16\"/>\n<circle class=\"n3\" cx=\"362\" cy=\"72\" r=\"16\"/>\n<circle class=\"n4\" cx=\"428\" cy=\"72\" r=\"16\"/>\n<text class=\"tm\" x=\"362\" y=\"108\" font-size=\"14\" text-anchor=\"middle\">0걸음 항이 합에 남아 있어요<\/text>\n<polygon class=\"arrow b2\" points=\"356,120 368,120 362,132\"/>\n<circle class=\"n2 b2\" cx=\"296\" cy=\"164\" r=\"16\"/>\n<circle class=\"n3 b2\" cx=\"362\" cy=\"164\" r=\"16\"/>\n<circle class=\"n4 b2\" cx=\"428\" cy=\"164\" r=\"16\"/>\n<text class=\"tm b2\" x=\"362\" y=\"202\" font-size=\"14\" text-anchor=\"middle\">걸음 20 이어도 색이 남아요<\/text>\n<text class=\"tb b2\" x=\"362\" y=\"228\" font-size=\"15\" text-anchor=\"middle\">가중치가 알아서 뒤를 줄여요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"260\" font-size=\"14\" text-anchor=\"middle\">노드를 구별하는 힘이 지워지지 않아요<\/text>\n<\/svg>","caption":"0걸음 항이 남아 있으면 노드를 구별하는 힘이 지워지지 않아요.","builds":3},{"kind":"points","head":"두 번째 이유가 더 중요해요","items":["학습된 가중치가 너무 커져서 표현이 뭉개지면 분류 정확도가 떨어져요.","그러면 손실이 올라가고 경사하강법이 그 가중치를 줄이는 방향으로 기울기를 보내요.","즉 모델이 스스로 **과평활화(Over-smoothing)** 를 피하도록 학습해요.","그래서 전파를 10단계 이상으로도 안전하게 키울 수 있어요."]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"GPR-GNN keeps every intermediate representation in the sum, so the stationary limit is provably avoided.","ko":"GPR-GNN 은 모든 중간 표현을 합에 남겨 두므로 정상 극한을 증명 가능하게 피한다.","tip":"뒤에 한 줄 덧붙이면 좋아요. 가중치가 분류 손실로 학습되므로 경사하강법 자체가 과평활화를 막는다."},{"kind":"warn","head":"여기서 헷갈리기 쉬워요","items":["파이는 원주율이 아니라 **정상 분포(Stationary Distribution)** 예요. **랜덤워크(Random Walk)** 를 무한히 돌렸을 때의 방문 확률이에요.","정리 2 가 **과평활화(Over-smoothing)** 를 완전히 없앤다는 뜻은 아니에요. 극한으로 수렴하지 않는다를 보장할 뿐이에요.","전파 10단계를 10층 GNN 으로 읽으면 안 돼요. 파라미터가 있는 층이 아니라 확산 단계예요."]},{"kind":"check","q":"보통 GNN 에서 전파를 무한히 늘리면 출력이 무엇으로 수렴하나요?","choices":["0","**정상 분포(Stationary Distribution)** 를 반영한 한 점","무한대","처음 값"],"a":1,"why":"모든 노드가 같은 방향을 가리키게 되어 노드별 구별 특징이 전부 벗겨져요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2739,0.1593],"c":[0,0.0019,0.3013,0.1913],"r":2.8,"img":"img/L5/walk/p096_h.jpg"},"parts":[{"b":[0.06,0.19,0.9,0.09],"c":[0.01,0.135,0.99,0.2],"r":8.8,"img":"img/L5/walk/p096_11_01.jpg","say":"첫 줄이에요. 학습되는 전파 가중치가 없으면 출력이 한 점으로 수렴해요."},{"b":[0.06,0.36,0.9,0.09],"c":[0.01,0.305,0.99,0.2],"r":8.8,"img":"img/L5/walk/p096_11_02.jpg","say":"둘째 줄이 보장이에요. 가중치가 무한 단계에만 몰리지 않으면 그 극한을 피해요."},{"b":[0.06,0.48,0.9,0.13],"c":[0.01,0.445,0.99,0.2],"r":8.8,"img":"img/L5/walk/p096_11_03.jpg","say":"셋째 줄이에요. 가중치가 분류 손실 위에서 학습되니 모델이 스스로 벌점을 줘요."}]}},{"p":97,"title":"마무리: 5주차를 한 장으로","terms":["Over-smoothing","Over-squashing","GCNII","JK-Net","MixHop","APPNP","GPR-GNN","BORF","SDRF","Rewiring","Layer Aggregation"],"pass1":[{"kind":"say","lines":["마지막 쪽은 글자 없이 Q 와 A 아이콘만 있는 닫는 슬라이드예요.","5주차의 질문은 하나였어요. 왜 GNN 은 깊게 못 쌓나, 어떻게 하면 쌓을 수 있나.","답은 다섯 갈래였어요."]},{"kind":"figure","head":"깊은 GNN 을 살리는 다섯 갈래","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"26\" font-size=\"17\" text-anchor=\"middle\">깊은 GNN 을 살리는 다섯 갈래<\/text>\n<rect class=\"box\" x=\"16\" y=\"48\" width=\"108\" height=\"58\" rx=\"8\"/>\n<text class=\"t\" x=\"70\" y=\"72\" font-size=\"15\" text-anchor=\"middle\">층 식을 고쳐요<\/text>\n<text class=\"tm\" x=\"70\" y=\"92\" font-size=\"14\" text-anchor=\"middle\">GCNII, PairNorm<\/text>\n<rect class=\"box b1\" x=\"132\" y=\"48\" width=\"108\" height=\"58\" rx=\"8\"/>\n<text class=\"t b1\" x=\"186\" y=\"72\" font-size=\"15\" text-anchor=\"middle\">학습을 고쳐요<\/text>\n<text class=\"tm b1\" x=\"186\" y=\"92\" font-size=\"14\" text-anchor=\"middle\">Dropout, DropEdge<\/text>\n<rect class=\"box b1\" x=\"248\" y=\"48\" width=\"108\" height=\"58\" rx=\"8\"/>\n<text class=\"t b1\" x=\"302\" y=\"72\" font-size=\"15\" text-anchor=\"middle\">그래프를 고쳐요<\/text>\n<text class=\"tm b1\" x=\"302\" y=\"92\" font-size=\"14\" text-anchor=\"middle\">SDRF, BORF<\/text>\n<rect class=\"box b2\" x=\"364\" y=\"48\" width=\"104\" height=\"58\" rx=\"8\"/>\n<text class=\"t b2\" x=\"416\" y=\"72\" font-size=\"15\" text-anchor=\"middle\">합치기를 고쳐요<\/text>\n<text class=\"tm b2\" x=\"416\" y=\"92\" font-size=\"14\" text-anchor=\"middle\">JK-Net, MixHop<\/text>\n<rect class=\"box2 b3\" x=\"132\" y=\"126\" width=\"224\" height=\"56\" rx=\"8\"/>\n<text class=\"t b3\" x=\"244\" y=\"150\" font-size=\"15\" text-anchor=\"middle\">전파를 신경망에서 떼어 내요<\/text>\n<text class=\"tm b3\" x=\"244\" y=\"170\" font-size=\"14\" text-anchor=\"middle\">PPNP, APPNP, GPR-GNN<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"218\" font-size=\"16\" text-anchor=\"middle\">문제는 하나였어요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"244\" font-size=\"14\" text-anchor=\"middle\">깊게 가고 싶은데 깊으면 망가진다<\/text>\n<\/svg>","caption":"문제는 하나였고 처방은 다섯 갈래였어요.","builds":3},{"kind":"compare","head":"5주차 뒷부분을 한 표로","cols":["갈래","모델","한 줄 요약"],"rows":[["합치기를 고쳐요","**제이케이넷(JK-Net)**","모든 층을 마지막에 모아 골라요"],["합치기를 고쳐요","**믹스홉(MixHop)**","한 층 안에 여러 홉을 나란히 둬요"],["전파를 떼어 내요","**에이피피엔피(APPNP)**","예측 먼저, 전파는 따로 반복해요"],["전파를 떼어 내요","**지피알 지엔엔(GPR-GNN)**","홉별 가중치를 직접 배워요"],["그래프를 고쳐요","**보알에프(BORF)**","배치로 더하고 빼서 양 끝을 잡아요"]]}],"pass2":[{"kind":"recap","items":["**과평활화(Over-smoothing)** 는 깊어질수록 모두가 같아지는 현상이에요.","**과압착(Over-squashing)** 은 좁은 통로에 정보가 눌려 담기는 현상이에요.","**재배선(Rewiring)** 은 모델이 아니라 그래프를 고치는 처방이에요.","**층 집계(Layer Aggregation)** 는 층마다의 표현을 합치는 단계예요.","오늘의 용어는 JK-Net, MixHop, APPNP, GPR-GNN, BORF 예요."]},{"kind":"points","head":"계산 문제에서 반드시 챙길 세 가지","items":["첫째, 행 정규화 인접행렬을 구한 뒤 행 합이 1 인지 검산하세요.","둘째, 렐루는 식에 적힌 자리에서만 씌우세요.","셋째, 식에 있는 계수를 하나도 빠뜨리지 마세요.","**지씨엔 투(GCNII)** 의 $(1-\\beta)$ 처럼 눈에 안 띄는 계수가 있어요."]}],"pass3":[{"kind":"points","head":"5주차 범위에서 확인된 기출","items":["**지씨엔 투(GCNII)** 는 2025 가을 중간 8번과 2024 가을 중간에 나왔어요.","**제이케이넷(JK-Net)** 은 2025 가을 중간 7번과 2024 가을 중간 5번에 나왔어요.","DeepGCN 은 2025 가을 중간 9번에 나왔어요. 잔차를 더하는 식이에요.","셋 다 행 정규화 인접행렬을 구하는 것으로 시작해요."]},{"kind":"check","q":"**제이케이넷(JK-Net)** 계산 문제에서 $k=2$ 이면 max 안에 항이 몇 개인가요?","choices":["1개","2개","3개","4개"],"a":1,"why":"식의 마지막 항이 $H^{(k-1)}$ 이라 0층과 1층 결과 두 개만 들어가요."},{"kind":"warn","head":"마지막으로 한 번 더","items":["**에스디알에프(SDRF)** 와 **보알에프(BORF)** 는 곡률로 그래프를 고치는 **재배선(Rewiring)** 이에요.","**믹스홉(MixHop)** 과 **제이케이넷(JK-Net)** 은 여러 홉이나 여러 층을 나란히 두는 처방이에요.","**에이피피엔피(APPNP)** 와 **지피알 지엔엔(GPR-GNN)** 은 전파를 신경망에서 떼어 낸 처방이에요.","모델 이름이 떠오르면 먼저 이 세 갈래 중 어디인지부터 찾으세요."]}],"pass4":[]}]};
